using System;
using System.IO;
using System.Text;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        var output = new StringBuilder();

        int testCases = scanner.NextInt();

        for (int test = 0; test < testCases; test++)
        {
            int n = scanner.NextInt();
            int[] digits = new int[n];

            for (int i = 0; i < n; i++)
                digits[i] = scanner.NextInt();

            long maximumProduct = 0;

            for (int incremented = 0; incremented < n; incremented++)
            {
                long product = 1;

                for (int i = 0; i < n; i++)
                    product *= digits[i] + (i == incremented ? 1 : 0);

                if (product > maximumProduct)
                    maximumProduct = product;
            }

            output.AppendLine(maximumProduct.ToString());
        }

        Console.Write(output.ToString());
    }
}
