                    if ((value & 1) == 0)
                        evenCount++;

                    int distance = (4 - value % 4) % 4;
                    if (distance < minimumDistanceToMultipleOfFour)
                        minimumDistanceToMultipleOfFour = distance;
                }
                else
                {
                    int distance = (k - value % k) % k;
                    if (distance < answer)
                        answer = distance;
                }
            }

            if (k == 4)
            {
                int distanceToTwoEvenNumbers = Math.Max(0, 2 - evenCount);
                answer = Math.Min(minimumDistanceToMultipleOfFour, distanceToTwoEvenNumbers);
            }

            output.AppendLine(answer.ToString());
        }

        Console.Write(output.ToString());
    }
