using System;
using System.Collections.Generic;

public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<int> values = ParseIntegers(input);

        if (values.Count == 0)
            return;

        int rows = values[0];
        int columns = (values.Count - 1) / rows;
        int[][] nums = new int[rows][];

        int index = 1;
        for (int i = 0; i < rows; i++)
        {
            nums[i] = new int[columns];
            for (int j = 0; j < columns; j++)
                nums[i][j] = values[index++];

            Array.Sort(nums[i]);
        }

        long score = 0;

        for (int column = 0; column < columns; column++)
        {
            int maximum = 0;
            for (int row = 0; row < rows; row++)
                maximum = Math.Max(maximum, nums[row][column]);

            score += maximum;
        }

        Console.WriteLine(score);
    }

    private static List<int> ParseIntegers(string input)
    {
        var result = new List<int>();
        int i = 0;

        while (i < input.Length)
        {
            while (i < input.Length && char.IsWhiteSpace(input[i]))
                i++;

            if (i >= input.Length)
                break;

            int sign = 1;
            if (input[i] == '-')
            {
                sign = -1;
                i++;
            }

            int value = 0;
            while (i < input.Length && input[i] >= '0' && input[i] <= '9')
            {
                value = value * 10 + (input[i] - '0');
                i++;
            }

            result.Add(value * sign);
        }

        return result;
    }
}
