            .Split((char[])null, StringSplitOptions.RemoveEmptyEntries)
            .Select(long.Parse)
            .ToArray();

        long maximum = long.MinValue;
        int subsetCount = 1 << nums.Length;

        for (int mask = 1; mask < subsetCount; mask++)
        {
            long product = 1;

            for (int i = 0; i < nums.Length; i++)
            {
                if ((mask & (1 << i)) != 0)
                    product *= nums[i];
            }

            if (product > maximum)
                maximum = product;
        }

        Console.WriteLine(maximum);
    }
