using System;

public class Program
{
    private const int Mod = 1000000007;

    private static int CountUpTo(string bound, int minSum, int maxSum)
    {
        int[,] dp = new int[maxSum + 1, 2];
        dp[0, 1] = 1;

        for (int pos = 0; pos < bound.Length; pos++)
        {
            int[,] next = new int[maxSum + 1, 2];
            int boundDigit = bound[pos] - '0';

            for (int sum = 0; sum <= maxSum; sum++)
            {
                for (int tight = 0; tight <= 1; tight++)
                {
                    int current = dp[sum, tight];
                    if (current == 0)
                        continue;

                    int limit = tight == 1 ? boundDigit : 9;
                    for (int digit = 0; digit <= limit && sum + digit <= maxSum; digit++)
                    {
                        int nextTight = (tight == 1 && digit == boundDigit) ? 1 : 0;
                        int value = next[sum + digit, nextTight] + current;
                        if (value >= Mod)
                            value -= Mod;
                        next[sum + digit, nextTight] = value;
                    }
                }
            }

            dp = next;
        }

        int result = 0;
        for (int sum = minSum; sum <= maxSum; sum++)
        {
            result += dp[sum, 0];
            if (result >= Mod)
                result -= Mod;

            result += dp[sum, 1];
            if (result >= Mod)
                result -= Mod;
        }

        return result;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split(
            new[] { ' ', '\t', '\r', '\n' },
            StringSplitOptions.RemoveEmptyEntries
        );

        string num1 = tokens[0];
        string num2 = tokens[1];
        int minSum = int.Parse(tokens[2]);
        int maxSum = int.Parse(tokens[3]);

        int countToNum2 = CountUpTo(num2, minSum, maxSum);
        int countToNum1 = CountUpTo(num1, minSum, maxSum);

        int num1DigitSum = 0;
        for (int i = 0; i < num1.Length; i++)
            num1DigitSum += num1[i] - '0';

        int num1IsGood =
            num1DigitSum >= minSum && num1DigitSum <= maxSum ? 1 : 0;

        int answer = countToNum2 - countToNum1 + num1IsGood;
        answer %= Mod;
        if (answer < 0)
            answer += Mod;

        Console.WriteLine(answer);
    }
}
