        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        int n = tokens.Length;
        if (n == 0)
            return;

        int[] nums = new int[n];
        for (int i = 0; i < n; i++)
            nums[i] = int.Parse(tokens[i]);

        int[] suffixDistinct = new int[n];
        HashSet<int> suffixSet = new HashSet<int>();

        for (int i = n - 1; i >= 0; i--)
        {
            suffixDistinct[i] = suffixSet.Count;
            suffixSet.Add(nums[i]);
        }

        HashSet<int> prefixSet = new HashSet<int>();
        int[] diff = new int[n];

        for (int i = 0; i < n; i++)
        {
            prefixSet.Add(nums[i]);
            diff[i] = prefixSet.Count - suffixDistinct[i];
        }

        Console.WriteLine(string.Join(" ", diff));
    }
