using System;
using System.IO;
using System.Text;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value * sign;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int queryCount = scanner.NextInt();

        int[] nums = new int[n];
        int adjacentPairs = 0;
        var output = new StringBuilder();

        for (int q = 0; q < queryCount; q++)
        {
            int index = scanner.NextInt();
            int newColor = scanner.NextInt();
            int oldColor = nums[index];

            if (oldColor != 0)
            {
                if (index > 0 && nums[index - 1] == oldColor)
                    adjacentPairs--;

                if (index + 1 < n && nums[index + 1] == oldColor)
                    adjacentPairs--;
            }

            nums[index] = newColor;

            if (index > 0 && nums[index - 1] == newColor)
                adjacentPairs++;

            if (index + 1 < n && nums[index + 1] == newColor)
                adjacentPairs++;

            if (q > 0)
                output.Append(' ');

            output.Append(adjacentPairs);
        }

        Console.WriteLine(output.ToString());
    }
}
