        long sumOfMinimums = 0;
        long answer = 0;

        foreach (int value in nums)
        {
            long x = value % Mod;
            long square = x * x % Mod;

            answer = (answer + square * ((x + sumOfMinimums) % Mod)) % Mod;
            sumOfMinimums = (2L * sumOfMinimums + x) % Mod;
        }

