            string digits = square.ToString();

            if (CanPartition(digits, 0, i))
                punishmentNumber += square;
        }

        Console.WriteLine(punishmentNumber);
    }

    private static bool CanPartition(string digits, int position, int remaining)
    {
        if (position == digits.Length)
            return remaining == 0;

        int value = 0;

        for (int end = position; end < digits.Length; end++)
        {
            value = value * 10 + (digits[end] - '0');

            if (value > remaining)
                break;

            if (CanPartition(digits, end + 1, remaining - value))
                return true;
        }

        return false;
    }
