        if (readingNumber)
            values.Add(number);

        if (values.Count < 2)
            return;

        int n = values.Count - 1;
        long x = values[n];
        var nums = new long[n];
        var minimumCosts = new long[n];

        for (int i = 0; i < n; i++)
        {
            nums[i] = values[i];
            minimumCosts[i] = nums[i];
        }

        long answer = long.MaxValue;

        for (int operations = 0; operations < n; operations++)
        {
            long collectionCost = 0;

            for (int i = 0; i < n; i++)
            {
                int sourceIndex = (i - operations + n) % n;
                minimumCosts[i] = Math.Min(minimumCosts[i], nums[sourceIndex]);
                collectionCost += minimumCosts[i];
            }

            long totalCost = collectionCost + (long)operations * x;
            answer = Math.Min(answer, totalCost);
        }

        Console.WriteLine(answer);
    }
