using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private class DisjointSet
    {
        private readonly int[] parent;
        private readonly int[] size;

        public DisjointSet(int n)
        {
            parent = new int[n];
            size = new int[n];

            for (int i = 0; i < n; i++)
            {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int Find(int x)
        {
            while (x != parent[x])
            {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }

            return x;
        }

        public void Union(int a, int b)
        {
            int rootA = Find(a);
            int rootB = Find(b);

            if (rootA == rootB)
                return;

            if (size[rootA] < size[rootB])
            {
                int temp = rootA;
                rootA = rootB;
                rootB = temp;
            }

            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<int> values = ParseIntegers(input);

        int n = values.Count;
        if (n <= 1)
        {
            Console.WriteLine("true");
            return;
        }

        int maxValue = 0;
        for (int i = 0; i < n; i++)
        {
            if (values[i] == 1)
            {
                Console.WriteLine("false");
                return;
            }

            if (values[i] > maxValue)
                maxValue = values[i];
        }

        int[] smallestPrimeFactor = BuildSmallestPrimeFactors(maxValue);
        int[] primeOwner = new int[maxValue + 1];

        for (int i = 0; i <= maxValue; i++)
            primeOwner[i] = -1;

        DisjointSet dsu = new DisjointSet(n);

        for (int i = 0; i < n; i++)
        {
            int value = values[i];

            while (value > 1)
            {
                int prime = smallestPrimeFactor[value];

                if (primeOwner[prime] == -1)
                    primeOwner[prime] = i;
                else
                    dsu.Union(i, primeOwner[prime]);

                while (value % prime == 0)
                    value /= prime;
            }
        }

        int root = dsu.Find(0);
        for (int i = 1; i < n; i++)
        {
            if (dsu.Find(i) != root)
            {
                Console.WriteLine("false");
                return;
            }
        }

        Console.WriteLine("true");
    }

    private static int[] BuildSmallestPrimeFactors(int maxValue)
    {
        int[] spf = new int[maxValue + 1];

        for (int i = 2; i <= maxValue; i++)
        {
            if (spf[i] != 0)
                continue;

            spf[i] = i;

            if ((long)i * i > maxValue)
                continue;

            for (int multiple = i * i; multiple <= maxValue; multiple += i)
            {
                if (spf[multiple] == 0)
                    spf[multiple] = i;
            }
        }

        return spf;
    }

    private static List<int> ParseIntegers(string input)
    {
        List<int> result = new List<int>();
        int i = 0;

        while (i < input.Length)
        {
            while (i < input.Length && !char.IsDigit(input[i]))
                i++;

            if (i >= input.Length)
                break;

            int value = 0;
            while (i < input.Length && char.IsDigit(input[i]))
            {
                value = value * 10 + (input[i] - '0');
                i++;
            }

            result.Add(value);
        }

        return result;
    }
}
