using System.IO;

public class Program
{
    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());
        List<int> input = new List<int>();
        int value;

        while (scanner.TryNextInt(out value))
            input.Add(value);

        if (input.Count < 2)
            return;

        int n = input.Count - 1;
        int k = input[n];

        List<int>[] positions = new List<int>[n + 1];

        for (int i = 0; i < n; i++)
        {
            int number = input[i];
            if (positions[number] == null)
                positions[number] = new List<int>();

            positions[number].Add(i);
        }

        int answer = 0;

        for (int number = 1; number <= n; number++)
        {
            List<int> list = positions[number];
            if (list == null)
                continue;

            int left = 0;

            for (int right = 0; right < list.Count; right++)
            {
                while (list[right] - list[left] - (right - left) > k)
                    left++;

                answer = Math.Max(answer, right - left + 1);
            }
        }

        Console.WriteLine(answer);
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int index;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (index >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                index = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[index++];
        }

        public bool TryNextInt(out int value)
        {
            value = 0;
            int c;

            do
            {
                c = Read();
                if (c == -1)
                    return false;
            }
            while (c <= 32);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            while (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            value *= sign;
            return true;
        }
    }
}
