using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

public class Program
{
    private struct LogEntry
    {
        public int ServerId;
        public int Time;

        public LogEntry(int serverId, int time)
        {
            ServerId = serverId;
            Time = time;
        }
    }

    private struct QueryEntry
    {
        public int Time;
        public int Index;

        public QueryEntry(int time, int index)
        {
            Time = time;
            Index = index;
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int n;
        if (!scanner.TryNextInt(out n))
            return;

        int logCount = scanner.NextInt();
        LogEntry[] logs = new LogEntry[logCount];

        for (int i = 0; i < logCount; i++)
        {
            int serverId = scanner.NextInt();
            int time = scanner.NextInt();
            logs[i] = new LogEntry(serverId, time);
        }

        int x = scanner.NextInt();

        List<int> queryValues = new List<int>();
        int value;
        while (scanner.TryNextInt(out value))
            queryValues.Add(value);

        Array.Sort(logs, delegate(LogEntry a, LogEntry b)
        {
            return a.Time.CompareTo(b.Time);
        });

        QueryEntry[] queries = new QueryEntry[queryValues.Count];
        for (int i = 0; i < queryValues.Count; i++)
            queries[i] = new QueryEntry(queryValues[i], i);

        Array.Sort(queries, delegate(QueryEntry a, QueryEntry b)
        {
            return a.Time.CompareTo(b.Time);
        });

        int[] serverRequestCounts = new int[n + 1];
        int[] answers = new int[queries.Length];

        int left = 0;
        int right = 0;
        int activeServers = 0;

        for (int i = 0; i < queries.Length; i++)
        {
            int queryTime = queries[i].Time;
            int windowStart = queryTime - x;

            while (right < logs.Length && logs[right].Time <= queryTime)
            {
                int serverId = logs[right].ServerId;
                if (serverRequestCounts[serverId] == 0)
                    activeServers++;

                serverRequestCounts[serverId]++;
                right++;
            }

            while (left < right && logs[left].Time < windowStart)
            {
                int serverId = logs[left].ServerId;
                serverRequestCounts[serverId]--;

                if (serverRequestCounts[serverId] == 0)
                    activeServers--;

                left++;
            }

            answers[queries[i].Index] = n - activeServers;
        }

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < answers.Length; i++)
        {
            if (i > 0)
                output.Append(' ');
            output.Append(answers[i]);
        }

        Console.WriteLine(output.ToString());
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public bool TryNextInt(out int value)
        {
            int c;
            do
            {
                c = ReadByte();
                if (c == -1)
                {
                    value = 0;
                    return false;
                }
            } while (c <= 32);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            int result = 0;
            while (c > 32 && c != -1)
            {
                result = result * 10 + (c - '0');
                c = ReadByte();
            }

            value = result * sign;
            return true;
        }

        public int NextInt()
        {
            int value;
            TryNextInt(out value);
            return value;
        }
    }
}
