        for (long operations = 1; operations <= 60; operations++)
        {
            long target = num1 - operations * num2;

            if (target < operations)
                continue;

            if (PopCount(target) <= operations)
            {
                Console.WriteLine(operations);
                return;
            }
        }

        Console.WriteLine(-1);
    }

    private static int PopCount(long value)
    {
        int count = 0;
        while (value > 0)
        {
            value &= value - 1;
            count++;
        }
        return count;
    }
}
