using System;
using System.IO;
using System.Text;
using System.Collections.Generic;

public class Program
{
    private struct Point
    {
        public long X;
        public long Y;
        public long Sum;
    }

    private struct Query
    {
        public long X;
        public long Y;
        public int Index;
    }

    private sealed class FenwickMax
    {
        private readonly long[] tree;

        public FenwickMax(int size)
        {
            tree = new long[size + 1];
            for (int i = 0; i < tree.Length; i++)
                tree[i] = -1;
        }

        public void Update(int index, long value)
        {
            for (int i = index; i < tree.Length; i += i & -i)
            {
                if (value > tree[i])
                    tree[i] = value;
            }
        }

        public long Query(int index)
        {
            long result = -1;
            for (int i = index; i > 0; i -= i & -i)
            {
                if (tree[i] > result)
                    result = tree[i];
            }
            return result;
        }
    }

    private static string ReadNonEmptyLine()
    {
        string line;
        while ((line = Console.ReadLine()) != null)
        {
            if (!string.IsNullOrWhiteSpace(line))
                return line;
        }
        return null;
    }

    private static long[] ParseLongArray(string line)
    {
        string[] parts = line.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
        long[] values = new long[parts.Length];
        for (int i = 0; i < parts.Length; i++)
            values[i] = long.Parse(parts[i]);
        return values;
    }

    private static int LowerBound(long[] array, long value)
    {
        int left = 0;
        int right = array.Length;

        while (left < right)
        {
            int middle = left + (right - left) / 2;
            if (array[middle] < value)
                left = middle + 1;
            else
                right = middle;
        }

        return left;
    }

    public static void Main()
    {
        string firstLine = ReadNonEmptyLine();
        if (firstLine == null)
            return;

        long[] nums1 = ParseLongArray(firstLine);
        long[] nums2 = ParseLongArray(ReadNonEmptyLine());
        int queryCount = int.Parse(ReadNonEmptyLine().Trim());

        int n = nums1.Length;
        Point[] points = new Point[n];
        long[] yValues = new long[n];

        for (int i = 0; i < n; i++)
        {
            points[i] = new Point
            {
                X = nums1[i],
                Y = nums2[i],
                Sum = nums1[i] + nums2[i]
            };
            yValues[i] = nums2[i];
        }

        Query[] queries = new Query[queryCount];
        for (int i = 0; i < queryCount; i++)
        {
            long[] values = ParseLongArray(ReadNonEmptyLine());
            queries[i] = new Query
            {
                X = values[0],
                Y = values[1],
                Index = i
            };
        }

        Array.Sort(points, delegate(Point a, Point b)
        {
            return b.X.CompareTo(a.X);
        });

        Array.Sort(queries, delegate(Query a, Query b)
        {
            return b.X.CompareTo(a.X);
        });

        Array.Sort(yValues);
        List<long> uniqueList = new List<long>();
        for (int i = 0; i < yValues.Length; i++)
        {
            if (i == 0 || yValues[i] != yValues[i - 1])
                uniqueList.Add(yValues[i]);
        }
        long[] uniqueY = uniqueList.ToArray();

        FenwickMax fenwick = new FenwickMax(uniqueY.Length);
        long[] answers = new long[queryCount];
        int pointIndex = 0;

        for (int i = 0; i < queryCount; i++)
        {
            Query query = queries[i];

            while (pointIndex < n && points[pointIndex].X >= query.X)
            {
                int position = LowerBound(uniqueY, points[pointIndex].Y);
                int reversedIndex = uniqueY.Length - position;
                fenwick.Update(reversedIndex, points[pointIndex].Sum);
                pointIndex++;
            }

            int firstValidPosition = LowerBound(uniqueY, query.Y);
            if (firstValidPosition == uniqueY.Length)
            {
                answers[query.Index] = -1;
            }
            else
            {
                int queryIndex = uniqueY.Length - firstValidPosition;
                answers[query.Index] = fenwick.Query(queryIndex);
            }
        }

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < answers.Length; i++)
        {
            if (i > 0)
                output.Append(' ');
            output.Append(answers[i]);
        }

        Console.WriteLine(output.ToString());
    }
}
