using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

public class Program
{
    private const long Mod = 1000000007L;

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        MatchCollection matches = Regex.Matches(input, @"\d+");

        var values = new List<long>();
        foreach (Match match in matches)
            values.Add(long.Parse(match.Value));

        int n = values.Count;
        int totalMasks = 1 << n;
        long[,] dp = new long[totalMasks, n];

        for (int i = 0; i < n; i++)
            dp[1 << i, i] = 1;

        for (int mask = 1; mask < totalMasks; mask++)
        {
            for (int last = 0; last < n; last++)
            {
                long count = dp[mask, last];
                if (count == 0)
                    continue;

                for (int next = 0; next < n; next++)
                {
                    if ((mask & (1 << next)) != 0)
                        continue;

                    if (values[last] % values[next] == 0 ||
                        values[next] % values[last] == 0)
                    {
                        int newMask = mask | (1 << next);
                        dp[newMask, next] = (dp[newMask, next] + count) % Mod;
                    }
                }
            }
        }

        long answer = 0;
        int fullMask = totalMasks - 1;

        for (int last = 0; last < n; last++)
            answer = (answer + dp[fullMask, last]) % Mod;

        Console.WriteLine(answer);
    }
}
