    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        int[] values = ParseIntegers(input);

        int x = values[0];
        int y = values[1];
        int z = values[2];

        // Last piece types: 0 = "AA", 1 = "BB", 2 = "AB"
        bool[,,,] reachable = new bool[x + 1, y + 1, z + 1, 3];

        if (x > 0) reachable[1, 0, 0, 0] = true;
        if (y > 0) reachable[0, 1, 0, 1] = true;
        if (z > 0) reachable[0, 0, 1, 2] = true;

        int maximumPieces = 0;

        for (int a = 0; a <= x; a++)
        {
            for (int b = 0; b <= y; b++)
            {
                for (int c = 0; c <= z; c++)
                {
                    for (int last = 0; last < 3; last++)
                    {
                        if (!reachable[a, b, c, last])
                            continue;

                        maximumPieces = Math.Max(maximumPieces, a + b + c);

                        // "AA" may follow "BB" or "AB".
                        if (a < x && (last == 1 || last == 2))
                            reachable[a + 1, b, c, 0] = true;

                        // "BB" may only follow "AA".
                        if (b < y && last == 0)
                            reachable[a, b + 1, c, 1] = true;

                        // "AB" may follow "BB" or "AB".
                        if (c < z && (last == 1 || last == 2))
                            reachable[a, b, c + 1, 2] = true;
                    }
                }
            }
        }

        Console.WriteLine(maximumPieces * 2);
    }

    private static int[] ParseIntegers(string input)
    {
        int[] result = new int[3];
        int count = 0;
        int i = 0;

        while (i < input.Length && count < 3)
        {
            while (i < input.Length && !char.IsDigit(input[i]))
                i++;

            int value = 0;
            while (i < input.Length && char.IsDigit(input[i]))
            {
                value = value * 10 + (input[i] - '0');
                i++;
            }

            if (i > 0)
                result[count++] = value;
        }

        return result;
    }
}
