        List<int> numbers = ParseIntegers(input);

        if (numbers.Count == 0)
        {
            Console.WriteLine(0);
            return;
        }

        int[] nums = numbers.ToArray();
        bool[] seen = new bool[2001];
        int totalDistinct = 0;

        foreach (int num in nums)
        {
            if (!seen[num])
            {
                seen[num] = true;
                totalDistinct++;
            }
        }

        long totalSubarrays = (long)nums.Length * (nums.Length + 1) / 2;
        long incompleteSubarrays = CountAtMostDistinct(nums, totalDistinct - 1);

        Console.WriteLine(totalSubarrays - incompleteSubarrays);
    }

    private static long CountAtMostDistinct(int[] nums, int limit)
    {
        if (limit < 0)
            return 0;

        int[] frequencies = new int[2001];
        int left = 0;
        int distinct = 0;
        long count = 0;

        for (int right = 0; right < nums.Length; right++)
        {
            if (frequencies[nums[right]]++ == 0)
                distinct++;

            while (distinct > limit)
            {
                if (--frequencies[nums[left]] == 0)
                    distinct--;
                left++;
            }

            count += right - left + 1;
        }

        return count;
    }

    private static List<int> ParseIntegers(string input)
    {
        List<int> result = new List<int>();
        int value = 0;
        bool readingNumber = false;

        foreach (char c in input)
        {
            if (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                readingNumber = true;
            }
            else if (readingNumber)
            {
                result.Add(value);
                value = 0;
                readingNumber = false;
            }
