using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public bool TryReadInt(out int value)
        {
            int c;
            do
            {
                c = Read();
                if (c == -1)
                {
                    value = 0;
                    return false;
                }
            } while (c <= 32);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int result = 0;
            while (c >= '0' && c <= '9')
            {
                result = result * 10 + (c - '0');
                c = Read();
            }

            value = result * sign;
            return true;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        var values = new List<int>();
        int value;

        while (scanner.TryReadInt(out value))
            values.Add(value);

        int n = values.Count;
        if (n == 0)
        {
            Console.WriteLine(0);
            return;
        }

        int[] maxDeque = new int[n];
        int[] minDeque = new int[n];
        int maxHead = 0, maxTail = 0;
        int minHead = 0, minTail = 0;
        int left = 0;
        long answer = 0;

        for (int right = 0; right < n; right++)
        {
            while (maxTail > maxHead &&
                   values[maxDeque[maxTail - 1]] <= values[right])
            {
                maxTail--;
            }
            maxDeque[maxTail++] = right;

            while (minTail > minHead &&
                   values[minDeque[minTail - 1]] >= values[right])
            {
                minTail--;
            }
            minDeque[minTail++] = right;

            while ((long)values[maxDeque[maxHead]] -
                   values[minDeque[minHead]] > 2)
            {
                if (maxDeque[maxHead] == left)
                    maxHead++;
                if (minDeque[minHead] == left)
                    minHead++;
                left++;
            }

            answer += right - left + 1L;
        }

        Console.WriteLine(answer);
    }
}
