using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    public static void Main()
    {
        var lines = new List<int[]>();
        string line;

        while ((line = Console.ReadLine()) != null)
        {
            int[] values = ParseLine(line);
            if (values.Length > 0)
                lines.Add(values);
        }

        int[] nums1;
        int[] nums2;

        // Supports both:
        // nums1 on first line, nums2 on second line
        // or n on first line, followed by the two arrays
        if (lines.Count >= 3 && lines[0].Length == 1 &&
            lines[1].Length == lines[0][0] &&
            lines[2].Length == lines[0][0])
        {
            nums1 = lines[1];
            nums2 = lines[2];
        }
        else
        {
            nums1 = lines[0];
            nums2 = lines[1];
        }

        int n = nums1.Length;
        int endWithFirst = 1;
        int endWithSecond = 1;
        int answer = 1;

        for (int i = 1; i < n; i++)
        {
            int previousFirst = endWithFirst;
            int previousSecond = endWithSecond;

            endWithFirst = 1;
            endWithSecond = 1;

            if (nums1[i] >= nums1[i - 1])
                endWithFirst = Math.Max(endWithFirst, previousFirst + 1);
            if (nums1[i] >= nums2[i - 1])
                endWithFirst = Math.Max(endWithFirst, previousSecond + 1);

            if (nums2[i] >= nums1[i - 1])
                endWithSecond = Math.Max(endWithSecond, previousFirst + 1);
            if (nums2[i] >= nums2[i - 1])
                endWithSecond = Math.Max(endWithSecond, previousSecond + 1);

            answer = Math.Max(answer, Math.Max(endWithFirst, endWithSecond));
        }

        Console.WriteLine(answer);
    }

    private static int[] ParseLine(string line)
    {
        var values = new List<int>();
        int value = 0;
        bool reading = false;
        bool negative = false;

