using System;

public class Program
{
    static string Merge(string first, string second)
    {
        if (first.Contains(second))
            return first;

        if (second.Contains(first))
            return second;

        int maxOverlap = Math.Min(first.Length, second.Length);

        for (int overlap = maxOverlap; overlap >= 0; overlap--)
        {
            bool matches = true;

            for (int i = 0; i < overlap; i++)
            {
                if (first[first.Length - overlap + i] != second[i])
                {
                    matches = false;
                    break;
                }
            }

            if (matches)
                return first + second.Substring(overlap);
        }

        return first + second;
    }

    static bool IsBetter(string candidate, string current)
    {
        return current == null ||
               candidate.Length < current.Length ||
               (candidate.Length == current.Length &&
                string.CompareOrdinal(candidate, current) < 0);
    }

    public static void Main()
    {
        string[] strings = new string[3];
        strings[0] = Console.ReadLine();
        strings[1] = Console.ReadLine();
        strings[2] = Console.ReadLine();

        int[,] permutations =
        {
            { 0, 1, 2 },
            { 0, 2, 1 },
            { 1, 0, 2 },
            { 1, 2, 0 },
            { 2, 0, 1 },
            { 2, 1, 0 }
        };

        string answer = null;

        for (int i = 0; i < 6; i++)
        {
            string candidate = Merge(strings[permutations[i, 0]],
                                     strings[permutations[i, 1]]);
            candidate = Merge(candidate, strings[permutations[i, 2]]);

            if (IsBetter(candidate, answer))
                answer = candidate;
        }

        Console.WriteLine(answer);
    }
}
