using System;

public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        string s = tokens[0];
        int k = int.Parse(tokens[1]);
        int n = s.Length;

        int[,] cost = new int[n, n];

        // Compute the minimum changes needed for every substring of length >= 2.
        for (int length = 2; length <= n; length++)
        {
            for (int left = 0; left + length <= n; left++)
            {
                int best = int.MaxValue;

                for (int d = 1; d < length; d++)
                {
                    if (length % d != 0)
                        continue;

                    int groupLength = length / d;
                    int changes = 0;

                    for (int remainder = 0; remainder < d; remainder++)
                    {
                        for (int i = 0; i < groupLength / 2; i++)
                        {
                            int first = left + remainder + i * d;
                            int second = left + remainder + (groupLength - 1 - i) * d;

                            if (s[first] != s[second])
                                changes++;
                        }
                    }

                    if (changes < best)
                        best = changes;
                }

                cost[left, left + length - 1] = best;
            }
        }

        const int INF = 1000000000;
        int[,] dp = new int[k + 1, n + 1];

        for (int parts = 0; parts <= k; parts++)
            for (int length = 0; length <= n; length++)
                dp[parts, length] = INF;

        dp[0, 0] = 0;

        for (int parts = 1; parts <= k; parts++)
        {
            for (int end = 2 * parts; end <= n; end++)
            {
                int minStart = 2 * (parts - 1);

                for (int start = minStart; start <= end - 2; start++)
                {
                    if (dp[parts - 1, start] == INF)
                        continue;

                    int candidate = dp[parts - 1, start] + cost[start, end - 1];
                    if (candidate < dp[parts, end])
                        dp[parts, end] = candidate;
                }
            }
        }

        Console.WriteLine(dp[k, n]);
    }
}
