        dp[0] = 1;

        for (int baseValue = 1; ; baseValue++)
        {
            long power = 1;
            for (int exponent = 0; exponent < x; exponent++)
            {
                power *= baseValue;
                if (power > n)
                    break;
            }

            if (power > n)
                break;

            int value = (int)power;

            for (int sum = n; sum >= value; sum--)
            {
                dp[sum] = (dp[sum] + dp[sum - value]) % Mod;
            }
        }

        Console.WriteLine(dp[n]);
