                continue;

            for (int end = i + 1; end <= n; end++)
            {
                string part = s.Substring(i, end - i);
                if (powersOfFive.Contains(part))
                    dp[end] = Math.Min(dp[end], dp[i] + 1);
            }
        }

        Console.WriteLine(dp[n] == int.MaxValue ? -1 : dp[n]);
    }
