using System;

public class Program
{
    private static int[] firstEdge;
    private static int[] edgeTo;
    private static int[] edgeNext;
    private static char[] edgeChar;
    private static bool[] terminal;
    private static int nodeCount;
    private static int edgeCount;

    private static int FindChild(int node, char c)
    {
        for (int edge = firstEdge[node]; edge != 0; edge = edgeNext[edge])
        {
            if (edgeChar[edge] == c)
                return edgeTo[edge];
        }
        return -1;
    }

    private static int AddChild(int node, char c)
    {
        int child = nodeCount++;
        int edge = ++edgeCount;

        edgeChar[edge] = c;
        edgeTo[edge] = child;
        edgeNext[edge] = firstEdge[node];
        firstEdge[node] = edge;

        return child;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        if (tokens.Length == 0)
            return;

        string word = tokens[0];
        int totalLength = 0;
        int maxForbiddenLength = 0;

        for (int i = 1; i < tokens.Length; i++)
        {
            totalLength += tokens[i].Length;
            if (tokens[i].Length > maxForbiddenLength)
                maxForbiddenLength = tokens[i].Length;
        }

        firstEdge = new int[totalLength + 2];
        edgeTo = new int[totalLength + 2];
        edgeNext = new int[totalLength + 2];
        edgeChar = new char[totalLength + 2];
        terminal = new bool[totalLength + 2];

        nodeCount = 1;
        edgeCount = 0;

        for (int i = 1; i < tokens.Length; i++)
        {
            string forbidden = tokens[i];
            int node = 0;

            for (int j = forbidden.Length - 1; j >= 0; j--)
            {
                char c = forbidden[j];
                int child = FindChild(node, c);

                if (child == -1)
                    child = AddChild(node, c);

                node = child;
            }

            terminal[node] = true;
        }

        int left = 0;
        int answer = 0;

        for (int right = 0; right < word.Length; right++)
        {
            int node = 0;
            int minimumIndex = Math.Max(left, right - maxForbiddenLength + 1);

            for (int i = right; i >= minimumIndex; i--)
            {
                node = FindChild(node, word[i]);

                if (node == -1)
                    break;

                if (terminal[node])
                {
                    left = i + 1;
                    break;
                }
            }

            int length = right - left + 1;
            if (length > answer)
                answer = length;
        }

        Console.WriteLine(answer);
    }
}
