        List<int> nums = ParseIntegers(input);

        int n = nums.Count;
        if (n < 2)
        {
            Console.WriteLine(-1);
            return;
        }

        int candidate = 0;
        int balance = 0;

        foreach (int value in nums)
        {
            if (balance == 0)
                candidate = value;

            balance += value == candidate ? 1 : -1;
        }

        int totalCount = 0;
        foreach (int value in nums)
        {
            if (value == candidate)
                totalCount++;
        }

        int leftCount = 0;

        for (int i = 0; i < n - 1; i++)
        {
            if (nums[i] == candidate)
                leftCount++;

            int leftLength = i + 1;
            int rightLength = n - leftLength;
            int rightCount = totalCount - leftCount;

            if (leftCount * 2 > leftLength &&
                rightCount * 2 > rightLength)
            {
                Console.WriteLine(i);
                return;
            }
        }

        Console.WriteLine(-1);
    }

    private static List<int> ParseIntegers(string input)
    {
        var result = new List<int>();
        int i = 0;

        while (i < input.Length)
        {
            while (i < input.Length &&
                   !char.IsDigit(input[i]) &&
                   input[i] != '-')
            {
                i++;
            }

            if (i >= input.Length)
                break;

            int sign = 1;
            if (input[i] == '-')
            {
                sign = -1;
                i++;
            }

            int value = 0;
            bool hasDigit = false;

            while (i < input.Length && char.IsDigit(input[i]))
            {
                hasDigit = true;
                value = value * 10 + (input[i] - '0');
                i++;
            }

            if (hasDigit)
                result.Add(value * sign);
        }

        return result;
    }
