        const long NegativeInfinity = long.MinValue / 4;

        long[] best = { NegativeInfinity, NegativeInfinity };
        int initialParity = nums[0] & 1;
        best[initialParity] = nums[0];

        for (int i = 1; i < nums.Count; i++)
        {
            int parity = nums[i] & 1;
            long sameParity = best[parity];
            long differentParity = best[1 - parity] - x;
            long current = Math.Max(sameParity, differentParity) + nums[i];

            if (current > best[parity])
                best[parity] = current;
        }

        Console.WriteLine(Math.Max(best[0], best[1]));
