            }

            if (!char.IsDigit(line[i]))
            {
                i++;
                continue;
            }

            long value = 0;
            while (i < line.Length && char.IsDigit(line[i]))
            {
                value = value * 10 + (line[i] - '0');
                i++;
            }

            numbers.Add(negative ? -value : value);
        }

        return numbers;
    }

    public static void Main()
    {
        var lines = new List<string>();
        string line;

        while ((line = Console.ReadLine()) != null)
        {
            if (!string.IsNullOrWhiteSpace(line))
                lines.Add(line);
        }

        if (lines.Count < 3)
            return;

        List<long> nums = ExtractNumbers(lines[0]);
        long modulo = ExtractNumbers(lines[1])[0];
        long k = ExtractNumbers(lines[2])[0];

        var frequencies = new Dictionary<long, long>();
        frequencies[0] = 1;

        long prefixCount = 0;
        long answer = 0;

        foreach (long value in nums)
        {
            long remainder = value % modulo;
            if (remainder < 0)
                remainder += modulo;

            if (remainder == k)
                prefixCount++;

            long current = prefixCount % modulo;
            long needed = (current - k + modulo) % modulo;

            long frequency;
            if (frequencies.TryGetValue(needed, out frequency))
                answer += frequency;

            if (frequencies.TryGetValue(current, out frequency))
                frequencies[current] = frequency + 1;
            else
                frequencies[current] = 1;
        }

        Console.WriteLine(answer);
    }
}
