    private struct PositionInfo
    {
        public int First;
        public int Last;
        public int MaxGap;

        public PositionInfo(int position)
        {
            First = position;
            Last = position;
            MaxGap = 0;
        }
    }

    public static void Main()
    {
        List<int> nums = ReadAllIntegers();
        int n = nums.Count;

        if (n <= 1)
        {
            Console.WriteLine(0);
            return;
        }

        var positions = new Dictionary<int, PositionInfo>();

        for (int i = 0; i < n; i++)
        {
            int value = nums[i];
            PositionInfo info;

            if (positions.TryGetValue(value, out info))
            {
                int gap = i - info.Last;
                if (gap > info.MaxGap)
                    info.MaxGap = gap;

                info.Last = i;
                positions[value] = info;
            }
            else
            {
                positions[value] = new PositionInfo(i);
            }
        }

        int answer = int.MaxValue;

        foreach (PositionInfo info in positions.Values)
        {
            int circularGap = n - info.Last + info.First;
            int maximumGap = Math.Max(info.MaxGap, circularGap);
            int seconds = maximumGap / 2;

            if (seconds < answer)
                answer = seconds;
        }

        Console.WriteLine(answer);
    }

    private static List<int> ReadAllIntegers()
    {
        var result = new List<int>();
        Stream input = Console.OpenStandardInput();
        int current = 0;
        int sign = 1;
        bool readingNumber = false;
        int b;

        while ((b = input.ReadByte()) != -1)
        {
            if (b == '-')
