using System;
using System.IO;

public class Program
{
    private const long Mod = 1000000007L;
    private static string digits;
    private static long[,] memo;

    private static long CountUpTo(string bound)
    {
        digits = bound;
        memo = new long[digits.Length, 11];

        for (int i = 0; i < digits.Length; i++)
            for (int j = 0; j <= 10; j++)
                memo[i, j] = -1;

        return Dfs(0, 10, true);
    }

    private static long Dfs(int position, int previousDigit, bool tight)
    {
        if (position == digits.Length)
            return previousDigit == 10 ? 0 : 1;

        if (!tight && memo[position, previousDigit] != -1)
            return memo[position, previousDigit];

        int limit = tight ? digits[position] - '0' : 9;
        long result = 0;

        for (int digit = 0; digit <= limit; digit++)
        {
            bool nextTight = tight && digit == limit;

            if (previousDigit == 10)
            {
                int nextPrevious = digit == 0 ? 10 : digit;
                result += Dfs(position + 1, nextPrevious, nextTight);
            }
            else if (Math.Abs(previousDigit - digit) == 1)
            {
                result += Dfs(position + 1, digit, nextTight);
            }

            result %= Mod;
        }

        if (!tight)
            memo[position, previousDigit] = result;

        return result;
    }

    private static string Decrement(string value)
    {
        char[] number = value.ToCharArray();
        int index = number.Length - 1;

        while (index >= 0 && number[index] == '0')
        {
            number[index] = '9';
            index--;
        }

        if (index >= 0)
            number[index]--;

        int start = 0;
        while (start < number.Length - 1 && number[start] == '0')
            start++;

        return new string(number, start, number.Length - start);
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split(
            (char[])null,
            StringSplitOptions.RemoveEmptyEntries
        );

        string low = tokens[0];
        string high = tokens[1];

        long highCount = CountUpTo(high);
        long lowCount = CountUpTo(Decrement(low));

        long answer = (highCount - lowCount + Mod) % Mod;
        Console.WriteLine(answer);
    }
}
