using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value * sign;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }
    }

    private static long Encode(int x, int y)
    {
        return ((long)x << 32) | (uint)y;
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int[] xs = new int[n];
        int[] ys = new int[n];

        for (int i = 0; i < n; i++)
        {
            xs[i] = scanner.NextInt();
            ys[i] = scanner.NextInt();
        }

        int k = scanner.NextInt();
        var frequencies = new Dictionary<long, int>(n * 2);
        long answer = 0;

        for (int i = 0; i < n; i++)
        {
            int x = xs[i];
            int y = ys[i];

            for (int xDistance = 0; xDistance <= k; xDistance++)
            {
                int yDistance = k - xDistance;
                long required = Encode(x ^ xDistance, y ^ yDistance);

                int count;
                if (frequencies.TryGetValue(required, out count))
                    answer += count;
            }

            long current = Encode(x, y);
            int currentCount;
            if (frequencies.TryGetValue(current, out currentCount))
                frequencies[current] = currentCount + 1;
            else
                frequencies[current] = 1;
        }

        Console.WriteLine(answer);
    }
}
