        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value * sign;
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();

        int n = scanner.NextInt();
        int offerCount = scanner.NextInt();

        Offer[] offers = new Offer[offerCount];
        for (int i = 0; i < offerCount; i++)
        {
            offers[i] = new Offer
            {
                Start = scanner.NextInt(),
                End = scanner.NextInt(),
                Gold = scanner.NextInt()
            };
