public class Program
{
    private static List<int> ParseIntegers(string line)
    {
        var values = new List<int>();
        int i = 0;

        while (i < line.Length)
        {
            while (i < line.Length && !char.IsDigit(line[i]) && line[i] != '-')
                i++;

            if (i >= line.Length)
                break;

            int sign = 1;
            if (line[i] == '-')
            {
                sign = -1;
                i++;
            }

            int value = 0;
            bool hasDigit = false;
            while (i < line.Length && char.IsDigit(line[i]))
            {
                hasDigit = true;
                value = value * 10 + (line[i] - '0');
                i++;
            }

            if (hasDigit)
                values.Add(value * sign);
        }

        return values;
    }

    public static void Main()
    {
        string numsLine = null;
        string xLine = null;
        string line;

        while ((line = Console.ReadLine()) != null)
        {
            if (string.IsNullOrWhiteSpace(line))
                continue;

            if (numsLine == null)
                numsLine = line;
            else
            {
                xLine = line;
                break;
            }
        }

        if (numsLine == null || xLine == null)
            return;

        List<int> nums = ParseIntegers(numsLine);
        List<int> xValues = ParseIntegers(xLine);

        if (nums.Count == 0 || xValues.Count == 0)
            return;

        int x = xValues[0];
        var eligible = new SortedSet<int>();
        long answer = long.MaxValue;

        for (int i = 0; i < nums.Count; i++)
        {
            if (i >= x)
                eligible.Add(nums[i - x]);

            if (eligible.Count == 0)
                continue;

            int value = nums[i];

            SortedSet<int> lower = eligible.GetViewBetween(int.MinValue, value);
            if (lower.Count > 0)
                answer = Math.Min(answer, (long)value - lower.Max);

            SortedSet<int> upper = eligible.GetViewBetween(value, int.MaxValue);
            if (upper.Count > 0)
                answer = Math.Min(answer, (long)upper.Min - value);

            if (answer == 0)
                break;
        }

        Console.WriteLine(answer);
    }
}
