using System;

public class Program
{
    private const long Mod = 1000000007L;

    private struct Matrix
    {
        public long A00, A01, A10, A11;

        public Matrix(long a00, long a01, long a10, long a11)
        {
            A00 = a00;
            A01 = a01;
            A10 = a10;
            A11 = a11;
        }
    }

    private static Matrix Multiply(Matrix x, Matrix y)
    {
        return new Matrix(
            (x.A00 * y.A00 % Mod + x.A01 * y.A10 % Mod) % Mod,
            (x.A00 * y.A01 % Mod + x.A01 * y.A11 % Mod) % Mod,
            (x.A10 * y.A00 % Mod + x.A11 * y.A10 % Mod) % Mod,
            (x.A10 * y.A01 % Mod + x.A11 * y.A11 % Mod) % Mod
        );
    }

    private static Matrix Power(Matrix matrix, long exponent)
    {
        Matrix result = new Matrix(1, 0, 0, 1);

        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = Multiply(result, matrix);

            matrix = Multiply(matrix, matrix);
            exponent >>= 1;
        }

        return result;
    }

    private static int CountMatchingRotations(string s, string t)
    {
        int n = s.Length;
        int[] prefix = new int[n];

        for (int i = 1, j = 0; i < n; i++)
        {
            while (j > 0 && t[i] != t[j])
                j = prefix[j - 1];

            if (t[i] == t[j])
                j++;

            prefix[i] = j;
        }

        int matches = 0;
        int matched = 0;

        for (int i = 0; i < 2 * n - 1; i++)
        {
            char current = s[i % n];

            while (matched > 0 && current != t[matched])
                matched = prefix[matched - 1];

            if (current == t[matched])
                matched++;

            if (matched == n)
            {
                matches++;
                matched = prefix[matched - 1];
            }
        }

        return matches;
    }

    public static void Main()
    {
        string s = Console.ReadLine();
        string t = Console.ReadLine();
        long k = long.Parse(Console.ReadLine().Trim());

        int n = s.Length;
        int matchingRotations = CountMatchingRotations(s, t);
        int zeroRotationMatches = string.Equals(s, t, StringComparison.Ordinal) ? 1 : 0;

        Matrix transition = new Matrix(
            0,
            n - 1,
            1,
            n - 2
        );

        Matrix powered = Power(transition, k);

        long waysToZeroRotation = powered.A00;
        long waysToEachNonZeroRotation = powered.A10;

        long answer = 0;

        if (zeroRotationMatches == 1)
            answer = waysToZeroRotation;

        answer = (answer +
                  (long)(matchingRotations - zeroRotationMatches) *
                  waysToEachNonZeroRotation) % Mod;

        Console.WriteLine(answer);
    }
}
