        {
            Console.WriteLine(-1);
            return;
        }

        var values = new List<long>();
        foreach (Match match in matches)
            values.Add(long.Parse(match.Value));

        long target = values[values.Count - 1];
        long[] count = new long[64];
        long total = 0;

        for (int i = 0; i < values.Count - 1; i++)
        {
            long value = values[i];
            total += value;

            int bit = 0;
            while ((1L << bit) != value)
                bit++;

            count[bit]++;
        }

        if (total < target)
        {
            Console.WriteLine(-1);
            return;
        }

        int operations = 0;

        for (int bit = 0; bit <= 30; bit++)
        {
            if (((target >> bit) & 1L) != 0)
            {
                if (count[bit] > 0)
                {
                    count[bit]--;
                }
                else
                {
                    int higher = bit + 1;
                    while (higher < count.Length && count[higher] == 0)
                        higher++;

                    if (higher == count.Length)
                    {
                        Console.WriteLine(-1);
                        return;
                    }

                    while (higher > bit)
                    {
                        count[higher]--;
                        count[higher - 1] += 2;
                        higher--;
                        operations++;
                    }

                    count[bit]--;
                }
            }

            count[bit + 1] += count[bit] / 2;
        }

        Console.WriteLine(operations);
    }
