        string input = Console.In.ReadToEnd();
        List<long> values = ParseNumbers(input);

        if (values.Count < 2)
            return;

        int n = values.Count - 1;
        long k = values[values.Count - 1];

        int[] receiver = new int[n];
        for (int i = 0; i < n; i++)
            receiver[i] = (int)values[i];

        int levels = 0;
        long temp = k;
        while (temp > 0)
        {
            levels++;
            temp >>= 1;
        }

        int[][] jump = new int[levels][];
        long[][] sums = new long[levels][];

        jump[0] = new int[n];
        sums[0] = new long[n];

        for (int i = 0; i < n; i++)
        {
            jump[0][i] = receiver[i];
            sums[0][i] = receiver[i];
        }

        for (int level = 1; level < levels; level++)
        {
            jump[level] = new int[n];
            sums[level] = new long[n];

            int[] previousJump = jump[level - 1];
            long[] previousSums = sums[level - 1];

            for (int i = 0; i < n; i++)
            {
                int middle = previousJump[i];
                jump[level][i] = previousJump[middle];
                sums[level][i] = previousSums[i] + previousSums[middle];
            }
        }

        long answer = 0;

        for (int start = 0; start < n; start++)
        {
            int current = start;
            long total = start;
            long passes = k;
            int level = 0;

            while (passes > 0)
            {
                if ((passes & 1L) != 0)
                {
                    total += sums[level][current];
                    current = jump[level][current];
                }

                passes >>= 1;
                level++;
            }

            if (total > answer)
                answer = total;
        }

        Console.WriteLine(answer);
    }

    private static List<long> ParseNumbers(string input)
    {
        List<long> numbers = new List<long>();
        int i = 0;

        while (i < input.Length)
        {
            while (i < input.Length && !char.IsDigit(input[i]) && input[i] != '-')
                i++;

            if (i >= input.Length)
                break;

            bool negative = false;
            if (input[i] == '-')
            {
                negative = true;
                i++;
            }

            long value = 0;
            while (i < input.Length && char.IsDigit(input[i]))
            {
                value = value * 10 + (input[i] - '0');
                i++;
            }

            numbers.Add(negative ? -value : value);
        }

        return numbers;
    }
