        var mismatches = new List<int>();

        for (int i = 0; i < s1.Length; i++)
        {
            if (s1[i] != s2[i])
                mismatches.Add(i);
        }

        int count = mismatches.Count;

        if ((count & 1) != 0)
        {
            Console.WriteLine(-1);
            return;
        }

        if (count == 0)
        {
            Console.WriteLine(0);
            return;
        }

        long[] dp = new long[count + 1];
        dp[0] = 0;
        dp[1] = x;

        for (int i = 2; i <= count; i++)
        {
            long useArbitraryOperation = dp[i - 1] + x;
            long useAdjacentOperations =
                dp[i - 2] + 2L * (mismatches[i - 1] - mismatches[i - 2]);

            dp[i] = Math.Min(useArbitraryOperation, useAdjacentOperations);
        }

        Console.WriteLine(dp[count] / 2);
    }
