        {
            for (int j = n - 1; j >= 0; j--)
            {
                if (num[j] != ending[1])
                    continue;

                for (int i = j - 1; i >= 0; i--)
                {
                    if (num[i] == ending[0])
                    {
                        int deletions = (j - i - 1) + (n - j - 1);
                        answer = Math.Min(answer, deletions);
                    }
                }
            }
        }

        // Keeping any single zero also produces the special number 0.
        if (num.IndexOf('0') >= 0)
            answer = Math.Min(answer, n - 1);

        Console.WriteLine(answer);
    }
