        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        int n = tokens.Length;
        var sums = new Dictionary<int, long>();
        long answer = 0;

        for (int i = 1; i <= n; i++)
        {
            long value = long.Parse(tokens[i - 1]);
            int kernel = SquareFreeKernel(i);

            long current;
            sums.TryGetValue(kernel, out current);
            current += value;
            sums[kernel] = current;

            if (current > answer)
                answer = current;
        }

        Console.WriteLine(answer);
    }

    private static int SquareFreeKernel(int number)
    {
        int x = number;
        int kernel = 1;

        for (int prime = 2; prime * prime <= x; prime++)
        {
            int count = 0;
            while (x % prime == 0)
            {
                x /= prime;
                count++;
            }

            if ((count & 1) != 0)
                kernel *= prime;
        }

        if (x > 1)
            kernel *= x;

        return kernel;
    }
}
