using System;
using System.Collections.Generic;

public class Program
{
    private const int Mod = 1000000007;

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        if (tokens.Length < 3)
            return;

        int l = int.Parse(tokens[tokens.Length - 2]);
        int r = int.Parse(tokens[tokens.Length - 1]);

        var frequencies = new Dictionary<int, int>();
        int zeroCount = 0;

        for (int i = 0; i < tokens.Length - 2; i++)
        {
            int value = int.Parse(tokens[i]);

            if (value == 0)
            {
                zeroCount++;
            }
            else if (value <= r)
            {
                int count;
                frequencies.TryGetValue(value, out count);
                frequencies[value] = count + 1;
            }
        }

        int[] dp = new int[r + 1];
        dp[0] = (zeroCount + 1) % Mod;

        foreach (KeyValuePair<int, int> entry in frequencies)
        {
            int value = entry.Key;
            int count = entry.Value;
            int[] next = new int[r + 1];
            long removedOffset = (long)(count + 1) * value;

            for (int sum = 0; sum <= r; sum++)
            {
                long ways = dp[sum];

                if (sum >= value)
                    ways += next[sum - value];

                if (sum >= removedOffset)
                    ways -= dp[sum - (int)removedOffset];

                ways %= Mod;
                if (ways < 0)
                    ways += Mod;

                next[sum] = (int)ways;
            }

            dp = next;
        }

        long answer = 0;
        for (int sum = l; sum <= r; sum++)
        {
            answer += dp[sum];
            if (answer >= Mod)
                answer -= Mod;
        }

        Console.WriteLine(answer);
    }
}
