            if (value > target)
                continue;

            for (int sum = target; sum >= value; sum--)
            {
                if (dp[sum - value] != -1)
                    dp[sum] = Math.Max(dp[sum], dp[sum - value] + 1);
            }
        }

        Console.WriteLine(dp[target]);
