        long[] tasks = new long[4 * n];

        for (int i = 0; i < n; i++)
            processorTime[i] = values[i];

        for (int i = 0; i < tasks.Length; i++)
            tasks[i] = values[n + i];

        Array.Sort(processorTime);
        Array.Sort(tasks);

        long answer = 0;

        for (int i = 0; i < n; i++)
        {
            long longestTask = tasks[tasks.Length - 1 - 4 * i];
            long finishTime = processorTime[i] + longestTask;
            if (finishTime > answer)
                answer = finishTime;
        }

        Console.WriteLine(answer);
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public bool TryNextLong(out long value)
        {
            value = 0;
            int c;

            do
            {
                c = Read();
                if (c == -1)
                    return false;
            } while (c <= 32);

            bool negative = false;
            if (c == '-')
            {
                negative = true;
                c = Read();
            }

            while (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            if (negative)
