{
    const long Mod = 1000000007L;

    static List<int> ExtractIntegers(string text)
    {
        var values = new List<int>();
        foreach (Match match in Regex.Matches(text, @"-?\d+"))
            values.Add(int.Parse(match.Value));
        return values;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] rawLines = input.Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
        var lines = new List<string>();

        foreach (string line in rawLines)
        {
            if (!string.IsNullOrWhiteSpace(line))
                lines.Add(line.Trim());
        }

        if (lines.Count < 2)
            return;

        List<int> nums;
        int k;

        // Also supports the conventional format:
        // n
        // nums...
        // k
        if (lines.Count >= 3)
        {
            List<int> first = ExtractIntegers(lines[0]);
            List<int> second = ExtractIntegers(lines[1]);

            if (first.Count == 1 && first[0] == second.Count)
            {
                nums = second;
                k = ExtractIntegers(lines[2])[0];
            }
            else
            {
                nums = first;
                k = ExtractIntegers(lines[1])[0];
            }
        }
        else
        {
            nums = ExtractIntegers(lines[0]);
            k = ExtractIntegers(lines[1])[0];
        }

        int[] bitCounts = new int[31];

        foreach (int value in nums)
        {
            for (int bit = 0; bit < 31; bit++)
            {
                if ((value & (1 << bit)) != 0)
                    bitCounts[bit]++;
            }
        }

        long answer = 0;

        for (int i = 0; i < k; i++)
        {
            long value = 0;

            for (int bit = 0; bit < 31; bit++)
            {
                if (bitCounts[bit] > 0)
                {
                    value |= 1L << bit;
                    bitCounts[bit]--;
                }
            }

            answer = (answer + (value * value) % Mod) % Mod;
        }

        Console.WriteLine(answer);
    }
}
