    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public bool TryReadInt(out int value)
        {
            int c;
            do
            {
                c = ReadByte();
                if (c == -1)
                {
                    value = 0;
                    return false;
                }
            } while (c <= 32);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            int number = 0;
            while (c > 32 && c != -1)
            {
                number = number * 10 + (c - '0');
                c = ReadByte();
            }

            value = number * sign;
            return true;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        var frequencies = new Dictionary<int, int>();

        int value;
        while (scanner.TryReadInt(out value))
        {
            int count;
            if (frequencies.TryGetValue(value, out count))
                frequencies[value] = count + 1;
            else
                frequencies[value] = 1;
        }

        if (frequencies.Count == 0)
            return;

        int minimumFrequency = int.MaxValue;
        foreach (int count in frequencies.Values)
            minimumFrequency = Math.Min(minimumFrequency, count);

        for (int smallerGroupSize = minimumFrequency; smallerGroupSize >= 1; smallerGroupSize--)
        {
            int totalGroups = 0;
            bool valid = true;

            foreach (int count in frequencies.Values)
            {
                int groups = (count + smallerGroupSize) / (smallerGroupSize + 1);

                if (groups * smallerGroupSize > count)
                {
                    valid = false;
                    break;
                }

                totalGroups += groups;
            }

            if (valid)
            {
                Console.WriteLine(totalGroups);
                return;
            }
        }
    }
}
