            int sign = 1;
            if (input[i] == '-')
            {
                sign = -1;
                i++;
            }

            int value = 0;
            bool hasDigit = false;
            while (i < input.Length && char.IsDigit(input[i]))
            {
                value = value * 10 + (input[i] - '0');
                hasDigit = true;
                i++;
            }

            if (hasDigit)
                nums.Add(sign * value);
        }

        if (nums.Count < 3)
        {
            Console.WriteLine(-1);
            return;
        }

        int n = nums.Count;
        int[] rightMin = new int[n];
        rightMin[n - 1] = nums[n - 1];

        for (int j = n - 2; j >= 0; j--)
            rightMin[j] = Math.Min(nums[j], rightMin[j + 1]);

