using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<long> nums = ParseNumbers(input);

        int n = nums.Count;
        if (n == 0)
            return;

        long[] keys = new long[n];
        for (int i = 0; i < n; i++)
            keys[i] = nums[i] - i;

        long[] sorted = (long[])keys.Clone();
        Array.Sort(sorted);

        int uniqueCount = 0;
        for (int i = 0; i < n; i++)
        {
            if (i == 0 || sorted[i] != sorted[i - 1])
                sorted[uniqueCount++] = sorted[i];
        }

        long[] fenwick = new long[uniqueCount + 1];
        long answer = long.MinValue;

        for (int i = 0; i < n; i++)
        {
            int position = LowerBound(sorted, uniqueCount, keys[i]) + 1;
            long bestPrevious = Query(fenwick, position);
            long current = nums[i] + bestPrevious;

            Update(fenwick, position, current);

            if (current > answer)
                answer = current;
        }

        Console.WriteLine(answer);
    }

    private static int LowerBound(long[] array, int length, long value)
    {
        int left = 0;
        int right = length;

        while (left < right)
        {
            int middle = left + (right - left) / 2;
            if (array[middle] < value)
                left = middle + 1;
            else
                right = middle;
        }

        return left;
    }

    private static long Query(long[] fenwick, int index)
    {
        long result = 0;

        while (index > 0)
        {
            if (fenwick[index] > result)
                result = fenwick[index];
            index -= index & -index;
        }

        return result;
    }

    private static void Update(long[] fenwick, int index, long value)
    {
        while (index < fenwick.Length)
        {
            if (value > fenwick[index])
                fenwick[index] = value;
            index += index & -index;
        }
    }

    private static List<long> ParseNumbers(string input)
    {
        List<long> numbers = new List<long>();
        int i = 0;

        while (i < input.Length)
        {
            while (i < input.Length && input[i] != '-' &&
                   (input[i] < '0' || input[i] > '9'))
            {
                i++;
            }

            if (i >= input.Length)
                break;

            bool negative = false;
            if (input[i] == '-')
            {
                negative = true;
                i++;
            }

            long value = 0;
            bool hasDigit = false;

            while (i < input.Length && input[i] >= '0' && input[i] <= '9')
            {
                hasDigit = true;
                value = value * 10 + (input[i] - '0');
                i++;
            }

            if (hasDigit)
                numbers.Add(negative ? -value : value);
        }

        return numbers;
