using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    public static void Main()
    {
        List<long> values = ReadAllNumbers();
        if (values.Count < 2)
            return;

        long k = values[values.Count - 1];
        int n = values.Count - 1;
        long[] nums = new long[n];

        for (int i = 0; i < n; i++)
            nums[i] = values[i];

        Array.Sort(nums);

        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++)
            prefix[i + 1] = prefix[i] + nums[i];

        int answer = 1;
        int left = 0;

        for (int right = 0; right < n; right++)
        {
            while (left <= right && GetCost(nums, prefix, left, right) > k)
                left++;

            answer = Math.Max(answer, right - left + 1);
        }

        Console.WriteLine(answer);
    }

    private static long GetCost(long[] nums, long[] prefix, int left, int right)
    {
        int middle = (left + right) / 2;
        long median = nums[middle];

        long leftCost =
            median * (middle - left) -
            (prefix[middle] - prefix[left]);

        long rightCost =
            (prefix[right + 1] - prefix[middle + 1]) -
            median * (right - middle);

        return leftCost + rightCost;
    }

    private static List<long> ReadAllNumbers()
    {
        List<long> numbers = new List<long>();
        string input = Console.In.ReadToEnd();

        int i = 0;
        while (i < input.Length)
        {
            while (i < input.Length &&
                   !char.IsDigit(input[i]) &&
                   input[i] != '-')
            {
                i++;
            }

            if (i >= input.Length)
                break;

            bool negative = false;
            if (input[i] == '-')
            {
                negative = true;
                i++;
            }

            long value = 0;
            bool hasDigit = false;

            while (i < input.Length && char.IsDigit(input[i]))
            {
                hasDigit = true;
                value = value * 10 + (input[i] - '0');
                i++;
            }

            if (hasDigit)
                numbers.Add(negative ? -value : value);
        }

        return numbers;
    }
