public class Program
{
    private const long Mod = 1000000007L;

    private static long ModPow(long value, int exponent)
    {
        long result = 1;
        value %= Mod;

        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * value % Mod;

            value = value * value % Mod;
            exponent >>= 1;
        }

        return result;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        int n = 0;

        foreach (char c in input)
        {
            if (c >= '0' && c <= '9')
                n = n * 10 + (c - '0');
        }

        long answer = ModPow(26, n);
        answer -= 3L * ModPow(25, n) % Mod;
        answer -= (long)n * ModPow(25, n - 1) % Mod;
        answer += 3L * ModPow(24, n) % Mod;
        answer += 2L * n % Mod * ModPow(24, n - 1) % Mod;
        answer -= ModPow(23, n);
        answer -= (long)n * ModPow(23, n - 1) % Mod;

        answer %= Mod;
        if (answer < 0)
            answer += Mod;

        Console.WriteLine(answer);
    }
}
