using System;
using System.IO;
using System.Text;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }

            return buffer[position++];
        }

        public string Next()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            if (c == -1) return null;

            StringBuilder sb = new StringBuilder();
            while (c > 32 && c != -1)
            {
                sb.Append((char)c);
                c = Read();
            }

            return sb.ToString();
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value * sign;
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();
        string s = scanner.Next();
        if (s == null) return;

        int n = s.Length;
        int half = n / 2;

        // left[i] = s[i]
        // right[i] = s[n - 1 - i]
        int[] leftPrefix = new int[(half + 1) * 26];
        int[] rightPrefix = new int[(half + 1) * 26];
        int[] mismatchPrefix = new int[half + 1];

        for (int i = 0; i < half; i++)
        {
            int previous = i * 26;
            int current = (i + 1) * 26;

            for (int ch = 0; ch < 26; ch++)
            {
                leftPrefix[current + ch] = leftPrefix[previous + ch];
                rightPrefix[current + ch] = rightPrefix[previous + ch];
            }

            char leftChar = s[i];
            char rightChar = s[n - 1 - i];

            leftPrefix[current + leftChar - 'a']++;
            rightPrefix[current + rightChar - 'a']++;

            mismatchPrefix[i + 1] = mismatchPrefix[i] +
                                      (leftChar == rightChar ? 0 : 1);
        }

        int queryCount = scanner.NextInt();
        StringBuilder output = new StringBuilder();

        for (int query = 0; query < queryCount; query++)
        {
            int a = scanner.NextInt();
            int b = scanner.NextInt();
            int c = scanner.NextInt();
            int d = scanner.NextInt();

            // Map the interval in the original right half into the reversed half.
            int left2 = n - 1 - d;
            int right2 = n - 1 - c;

            int intersectionLeft = Math.Max(a, left2);
            int intersectionRight = Math.Min(b, right2);
            bool intersects = intersectionLeft <= intersectionRight;

            int mismatchInFirst =
                mismatchPrefix[b + 1] - mismatchPrefix[a];
            int mismatchInSecond =
                mismatchPrefix[right2 + 1] - mismatchPrefix[left2];
            int mismatchInIntersection = intersects
                ? mismatchPrefix[intersectionRight + 1] -
                  mismatchPrefix[intersectionLeft]
                : 0;

            int mismatchInUnion =
                mismatchInFirst + mismatchInSecond - mismatchInIntersection;

            bool possible = mismatchPrefix[half] == mismatchInUnion;

            if (possible)
            {
                int aStart = a * 26;
                int aEnd = (b + 1) * 26;
                int jStart = left2 * 26;
                int jEnd = (right2 + 1) * 26;

                int intersectionStart = intersects
                    ? intersectionLeft * 26
                    : 0;
                int intersectionEnd = intersects
                    ? (intersectionRight + 1) * 26
                    : 0;

                for (int ch = 0; ch < 26; ch++)
                {
                    int availableLeft =
                        leftPrefix[aEnd + ch] - leftPrefix[aStart + ch];

                    int availableRight =
                        rightPrefix[jEnd + ch] - rightPrefix[jStart + ch];

                    int rightInFirst =
                        rightPrefix[aEnd + ch] - rightPrefix[aStart + ch];

                    int leftInSecond =
                        leftPrefix[jEnd + ch] - leftPrefix[jStart + ch];

                    int rightInIntersection = intersects
                        ? rightPrefix[intersectionEnd + ch] -
                          rightPrefix[intersectionStart + ch]
                        : 0;

                    int leftInIntersection = intersects
                        ? leftPrefix[intersectionEnd + ch] -
                          leftPrefix[intersectionStart + ch]
                        : 0;

                    // Fixed characters that must be supplied outside the overlap.
                    int requiredFromLeft =
                        rightInFirst - rightInIntersection;
                    int requiredFromRight =
                        leftInSecond - leftInIntersection;

                    int remainingLeft = availableLeft - requiredFromLeft;
                    int remainingRight = availableRight - requiredFromRight;

                    if (remainingLeft < 0 ||
                        remainingRight < 0 ||
                        remainingLeft != remainingRight)
                    {
                        possible = false;
                        break;
                    }
                }
            }

            if (query > 0) output.Append(' ');
            output.Append(possible ? "true" : "false");
        }

        Console.WriteLine(output.ToString());
    }
}
