using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public bool TryReadLong(out long value)
        {
            value = 0;
            int c;
            do
            {
                c = Read();
                if (c == -1)
                    return false;
            } while ((c < '0' || c > '9') && c != '-');

            bool negative = false;
            if (c == '-')
            {
                negative = true;
                c = Read();
            }

            while (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            if (negative)
                value = -value;

            return true;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        var nums = new List<long>();
        long value;

        while (scanner.TryReadLong(out value))
            nums.Add(value);

        int n = nums.Count;
        if (n == 0)
        {
            Console.WriteLine(0);
            return;
        }

        long[] prefix = new long[n + 1];
        long[] lastSum = new long[n + 1];
        int[] dp = new int[n + 1];
        int[] deque = new int[n + 1];

        for (int i = 1; i <= n; i++)
            prefix[i] = prefix[i - 1] + nums[i - 1];

        int head = 0;
        int tail = 1;
        deque[0] = 0;

        for (int i = 1; i <= n; i++)
        {
            while (head + 1 < tail)
            {
                int next = deque[head + 1];
                if (prefix[next] + lastSum[next] > prefix[i])
                    break;
                head++;
            }

            int previous = deque[head];
            dp[i] = dp[previous] + 1;
            lastSum[i] = prefix[i] - prefix[previous];

            long threshold = prefix[i] + lastSum[i];

            while (head < tail)
            {
                int back = deque[tail - 1];
                if (prefix[back] + lastSum[back] < threshold)
                    break;
                tail--;
            }

            deque[tail++] = i;
        }

        Console.WriteLine(dp[n]);
    }
}
