    private static List<int> ParseIntegers(string line)
    {
        var numbers = new List<int>();
        long value = 0;
        bool reading = false;

        for (int i = 0; i <= line.Length; i++)
        {
            char c = i < line.Length ? line[i] : ' ';

            if (c >= '0' && c <= '9')
            {
