            int end = start;

            while (end + 1 < n &&
                   (long)items[end + 1].Value - items[end].Value <= limit)
            {
                end++;
            }

            int length = end - start + 1;
            int[] indices = new int[length];

            for (int i = 0; i < length; i++)
                indices[i] = items[start + i].Index;

            Array.Sort(indices);

            for (int i = 0; i < length; i++)
                result[indices[i]] = items[start + i].Value;

            start = end + 1;
        }

        var output = new StringBuilder();

        for (int i = 0; i < n; i++)
        {
            if (i > 0)
                output.Append(' ');

            output.Append(result[i]);
        }

