using System.IO;

public class Program
{
    const long Mod = 1000000007L;

    static long ModPow(long value, long exponent)
    {
        long result = 1;
        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * value % Mod;

            value = value * value % Mod;
            exponent >>= 1;
        }
        return result;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        if (tokens.Length < 2)
            return;

        int n = int.Parse(tokens[0]);
        int sickCount = tokens.Length - 1;
        int[] sick = new int[sickCount];

        for (int i = 0; i < sickCount; i++)
            sick[i] = int.Parse(tokens[i + 1]);

        int healthyCount = n - sickCount;

        long[] factorial = new long[healthyCount + 1];
        long[] inverseFactorial = new long[healthyCount + 1];

        factorial[0] = 1;
        for (int i = 1; i <= healthyCount; i++)
            factorial[i] = factorial[i - 1] * i % Mod;

        inverseFactorial[healthyCount] =
            ModPow(factorial[healthyCount], Mod - 2);

        for (int i = healthyCount; i > 0; i--)
            inverseFactorial[i - 1] = inverseFactorial[i] * i % Mod;

        long answer = factorial[healthyCount];

        int leftGap = sick[0];
        answer = answer * inverseFactorial[leftGap] % Mod;

        int rightGap = n - 1 - sick[sickCount - 1];
        answer = answer * inverseFactorial[rightGap] % Mod;

        for (int i = 1; i < sickCount; i++)
        {
            int gap = sick[i] - sick[i - 1] - 1;
            answer = answer * inverseFactorial[gap] % Mod;

            if (gap > 0)
                answer = answer * ModPow(2, gap - 1) % Mod;
        }

        Console.WriteLine(answer);
    }
}
