        int n = scanner.NextInt();
        int total = n * n;
        bool[] seen = new bool[total + 1];
        int repeated = -1;

        for (int i = 0; i < total; i++)
        {
            int value = scanner.NextInt();
            if (seen[value])
                repeated = value;
            else
                seen[value] = true;
        }

        int missing = -1;
        for (int value = 1; value <= total; value++)
        {
            if (!seen[value])
            {
                missing = value;
                break;
            }
        }

        Console.WriteLine(repeated + " " + missing);
    }
