using System;
using System.Collections.Generic;

public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<int> values = ParseIntegers(input);

        if (values.Count == 0)
            return;

        int[] nums = values.ToArray();
        Array.Sort(nums);

        int median = nums[nums.Length / 2];
        List<int> palindromes = GeneratePalindromes();

        int index = LowerBound(palindromes, median);
        long answer = long.MaxValue;

        if (index < palindromes.Count)
            answer = Math.Min(answer, CalculateCost(nums, palindromes[index]));

        if (index > 0)
            answer = Math.Min(answer, CalculateCost(nums, palindromes[index - 1]));

        Console.WriteLine(answer);
    }

    private static List<int> ParseIntegers(string input)
    {
        List<int> result = new List<int>();
        int i = 0;

        while (i < input.Length)
        {
            while (i < input.Length && !char.IsDigit(input[i]) && input[i] != '-')
                i++;

            if (i >= input.Length)
                break;

            int sign = 1;
            if (input[i] == '-')
            {
                sign = -1;
                i++;
                if (i >= input.Length || !char.IsDigit(input[i]))
                    continue;
            }

            int value = 0;
            while (i < input.Length && char.IsDigit(input[i]))
            {
                value = value * 10 + (input[i] - '0');
                i++;
            }

            result.Add(value * sign);
        }

        return result;
    }

    private static List<int> GeneratePalindromes()
    {
        List<int> palindromes = new List<int>();

        for (int seed = 1; seed <= 99999; seed++)
        {
            long odd = MakePalindrome(seed, true);
            if (odd < 1000000000L)
                palindromes.Add((int)odd);

            long even = MakePalindrome(seed, false);
            if (even < 1000000000L)
                palindromes.Add((int)even);
        }

        palindromes.Sort();
        return palindromes;
    }

    private static long MakePalindrome(int seed, bool oddLength)
    {
        long result = seed;
        int remaining = oddLength ? seed / 10 : seed;

        while (remaining > 0)
        {
            result = result * 10 + remaining % 10;
            remaining /= 10;
        }

        return result;
    }

    private static int LowerBound(List<int> values, int target)
    {
        int left = 0;
        int right = values.Count;

        while (left < right)
        {
            int middle = left + (right - left) / 2;
            if (values[middle] < target)
                left = middle + 1;
            else
                right = middle;
        }

        return left;
    }

    private static long CalculateCost(int[] nums, int target)
    {
        long cost = 0;

        for (int i = 0; i < nums.Length; i++)
            cost += Math.Abs((long)nums[i] - target);

        return cost;
    }
}
