using System;

public class Program
{
    private static int n;
    private static int k;
    private static int[] nextPosition;
    private static byte[] characterOrder;
    private static int[] normalPartitions;

    private static int FindOverflow(int start, int mask, int distinctCount)
    {
        int needed = k - distinctCount + 1;
        if (needed > 26 - distinctCount)
            return n;

        int row = start * 26;

        for (int i = 0; i < 26; i++)
        {
            int ch = characterOrder[row + i];
            int bit = 1 << ch;

            if ((mask & bit) != 0)
                continue;

            needed--;
            if (needed == 0)
                return nextPosition[row + ch];
        }

        return n;
    }

    private static int PartitionsWithCurrentSegment(int start, int mask, int distinctCount)
    {
        int overflow = FindOverflow(start, mask, distinctCount);
        return overflow == n ? 1 : 1 + normalPartitions[overflow];
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        if (tokens.Length < 2)
            return;

        string s = tokens[0];
        k = int.Parse(tokens[1]);
        n = s.Length;

        int rows = n + 1;
        nextPosition = new int[rows * 26];
        characterOrder = new byte[rows * 26];
        normalPartitions = new int[rows];

        int lastRow = n * 26;
        for (int c = 0; c < 26; c++)
        {
            nextPosition[lastRow + c] = n;
            characterOrder[lastRow + c] = (byte)c;
        }

        for (int i = n - 1; i >= 0; i--)
        {
            int currentRow = i * 26;
            int followingRow = (i + 1) * 26;
            int currentChar = s[i] - 'a';

            for (int c = 0; c < 26; c++)
                nextPosition[currentRow + c] = nextPosition[followingRow + c];

            nextPosition[currentRow + currentChar] = i;

            int index = 0;
            characterOrder[currentRow + index++] = (byte)currentChar;

            for (int j = 0; j < 26; j++)
            {
                byte c = characterOrder[followingRow + j];
                if (c != currentChar)
                    characterOrder[currentRow + index++] = c;
            }
        }

        normalPartitions[n] = 0;

        for (int i = n - 1; i >= 0; i--)
        {
            int overflow = n;

            if (k < 26)
            {
                int row = i * 26;
                int overflowChar = characterOrder[row + k];
                overflow = nextPosition[row + overflowChar];
            }

            normalPartitions[i] =
                overflow == n ? 1 : 1 + normalPartitions[overflow];
        }

        int answer = normalPartitions[0];
        int completedPartitions = 0;
        int prefixMask = 0;
        int prefixDistinct = 0;

        for (int i = 0; i < n; i++)
        {
            for (int replacement = 0; replacement < 26; replacement++)
            {
                int bit = 1 << replacement;
                bool alreadyPresent = (prefixMask & bit) != 0;
                int newDistinct = prefixDistinct + (alreadyPresent ? 0 : 1);
                int candidate;

                if (newDistinct > k)
                {
                    candidate = completedPartitions + 1
                        + PartitionsWithCurrentSegment(i + 1, bit, 1);
                }
                else
                {
                    candidate = completedPartitions
                        + PartitionsWithCurrentSegment(
                            i + 1,
                            prefixMask | bit,
                            newDistinct);
                }

                if (candidate > answer)
                    answer = candidate;
            }

            int originalBit = 1 << (s[i] - 'a');

            if ((prefixMask & originalBit) == 0)
            {
                if (prefixDistinct == k)
                {
                    completedPartitions++;
                    prefixMask = originalBit;
                    prefixDistinct = 1;
                }
                else
                {
                    prefixMask |= originalBit;
                    prefixDistinct++;
                }
            }
        }

        Console.WriteLine(answer);
    }
}
