using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private static long ModPow(long baseValue, long exponent, long modulus)
    {
        if (modulus == 1)
            return 0;

        long result = 1 % modulus;
        baseValue %= modulus;

        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = (result * baseValue) % modulus;

            baseValue = (baseValue * baseValue) % modulus;
            exponent >>= 1;
        }

        return result;
    }

    public static void Main()
    {
        var input = new FastScanner(Console.OpenStandardInput());
        int n = input.NextInt();
        var goodIndices = new List<int>();

        for (int i = 0; i < n; i++)
        {
            int a = input.NextInt();
            int b = input.NextInt();
            int c = input.NextInt();
            int m = input.NextInt();

            long firstPower = ModPow(a, b, 10);
            long value = ModPow(firstPower, c, m);

            // Store values temporarily because target is read after all rows.
            input.Values[i] = value;
        }

        int target = input.NextInt();

        for (int i = 0; i < n; i++)
        {
            if (input.Values[i] == target)
                goodIndices.Add(i);
        }

        Console.WriteLine(string.Join(" ", goodIndices));
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public long[] Values { get; } = new long[101];

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int character;
            do
            {
                character = Read();
            } while (character <= 32 && character != -1);

            int sign = 1;
            if (character == '-')
            {
                sign = -1;
                character = Read();
            }

            int value = 0;
            while (character > 32 && character != -1)
            {
                value = value * 10 + character - '0';
                character = Read();
            }

            return value * sign;
        }
    }
