        string source = tokens[0];
        string target = tokens[1];

        int operationCount = (tokens.Length - 2) / 3;
        int originalStart = 2;
        int changedStart = originalStart + operationCount;
        int costStart = changedStart + operationCount;

        const long INF = long.MaxValue / 4;
        long[,] distance = new long[26, 26];

        for (int i = 0; i < 26; i++)
        {
            for (int j = 0; j < 26; j++)
                distance[i, j] = i == j ? 0 : INF;
        }

        for (int i = 0; i < operationCount; i++)
        {
            int from = tokens[originalStart + i][0] - 'a';
            int to = tokens[changedStart + i][0] - 'a';
            long cost = long.Parse(tokens[costStart + i]);

            if (cost < distance[from, to])
                distance[from, to] = cost;
        }

        for (int k = 0; k < 26; k++)
        {
            for (int i = 0; i < 26; i++)
            {
                if (distance[i, k] == INF)
                    continue;

                for (int j = 0; j < 26; j++)
                {
                    if (distance[k, j] == INF)
                        continue;

                    long candidate = distance[i, k] + distance[k, j];
                    if (candidate < distance[i, j])
                        distance[i, j] = candidate;
                }
            }
