using System;

public class Program
{
    static long CountPrice(long num, int x, long limit)
    {
        long count = 0;
        long totalNumbers = num + 1; // Includes 0, which contributes nothing.

        for (int position = x; position <= 62; position += x)
        {
            long bit = 1L << (position - 1);

            if (bit > num)
                break;

            long cycle = bit * 2;
            long fullCycles = totalNumbers / cycle;
            long remainder = totalNumbers % cycle;

            long ones = fullCycles * bit;
            if (remainder > bit)
                ones += remainder - bit;

            count += ones;
            if (count > limit)
                return limit + 1;
        }

        return count;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] parts = input.Split(
            new char[] { ' ', '\t', '\r', '\n', ',', '=' },
            StringSplitOptions.RemoveEmptyEntries
        );

        long k = 0;
        int x = 0;
        int found = 0;

        foreach (string part in parts)
        {
            long value;
            if (long.TryParse(part, out value))
            {
                if (found == 0)
                    k = value;
                else
                {
                    x = (int)value;
                    break;
                }
                found++;
            }
        }

        long low = 0;
        long high = 1;

        while (CountPrice(high, x, k) <= k)
            high *= 2;

        while (low + 1 < high)
        {
            long mid = low + (high - low) / 2;

            if (CountPrice(mid, x, k) <= k)
                low = mid;
            else
                high = mid;
        }

        Console.WriteLine(low);
    }
}
