using System;

public class Program
{
    public static void Main()
    {
        string[] input = Console.In.ReadToEnd()
            .Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        long start = long.Parse(input[0]);
        long finish = long.Parse(input[1]);
        int limit = int.Parse(input[2]);
        string suffix = input[3];

        long answer = CountUpTo(finish, limit, suffix)
                    - CountUpTo(start - 1, limit, suffix);

        Console.WriteLine(answer);
    }

    private static long CountUpTo(long bound, int limit, string suffix)
    {
        if (bound <= 0)
            return 0;

        string upper = bound.ToString();
        int suffixLength = suffix.Length;
        long total = 0;

        for (int length = suffixLength; length <= upper.Length; length++)
        {
            string lengthUpper = length == upper.Length
                ? upper
                : new string('9', length);

            long[] dp = new long[2];
            dp[1] = 1;

            for (int position = 0; position < length; position++)
            {
                long[] next = new long[2];
                int upperDigit = lengthUpper[position] - '0';
                bool isSuffixPosition = position >= length - suffixLength;

                for (int tight = 0; tight <= 1; tight++)
                {
                    if (dp[tight] == 0)
                        continue;

                    int maximum = tight == 1 ? upperDigit : 9;

                    if (isSuffixPosition)
                    {
                        int digit = suffix[position - (length - suffixLength)] - '0';

                        if (digit <= limit &&
                            digit <= maximum &&
                            !(position == 0 && digit == 0))
                        {
                            int nextTight = tight == 1 && digit == upperDigit ? 1 : 0;
                            next[nextTight] += dp[tight];
                        }
                    }
                    else
                    {
                        int minimum = position == 0 ? 1 : 0;
                        int lastDigit = Math.Min(limit, maximum);

                        for (int digit = minimum; digit <= lastDigit; digit++)
                        {
                            int nextTight = tight == 1 && digit == upperDigit ? 1 : 0;
                            next[nextTight] += dp[tight];
                        }
                    }
                }

                dp = next;
            }

            total += dp[0] + dp[1];
        }

        return total;
    }
}
