    private static bool MatchesAt(string s, string pattern, int index)
    {
        if (index + pattern.Length > s.Length)
            return false;

        for (int i = 0; i < pattern.Length; i++)
        {
            if (s[index + i] != pattern[i])
                return false;
        }

        return true;
    }

    private static List<int> FindOccurrences(string s, string pattern)
    {
        var occurrences = new List<int>();

        for (int i = 0; i + pattern.Length <= s.Length; i++)
        {
            if (MatchesAt(s, pattern, i))
                occurrences.Add(i);
        }

        return occurrences;
    }

    public static void Main()
    {
        string s = Console.ReadLine();
        string a = Console.ReadLine();
        string b = Console.ReadLine();
        int k = int.Parse(Console.ReadLine());

        List<int> aIndices = FindOccurrences(s, a);
        List<int> bIndices = FindOccurrences(s, b);
        var result = new List<int>();

        int bPointer = 0;

        foreach (int i in aIndices)
        {
            while (bPointer < bIndices.Count && bIndices[bPointer] < i - k)
                bPointer++;

            if (bPointer < bIndices.Count && bIndices[bPointer] <= i + k)
                result.Add(i);
        }

