public class Program
{
    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int previous;
        if (!scanner.TryNextInt(out previous))
            return;

        int xor = 0;
        int current;

        // The final input value is k; all preceding values are nums.
        while (scanner.TryNextInt(out current))
        {
            xor ^= previous;
            previous = current;
        }

        int difference = xor ^ previous;
        int operations = 0;

        while (difference != 0)
        {
            difference &= difference - 1;
            operations++;
        }

        Console.WriteLine(operations);
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public bool TryNextInt(out int value)
        {
            int c;
            do
            {
                c = Read();
                if (c == -1)
                {
                    value = 0;
                    return false;
                }
            }
            while (c <= 32);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int result = 0;
            while (c > 32 && c != -1)
            {
                result = result * 10 + (c - '0');
                c = Read();
            }

            value = result * sign;
            return true;
        }
    }
}
