using System;
using System.Collections.Generic;

public class Program
{
    private const int AllBits = (1 << 30) - 1;

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<int> values = ParseIntegers(input);

        if (values.Count < 2)
            return;

        int k = values[values.Count - 1];
        int n = values.Count - 1;
        int[] nums = new int[n];

        for (int i = 0; i < n; i++)
            nums[i] = values[i];

        int requiredGroups = n - k;
        int forbiddenMask = 0;
        int answer = 0;

        for (int bit = 29; bit >= 0; bit--)
        {
            int bitValue = 1 << bit;
            int trialMask = forbiddenMask | bitValue;

            if (CanAvoidBits(nums, requiredGroups, trialMask))
                forbiddenMask = trialMask;
            else
                answer |= bitValue;
        }

        Console.WriteLine(answer);
    }

    private static bool CanAvoidBits(int[] nums, int requiredGroups, int forbiddenMask)
    {
        int currentAnd = AllBits;
        int groups = 0;

        for (int i = 0; i < nums.Length; i++)
        {
            currentAnd &= nums[i];

            if ((currentAnd & forbiddenMask) == 0)
            {
                groups++;
                currentAnd = AllBits;

                if (groups >= requiredGroups)
                    return true;
            }
        }

        return false;
    }

    private static List<int> ParseIntegers(string input)
    {
        List<int> result = new List<int>();
        int i = 0;

        while (i < input.Length)
        {
            while (i < input.Length && !char.IsDigit(input[i]) && input[i] != '-')
                i++;

            if (i >= input.Length)
                break;

            int sign = 1;
            if (input[i] == '-')
            {
                sign = -1;
                i++;
            }

            int value = 0;
            bool hasDigit = false;

            while (i < input.Length && char.IsDigit(input[i]))
            {
                hasDigit = true;
                value = value * 10 + (input[i] - '0');
                i++;
            }

            if (hasDigit)
                result.Add(value * sign);
        }

        return result;
    }
}
