    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<long> values = ParseNumbers(input);

        if (values.Count < 3)
        {
            Console.WriteLine(0);
            return;
        }

        long k = values[values.Count - 1];
        int n = values.Count - 1;

        var minPrefixByValue = new Dictionary<long, long>();
        long prefixSum = 0;
        long best = long.MinValue;
        bool found = false;

        for (int i = 0; i < n; i++)
        {
            long current = values[i];
            long minimumPrefix;

            if (minPrefixByValue.TryGetValue(current - k, out minimumPrefix))
            {
                long candidate = prefixSum + current - minimumPrefix;
                if (!found || candidate > best)
                    best = candidate;
                found = true;
            }

            if (minPrefixByValue.TryGetValue(current + k, out minimumPrefix))
            {
                long candidate = prefixSum + current - minimumPrefix;
                if (!found || candidate > best)
                    best = candidate;
                found = true;
            }

            long existingPrefix;
            if (!minPrefixByValue.TryGetValue(current, out existingPrefix) ||
                prefixSum < existingPrefix)
            {
                minPrefixByValue[current] = prefixSum;
            }

            prefixSum += current;
        }

        Console.WriteLine(found ? best : 0);
    }

    private static List<long> ParseNumbers(string input)
    {
        var numbers = new List<long>();
        int i = 0;

        while (i < input.Length)
        {
            while (i < input.Length &&
                   input[i] != '-' &&
                   (input[i] < '0' || input[i] > '9'))
            {
                i++;
            }

            if (i >= input.Length)
                break;

            bool negative = false;
            if (input[i] == '-')
            {
                negative = true;
                i++;
            }

            long value = 0;
            bool hasDigit = false;

            while (i < input.Length && input[i] >= '0' && input[i] <= '9')
            {
                value = value * 10 + (input[i] - '0');
                hasDigit = true;
                i++;
            }

            if (hasDigit)
                numbers.Add(negative ? -value : value);
        }

        return numbers;
    }
}
