    private static int PopCount(int value)
    {
        int count = 0;
        while (value > 0)
        {
            count += value & 1;
            value >>= 1;
        }
        return count;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        MatchCollection matches = Regex.Matches(input, @"\d+");

        var nums = new List<int>();
        foreach (Match match in matches)
            nums.Add(int.Parse(match.Value));

        int previousGroupMax = int.MinValue;
        int index = 0;

        while (index < nums.Count)
        {
            int bits = PopCount(nums[index]);
            int groupMin = nums[index];
            int groupMax = nums[index];

            int next = index + 1;
            while (next < nums.Count && PopCount(nums[next]) == bits)
            {
                groupMin = Math.Min(groupMin, nums[next]);
                groupMax = Math.Max(groupMax, nums[next]);
                next++;
            }

            if (groupMin < previousGroupMax)
            {
                Console.WriteLine("false");
                return;
            }

            previousGroupMax = groupMax;
            index = next;
        }

        Console.WriteLine("true");
    }
