    static long[] nums;
    static int[] changeIndices;
    static int n;
    static int m;

    static long[] ParseLongArray(string line)
    {
        MatchCollection matches = Regex.Matches(line, @"-?\d+");
        long[] result = new long[matches.Count];

        for (int i = 0; i < matches.Count; i++)
            result[i] = long.Parse(matches[i].Value);

        return result;
    }

    static bool CanMarkAll(int seconds)
    {
        if (seconds < n)
            return false;

        int[] lastOccurrence = new int[n];
        for (int i = 0; i < n; i++)
            lastOccurrence[i] = -1;

        for (int second = 0; second < seconds; second++)
            lastOccurrence[changeIndices[second]] = second;

        for (int i = 0; i < n; i++)
        {
            if (lastOccurrence[i] == -1)
                return false;
        }

        long availableSeconds = 0;
        int marked = 0;

        for (int second = 0; second < seconds; second++)
        {
            int index = changeIndices[second];

            if (lastOccurrence[index] == second)
            {
                if (nums[index] > availableSeconds)
                    return false;

                availableSeconds -= nums[index];
                marked++;
            }
            else
            {
                availableSeconds++;
            }
        }

        return marked == n;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] rawLines = input.Split(new[] { '\r', '\n' },
                                        StringSplitOptions.RemoveEmptyEntries);
        List<string> lines = new List<string>();

        foreach (string line in rawLines)
        {
            if (!string.IsNullOrWhiteSpace(line))
                lines.Add(line.Trim());
        }

        if (lines.Count < 2)
            return;

        nums = ParseLongArray(lines[0]);
        long[] changes = ParseLongArray(lines[1]);

        n = nums.Length;
        m = changes.Length;
        changeIndices = new int[m];

        for (int i = 0; i < m; i++)
            changeIndices[i] = (int)changes[i] - 1;

        int left = 1;
        int right = m;
        int answer = -1;

        while (left <= right)
        {
            int middle = left + (right - left) / 2;

            if (CanMarkAll(middle))
            {
                answer = middle;
                right = middle - 1;
            }
            else
            {
                left = middle + 1;
            }
        }

        Console.WriteLine(answer);
    }
}
