using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public bool TryReadLong(out long value)
        {
            value = 0;
            int c;
            do
            {
                c = ReadByte();
                if (c == -1) return false;
            }
            while (c < '0' || c > '9');

            do
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            while (c >= '0' && c <= '9');

            return true;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        var counts = new Dictionary<long, int>();
        long value;

        while (scanner.TryReadLong(out value))
        {
            int count;
            counts.TryGetValue(value, out count);
            counts[value] = count + 1;
        }

        int answer = 0;

        int ones;
        if (counts.TryGetValue(1, out ones))
            answer = (ones % 2 == 1) ? ones : ones - 1;

        foreach (var entry in counts)
        {
            long current = entry.Key;
            if (current == 1) continue;

            int pairLevels = 0;
            int count;

            while (counts.TryGetValue(current, out count) && count >= 2)
            {
                pairLevels++;
                current *= current;
            }

            int length;
            if (counts.TryGetValue(current, out count) && count >= 1)
                length = pairLevels * 2 + 1;
            else
                length = pairLevels * 2 - 1;

            if (length > answer)
                answer = length;
        }

        Console.WriteLine(answer);
    }
}
