using System;
using System.IO;
using System.Text;

public class Program
{
    private static string ReadNonEmptyLine(StreamReader reader)
    {
        string line;
        while ((line = reader.ReadLine()) != null)
        {
            if (!string.IsNullOrWhiteSpace(line))
                return line;
        }
        return null;
    }

    private static int[] ParseInts(string line)
    {
        string[] parts = line.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);
        int[] values = new int[parts.Length];
        for (int i = 0; i < parts.Length; i++)
            values[i] = int.Parse(parts[i]);
        return values;
    }

    public static void Main()
    {
        StreamReader reader = new StreamReader(Console.OpenStandardInput());

        string numsLine = ReadNonEmptyLine(reader);
        if (numsLine == null)
            return;

        int[] nums = ParseInts(numsLine);
        int n = nums.Length;

        string queryCountLine = ReadNonEmptyLine(reader);
        if (queryCountLine == null)
            return;

        int m = int.Parse(queryCountLine.Trim());

        int[] order = new int[n];
        for (int i = 0; i < n; i++)
            order[i] = i;

        Array.Sort(order, delegate(int a, int b)
        {
            int comparison = nums[a].CompareTo(nums[b]);
            return comparison != 0 ? comparison : a.CompareTo(b);
        });

        bool[] marked = new bool[n];
        long unmarkedSum = 0;
        for (int i = 0; i < n; i++)
            unmarkedSum += nums[i];

        long[] answers = new long[m];
        int pointer = 0;

        for (int q = 0; q < m; q++)
        {
            int[] query = ParseInts(ReadNonEmptyLine(reader));
            int index = query[0];
            int k = query[1];

            if (!marked[index])
            {
                marked[index] = true;
                unmarkedSum -= nums[index];
            }

            while (k > 0)
            {
                while (pointer < n && marked[order[pointer]])
                    pointer++;

                if (pointer >= n)
                    break;

                int selectedIndex = order[pointer++];
                marked[selectedIndex] = true;
                unmarkedSum -= nums[selectedIndex];
                k--;
            }

            answers[q] = unmarkedSum;
        }

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < m; i++)
        {
            if (i > 0)
                output.Append(' ');
            output.Append(answers[i]);
        }

        Console.WriteLine(output.ToString());
    }
}
