using System.IO;

public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<long> values = ParseIntegers(input);

        if (values.Count < 2)
            return;

        int k = (int)values[values.Count - 1];
        int n = values.Count - 1;

        const long NEG = long.MinValue / 4;

        long[] best = new long[k + 1];
        long[] ending = new long[k + 1];

        for (int j = 1; j <= k; j++)
        {
            best[j] = NEG;
            ending[j] = NEG;
        }

        best[0] = 0;

        for (int i = 0; i < n; i++)
        {
            long value = values[i];
            int upper = Math.Min(k, i + 1);

            for (int j = upper; j >= 1; j--)
            {
                long coefficient = k - j + 1L;
                if ((j & 1) == 0)
                    coefficient = -coefficient;

                long contribution = value * coefficient;
                long previous = Math.Max(ending[j], best[j - 1]);

                ending[j] = previous + contribution;
                if (ending[j] > best[j])
                    best[j] = ending[j];
            }
        }

        Console.WriteLine(best[k]);
    }

    private static List<long> ParseIntegers(string input)
    {
        var result = new List<long>();
        int i = 0;

        while (i < input.Length)
        {
            while (i < input.Length &&
                   input[i] != '-' &&
                   (input[i] < '0' || input[i] > '9'))
            {
                i++;
            }

            if (i >= input.Length)
                break;

            long sign = 1;
            if (input[i] == '-')
            {
                sign = -1;
                i++;
            }

            long value = 0;
            bool hasDigit = false;

            while (i < input.Length && input[i] >= '0' && input[i] <= '9')
            {
                hasDigit = true;
                value = value * 10 + (input[i] - '0');
                i++;
            }

            if (hasDigit)
                result.Add(value * sign);
        }

        return result;
    }
}
