using System;
using System.Collections.Generic;

public class Program
{
    private const long Mod = 1000000007L;

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<long> values = ParseIntegers(input);

        if (values.Count < 3)
            return;

        int k = (int)values[values.Count - 1];
        int n = values.Count - 1;
        long[] nums = new long[n];

        for (int i = 0; i < n; i++)
            nums[i] = values[i];

        Array.Sort(nums);

        HashSet<long> uniqueDistances = new HashSet<long>();
        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                long difference = nums[j] - nums[i];
                if (difference > 0)
                    uniqueDistances.Add(difference);
            }
        }

        List<long> distances = new List<long>(uniqueDistances);
        distances.Sort();

        long answer = 0;
        long countAtNextLargerDistance = 0;

        for (int i = distances.Count - 1; i >= 0; i--)
        {
            long distance = distances[i];
            long currentCount = CountSubsequences(nums, k, distance);

            long exactCount = currentCount - countAtNextLargerDistance;
            if (exactCount < 0)
                exactCount += Mod;

            answer = (answer + (distance % Mod) * exactCount) % Mod;
            countAtNextLargerDistance = currentCount;
        }

        Console.WriteLine(answer);
    }

    private static long CountSubsequences(long[] nums, int k, long minimumDistance)
    {
        int n = nums.Length;
        long[,] dp = new long[n + 1, k + 1];
        dp[0, 0] = 1;

        int qualifyingCount = 0;

        for (int i = 1; i <= n; i++)
        {
            while (qualifyingCount < i - 1 &&
                   nums[i - 1] - nums[qualifyingCount] >= minimumDistance)
            {
                qualifyingCount++;
            }

            dp[i, 0] = 1;

            for (int selected = 1; selected <= k; selected++)
            {
                long value = dp[i - 1, selected] +
                             dp[qualifyingCount, selected - 1];

                if (value >= Mod)
                    value -= Mod;

                dp[i, selected] = value;
            }
        }

        return dp[n, k];
    }

    private static List<long> ParseIntegers(string input)
    {
        List<long> result = new List<long>();
        int i = 0;

        while (i < input.Length)
        {
            while (i < input.Length &&
                   !char.IsDigit(input[i]) &&
                   !(input[i] == '-' &&
                     i + 1 < input.Length &&
                     char.IsDigit(input[i + 1])))
            {
                i++;
            }

            if (i >= input.Length)
                break;

            long sign = 1;
            if (input[i] == '-')
            {
                sign = -1;
                i++;
            }

            long value = 0;
            while (i < input.Length && char.IsDigit(input[i]))
            {
                value = value * 10 + (input[i] - '0');
                i++;
            }

            result.Add(value * sign);
        }

        return result;
    }
}
