using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<int> values = ParseIntegers(input);

        int count = values.Count;
        int k = values[count - 2];
        int maxChanges = values[count - 1];
        int n = count - 2;

        int[] nums = new int[n];
        List<int> positions = new List<int>();

        int nearbyOnes = 0;

        for (int i = 0; i < n; i++)
        {
            nums[i] = values[i];
            if (nums[i] == 1)
                positions.Add(i);
        }

        for (int i = 0; i < n; i++)
        {
            if (nums[i] == 0)
                continue;

            int current = 1;
            if (i > 0 && nums[i - 1] == 1)
                current++;
            if (i + 1 < n && nums[i + 1] == 1)
                current++;

            nearbyOnes = Math.Max(nearbyOnes, current);
        }

        nearbyOnes = Math.Min(nearbyOnes, k);

        if (maxChanges >= k - nearbyOnes)
        {
            long answer = Math.Max(nearbyOnes - 1, 0)
                        + 2L * (k - nearbyOnes);
            Console.WriteLine(answer);
            return;
        }

        int requiredOriginalOnes = k - maxChanges;
        int onesCount = positions.Count;

        long[] prefix = new long[onesCount + 1];
        for (int i = 0; i < onesCount; i++)
            prefix[i + 1] = prefix[i] + positions[i];

        long minimumDistance = long.MaxValue;

        for (int left = 0; left + requiredOriginalOnes <= onesCount; left++)
        {
            int right = left + requiredOriginalOnes - 1;
            int middle = (left + right) / 2;
            long median = positions[middle];

            long leftCost =
                median * (middle - left)
                - (prefix[middle] - prefix[left]);

            long rightCost =
                (prefix[right + 1] - prefix[middle + 1])
                - median * (right - middle);

            minimumDistance = Math.Min(minimumDistance, leftCost + rightCost);
        }

        long result = minimumDistance + 2L * maxChanges;
        Console.WriteLine(result);
    }

    private static List<int> ParseIntegers(string input)
    {
        List<int> result = new List<int>();
        int value = 0;
        bool readingNumber = false;

        for (int i = 0; i < input.Length; i++)
        {
            char c = input[i];

            if (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                readingNumber = true;
            }
            else if (readingNumber)
            {
                result.Add(value);
                value = 0;
                readingNumber = false;
            }
        }

        if (readingNumber)
            result.Add(value);

        return result;
    }
}
