    public static void Main()
    {
        string firstLine = null;
        string secondLine = null;
        string line;

        while ((line = Console.ReadLine()) != null)
        {
            if (string.IsNullOrWhiteSpace(line))
                continue;

            if (firstLine == null)
                firstLine = line;
            else
            {
                secondLine = line;
                break;
            }
        }

        if (firstLine == null || secondLine == null)
        {
            Console.WriteLine(0);
            return;
        }

        int[] arr1 = ParseArray(firstLine);
        int[] arr2 = ParseArray(secondLine);

        var prefixes = new HashSet<int>();

        foreach (int value in arr1)
        {
            int prefix = value;
            while (prefix > 0)
            {
                prefixes.Add(prefix);
                prefix /= 10;
            }
        }

        int longest = 0;

        foreach (int value in arr2)
        {
            int prefix = value;
            int length = DigitCount(value);

            while (prefix > 0 && length > longest)
            {
                if (prefixes.Contains(prefix))
                {
                    longest = length;
                    break;
                }

                prefix /= 10;
                length--;
            }
        }

        Console.WriteLine(longest);
    }

    private static int[] ParseArray(string line)
    {
        string[] parts = line.Split(
            new[] { ' ', '\t', ',', '[', ']' },
            StringSplitOptions.RemoveEmptyEntries
        );

        int[] result = new int[parts.Length];
        for (int i = 0; i < parts.Length; i++)
            result[i] = int.Parse(parts[i]);

        return result;
    }

    private static int DigitCount(int value)
    {
        int count = 0;
        while (value > 0)
        {
            count++;
            value /= 10;
        }
        return count;
    }
