using System;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c != -1 && c != '-' && (c < '0' || c > '9'));

            bool negative = false;
            if (c == '-')
            {
                negative = true;
                c = Read();
            }

            long value = 0;
            while (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return negative ? -value : value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = (int)scanner.NextLong();

        long[] sum = new long[n];
        long[] diff = new long[n];

        for (int i = 0; i < n; i++)
        {
            long x = scanner.NextLong();
            long y = scanner.NextLong();
            sum[i] = x + y;
            diff[i] = x - y;
        }

        long[] suffixMaxSum = new long[n];
        long[] suffixMinSum = new long[n];
        long[] suffixMaxDiff = new long[n];
        long[] suffixMinDiff = new long[n];

        suffixMaxSum[n - 1] = suffixMinSum[n - 1] = sum[n - 1];
        suffixMaxDiff[n - 1] = suffixMinDiff[n - 1] = diff[n - 1];

        for (int i = n - 2; i >= 0; i--)
        {
            suffixMaxSum[i] = Math.Max(sum[i], suffixMaxSum[i + 1]);
            suffixMinSum[i] = Math.Min(sum[i], suffixMinSum[i + 1]);
            suffixMaxDiff[i] = Math.Max(diff[i], suffixMaxDiff[i + 1]);
            suffixMinDiff[i] = Math.Min(diff[i], suffixMinDiff[i + 1]);
        }

        long prefixMaxSum = long.MinValue;
        long prefixMinSum = long.MaxValue;
        long prefixMaxDiff = long.MinValue;
        long prefixMinDiff = long.MaxValue;
        long answer = long.MaxValue;

        for (int removed = 0; removed < n; removed++)
        {
            long maxSum = prefixMaxSum;
            long minSum = prefixMinSum;
            long maxDiff = prefixMaxDiff;
            long minDiff = prefixMinDiff;

            if (removed + 1 < n)
            {
                maxSum = Math.Max(maxSum, suffixMaxSum[removed + 1]);
                minSum = Math.Min(minSum, suffixMinSum[removed + 1]);
                maxDiff = Math.Max(maxDiff, suffixMaxDiff[removed + 1]);
                minDiff = Math.Min(minDiff, suffixMinDiff[removed + 1]);
            }

            long maximumDistance = Math.Max(maxSum - minSum, maxDiff - minDiff);
            answer = Math.Min(answer, maximumDistance);

            prefixMaxSum = Math.Max(prefixMaxSum, sum[removed]);
            prefixMinSum = Math.Min(prefixMinSum, sum[removed]);
            prefixMaxDiff = Math.Max(prefixMaxDiff, diff[removed]);
            prefixMinDiff = Math.Min(prefixMinDiff, diff[removed]);
        }

        Console.WriteLine(answer);
    }
}
