public class Program
{
    private const long Mod = 1000000007L;

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<int> values = ParseIntegers(input);

        if (values.Count < 2)
        {
            Console.WriteLine(0);
            return;
        }

        int k = values[values.Count - 1];
        long[] dp = new long[k + 1];
        dp[0] = 1;

        for (int i = 0; i < values.Count - 1; i++)
        {
            int x = values[i];

            for (int sum = k; sum >= 0; sum--)
            {
                long ways = (2L * dp[sum]) % Mod;

                if (sum >= x)
                    ways = (ways + dp[sum - x]) % Mod;

                dp[sum] = ways;
            }
        }

        Console.WriteLine(dp[k]);
    }

    private static List<int> ParseIntegers(string input)
    {
        var result = new List<int>();
        int value = 0;
        bool reading = false;
        bool negative = false;

        foreach (char c in input)
        {
            if (c == '-' && !reading)
            {
                negative = true;
                reading = true;
                value = 0;
            }
            else if (c >= '0' && c <= '9')
            {
                if (!reading)
                {
                    reading = true;
                    negative = false;
                    value = 0;
                }

                value = value * 10 + (c - '0');
            }
            else if (reading)
            {
                result.Add(negative ? -value : value);
                reading = false;
                negative = false;
                value = 0;
            }
        }

        if (reading)
            result.Add(negative ? -value : value);

        return result;
    }
}
