    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        if (tokens.Length == 0)
            return;

        int start = 0;
        int declaredCount;
        if (int.TryParse(tokens[0], out declaredCount) &&
            declaredCount >= 0 &&
            tokens.Length >= declaredCount + 1)
        {
            start = 1;
        }

        int n = tokens.Length - start;
        string[] arr = new string[n];
        Array.Copy(tokens, start, arr, 0, n);

        var occurrenceCount = new Dictionary<string, int>();

        for (int i = 0; i < n; i++)
        {
            var seen = new HashSet<string>();

            for (int begin = 0; begin < arr[i].Length; begin++)
            {
                for (int length = 1; begin + length <= arr[i].Length; length++)
                    seen.Add(arr[i].Substring(begin, length));
            }

            foreach (string substring in seen)
            {
                int count;
                occurrenceCount.TryGetValue(substring, out count);
                occurrenceCount[substring] = count + 1;
            }
        }

        string[] answer = new string[n];

        for (int i = 0; i < n; i++)
        {
            for (int length = 1; length <= arr[i].Length; length++)
            {
                string best = null;

                for (int begin = 0; begin + length <= arr[i].Length; begin++)
                {
                    string candidate = arr[i].Substring(begin, length);

                    if (occurrenceCount[candidate] == 1 &&
                        (best == null || string.CompareOrdinal(candidate, best) < 0))
                    {
                        best = candidate;
                    }
                }

                if (best != null)
                {
                    answer[i] = best;
                    break;
                }
            }

            if (answer[i] == null)
                answer[i] = "";
        }

        Console.Write(string.Join(" ", answer));
    }
