using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<int> values = ParseIntegers(input);

        if (values.Count == 0)
            return;

        int[] nums = values.ToArray();
        int n = nums.Length;

        long totalSubarrays = (long)n * (n + 1) / 2;
        long medianRank = (totalSubarrays + 1) / 2;

        int low = 1;
        int high = n;

        while (low < high)
        {
            int mid = low + (high - low) / 2;

            if (CountAtMost(nums, mid, medianRank) >= medianRank)
                high = mid;
            else
                low = mid + 1;
        }

        Console.WriteLine(low);
    }

    private static long CountAtMost(int[] nums, int maxDistinct, long limit)
    {
        int[] frequencies = new int[100001];
        int left = 0;
        int distinct = 0;
        long count = 0;

        for (int right = 0; right < nums.Length; right++)
        {
            if (frequencies[nums[right]]++ == 0)
                distinct++;

            while (distinct > maxDistinct)
            {
                if (--frequencies[nums[left]] == 0)
                    distinct--;
                left++;
            }

            count += right - left + 1;

            if (count >= limit)
                return count;
        }

        return count;
    }

    private static List<int> ParseIntegers(string input)
    {
        List<int> result = new List<int>();

        for (int i = 0; i < input.Length;)
        {
            while (i < input.Length && !char.IsDigit(input[i]) && input[i] != '-')
                i++;

            if (i >= input.Length)
                break;

            int sign = 1;
            if (input[i] == '-')
            {
                sign = -1;
                i++;
            }

            int value = 0;
            bool hasDigit = false;

            while (i < input.Length && char.IsDigit(input[i]))
            {
                hasDigit = true;
                value = value * 10 + (input[i] - '0');
                i++;
            }

            if (hasDigit)
                result.Add(value * sign);
        }

        return result;
    }
}
