        string freqLine = ReadNonEmptyLine();

        if (numsLine == null || freqLine == null)
            return;

        long[] nums = ParseNumbers(numsLine);
        long[] freq = ParseNumbers(freqLine);
        int n = Math.Min(nums.Length, freq.Length);

        var idCounts = new Dictionary<long, long>();
        var countFrequencies = new Dictionary<long, int>();
        var activeCounts = new SortedSet<long>();
        var answer = new long[n];

        for (int i = 0; i < n; i++)
        {
            long id = nums[i];
            long oldCount;
            idCounts.TryGetValue(id, out oldCount);

            if (oldCount > 0)
                RemoveCount(oldCount, countFrequencies, activeCounts);

            long newCount = oldCount + freq[i];

            if (newCount == 0)
            {
                idCounts.Remove(id);
            }
            else
            {
                idCounts[id] = newCount;
                AddCount(newCount, countFrequencies, activeCounts);
            }

            answer[i] = activeCounts.Count == 0 ? 0 : activeCounts.Max;
        }

        var output = new StringBuilder();
        for (int i = 0; i < n; i++)
        {
            if (i > 0)
                output.Append(' ');
            output.Append(answer[i]);
        }

        Console.WriteLine(output.ToString());
    }

    private static void AddCount(
        long count,
        Dictionary<long, int> countFrequencies,
        SortedSet<long> activeCounts)
    {
        int frequency;
        if (countFrequencies.TryGetValue(count, out frequency))
        {
            countFrequencies[count] = frequency + 1;
        }
        else
        {
            countFrequencies[count] = 1;
            activeCounts.Add(count);
        }
    }

    private static void RemoveCount(
        long count,
        Dictionary<long, int> countFrequencies,
        SortedSet<long> activeCounts)
    {
        int frequency = countFrequencies[count];

        if (frequency == 1)
        {
            countFrequencies.Remove(count);
            activeCounts.Remove(count);
        }
        else
        {
            countFrequencies[count] = frequency - 1;
        }
    }

    private static string ReadNonEmptyLine()
    {
        string line;
        while ((line = Console.ReadLine()) != null)
        {
            if (!string.IsNullOrWhiteSpace(line))
                return line;
        }
        return null;
    }

    private static long[] ParseNumbers(string line)
    {
        var numbers = new List<long>();
        int i = 0;

        while (i < line.Length)
        {
            while (i < line.Length && line[i] != '-' && !char.IsDigit(line[i]))
                i++;

            if (i >= line.Length)
                break;

            bool negative = false;
            if (line[i] == '-')
            {
                negative = true;
                i++;
            }

            long value = 0;
            bool hasDigit = false;

            while (i < line.Length && char.IsDigit(line[i]))
            {
                hasDigit = true;
                value = value * 10 + (line[i] - '0');
                i++;
            }

            if (hasDigit)
                numbers.Add(negative ? -value : value);
        }

        return numbers.ToArray();
    }
