using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private const long INF = long.MaxValue / 4;

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] lines = input.Replace("\r", "").Split('\n');

        var arrays = new List<int[]>();
        foreach (string line in lines)
        {
            int[] values = ParseNumbers(line);
            if (values.Length > 0)
                arrays.Add(values);
        }

        if (arrays.Count < 2)
        {
            Console.WriteLine(-1);
            return;
        }

        int[] nums = arrays[0];
        int[] andValues = arrays[1];

        Console.WriteLine(MinimumValueSum(nums, andValues));
    }

    private static long MinimumValueSum(int[] nums, int[] andValues)
    {
        int n = nums.Length;
        int m = andValues.Length;

        if (m > n)
            return -1;

        var active = new Dictionary<int, long>[m];
        for (int j = 0; j < m; j++)
            active[j] = new Dictionary<int, long>();

        long[] previousClosed = new long[m];
        for (int j = 0; j < m; j++)
            previousClosed[j] = INF;

        for (int i = 0; i < n; i++)
        {
            var nextActive = new Dictionary<int, long>[m];
            long[] currentClosed = new long[m];

            for (int j = 0; j < m; j++)
            {
                currentClosed[j] = INF;
                nextActive[j] = new Dictionary<int, long>();

                int target = andValues[j];

                foreach (KeyValuePair<int, long> state in active[j])
                {
                    int newAnd = state.Key & nums[i];

                    if ((newAnd & target) == target)
                        AddMinimum(nextActive[j], newAnd, state.Value);
                }

                long startCost = INF;
                if (j == 0)
                {
                    if (i == 0)
                        startCost = 0;
                }
                else
                {
                    startCost = previousClosed[j - 1];
                }

                if (startCost < INF && (nums[i] & target) == target)
                    AddMinimum(nextActive[j], nums[i], startCost);

                long baseCost;
                if (nextActive[j].TryGetValue(target, out baseCost))
                    currentClosed[j] = baseCost + nums[i];
            }

            active = nextActive;
            previousClosed = currentClosed;
        }

        return previousClosed[m - 1] >= INF ? -1 : previousClosed[m - 1];
    }

    private static void AddMinimum(Dictionary<int, long> map, int key, long value)
    {
        long existing;
        if (!map.TryGetValue(key, out existing) || value < existing)
            map[key] = value;
    }

    private static int[] ParseNumbers(string line)
    {
        var numbers = new List<int>();
        int value = 0;
        bool reading = false;

        for (int i = 0; i <= line.Length; i++)
        {
            if (i < line.Length && char.IsDigit(line[i]))
            {
                value = value * 10 + (line[i] - '0');
                reading = true;
            }
            else if (reading)
            {
                numbers.Add(value);
                value = 0;
                reading = false;
            }
        }

        return numbers.ToArray();
    }
}
