using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

public class Program
{
    static long[] lcms;
    static int[] signs;

    static long Gcd(long a, long b)
    {
        while (b != 0)
        {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    static long CountAmounts(long value)
    {
        long count = 0;
        for (int i = 0; i < lcms.Length; i++)
        {
            if (lcms[i] <= value)
                count += signs[i] * (value / lcms[i]);
        }
        return count;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        MatchCollection matches = Regex.Matches(input, @"\d+");

        if (matches.Count < 2)
            return;

        long k = long.Parse(matches[matches.Count - 1].Value);
        var rawCoins = new List<int>();

        for (int i = 0; i < matches.Count - 1; i++)
            rawCoins.Add(int.Parse(matches[i].Value));

        rawCoins.Sort();

        var coins = new List<int>();
        foreach (int coin in rawCoins)
        {
            bool redundant = false;
            foreach (int existing in coins)
            {
                if (coin % existing == 0)
                {
                    redundant = true;
                    break;
                }
            }

            if (!redundant)
                coins.Add(coin);
        }

        long upper = (long)coins[0] * k;
        int subsetCount = 1 << coins.Count;
        long[] subsetLcm = new long[subsetCount];
        int[] subsetSign = new int[subsetCount];
        subsetLcm[0] = 1;
        subsetSign[0] = -1;

        var lcmList = new List<long>();
        var signList = new List<int>();

        for (int mask = 1; mask < subsetCount; mask++)
        {
            int previous = mask & (mask - 1);
            int addedBit = mask ^ previous;
            int index = 0;

            while ((addedBit >>= 1) != 0)
                index++;

            subsetSign[mask] = -subsetSign[previous];

            long previousLcm = subsetLcm[previous];
            if (previousLcm > upper)
            {
                subsetLcm[mask] = upper + 1;
                continue;
            }

            long coin = coins[index];
            long gcd = Gcd(previousLcm, coin);
            long divided = previousLcm / gcd;

            if (divided > upper / coin)
            {
                subsetLcm[mask] = upper + 1;
                continue;
            }

            subsetLcm[mask] = divided * coin;
            lcmList.Add(subsetLcm[mask]);
            signList.Add(subsetSign[mask]);
        }

        lcms = lcmList.ToArray();
        signs = signList.ToArray();

        long low = 1;
        long high = upper;

        while (low < high)
        {
            long middle = low + (high - low) / 2;

            if (CountAmounts(middle) >= k)
                high = middle;
            else
                low = middle + 1;
        }

        Console.WriteLine(low);
    }
}
