using System;
using System.Text;

public static class Program
{
    private static int[] head;
    private static int[] bestIndex;
    private static int[] nextEdge;
    private static int[] edgeTo;
    private static byte[] edgeChar;
    private static int nodeCount;
    private static int edgeCount;
    private static string[] containers;

    private static int FindChild(int node, byte ch)
    {
        for (int edge = head[node]; edge != 0; edge = nextEdge[edge])
        {
            if (edgeChar[edge] == ch)
                return edgeTo[edge];
        }
        return -1;
    }

    private static int AddChild(int node, byte ch)
    {
        int child = nodeCount++;
        bestIndex[child] = -1;

        int edge = ++edgeCount;
        edgeChar[edge] = ch;
        edgeTo[edge] = child;
        nextEdge[edge] = head[node];
        head[node] = edge;

        return child;
    }

    private static void UpdateBest(int node, int index)
    {
        int current = bestIndex[node];
        if (current == -1 ||
            containers[index].Length < containers[current].Length ||
            (containers[index].Length == containers[current].Length && index < current))
        {
            bestIndex[node] = index;
        }
    }

    private static string ReadNonEmptyLine()
    {
        string line;
        while ((line = Console.ReadLine()) != null)
        {
            if (line.Trim().Length > 0)
                return line;
        }
        return null;
    }

    private static string[] SplitWords(string line)
    {
        return line.Split(new[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
    }

    public static void Main()
    {
        string containerLine = ReadNonEmptyLine();
        string queryLine = ReadNonEmptyLine();

        if (containerLine == null || queryLine == null)
            return;

        containers = SplitWords(containerLine);
        string[] queries = SplitWords(queryLine);

        int totalLength = 0;
        for (int i = 0; i < containers.Length; i++)
            totalLength += containers[i].Length;

        int maxNodes = totalLength + 1;
        head = new int[maxNodes];
        bestIndex = new int[maxNodes];
        nextEdge = new int[maxNodes];
        edgeTo = new int[maxNodes];
        edgeChar = new byte[maxNodes];

        nodeCount = 1;
        edgeCount = 0;
        bestIndex[0] = -1;

        for (int i = 0; i < containers.Length; i++)
        {
            string word = containers[i];
            int node = 0;
            UpdateBest(node, i);

            for (int j = word.Length - 1; j >= 0; j--)
            {
                byte ch = (byte)(word[j] - 'a');
                int child = FindChild(node, ch);
                if (child == -1)
                    child = AddChild(node, ch);

                node = child;
                UpdateBest(node, i);
            }
        }

        StringBuilder output = new StringBuilder();

        for (int i = 0; i < queries.Length; i++)
        {
            string query = queries[i];
            int node = 0;

            for (int j = query.Length - 1; j >= 0; j--)
            {
                byte ch = (byte)(query[j] - 'a');
                int child = FindChild(node, ch);
                if (child == -1)
                    break;
                node = child;
            }

            if (i > 0)
                output.Append(' ');
            output.Append(bestIndex[node]);
        }

        Console.WriteLine(output.ToString());
    }
}
