            return;

        int n = values.Count - 1;
        int k = values[n];
        long[] dp = new long[n];
        long answer = long.MinValue;

        for (int i = n - 1; i >= 0; i--)
        {
            dp[i] = values[i];

            if (i + k < n)
                dp[i] += dp[i + k];

            if (dp[i] > answer)
                answer = dp[i];
        }

        Console.WriteLine(answer);
