        {
            char c = i < input.Length ? input[i] : ' ';

            if (c == '-' && !reading)
            {
                negative = true;
                reading = true;
                number = 0;
            }
            else if (c >= '0' && c <= '9')
            {
                if (!reading)
                {
                    reading = true;
                    negative = false;
                    number = 0;
                }
                number = number * 10 + (c - '0');
            }
            else if (reading)
            {
                values.Add(negative ? -number : number);
                reading = false;
                negative = false;
                number = 0;
            }
        }

        if (values.Count < 2)
            return;

        long k = values[values.Count - 1];
        int n = values.Count - 1;
        long[] nums = new long[n];

        for (int i = 0; i < n; i++)
            nums[i] = values[i];

        Array.Sort(nums);

        int medianIndex = n / 2;
        long operations = 0;

        for (int i = 0; i <= medianIndex; i++)
        {
            if (nums[i] > k)
                operations += nums[i] - k;
        }

        for (int i = medianIndex; i < n; i++)
        {
            if (nums[i] < k)
                operations += k - nums[i];
        }

        Console.WriteLine(operations);
