using System;
using System.Collections.Generic;

public static class Program
{
    private const long Mod = 1000000007L;

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<long> values = ParseNumbers(input);

        if (values.Count < 3)
            return;

        int n = values.Count - 2;
        long cost1 = values[values.Count - 2];
        long cost2 = values[values.Count - 1];

        long sum = 0;
        long minValue = long.MaxValue;
        long maxValue = long.MinValue;

        for (int i = 0; i < n; i++)
        {
            long value = values[i];
            sum += value;
            if (value < minValue) minValue = value;
            if (value > maxValue) maxValue = value;
        }

        if (n == 1)
        {
            Console.WriteLine(0);
            return;
        }

        if (n == 2)
        {
            long answer = (maxValue - minValue) * cost1;
            Console.WriteLine(answer % Mod);
            return;
        }

        if (cost2 >= 2L * cost1)
        {
            long increments = n * maxValue - sum;
            Console.WriteLine((increments * cost1) % Mod);
            return;
        }

        long answerAtMax = CalculateCost(
            maxValue, n, sum, minValue, cost1, cost2);

        long numerator = sum - 2L * minValue;
        long balancedTarget = (numerator + (n - 3L)) / (n - 2L);
        if (balancedTarget < maxValue)
            balancedTarget = maxValue;

        long answerAtBalanced = CalculateCost(
            balancedTarget, n, sum, minValue, cost1, cost2);

        long answerAtNext = CalculateCost(
            balancedTarget + 1L, n, sum, minValue, cost1, cost2);

        long answer = Math.Min(answerAtMax, Math.Min(answerAtBalanced, answerAtNext));
        Console.WriteLine(answer % Mod);
    }

    private static long CalculateCost(
        long target,
        int n,
        long sum,
        long minValue,
        long cost1,
        long cost2)
    {
        long totalDeficit = target * n - sum;
        long largestDeficit = target - minValue;

        long pairs = Math.Min(totalDeficit / 2L, totalDeficit - largestDeficit);
        long singles = totalDeficit - 2L * pairs;

        return pairs * cost2 + singles * cost1;
    }

    private static List<long> ParseNumbers(string input)
    {
        var result = new List<long>();
        int i = 0;

        while (i < input.Length)
        {
            while (i < input.Length &&
                   !char.IsDigit(input[i]) &&
                   input[i] != '-')
            {
                i++;
            }

            if (i >= input.Length)
                break;

            long sign = 1;
            if (input[i] == '-')
            {
                sign = -1;
                i++;
            }

            long number = 0;
            bool hasDigit = false;

            while (i < input.Length && char.IsDigit(input[i]))
            {
                hasDigit = true;
                number = number * 10 + (input[i] - '0');
                i++;
            }

            if (hasDigit)
                result.Add(number * sign);
        }

        return result;
    }
}
