using System;
using System.IO;
using System.Text;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            long sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value * sign;
        }
    }

    // Number of elements contributed by powerful arrays of 1 through n.
    private static long ElementCount(long n)
    {
        if (n <= 0)
            return 0;

        long total = 0;

        for (long half = 1; half <= n; half <<= 1)
        {
            long cycle = half << 1;
            long values = n + 1;
            long fullCycles = values / cycle;
            long remainder = values % cycle;

            long ones = fullCycles * half;
            if (remainder > half)
                ones += remainder - half;

            total += ones;
        }

        return total;
    }

    // Sum of exponents of two among all elements contributed by 1 through n.
    private static long ExponentSum(long n)
    {
        if (n <= 0)
            return 0;

        long total = 0;
        int bit = 0;

        for (long half = 1; half <= n; half <<= 1, bit++)
        {
            long cycle = half << 1;
            long values = n + 1;
            long fullCycles = values / cycle;
            long remainder = values % cycle;

            long ones = fullCycles * half;
            if (remainder > half)
                ones += remainder - half;

            total += ones * bit;
        }

        return total;
    }

    // Sum of exponents in the first count elements of big_nums.
    private static long PrefixExponent(long count)
    {
        if (count <= 0)
            return 0;

        long low = 0;
        long high = count;

        while (low < high)
        {
            long mid = low + (high - low + 1) / 2;
            if (ElementCount(mid) <= count)
                low = mid;
            else
                high = mid - 1;
        }

        long completeNumbers = low;
        long exponent = ExponentSum(completeNumbers);
        long remaining = count - ElementCount(completeNumbers);

        if (remaining > 0)
        {
            long next = completeNumbers + 1;
            int bit = 0;

            while (remaining > 0)
            {
                if ((next & 1L) != 0)
                {
                    exponent += bit;
                    remaining--;
                }

                next >>= 1;
                bit++;
            }
        }

        return exponent;
    }

    private static long PowerOfTwoMod(long exponent, long modulus)
    {
        if (modulus == 1)
            return 0;

        long result = 1 % modulus;
        long value = 2 % modulus;

        while (exponent > 0)
        {
            if ((exponent & 1L) != 0)
                result = (result * value) % modulus;

            value = (value * value) % modulus;
            exponent >>= 1;
        }

        return result;
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();
        int queryCount = (int)scanner.NextLong();
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < queryCount; i++)
        {
            long from = scanner.NextLong();
            long to = scanner.NextLong();
            long modulus = scanner.NextLong();

            long exponent = PrefixExponent(to + 1) - PrefixExponent(from);
            long answer = PowerOfTwoMod(exponent, modulus);

            if (i > 0)
                output.Append(' ');
            output.Append(answer);
        }

        Console.WriteLine(output.ToString());
    }
}
