using System;
using System.Text.RegularExpressions;

public class Program
{
    static long Combination(int n, int r)
    {
        if (r < 0 || r > n)
            return 0;

        r = Math.Min(r, n - r);
        long result = 1;

        for (int i = 1; i <= r; i++)
            result = result * (n - r + i) / i;

        return result;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        Match match = Regex.Match(input, @"\d+");

        if (!match.Success)
            return;

        long k = long.Parse(match.Value);
        long ways = 0;
        long power = 1;

        for (int jump = 0; jump < 63; jump++)
        {
            long downMoves = power - k;

            if (downMoves >= 0 && downMoves <= jump + 1)
                ways += Combination(jump + 1, (int)downMoves);

            if (downMoves > jump + 1)
                break;

            power <<= 1;
        }

        Console.WriteLine(ways);
    }
}
