public class Program
{
    const long Mod = 1000000007L;

    static long ModPow(long value, long exponent)
    {
        long result = 1;
        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * value % Mod;

            value = value * value % Mod;
            exponent >>= 1;
        }
        return result;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        var numbers = new List<int>();
        int current = 0;
        bool reading = false;

        foreach (char c in input)
        {
            if (c >= '0' && c <= '9')
            {
                current = current * 10 + (c - '0');
                reading = true;
            }
            else if (reading)
            {
                numbers.Add(current);
                current = 0;
                reading = false;
            }
        }

        if (reading)
            numbers.Add(current);

        int n = numbers[0];
        int k = numbers[1];
        int total = n + k - 1;

        long[] factorial = new long[total + 1];
        factorial[0] = 1;

        for (int i = 1; i <= total; i++)
            factorial[i] = factorial[i - 1] * i % Mod;

        long answer = factorial[total];
        answer = answer * ModPow(factorial[n - 1], Mod - 2) % Mod;
        answer = answer * ModPow(factorial[k], Mod - 2) % Mod;

        Console.WriteLine(answer);
    }
}
