using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private const long NegInf = long.MinValue / 4;
    private const long Mod = 1000000007L;

    private struct Node
    {
        public long D00;
        public long D01;
        public long D10;
        public long D11;

        public Node(long value)
        {
            D00 = 0;
            D01 = NegInf;
            D10 = NegInf;
            D11 = value;
        }
    }

    private static Node Merge(Node left, Node right)
    {
        Node result = new Node();

        result.D00 = Max3(
            left.D00 + right.D00,
            left.D00 + right.D10,
            left.D01 + right.D00
        );

        result.D01 = Max3(
            left.D00 + right.D01,
            left.D00 + right.D11,
            left.D01 + right.D01
        );

        result.D10 = Max3(
            left.D10 + right.D00,
            left.D10 + right.D10,
            left.D11 + right.D00
        );

        result.D11 = Max3(
            left.D10 + right.D01,
            left.D10 + right.D11,
            left.D11 + right.D01
        );

        return result;
    }

    private static long Max3(long a, long b, long c)
    {
        return Math.Max(a, Math.Max(b, c));
    }

    private static long GetMaximum(Node node)
    {
        return Math.Max(Math.Max(node.D00, node.D01),
                        Math.Max(node.D10, node.D11));
    }

    private static List<int> ExtractIntegers(string text)
    {
        List<int> numbers = new List<int>();

        for (int i = 0; i < text.Length;)
        {
            while (i < text.Length && text[i] != '-' &&
                   (text[i] < '0' || text[i] > '9'))
            {
                i++;
            }

            if (i >= text.Length)
                break;

            int sign = 1;
            if (text[i] == '-')
            {
                sign = -1;
                i++;
            }

            int value = 0;
            bool hasDigit = false;

            while (i < text.Length && text[i] >= '0' && text[i] <= '9')
            {
                hasDigit = true;
                value = value * 10 + (text[i] - '0');
                i++;
            }

            if (hasDigit)
                numbers.Add(sign * value);
        }

        return numbers;
    }

    public static void Main()
    {
        StreamReader reader = new StreamReader(Console.OpenStandardInput());

        string firstLine = null;
        while ((firstLine = reader.ReadLine()) != null)
        {
            if (!string.IsNullOrWhiteSpace(firstLine))
                break;
        }

        if (firstLine == null)
            return;

        List<int> nums = ExtractIntegers(firstLine);
        List<int> remaining = ExtractIntegers(reader.ReadToEnd());

        if (nums.Count == 0 || remaining.Count == 0)
            return;

        int queryCount = remaining[0];
        int n = nums.Count;

        int size = 1;
        while (size < n)
            size <<= 1;

        Node[] tree = new Node[size << 1];

        for (int i = 0; i < size; i++)
        {
            tree[size + i] = new Node(i < n ? nums[i] : 0);
        }

        for (int i = size - 1; i >= 1; i--)
        {
            tree[i] = Merge(tree[i << 1], tree[(i << 1) | 1]);
        }

        long answer = 0;
        int inputIndex = 1;

        for (int q = 0; q < queryCount; q++)
        {
            int position = remaining[inputIndex++];
            int value = remaining[inputIndex++];

            int treeIndex = size + position;
            tree[treeIndex] = new Node(value);

            treeIndex >>= 1;
            while (treeIndex >= 1)
            {
                tree[treeIndex] = Merge(
                    tree[treeIndex << 1],
                    tree[(treeIndex << 1) | 1]
                );
                treeIndex >>= 1;
            }

            long best = GetMaximum(tree[1]);
            answer = (answer + best) % Mod;
        }

        Console.WriteLine(answer);
    }
}
