using System;
using System.IO;

public class Program
{
    private struct Interval
    {
        public long Start;
        public long End;

        public Interval(long start, long end)
        {
            Start = start;
            End = end;
        }
    }

    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }
            return buffer[position++];
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        long days = scanner.NextLong();
        int n = (int)scanner.NextLong();

        var meetings = new Interval[n];
        for (int i = 0; i < n; i++)
        {
            meetings[i] = new Interval(scanner.NextLong(), scanner.NextLong());
        }

        Array.Sort(meetings, (a, b) =>
        {
            int comparison = a.Start.CompareTo(b.Start);
            return comparison != 0 ? comparison : a.End.CompareTo(b.End);
        });

        long coveredDays = 0;
        long currentStart = meetings[0].Start;
        long currentEnd = meetings[0].End;

        for (int i = 1; i < n; i++)
        {
            if (meetings[i].Start <= currentEnd + 1)
            {
                if (meetings[i].End > currentEnd)
                    currentEnd = meetings[i].End;
            }
            else
            {
                coveredDays += currentEnd - currentStart + 1;
                currentStart = meetings[i].Start;
                currentEnd = meetings[i].End;
