                if (current[current.Count - 1] != orValue)
                    current.Add(orValue);
            }

            for (int j = 0; j < current.Count; j++)
            {
                long difference = Math.Abs((long)current[j] - k);
                if (difference < minimumDifference)
                    minimumDifference = difference;
            }

            if (minimumDifference == 0)
                break;

            previous = current;
        }

        Console.WriteLine(minimumDifference);
    }

