using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private class FenwickTree
    {
        private readonly int[] tree;

        public FenwickTree(int size)
        {
            tree = new int[size + 1];
        }

        public void Add(int index, int delta)
        {
            for (int i = index + 1; i < tree.Length; i += i & -i)
                tree[i] += delta;
        }

        private int PrefixSum(int index)
        {
            int sum = 0;
            for (int i = index + 1; i > 0; i -= i & -i)
                sum += tree[i];
            return sum;
        }

        public int RangeSum(int left, int right)
        {
            if (left > right)
                return 0;

            return PrefixSum(right) - (left > 0 ? PrefixSum(left - 1) : 0);
        }
    }

    private static string ReadNonEmptyLine(StreamReader reader)
    {
        string line;
        while ((line = reader.ReadLine()) != null)
        {
            if (!string.IsNullOrWhiteSpace(line))
                return line;
        }
        return null;
    }

    private static int[] ParseLine(string line)
    {
        string[] parts = line.Split(
            new[] { ' ', '\t', ',', '[', ']' },
            StringSplitOptions.RemoveEmptyEntries);

        int[] values = new int[parts.Length];
        for (int i = 0; i < parts.Length; i++)
            values[i] = int.Parse(parts[i]);

        return values;
    }

    private static bool IsPeak(int[] nums, int index)
    {
        return index > 0 &&
               index < nums.Length - 1 &&
               nums[index] > nums[index - 1] &&
               nums[index] > nums[index + 1];
    }

    public static void Main()
    {
        using (StreamReader reader = new StreamReader(Console.OpenStandardInput()))
        {
            string numsLine = ReadNonEmptyLine(reader);
            if (numsLine == null)
                return;

            int[] nums = ParseLine(numsLine);
            string queryCountLine = ReadNonEmptyLine(reader);
            if (queryCountLine == null)
                return;

            int queryCount = int.Parse(queryCountLine.Trim());
            FenwickTree fenwick = new FenwickTree(nums.Length);
            bool[] peaks = new bool[nums.Length];

            for (int i = 1; i < nums.Length - 1; i++)
            {
                peaks[i] = IsPeak(nums, i);
                if (peaks[i])
                    fenwick.Add(i, 1);
            }

            List<int> answers = new List<int>();

            for (int q = 0; q < queryCount; q++)
            {
                string queryLine = ReadNonEmptyLine(reader);
                if (queryLine == null)
                    break;

                int[] query = ParseLine(queryLine);
                int type = query[0];
                int x = query[1];
                int y = query[2];

                if (type == 1)
                {
                    int left = x;
                    int right = y;

                    if (right - left < 2)
                        answers.Add(0);
                    else
                        answers.Add(fenwick.RangeSum(left + 1, right - 1));
                }
                else
                {
                    int index = x;
                    int value = y;

                    for (int i = index - 1; i <= index + 1; i++)
                    {
                        if (i > 0 && i < nums.Length - 1 && peaks[i])
                        {
                            fenwick.Add(i, -1);
                            peaks[i] = false;
                        }
                    }

                    nums[index] = value;

                    for (int i = index - 1; i <= index + 1; i++)
                    {
                        if (i > 0 && i < nums.Length - 1)
                        {
                            peaks[i] = IsPeak(nums, i);
                            if (peaks[i])
                                fenwick.Add(i, 1);
                        }
                    }
                }
            }

            Console.WriteLine(string.Join(" ", answers));
        }
    }
}
