using System;
using System.IO;

public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        if (tokens.Length < 2)
            return;

        int n = tokens.Length - 1;
        int[] nums = new int[n];

        for (int i = 0; i < n; i++)
            nums[i] = int.Parse(tokens[i]);

        int k = int.Parse(tokens[n]);
        int[,] dp = new int[n, k + 1];
        int answer = 1;

        for (int i = 0; i < n; i++)
        {
            dp[i, 0] = 1;

            for (int changes = 1; changes <= k; changes++)
                dp[i, changes] = 1;

            for (int previous = 0; previous < i; previous++)
            {
                for (int changes = 0; changes <= k; changes++)
                {
                    if (nums[previous] == nums[i])
                    {
                        dp[i, changes] = Math.Max(
                            dp[i, changes],
                            dp[previous, changes] + 1
                        );
                    }
                    else if (changes > 0)
                    {
                        dp[i, changes] = Math.Max(
                            dp[i, changes],
                            dp[previous, changes - 1] + 1
                        );
                    }
                }
            }

            for (int changes = 0; changes <= k; changes++)
                answer = Math.Max(answer, dp[i, changes]);
        }

        Console.WriteLine(answer);
    }
