using System;
using System.IO;

public class Program
{
    private const long Mod = 1000000007L;

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        int requirementCount = scanner.NextInt();

        int[] required = new int[n];
        for (int i = 0; i < n; i++)
            required[i] = -1;

        for (int i = 0; i < requirementCount; i++)
        {
            int end = scanner.NextInt();
            int count = scanner.NextInt();
            required[end] = count;
        }

        int finalCount = required[n - 1];
        if (finalCount < 0)
        {
            Console.WriteLine(0);
            return;
        }

        long[] dp = new long[finalCount + 1];
        long[] next = new long[finalCount + 1];
        dp[0] = 1;

        for (int i = 0; i < n; i++)
        {
            long window = 0;

            for (int inversions = 0; inversions <= finalCount; inversions++)
            {
                window += dp[inversions];
                if (window >= Mod)
                    window -= Mod;

                int removedIndex = inversions - i - 1;
                if (removedIndex >= 0)
                {
                    window -= dp[removedIndex];
                    if (window < 0)
                        window += Mod;
                }

                next[inversions] = window;
            }

            if (required[i] >= 0)
            {
                int target = required[i];

                if (target > finalCount)
                {
                    Console.WriteLine(0);
                    return;
                }

                long value = next[target];
                Array.Clear(next, 0, next.Length);
                next[target] = value;
            }

            long[] temporary = dp;
            dp = next;
            next = temporary;
        }

        Console.WriteLine(dp[finalCount] % Mod);
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c != -1 && c != '-' && (c < '0' || c > '9'));

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value * sign;
        }
    }
}
