using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private struct State
    {
        public int Value;
        public long Count;

        public State(int value, long count)
        {
            Value = value;
            Count = count;
        }
    }

    private static List<int> ParseIntegers(string line)
    {
        var values = new List<int>();
        int i = 0;

        while (i < line.Length)
        {
            while (i < line.Length && !char.IsDigit(line[i]) && line[i] != '-')
                i++;

            if (i >= line.Length)
                break;

            int sign = 1;
            if (line[i] == '-')
            {
                sign = -1;
                i++;
            }

            int value = 0;
            bool hasDigit = false;
            while (i < line.Length && char.IsDigit(line[i]))
            {
                value = value * 10 + (line[i] - '0');
                hasDigit = true;
                i++;
            }

            if (hasDigit)
                values.Add(value * sign);
        }

        return values;
    }

    public static void Main()
    {
        var lines = new List<string>();
        string line;

        while ((line = Console.ReadLine()) != null)
        {
            if (!string.IsNullOrWhiteSpace(line))
                lines.Add(line);
        }

        if (lines.Count == 0)
            return;

        List<int> nums;
        int k;

        if (lines.Count >= 2)
        {
            nums = ParseIntegers(lines[0]);
            List<int> kValues = ParseIntegers(lines[1]);
            if (kValues.Count == 0)
                return;
            k = kValues[0];
        }
        else
        {
            List<int> values = ParseIntegers(lines[0]);
            if (values.Count < 2)
                return;

            k = values[values.Count - 1];
            values.RemoveAt(values.Count - 1);
            nums = values;
        }

        long answer = 0;
        var previous = new List<State>();

        foreach (int x in nums)
        {
            var current = new List<State>();
            current.Add(new State(x, 1));

            for (int i = 0; i < previous.Count; i++)
            {
                int andValue = previous[i].Value & x;
                long count = previous[i].Count;

                int last = current.Count - 1;
                if (current[last].Value == andValue)
                {
                    State merged = current[last];
                    merged.Count += count;
                    current[last] = merged;
                }
                else
                {
                    current.Add(new State(andValue, count));
                }
            }

            for (int i = 0; i < current.Count; i++)
            {
                if (current[i].Value == k)
                    answer += current[i].Count;
            }

            previous = current;
        }

        Console.WriteLine(answer);
    }
}
