        int row = 1;

        while (true)
        {
            if (row % 2 == 1)
            {
                if (firstColor < row)
                    break;
                firstColor -= row;
            }
            else
            {
                if (secondColor < row)
                    break;
                secondColor -= row;
            }

            height++;
            row++;
        }

        return height;
    }
