using System;
using System.Collections.Generic;

public class Program
{
    private const ulong HashBase = 911382323UL;

    private sealed class WordEntry
    {
        public string Word;
        public int Cost;
        public WordEntry Next;

        public WordEntry(string word, int cost, WordEntry next)
        {
            Word = word;
            Cost = cost;
            Next = next;
        }
    }

    private sealed class LengthGroup
    {
        public int Length;
        public Dictionary<ulong, WordEntry> Words;

        public LengthGroup(int length)
        {
            Length = length;
            Words = new Dictionary<ulong, WordEntry>();
        }
    }

    private static ulong GetWordHash(string word)
    {
        ulong hash = 0;
        for (int i = 0; i < word.Length; i++)
        {
            hash = unchecked(hash * HashBase + (ulong)(word[i] - 'a' + 1));
        }
        return hash;
    }

    private static int GetMatchingCost(
        LengthGroup group,
        ulong hash,
        string target,
        int start)
    {
        WordEntry entry;
        if (!group.Words.TryGetValue(hash, out entry))
            return -1;

        int best = int.MaxValue;

        while (entry != null)
        {
            string word = entry.Word;
            bool matches = true;

            for (int i = 0; i < word.Length; i++)
            {
                if (target[start + i] != word[i])
                {
                    matches = false;
                    break;
                }
            }

            if (matches && entry.Cost < best)
                best = entry.Cost;

            entry = entry.Next;
        }

        return best == int.MaxValue ? -1 : best;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split(
            (char[])null,
            StringSplitOptions.RemoveEmptyEntries);

        if (tokens.Length == 0)
            return;

        string target = tokens[0];

        int costStart = 1;
        while (costStart < tokens.Length &&
               !char.IsDigit(tokens[costStart][0]))
        {
            costStart++;
        }

        int wordCount = costStart - 1;
        if (wordCount <= 0 || tokens.Length - costStart < wordCount)
        {
            Console.WriteLine("-1");
            return;
        }

        Dictionary<int, LengthGroup> groupsByLength =
            new Dictionary<int, LengthGroup>();

        for (int i = 0; i < wordCount; i++)
        {
            string word = tokens[i + 1];
            int cost = int.Parse(tokens[costStart + i]);

            LengthGroup group;
            if (!groupsByLength.TryGetValue(word.Length, out group))
            {
                group = new LengthGroup(word.Length);
                groupsByLength.Add(word.Length, group);
            }

            ulong hash = GetWordHash(word);
            WordEntry head;

            if (!group.Words.TryGetValue(hash, out head))
            {
                group.Words.Add(hash, new WordEntry(word, cost, null));
            }
            else
            {
                WordEntry current = head;
                bool found = false;

                while (current != null)
                {
                    if (string.Equals(current.Word, word, StringComparison.Ordinal))
                    {
                        if (cost < current.Cost)
                            current.Cost = cost;
                        found = true;
                        break;
                    }
                    current = current.Next;
                }

                if (!found)
                    group.Words[hash] = new WordEntry(word, cost, head);
            }
        }

        List<LengthGroup> groups =
            new List<LengthGroup>(groupsByLength.Values);

        groups.Sort(delegate(LengthGroup a, LengthGroup b)
        {
            return a.Length.CompareTo(b.Length);
        });

        int n = target.Length;
        ulong[] powers = new ulong[n + 1];
        ulong[] prefix = new ulong[n + 1];
        powers[0] = 1;

        for (int i = 0; i < n; i++)
        {
            powers[i + 1] = unchecked(powers[i] * HashBase);
            prefix[i + 1] = unchecked(
                prefix[i] * HashBase + (ulong)(target[i] - 'a' + 1));
        }

        const long Infinity = long.MaxValue / 4;
        long[] dp = new long[n + 1];

        for (int i = 1; i <= n; i++)
            dp[i] = Infinity;

        dp[0] = 0;

        for (int start = 0; start < n; start++)
        {
            if (dp[start] == Infinity)
                continue;

            for (int g = 0; g < groups.Count; g++)
            {
                LengthGroup group = groups[g];
                int end = start + group.Length;

                if (end > n)
                    break;

                ulong hash = unchecked(
                    prefix[end] - prefix[start] * powers[group.Length]);

                int cost = GetMatchingCost(group, hash, target, start);
                if (cost < 0)
                    continue;

                long candidate = dp[start] + cost;
                if (candidate < dp[end])
                    dp[end] = candidate;
            }
        }

        Console.WriteLine(dp[n] == Infinity ? "-1" : dp[n].ToString());
    }
}
