    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<long> values = ParseNumbers(input);

        if (values.Count < 3)
            return;

        long d = values[values.Count - 1];
        int n = values.Count - 1;
        long[] start = new long[n];

        for (int i = 0; i < n; i++)
            start[i] = values[i];

        Array.Sort(start);

        long low = 0;
        long high = (start[n - 1] + d - start[0]) / (n - 1);

        while (low < high)
        {
            long mid = low + (high - low + 1) / 2;

            if (CanChoose(start, d, mid))
                low = mid;
            else
                high = mid - 1;
        }

        Console.WriteLine(low);
    }

    private static bool CanChoose(long[] start, long d, long distance)
    {
        long previous = start[0];

        for (int i = 1; i < start.Length; i++)
        {
            long current = Math.Max(start[i], previous + distance);

            if (current > start[i] + d)
                return false;

            previous = current;
        }

        return true;
    }

    private static List<long> ParseNumbers(string input)
    {
        List<long> numbers = new List<long>();
        int i = 0;

        while (i < input.Length)
        {
            while (i < input.Length && !char.IsDigit(input[i]) && input[i] != '-')
                i++;

            if (i >= input.Length)
                break;

            bool negative = false;
            if (input[i] == '-')
            {
                negative = true;
                i++;
            }

            long value = 0;
            while (i < input.Length && char.IsDigit(input[i]))
            {
                value = value * 10 + (input[i] - '0');
                i++;
            }

            numbers.Add(negative ? -value : value);
        }

        return numbers;
