public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public string Next()
        {
            int c;
            do
            {
                c = Read();
            } while (c != -1 && char.IsWhiteSpace((char)c));

            if (c == -1)
                return null;

            System.Text.StringBuilder result = new System.Text.StringBuilder();
            while (c != -1 && !char.IsWhiteSpace((char)c))
            {
                result.Append((char)c);
                c = Read();
            }

            return result.ToString();
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();

        string source = scanner.Next();
        string pattern = scanner.Next();

        bool[] isTarget = new bool[source.Length];
        int targetCount = 0;
        string token;

        while ((token = scanner.Next()) != null)
        {
            int index = int.Parse(token);
            isTarget[index] = true;
            targetCount++;
        }

        int m = pattern.Length;
        int inf = int.MaxValue / 4;
        int[] dp = new int[m + 1];

        for (int j = 1; j <= m; j++)
            dp[j] = inf;

        for (int i = 0; i < source.Length; i++)
        {
            int cost = isTarget[i] ? 1 : 0;
            int upper = Math.Min(m, i + 1);

            for (int j = upper; j >= 1; j--)
            {
                if (source[i] == pattern[j - 1] && dp[j - 1] != inf)
                {
                    dp[j] = Math.Min(dp[j], dp[j - 1] + cost);
                }
            }
        }

        Console.WriteLine(targetCount - dp[m]);
    }
}
