using System;
using System.IO;

public static class Program
{
    public static void Main()
    {
        Stream input = Console.OpenStandardInput();

        int evenCount = 0;
        int oddCount = 0;
        int alternatingLength = 0;
        int previousParity = -1;

        int value = 0;
        bool readingNumber = false;
        bool negative = false;

        while (true)
        {
            int b = input.ReadByte();

            if (b >= '0' && b <= '9')
            {
                value = value * 10 + (b - '0');
                readingNumber = true;
            }
            else
            {
                if (b == '-' && !readingNumber)
                {
                    negative = true;
                }
                else if (readingNumber)
                {
                    if (negative) value = -value;
                    Process(value, ref evenCount, ref oddCount,
                            ref alternatingLength, ref previousParity);

                    value = 0;
                    readingNumber = false;
                    negative = false;
                }
                else
                {
                    negative = false;
                }

                if (b == -1) break;
            }
        }

        int answer = Math.Max(alternatingLength, Math.Max(evenCount, oddCount));
        Console.WriteLine(answer);
    }

    private static void Process(
        int value,
        ref int evenCount,
        ref int oddCount,
        ref int alternatingLength,
        ref int previousParity)
    {
        int parity = Math.Abs(value % 2);

        if (parity == 0)
            evenCount++;
        else
            oddCount++;

        if (previousParity == -1)
        {
            alternatingLength = 1;
        }
        else if (parity != previousParity)
        {
            alternatingLength++;
        }

        previousParity = parity;
    }
}
