public class Program
{
    public static void Main()
    {
        StreamReader reader = new StreamReader(Console.OpenStandardInput());

        string header;
        do
        {
            header = reader.ReadLine();
        } while (header != null && header.Trim().Length == 0);

        if (header == null)
            return;

        string[] dimensions = header.Split(
            new char[] { ' ', '\t' },
            StringSplitOptions.RemoveEmptyEntries
        );

        int rows = int.Parse(dimensions[0]);
        int columns = dimensions.Length > 1 ? int.Parse(dimensions[1]) : -1;

        int[] balancePrefix = null;
        int[] xPrefix = null;
        long answer = 0;

        for (int i = 0; i < rows; i++)
        {
            string row = ReadGridRow(reader);

            if (columns < 0)
                columns = row.Length;

            if (balancePrefix == null)
            {
                balancePrefix = new int[columns];
                xPrefix = new int[columns];
            }

            int rowBalance = 0;
            int rowXCount = 0;

            for (int j = 0; j < columns; j++)
            {
                char cell = row[j];

                if (cell == 'X')
                {
                    rowBalance++;
                    rowXCount++;
                }
                else if (cell == 'Y')
                {
                    rowBalance--;
                }

                balancePrefix[j] += rowBalance;
                xPrefix[j] += rowXCount;

                if (balancePrefix[j] == 0 && xPrefix[j] > 0)
                    answer++;
            }
        }

        Console.WriteLine(answer);
    }

    private static string ReadGridRow(StreamReader reader)
    {
        while (true)
        {
            string line = reader.ReadLine();
            if (line == null)
                return string.Empty;

            StringBuilder row = new StringBuilder();

            foreach (char c in line)
            {
                if (c == 'X' || c == 'Y' || c == '.')
                    row.Append(c);
            }

            if (row.Length > 0)
                return row.ToString();
        }
    }
}
