using System;
using System.IO;
using System.Text;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            long sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value * sign;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    private sealed class MaxHeap
    {
        private readonly long[] heap;
        public int Count { get; private set; }

        public MaxHeap(int capacity)
        {
            heap = new long[capacity];
        }

        public long Peek()
        {
            return heap[0];
        }

        public void Add(long value)
        {
            int index = Count++;
            heap[index] = value;

            while (index > 0)
            {
                int parent = (index - 1) / 2;
                if (heap[parent] >= heap[index])
                    break;

                long temp = heap[parent];
                heap[parent] = heap[index];
                heap[index] = temp;
                index = parent;
            }
        }

        public void ReplaceRoot(long value)
        {
            heap[0] = value;
            int index = 0;

            while (true)
            {
                int left = index * 2 + 1;
                if (left >= Count)
                    break;

                int right = left + 1;
                int largerChild = left;

                if (right < Count && heap[right] > heap[left])
                    largerChild = right;

                if (heap[index] >= heap[largerChild])
                    break;

                long temp = heap[index];
                heap[index] = heap[largerChild];
                heap[largerChild] = temp;
                index = largerChild;
            }
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();

        int queryCount = scanner.NextInt();
        long[] distances = new long[queryCount];

        for (int i = 0; i < queryCount; i++)
        {
            long x = scanner.NextLong();
            long y = scanner.NextLong();
            distances[i] = Math.Abs(x) + Math.Abs(y);
        }

        int k = scanner.NextInt();
        MaxHeap heap = new MaxHeap(k);
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < queryCount; i++)
        {
            long distance = distances[i];

            if (heap.Count < k)
            {
                heap.Add(distance);
            }
            else if (distance < heap.Peek())
            {
                heap.ReplaceRoot(distance);
            }

            if (i > 0)
                output.Append(' ');

            if (heap.Count < k)
                output.Append("-1");
            else
                output.Append(heap.Peek());
        }

        Console.WriteLine(output.ToString());
    }
}
