using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<int> values = ParseIntegers(input);

        if (values.Count < 3)
            return;

        int k = values[values.Count - 1];
        int n = values.Count - 1;
        int pairs = n / 2;

        int[] rangeDelta = new int[k + 2];
        int[] exactDifference = new int[k + 1];

        for (int i = 0; i < pairs; i++)
        {
            int a = values[i];
            int b = values[n - 1 - i];

            int difference = Math.Abs(a - b);
            exactDifference[difference]++;

            int smaller = Math.Min(a, b);
            int larger = Math.Max(a, b);
            int oneChangeLimit = Math.Max(larger, k - smaller);

            rangeDelta[0]++;
            rangeDelta[oneChangeLimit + 1]--;
        }

        int answer = int.MaxValue;
        int oneChangePossible = 0;

        for (int x = 0; x <= k; x++)
        {
            oneChangePossible += rangeDelta[x];

            // Pairs outside oneChangePossible need two changes.
            // Pairs inside need one change, except those already having difference x.
            int changes = 2 * pairs - oneChangePossible - exactDifference[x];
            answer = Math.Min(answer, changes);
        }

        Console.WriteLine(answer);
    }

    private static List<int> ParseIntegers(string input)
    {
        List<int> result = new List<int>();
        int value = 0;
        bool reading = false;

        for (int i = 0; i <= input.Length; i++)
        {
            char c = i < input.Length ? input[i] : ' ';

            if (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                reading = true;
            }
            else if (reading)
            {
                result.Add(value);
                value = 0;
                reading = false;
            }
        }

        return result;
    }
}
