    private static long ReadLong()
    {
        Stream input = Console.OpenStandardInput();
        int c;
        do
        {
            c = input.ReadByte();
        } while (c != -1 && (c < '0' || c > '9'));

        long value = 0;
        while (c >= '0' && c <= '9')
        {
            value = value * 10 + (c - '0');
            c = input.ReadByte();
        }

        return value;
    }

    public static void Main()
    {
        long l = ReadLong();
        long r = ReadLong();

        int limit = (int)Math.Sqrt(r);
        while ((long)(limit + 1) * (limit + 1) <= r) limit++;
        while ((long)limit * limit > r) limit--;

        bool[] composite = new bool[limit + 1];

        for (int i = 2; (long)i * i <= limit; i++)
        {
            if (!composite[i])
            {
                for (int j = i * i; j <= limit; j += i)
                    composite[j] = true;
            }
        }

        long specialCount = 0;
        for (int p = 2; p <= limit; p++)
        {
            if (!composite[p] && (long)p * p >= l)
                specialCount++;
        }

        long result = r - l + 1 - specialCount;
        Console.WriteLine(result);
    }
