    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int queryCount = scanner.NextInt();

        var roads = new List<int>[n];
        for (int i = 0; i < n; i++)
            roads[i] = new List<int>();

        int[] answer = new int[queryCount];
        int[] distance = new int[n];

        for (int queryIndex = 0; queryIndex < queryCount; queryIndex++)
        {
            int u = scanner.NextInt();
            int v = scanner.NextInt();
            roads[u].Add(v);

            for (int i = 0; i < n; i++)
                distance[i] = int.MaxValue;

            distance[0] = 0;

            for (int city = 0; city < n; city++)
            {
                if (city + 1 < n && distance[city] + 1 < distance[city + 1])
                    distance[city + 1] = distance[city] + 1;

                foreach (int destination in roads[city])
                {
                    if (distance[city] + 1 < distance[destination])
                        distance[destination] = distance[city] + 1;
                }
            }

            answer[queryIndex] = distance[n - 1];
        }

        var output = new StringBuilder();
        for (int i = 0; i < answer.Length; i++)
        {
            if (i > 0)
                output.Append(' ');
            output.Append(answer[i]);
        }

        Console.WriteLine(output.ToString());
    }
