using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

public class Program
{
    private class PositionFenwick
    {
        private readonly int n;
        private readonly int[] tree;

        public PositionFenwick(int n)
        {
            this.n = n;
            tree = new int[n + 1];
        }

        public void Add(int index, int delta)
        {
            for (int i = index + 1; i <= n; i += i & -i)
                tree[i] += delta;
        }

        public int PrefixSum(int index)
        {
            int result = 0;
            for (int i = index + 1; i > 0; i -= i & -i)
                result += tree[i];
            return result;
        }

        // Returns the zero-based index of the k-th occupied position.
        public int FindKth(int k)
        {
            int index = 0;
            int step = 1;

            while ((step << 1) <= n)
                step <<= 1;

            for (; step > 0; step >>= 1)
            {
                int next = index + step;
                if (next <= n && tree[next] < k)
                {
                    index = next;
                    k -= tree[next];
                }
            }

            return index;
        }
    }

    private class GapFenwick
    {
        private readonly int n;
        private readonly long[] countTree;
        private readonly long[] sumTree;

        public GapFenwick(int n)
        {
            this.n = n;
            countTree = new long[n + 1];
            sumTree = new long[n + 1];
        }

        public void Add(int length, int delta)
        {
            for (int i = length; i <= n; i += i & -i)
            {
                countTree[i] += delta;
                sumTree[i] += (long)delta * length;
            }
        }

        private long Prefix(long[] tree, int index)
        {
            long result = 0;
            for (int i = index; i > 0; i -= i & -i)
                result += tree[i];
            return result;
        }

        public long CountGroups(int size)
        {
            long totalCount = Prefix(countTree, n);
            long totalSum = Prefix(sumTree, n);

            long smallerCount = Prefix(countTree, size - 1);
            long smallerSum = Prefix(sumTree, size - 1);

            long applicableCount = totalCount - smallerCount;
            long applicableSum = totalSum - smallerSum;

            return applicableSum - (long)(size - 1) * applicableCount;
        }
    }

    private class AlternatingCircle
    {
        private readonly int n;
        private readonly PositionFenwick badPositions;
        private readonly GapFenwick gaps;
        private int badCount;

        public AlternatingCircle(int[] colors)
        {
            n = colors.Length;
            badPositions = new PositionFenwick(n);
            gaps = new GapFenwick(n);
            badCount = 0;

            for (int i = 0; i < n; i++)
            {
                int next = (i + 1) % n;
                if (colors[i] == colors[next])
                    InsertBadEdge(i);
            }
        }

        private int Distance(int from, int to)
        {
            int distance = to - from;
            if (distance <= 0)
                distance += n;
            return distance;
        }

        public void InsertBadEdge(int index)
        {
            if (badCount == 0)
            {
                badPositions.Add(index, 1);
                gaps.Add(n, 1);
                badCount = 1;
                return;
            }

            int less = badPositions.PrefixSum(index - 1);
            int previous = less > 0
                ? badPositions.FindKth(less)
                : badPositions.FindKth(badCount);

            int next = less < badCount
                ? badPositions.FindKth(less + 1)
                : badPositions.FindKth(1);

            gaps.Add(Distance(previous, next), -1);
            gaps.Add(Distance(previous, index), 1);
            gaps.Add(Distance(index, next), 1);

            badPositions.Add(index, 1);
            badCount++;
        }

        public void RemoveBadEdge(int index)
        {
            if (badCount == 1)
            {
                gaps.Add(n, -1);
                badPositions.Add(index, -1);
                badCount = 0;
                return;
            }

            int less = badPositions.PrefixSum(index - 1);

            int previous = less > 0
                ? badPositions.FindKth(less)
                : badPositions.FindKth(badCount);

            int next = less + 1 < badCount
                ? badPositions.FindKth(less + 2)
                : badPositions.FindKth(1);

            gaps.Add(Distance(previous, index), -1);
            gaps.Add(Distance(index, next), -1);
            gaps.Add(Distance(previous, next), 1);

            badPositions.Add(index, -1);
            badCount--;
        }

        public long Query(int size)
        {
            if (badCount == 0)
                return n;

            return gaps.CountGroups(size);
        }
    }

    private class FastScanner
    {
        private readonly TextReader reader;
        private readonly char[] buffer = new char[1 << 16];
        private int length;
        private int position;

        public FastScanner(TextReader reader)
        {
            this.reader = reader;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = reader.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c >= 0 && c <= ' ');

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value * sign;
        }
    }

    private static string ReadNonEmptyLine()
    {
        string line;
        while ((line = Console.ReadLine()) != null)
        {
            if (line.Trim().Length > 0)
                return line;
        }
        return null;
    }

    public static void Main()
    {
        string colorsLine = ReadNonEmptyLine();
        if (colorsLine == null)
            return;

        string[] colorParts = colorsLine.Split(
            new char[] { ' ', '\t' },
            StringSplitOptions.RemoveEmptyEntries
        );

        int[] colors = new int[colorParts.Length];
        for (int i = 0; i < colorParts.Length; i++)
            colors[i] = int.Parse(colorParts[i]);

        string queryCountLine = ReadNonEmptyLine();
        int queryCount = int.Parse(queryCountLine.Trim());

        FastScanner scanner = new FastScanner(Console.In);
        AlternatingCircle circle = new AlternatingCircle(colors);
        List<long> answers = new List<long>();

        int n = colors.Length;

        for (int q = 0; q < queryCount; q++)
        {
            int type = scanner.NextInt();

            if (type == 1)
            {
                int size = scanner.NextInt();
                answers.Add(circle.Query(size));
            }
            else
            {
                int index = scanner.NextInt();
                int newColor = scanner.NextInt();

                if (colors[index] == newColor)
                    continue;

                int leftEdge = (index - 1 + n) % n;
                int rightEdge = index;

                bool oldLeftBad = colors[leftEdge] == colors[index];
                bool oldRightBad = colors[index] == colors[(index + 1) % n];

                colors[index] = newColor;

                bool newLeftBad = colors[leftEdge] == colors[index];
                bool newRightBad = colors[index] == colors[(index + 1) % n];

                if (oldLeftBad && !newLeftBad)
                    circle.RemoveBadEdge(leftEdge);
                else if (!oldLeftBad && newLeftBad)
                    circle.InsertBadEdge(leftEdge);

                if (oldRightBad && !newRightBad)
                    circle.RemoveBadEdge(rightEdge);
                else if (!oldRightBad && newRightBad)
                    circle.InsertBadEdge(rightEdge);
            }
        }

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < answers.Count; i++)
        {
            if (i > 0)
                output.Append(' ');
            output.Append(answers[i]);
        }

        Console.WriteLine(output.ToString());
    }
}
