        public long Damage;
        public long Hits;

        public Enemy(long damage, long hits)
        {
            Damage = damage;
            Hits = hits;
        }
    }

    private static List<long> ParseNumbers(string line)
    {
        var numbers = new List<long>();
        long value = 0;
        bool reading = false;

        for (int i = 0; i <= line.Length; i++)
        {
            char c = i < line.Length ? line[i] : ' ';
            if (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                reading = true;
            }
            else if (reading)
            {
                numbers.Add(value);
                value = 0;
                reading = false;
            }
        }

        return numbers;
    }

    public static void Main()
    {
        var lines = new List<string>();
        string line;

        while ((line = Console.ReadLine()) != null)
        {
            if (!string.IsNullOrWhiteSpace(line))
                lines.Add(line);
        }

        if (lines.Count < 3)
            return;

        long power = ParseNumbers(lines[0])[0];
        List<long> damage = ParseNumbers(lines[1]);
        List<long> health = ParseNumbers(lines[2]);

        int n = Math.Min(damage.Count, health.Count);
        var enemies = new Enemy[n];
        long currentDamage = 0;

        for (int i = 0; i < n; i++)
        {
            long hits = (health[i] + power - 1) / power;
            enemies[i] = new Enemy(damage[i], hits);
            currentDamage += damage[i];
        }

        Array.Sort(enemies, delegate (Enemy a, Enemy b)
        {
            long left = a.Hits * b.Damage;
            long right = b.Hits * a.Damage;

            if (left < right) return -1;
            if (left > right) return 1;
            return 0;
        });

        long answer = 0;

        for (int i = 0; i < n; i++)
        {
            answer += currentDamage * enemies[i].Hits;
            currentDamage -= enemies[i].Damage;
        }

        Console.WriteLine(answer);
    }
}
