using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value * sign;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int edgeCount = scanner.NextInt();
        int n = edgeCount + 1;

        var graph = new List<int>[n];
        for (int i = 0; i < n; i++)
            graph[i] = new List<int>();

        for (int i = 0; i < edgeCount; i++)
        {
            int u = scanner.NextInt();
            int v = scanner.NextInt();
            graph[u].Add(v);
            graph[v].Add(u);
        }

        int[] parent = new int[n];
        int[] order = new int[n];
        Array.Fill(parent, -2);

        int orderSize = 0;
        int[] stack = new int[n];
        int stackSize = 0;

        parent[0] = -1;
        stack[stackSize++] = 0;

        while (stackSize > 0)
        {
            int u = stack[--stackSize];
            order[orderSize++] = u;

            foreach (int v in graph[u])
            {
                if (v == parent[u]) continue;
                parent[v] = u;
                stack[stackSize++] = v;
            }
        }

        int[] down = new int[n];
        int[] up = new int[n];
        int[] bestChild = new int[n];
        int[] bestValue = new int[n];
        int[] secondBestValue = new int[n];

        Array.Fill(bestChild, -1);

        for (int i = n - 1; i >= 0; i--)
        {
            int u = order[i];
            int first = 0;
            int second = 0;
            int firstChild = -1;

            foreach (int v in graph[u])
            {
                if (parent[v] != u) continue;

                int cost = ((v & 1) == 1 ? 1 : 2) + down[v];

                if (cost > first)
                {
                    second = first;
                    first = cost;
                    firstChild = v;
                }
                else if (cost > second)
                {
                    second = cost;
                }
            }

            down[u] = first;
            bestValue[u] = first;
            secondBestValue[u] = second;
            bestChild[u] = firstChild;
        }

        int[] answer = new int[n];

        for (int i = 0; i < n; i++)
        {
            int u = order[i];
            answer[u] = Math.Max(down[u], up[u]);

            foreach (int v in graph[u])
            {
                if (parent[v] != u) continue;

                int siblingBest = bestChild[u] == v
                    ? secondBestValue[u]
                    : bestValue[u];

                int bestOutside = Math.Max(up[u], siblingBest);
                int costToEnterParent = ((u & 1) == 1) ? 1 : 2;

                up[v] = costToEnterParent + bestOutside;
            }
        }

        var output = new StringBuilder();
        for (int i = 0; i < n; i++)
        {
            if (i > 0) output.Append(' ');
            output.Append(answer[i]);
        }

        Console.WriteLine(output.ToString());
    }
}
