public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        MatchCollection matches = Regex.Matches(input, @"\d+");

        var nums = new List<int>();
        foreach (Match match in matches)
            nums.Add(int.Parse(match.Value));

        long count = 0;

        for (int i = 0; i < nums.Count; i++)
        {
            for (int j = i + 1; j < nums.Count; j++)
            {
                if (AreAlmostEqual(nums[i], nums[j]))
                    count++;
            }
        }

        Console.WriteLine(count);
    }

    private static bool AreAlmostEqual(int x, int y)
    {
        if (x == y)
            return true;

        return CanBecome(x, y) || CanBecome(y, x);
    }

    private static bool CanBecome(int source, int target)
    {
        char[] digits = source.ToString().ToCharArray();

        for (int i = 0; i < digits.Length; i++)
        {
            for (int j = i + 1; j < digits.Length; j++)
            {
                char temp = digits[i];
                digits[i] = digits[j];
                digits[j] = temp;

                int value = 0;
                for (int k = 0; k < digits.Length; k++)
                    value = value * 10 + (digits[k] - '0');

                temp = digits[i];
                digits[i] = digits[j];
                digits[j] = temp;

                if (value == target)
                    return true;
            }
        }

        return false;
    }
}
