    private const int Mod = 1000000007;

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<int> nums = ParseIntegers(input);

        if (nums.Count == 0)
        {
            Console.WriteLine(0);
            return;
        }

        int[] dp = new int[nums[0] + 1];
        for (int value = 0; value <= nums[0]; value++)
            dp[value] = 1;

        for (int i = 1; i < nums.Count; i++)
        {
            int[] prefix = new int[dp.Length];
            prefix[0] = dp[0];

            for (int value = 1; value < dp.Length; value++)
            {
                prefix[value] = prefix[value - 1] + dp[value];
                if (prefix[value] >= Mod)
                    prefix[value] -= Mod;
            }

            int requiredIncrease = Math.Max(0, nums[i] - nums[i - 1]);
            int[] next = new int[nums[i] + 1];

            for (int value = 0; value <= nums[i]; value++)
            {
                int maxPrevious = value - requiredIncrease;
                if (maxPrevious >= 0)
                {
                    if (maxPrevious >= prefix.Length)
                        maxPrevious = prefix.Length - 1;

                    next[value] = prefix[maxPrevious];
                }
            }

            dp = next;
        }

        long answer = 0;
        for (int i = 0; i < dp.Length; i++)
            answer = (answer + dp[i]) % Mod;

        Console.WriteLine(answer);
    }

    private static List<int> ParseIntegers(string input)
    {
        List<int> values = new List<int>();
        int current = 0;
        bool readingNumber = false;

        for (int i = 0; i <= input.Length; i++)
        {
            if (i < input.Length && char.IsDigit(input[i]))
            {
                current = current * 10 + (input[i] - '0');
                readingNumber = true;
            }
            else if (readingNumber)
            {
                values.Add(current);
                current = 0;
                readingNumber = false;
            }
        }

        return values;
    }
}
