using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        MatchCollection matches = Regex.Matches(input, @"\d+");

        if (matches.Count < 2)
            return;

        int n = int.Parse(matches[0].Value);
        int k = int.Parse(matches[1].Value);

        long[] factorial = new long[n + 1];
        factorial[0] = 1;
        for (int i = 1; i <= n; i++)
            factorial[i] = factorial[i - 1] * i;

        int halfLength = (n + 1) / 2;
        int start = PowerOfTen(halfLength - 1);
        int end = PowerOfTen(halfLength);

        HashSet<long> signatures = new HashSet<long>();
        long answer = 0;

        for (int half = start; half < end; half++)
        {
            long palindrome = BuildPalindrome(half, n % 2 == 1);

            if (palindrome % k != 0)
                continue;

            int[] counts = new int[10];
            long value = palindrome;

            while (value > 0)
            {
                counts[(int)(value % 10)]++;
                value /= 10;
            }

            long signature = 0;
            long multiplier = 1;
            for (int digit = 0; digit < 10; digit++)
            {
                signature += counts[digit] * multiplier;
                multiplier *= 11;
            }

            if (!signatures.Add(signature))
                continue;

            long denominator = 1;
            for (int digit = 0; digit < 10; digit++)
                denominator *= factorial[counts[digit]];

            long permutations = factorial[n] / denominator;

            if (counts[0] > 0)
            {
                long leadingZeroDenominator = factorial[counts[0] - 1];
                for (int digit = 1; digit < 10; digit++)
                    leadingZeroDenominator *= factorial[counts[digit]];

                permutations -= factorial[n - 1] / leadingZeroDenominator;
            }

            answer += permutations;
        }

        Console.WriteLine(answer);
    }

    private static long BuildPalindrome(int half, bool oddLength)
    {
        long palindrome = half;
        int remaining = oddLength ? half / 10 : half;

        while (remaining > 0)
        {
            palindrome = palindrome * 10 + remaining % 10;
            remaining /= 10;
        }

        return palindrome;
    }

    private static int PowerOfTen(int exponent)
    {
        int result = 1;
        for (int i = 0; i < exponent; i++)
            result *= 10;
        return result;
    }
