using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private struct Cell
    {
        public int Row;
        public int Col;
        public long Value;

        public Cell(int row, int col, long value)
        {
            Row = row;
            Col = col;
            Value = value;
        }
    }

    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }
            return buffer[position++];
        }

        public bool TryNextLong(out long value)
        {
            int c;
            do
            {
                c = ReadByte();
                if (c == -1)
                {
                    value = 0;
                    return false;
                }
            } while (c <= 32);

            bool negative = false;
            if (c == '-')
            {
                negative = true;
                c = ReadByte();
            }

            long result = 0;
            while (c >= '0' && c <= '9')
            {
                result = result * 10 + (c - '0');
                c = ReadByte();
            }

            value = negative ? -result : result;
            return true;
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();

        long rowCountValue;
        if (!scanner.TryNextLong(out rowCountValue))
            return;

        int rows = (int)rowCountValue;
        List<long> values = new List<long>();

        long value;
        while (scanner.TryNextLong(out value))
            values.Add(value);

        int columns = values.Count / rows;
        List<Cell> candidates = new List<Cell>(rows * 3);

        for (int row = 0; row < rows; row++)
        {
            long[] bestValues = { long.MinValue, long.MinValue, long.MinValue };
            int[] bestColumns = { -1, -1, -1 };

            for (int col = 0; col < columns; col++)
            {
                long current = values[row * columns + col];

                for (int position = 0; position < 3; position++)
                {
                    if (current > bestValues[position])
                    {
                        for (int shift = 2; shift > position; shift--)
                        {
                            bestValues[shift] = bestValues[shift - 1];
                            bestColumns[shift] = bestColumns[shift - 1];
                        }

                        bestValues[position] = current;
                        bestColumns[position] = col;
                        break;
                    }
                }
            }

            for (int i = 0; i < 3; i++)
                candidates.Add(new Cell(row, bestColumns[i], bestValues[i]));
        }

        long answer = long.MinValue;
        int count = candidates.Count;

        for (int i = 0; i < count - 2; i++)
        {
            Cell first = candidates[i];

            for (int j = i + 1; j < count - 1; j++)
            {
                Cell second = candidates[j];

                if (first.Row == second.Row || first.Col == second.Col)
                    continue;

                for (int k = j + 1; k < count; k++)
                {
                    Cell third = candidates[k];

                    if (third.Row == first.Row || third.Row == second.Row ||
                        third.Col == first.Col || third.Col == second.Col)
                        continue;

                    long sum = first.Value + second.Value + third.Value;
                    if (sum > answer)
                        answer = sum;
                }
            }
        }

        Console.WriteLine(answer);
    }
}
