    private sealed class FastScanner
    {
        private readonly TextReader reader;
        private readonly char[] buffer = new char[1 << 16];
        private int position;
        private int length;

        public FastScanner(TextReader reader)
        {
            this.reader = reader;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = reader.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c >= 0 && char.IsWhiteSpace((char)c));

            int value = 0;
            while (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value;
        }
    }

    public static void Main()
    {
        TextReader input = Console.In;
        string firstLine;

        do
        {
            firstLine = input.ReadLine();
        } while (firstLine != null && firstLine.Trim().Length == 0);

        if (firstLine == null)
            return;

        string[] parts = firstLine.Split(
            new[] { ' ', '\t' },
            StringSplitOptions.RemoveEmptyEntries
        );

        int n = parts.Length;
        int[] scores = new int[n];
        int[][] maximum = new int[n][];

        for (int i = 0; i < n; i++)
        {
            scores[i] = int.Parse(parts[i]);
            maximum[i] = new int[n];
            maximum[i][i] = scores[i];
        }

        for (int length = 2; length <= n; length++)
        {
            int lastLeft = n - length;

            for (int left = 0; left <= lastLeft; left++)
            {
                int right = left + length - 1;

                scores[left] ^= scores[left + 1];

                int best = scores[left];

                if (maximum[left][right - 1] > best)
                    best = maximum[left][right - 1];

                if (maximum[left + 1][right] > best)
                    best = maximum[left + 1][right];

                maximum[left][right] = best;
            }
        }

        FastScanner scanner = new FastScanner(input);
        int q = scanner.NextInt();
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < q; i++)
        {
            int left = scanner.NextInt();
            int right = scanner.NextInt();

            if (i > 0)
                output.Append(' ');

            output.Append(maximum[left][right]);
        }

        Console.WriteLine(output.ToString());
    }
}
