using System;
using System.IO;

public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        int position = 0;
        int n = ReadNextInt(input, ref position);
        int k = ReadNextInt(input, ref position);

        int halfLength = (n + 1) / 2;

        int[] powersOfTen = new int[n];
        powersOfTen[0] = 1 % k;
        for (int i = 1; i < n; i++)
            powersOfTen[i] = (powersOfTen[i - 1] * 10) % k;

        int[] weights = new int[halfLength];
        for (int i = 0; i < halfLength; i++)
        {
            int mirror = n - 1 - i;
            if (i == mirror)
                weights[i] = powersOfTen[i];
            else
                weights[i] = (powersOfTen[i] + powersOfTen[mirror]) % k;
        }

        // possible[i, r] indicates whether positions i through the end
        // can contribute a remainder r modulo k.
        bool[] possible = new bool[(halfLength + 1) * k];
        possible[halfLength * k] = true;

        for (int i = halfLength - 1; i >= 0; i--)
        {
            int currentBase = i * k;
            int nextBase = (i + 1) * k;

            for (int suffixRemainder = 0; suffixRemainder < k; suffixRemainder++)
            {
                if (!possible[nextBase + suffixRemainder])
                    continue;

                for (int digit = 0; digit <= 9; digit++)
                {
                    int remainder = (suffixRemainder + digit * weights[i]) % k;
                    possible[currentBase + remainder] = true;
                }
            }
        }

        char[] answer = new char[n];
        int prefixRemainder = 0;

        for (int i = 0; i < halfLength; i++)
        {
            int minimumDigit = (i == 0) ? 1 : 0;
            int nextBase = (i + 1) * k;

            for (int digit = 9; digit >= minimumDigit; digit--)
            {
                int newRemainder = (prefixRemainder + digit * weights[i]) % k;
                int requiredSuffix = (k - newRemainder) % k;

                if (possible[nextBase + requiredSuffix])
                {
                    answer[i] = (char)('0' + digit);
                    answer[n - 1 - i] = (char)('0' + digit);
                    prefixRemainder = newRemainder;
                    break;
                }
            }
        }

        Console.WriteLine(new string(answer));
    }

    private static int ReadNextInt(string input, ref int position)
    {
        while (position < input.Length && !char.IsDigit(input[position]))
            position++;

        int value = 0;
        while (position < input.Length && char.IsDigit(input[position]))
        {
            value = value * 10 + (input[position] - '0');
            position++;
        }

        return value;
    }
}
