using System;
using System.Collections.Generic;

public class Program
{
    private class Deque<T>
    {
        private T[] data;
        private int head;
        private int count;

        public Deque(int capacity)
        {
            data = new T[Math.Max(4, capacity)];
        }

        public int Count { get { return count; } }

        public void AddFirst(T item)
        {
            EnsureCapacity();
            head = (head - 1 + data.Length) % data.Length;
            data[head] = item;
            count++;
        }

        public void AddLast(T item)
        {
            EnsureCapacity();
            data[(head + count) % data.Length] = item;
            count++;
        }

        public T RemoveFirst()
        {
            T item = data[head];
            head = (head + 1) % data.Length;
            count--;
            return item;
        }

        private void EnsureCapacity()
        {
            if (count < data.Length)
                return;

            T[] larger = new T[data.Length * 2];
            for (int i = 0; i < count; i++)
                larger[i] = data[(head + i) % data.Length];

            data = larger;
            head = 0;
        }
    }

    public static void Main()
    {
        string line = ReadNonEmptyLine();
        if (line == null)
            return;

        int rows = int.Parse(line.Trim());
        int[][] grid = new int[rows][];

        for (int i = 0; i < rows; i++)
        {
            string[] parts = ReadNonEmptyLine()
                .Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

            grid[i] = new int[parts.Length];
            for (int j = 0; j < parts.Length; j++)
                grid[i][j] = int.Parse(parts[j]);
        }

        int health = int.Parse(ReadNonEmptyLine().Trim());
        int cols = grid[0].Length;
        int total = rows * cols;

        int[] distance = new int[total];
        for (int i = 0; i < total; i++)
            distance[i] = int.MaxValue;

        distance[0] = grid[0][0];

        Deque<int> deque = new Deque<int>(total);
        deque.AddFirst(0);

        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        while (deque.Count > 0)
        {
            int cell = deque.RemoveFirst();
            int r = cell / cols;
            int c = cell % cols;

            for (int d = 0; d < 4; d++)
            {
                int nr = r + dr[d];
                int nc = c + dc[d];

                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols)
                    continue;

                int next = nr * cols + nc;
                int cost = grid[nr][nc];
                int newDistance = distance[cell] + cost;

                if (newDistance < distance[next])
                {
                    distance[next] = newDistance;

                    if (cost == 0)
                        deque.AddFirst(next);
                    else
                        deque.AddLast(next);
                }
            }
        }

        Console.WriteLine(distance[total - 1] < health ? "true" : "false");
    }

    private static string ReadNonEmptyLine()
    {
        string line;
        while ((line = Console.ReadLine()) != null)
        {
            if (!string.IsNullOrWhiteSpace(line))
                return line;
        }
        return null;
    }
}
