            (char[])null,
            StringSplitOptions.RemoveEmptyEntries
        );

        target = target.Trim();

        int totalLength = 0;
        foreach (string word in words)
            totalLength += word.Length;

        int[] trie = new int[(totalLength + 1) * 26];
        int nodeCount = 1;

        foreach (string word in words)
        {
            int node = 0;

            foreach (char ch in word)
            {
                int index = node * 26 + (ch - 'a');

                if (trie[index] == 0)
                    trie[index] = nodeCount++;

                node = trie[index];
            }
        }

        int n = target.Length;
        int jumps = 0;
        int currentEnd = 0;
        int farthest = 0;

        for (int start = 0; start < n; start++)
        {
            if (start > farthest)
            {
                Console.WriteLine(-1);
                return;
            }

            int node = 0;
            int end = start;

            while (end < n)
            {
                int nextNode = trie[node * 26 + (target[end] - 'a')];
                if (nextNode == 0)
                    break;

                node = nextNode;
                end++;
            }

            if (end > farthest)
                farthest = end;

            if (start == currentEnd)
            {
                if (farthest == currentEnd)
                {
                    Console.WriteLine(-1);
                    return;
                }

                jumps++;
                currentEnd = farthest;

                if (currentEnd >= n)
                {
                    Console.WriteLine(jumps);
                    return;
                }
            }
        }

        Console.WriteLine(currentEnd >= n ? jumps : -1);
