using System;
using System.IO;

public class Program
{
    private const int BoardSize = 50;

    private static int pawnCount;
    private static int nodeCount;
    private static int[,] distances;
    private static int[] memo;

    private static readonly int[] dx = { 2, 2, -2, -2, 1, 1, -1, -1 };
    private static readonly int[] dy = { 1, -1, 1, -1, 2, -2, 2, -2 };

    private static int Solve(int remainingMask, int current)
    {
        if (remainingMask == 0)
            return 0;

        int memoIndex = remainingMask * nodeCount + current;
        if (memo[memoIndex] != -1)
            return memo[memoIndex];

        int captured = pawnCount - PopCount(remainingMask);
        bool aliceTurn = (captured % 2 == 0);

        int best = aliceTurn ? int.MinValue : int.MaxValue;

        for (int pawn = 0; pawn < pawnCount; pawn++)
        {
            int bit = 1 << pawn;
            if ((remainingMask & bit) == 0)
                continue;

            int value = distances[current, pawn] +
                        Solve(remainingMask ^ bit, pawn);

            if (aliceTurn)
            {
                if (value > best)
                    best = value;
            }
            else
            {
                if (value < best)
                    best = value;
            }
        }

        memo[memoIndex] = best;
        return best;
    }

    private static int PopCount(int value)
    {
        int count = 0;
        while (value != 0)
        {
            value &= value - 1;
            count++;
        }
        return count;
    }

    private static int[] Bfs(int startX, int startY)
    {
        int totalCells = BoardSize * BoardSize;
        int[] distance = new int[totalCells];
        for (int i = 0; i < totalCells; i++)
            distance[i] = -1;

        int[] queue = new int[totalCells];
        int head = 0;
        int tail = 0;

        int start = startX * BoardSize + startY;
        distance[start] = 0;
        queue[tail++] = start;

        while (head < tail)
        {
            int cell = queue[head++];
            int x = cell / BoardSize;
            int y = cell % BoardSize;

            for (int move = 0; move < 8; move++)
            {
                int nx = x + dx[move];
                int ny = y + dy[move];

                if (nx < 0 || nx >= BoardSize || ny < 0 || ny >= BoardSize)
                    continue;

                int next = nx * BoardSize + ny;
                if (distance[next] != -1)
                    continue;

                distance[next] = distance[cell] + 1;
                queue[tail++] = next;
            }
        }

        return distance;
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int kx = scanner.NextInt();
        int ky = scanner.NextInt();
        pawnCount = scanner.NextInt();

        nodeCount = pawnCount + 1;
        int[] xs = new int[nodeCount];
        int[] ys = new int[nodeCount];

        for (int i = 0; i < pawnCount; i++)
        {
            xs[i] = scanner.NextInt();
            ys[i] = scanner.NextInt();
        }

        // The knight's initial position is stored as the last node.
        xs[pawnCount] = kx;
        ys[pawnCount] = ky;

        distances = new int[nodeCount, pawnCount];

        for (int source = 0; source < nodeCount; source++)
        {
            int[] boardDistances = Bfs(xs[source], ys[source]);

            for (int pawn = 0; pawn < pawnCount; pawn++)
            {
                int target = xs[pawn] * BoardSize + ys[pawn];
                distances[source, pawn] = boardDistances[target];
            }
        }

        int maskCount = 1 << pawnCount;
        memo = new int[maskCount * nodeCount];
        for (int i = 0; i < memo.Length; i++)
            memo[i] = -1;

        int answer = Solve(maskCount - 1, pawnCount);
        Console.WriteLine(answer);
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value * sign;
        }
    }
}
