using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

public class Program
{
    private struct Interval
    {
        public int Left;
        public int Right;
        public long Weight;
        public int Index;
    }

    private sealed class IntervalComparer : IComparer<Interval>
    {
        public int Compare(Interval x, Interval y)
        {
            if (x.Right != y.Right)
                return x.Right < y.Right ? -1 : 1;
            if (x.Left != y.Left)
                return x.Left < y.Left ? -1 : 1;
            return x.Index.CompareTo(y.Index);
        }
    }

    private struct State
    {
        public long Score;
        public int Count;
        public int A;
        public int B;
        public int C;
        public int D;
    }

    private static int GetIndex(State state, int position)
    {
        switch (position)
        {
            case 0: return state.A;
            case 1: return state.B;
            case 2: return state.C;
            default: return state.D;
        }
    }

    private static int CompareLexicographically(State x, State y)
    {
        int length = Math.Min(x.Count, y.Count);

        for (int i = 0; i < length; i++)
        {
            int xi = GetIndex(x, i);
            int yi = GetIndex(y, i);

            if (xi != yi)
                return xi < yi ? -1 : 1;
        }

        if (x.Count == y.Count)
            return 0;

        return x.Count < y.Count ? -1 : 1;
    }

    private static bool IsBetter(State candidate, State current)
    {
        if (candidate.Score != current.Score)
            return candidate.Score > current.Score;

        return CompareLexicographically(candidate, current) < 0;
    }

    private static State AddInterval(State state, int index, long weight)
    {
        State result = state;
        result.Score += weight;

        if (state.Count == 0)
        {
            result.A = index;
        }
        else if (state.Count == 1)
        {
            if (index < state.A)
            {
                result.A = index;
                result.B = state.A;
            }
            else
            {
                result.B = index;
            }
        }
        else if (state.Count == 2)
        {
            if (index < state.A)
            {
                result.A = index;
                result.B = state.A;
                result.C = state.B;
            }
            else if (index < state.B)
            {
                result.B = index;
                result.C = state.B;
            }
            else
            {
                result.C = index;
            }
        }
        else
        {
            if (index < state.A)
            {
                result.A = index;
                result.B = state.A;
                result.C = state.B;
                result.D = state.C;
            }
            else if (index < state.B)
            {
                result.B = index;
                result.C = state.B;
                result.D = state.C;
            }
            else if (index < state.C)
            {
                result.C = index;
                result.D = state.C;
            }
            else
            {
                result.D = index;
            }
        }

        result.Count = state.Count + 1;
        return result;
    }

    private static int FindCompatibleCount(Interval[] intervals, int left)
    {
        int low = 0;
        int high = intervals.Length;

        while (low < high)
        {
            int mid = low + (high - low) / 2;

            if (intervals[mid].Right < left)
                low = mid + 1;
            else
                high = mid;
        }

        return low;
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());
        int n = scanner.NextInt();

        if (n <= 0)
        {
            Console.WriteLine();
            return;
        }

        Interval[] intervals = new Interval[n];

        for (int i = 0; i < n; i++)
        {
            intervals[i] = new Interval
            {
                Left = scanner.NextInt(),
                Right = scanner.NextInt(),
                Weight = scanner.NextLong(),
                Index = i
            };
        }

        Array.Sort(intervals, new IntervalComparer());

        int[] compatibleCounts = new int[n];
        for (int i = 0; i < n; i++)
            compatibleCounts[i] = FindCompatibleCount(intervals, intervals[i].Left);

        State[] previous = new State[n + 1];
        State[] current = new State[n + 1];

        State answer = previous[n];

        for (int selectedCount = 1; selectedCount <= 4; selectedCount++)
        {
            current[0] = new State { Score = -1 };

            for (int i = 1; i <= n; i++)
            {
                State best = current[i - 1];
                State source = previous[compatibleCounts[i - 1]];

                if (source.Score >= 0)
                {
                    State candidate = AddInterval(
                        source,
                        intervals[i - 1].Index,
                        intervals[i - 1].Weight
                    );

                    if (IsBetter(candidate, best))
                        best = candidate;
                }

                current[i] = best;
            }

            State[] temporary = previous;
            previous = current;
            current = temporary;

            if (previous[n].Score >= 0 && IsBetter(previous[n], answer))
                answer = previous[n];
        }

        StringBuilder output = new StringBuilder();

        for (int i = 0; i < answer.Count; i++)
        {
            if (i > 0)
                output.Append(' ');

            output.Append(GetIndex(answer, i));
        }

        Console.WriteLine(output.ToString());
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            return (int)NextLong();
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            }
            while (c != -1 && c != '-' && (c < '0' || c > '9'));

            if (c == -1)
                return 0;

            bool negative = false;
            if (c == '-')
            {
                negative = true;
                c = Read();
            }

            long value = 0;
            while (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return negative ? -value : value;
        }
    }
}
