        string firstLine;
        do
        {
            firstLine = Console.ReadLine();
        }
        while (firstLine != null && firstLine.Trim().Length == 0);

        if (firstLine == null)
            return;

        int rows = int.Parse(firstLine.Trim());
        int[] rowsForValue = new int[101];

        for (int row = 0; row < rows; row++)
        {
            string line;
            do
            {
                line = Console.ReadLine();
            }
            while (line != null && line.Trim().Length == 0);

            if (line == null)
                break;

            string[] parts = line.Split(new[] { ' ', '\t' },
                                        StringSplitOptions.RemoveEmptyEntries);

            foreach (string part in parts)
            {
                int value = int.Parse(part);
                rowsForValue[value] |= 1 << row;
            }
        }

        int maskCount = 1 << rows;
        int[] dp = new int[maskCount];

        for (int i = 1; i < maskCount; i++)
            dp[i] = -1;

        for (int value = 1; value <= 100; value++)
        {
            int availableRows = rowsForValue[value];
            if (availableRows == 0)
                continue;

            int[] next = (int[])dp.Clone();

            for (int mask = 0; mask < maskCount; mask++)
            {
                if (dp[mask] < 0)
                    continue;

                int choices = availableRows & ~mask;
                while (choices != 0)
                {
                    int bit = choices & -choices;
                    int newMask = mask | bit;
                    int score = dp[mask] + value;

                    if (score > next[newMask])
                        next[newMask] = score;

                    choices -= bit;
                }
            }

            dp = next;
        }

        int answer = 0;
        for (int mask = 0; mask < maskCount; mask++)
            answer = Math.Max(answer, dp[mask]);

        Console.WriteLine(answer);
    }
}
