using System;
using System.Collections.Generic;

public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<int> values = ParseIntegers(input);

        if (values.Count < 2)
            return;

        int k = values[values.Count - 1];
        int n = values.Count - 1;
        int[] nums = new int[n];

        for (int i = 0; i < n; i++)
            nums[i] = values[i];

        const int MaxOr = 128;
        bool[,] prefix = new bool[n + 1, MaxOr];
        bool[,] suffix = new bool[n + 1, MaxOr];
        bool[,] dp = new bool[k + 1, MaxOr];

        dp[0, 0] = true;

        for (int i = 0; i < n; i++)
        {
            int maxCount = Math.Min(k, i + 1);

            for (int count = maxCount; count >= 1; count--)
            {
                for (int orValue = 0; orValue < MaxOr; orValue++)
                {
                    if (dp[count - 1, orValue])
                        dp[count, orValue | nums[i]] = true;
                }
            }

            for (int orValue = 0; orValue < MaxOr; orValue++)
                prefix[i + 1, orValue] = dp[k, orValue];
        }

        dp = new bool[k + 1, MaxOr];
        dp[0, 0] = true;

        int processed = 0;
        for (int i = n - 1; i >= 0; i--)
        {
            processed++;
            int maxCount = Math.Min(k, processed);

            for (int count = maxCount; count >= 1; count--)
            {
                for (int orValue = 0; orValue < MaxOr; orValue++)
                {
                    if (dp[count - 1, orValue])
                        dp[count, orValue | nums[i]] = true;
                }
            }

            for (int orValue = 0; orValue < MaxOr; orValue++)
                suffix[i, orValue] = dp[k, orValue];
        }

        int answer = 0;

        for (int split = k; split <= n - k; split++)
        {
            for (int leftOr = 0; leftOr < MaxOr; leftOr++)
            {
                if (!prefix[split, leftOr])
                    continue;

                for (int rightOr = 0; rightOr < MaxOr; rightOr++)
                {
                    if (suffix[split, rightOr])
                        answer = Math.Max(answer, leftOr ^ rightOr);
                }
            }
        }

        Console.WriteLine(answer);
    }

    private static List<int> ParseIntegers(string input)
    {
        List<int> result = new List<int>();
        int i = 0;

        while (i < input.Length)
        {
            while (i < input.Length && !char.IsDigit(input[i]))
                i++;

            if (i >= input.Length)
                break;

            int value = 0;
            while (i < input.Length && char.IsDigit(input[i]))
            {
                value = value * 10 + (input[i] - '0');
                i++;
            }

            result.Add(value);
        }

        return result;
    }
}
