public class Program
{
    private static int[] ComputeZ(string text)
    {
        int n = text.Length;
        int[] z = new int[n];
        int left = 0, right = 0;

        for (int i = 1; i < n; i++)
        {
            if (i <= right)
                z[i] = Math.Min(right - i + 1, z[i - left]);

            while (i + z[i] < n && text[z[i]] == text[i + z[i]])
                z[i]++;

            if (i + z[i] - 1 > right)
            {
                left = i;
                right = i + z[i] - 1;
            }
        }

        z[0] = n;
        return z;
    }

    private static string Reverse(string value)
    {
        char[] chars = value.ToCharArray();
        Array.Reverse(chars);
        return new string(chars);
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split(
            (char[])null,
            StringSplitOptions.RemoveEmptyEntries
        );

        if (tokens.Length < 2)
            return;

        string s = tokens[0];
        string pattern = tokens[1];

        int n = s.Length;
        int m = pattern.Length;

        if (m > n)
        {
            Console.WriteLine(-1);
            return;
        }

        string forward = pattern + "#" + s;
        int[] forwardZ = ComputeZ(forward);

        string reversedPattern = Reverse(pattern);
        string reversedS = Reverse(s);
        string backward = reversedPattern + "#" + reversedS;
        int[] backwardZ = ComputeZ(backward);

        int offset = m + 1;

        for (int start = 0; start <= n - m; start++)
        {
            int prefixMatches = Math.Min(m, forwardZ[offset + start]);
            int reversedStart = n - (start + m);
            int suffixMatches = Math.Min(m, backwardZ[offset + reversedStart]);

            if (prefixMatches + suffixMatches >= m - 1)
            {
                Console.WriteLine(start);
                return;
            }
        }

        Console.WriteLine(-1);
    }
}
