using System;
using System.Collections.Generic;
using System.Text;

public class Program
{
    static long[] ParseNumbers(string line)
    {
        List<long> numbers = new List<long>();
        long value = 0;
        bool reading = false;

        for (int i = 0; i <= line.Length; i++)
        {
            char c = i < line.Length ? line[i] : ' ';
            if (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                reading = true;
            }
            else if (reading)
            {
                numbers.Add(value);
                value = 0;
                reading = false;
            }
        }

        return numbers.ToArray();
    }

    public static void Main()
    {
        string numsLine = null;
        string queriesLine = null;
        string line;

        while ((line = Console.ReadLine()) != null)
        {
            if (string.IsNullOrWhiteSpace(line))
                continue;

            if (numsLine == null)
                numsLine = line;
            else
            {
                queriesLine = line;
                break;
            }
        }

        if (numsLine == null || queriesLine == null)
            return;

        long[] parsedNums = ParseNumbers(numsLine);
        long[] queries = ParseNumbers(queriesLine);

        int maxValue = 0;
        for (int i = 0; i < parsedNums.Length; i++)
        {
            int value = (int)parsedNums[i];
            if (value > maxValue)
                maxValue = value;
        }

        int[] frequency = new int[maxValue + 1];
        for (int i = 0; i < parsedNums.Length; i++)
            frequency[(int)parsedNums[i]]++;

        long[] exactGcdPairs = new long[maxValue + 1];

        for (int gcd = maxValue; gcd >= 1; gcd--)
        {
            long divisibleCount = 0;

            for (int multiple = gcd; multiple <= maxValue; multiple += gcd)
                divisibleCount += frequency[multiple];

            long pairs = divisibleCount * (divisibleCount - 1) / 2;

            for (int multiple = gcd + gcd; multiple <= maxValue; multiple += gcd)
                pairs -= exactGcdPairs[multiple];

            exactGcdPairs[gcd] = pairs;
        }

        long[] prefix = new long[maxValue + 1];
        for (int gcd = 1; gcd <= maxValue; gcd++)
            prefix[gcd] = prefix[gcd - 1] + exactGcdPairs[gcd];

        StringBuilder output = new StringBuilder();

        for (int i = 0; i < queries.Length; i++)
        {
            long target = queries[i] + 1;
            int left = 1;
            int right = maxValue;

            while (left < right)
            {
                int middle = left + (right - left) / 2;
                if (prefix[middle] >= target)
                    right = middle;
                else
                    left = middle + 1;
            }

            if (i > 0)
                output.Append(' ');
            output.Append(left);
        }

        Console.WriteLine(output.ToString());
    }
}
