            right[i] = -1;

        int source = n - 1;
        for (int target = m - 1; target >= 0; target--)
        {
            while (source >= 0 && word1[source] != word2[target])
                source--;

            if (source < 0)
                break;

            right[target] = source;
            source--;
        }

        int[] result = new int[m];
        source = 0;
        bool mismatchUsed = false;

        for (int target = 0; target < m; target++)
        {
