            while (source < n)
            {
                if (word1[source] == word2[target])
                {
                    result[target] = source++;
                    found = true;
                    break;
                }

                bool suffixCanMatchExactly =
                    target == m - 1 || right[target + 1] > source;

                if (!mismatchUsed && suffixCanMatchExactly)
                {
                    result[target] = source++;
                    mismatchUsed = true;
                    found = true;
                    break;
                }

                source++;
            }

            if (!found)
            {
                Console.WriteLine();
                return;
            }
