public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value * sign;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int k = scanner.NextInt();

        int stayRows = scanner.NextInt();
        int[,] stayScore = new int[stayRows, n];

        for (int day = 0; day < stayRows; day++)
        {
            for (int city = 0; city < n; city++)
            {
                stayScore[day, city] = scanner.NextInt();
            }
        }

        int travelRows = scanner.NextInt();
        int[,] travelScore = new int[travelRows, n];

        for (int from = 0; from < travelRows; from++)
        {
            for (int to = 0; to < n; to++)
            {
                travelScore[from, to] = scanner.NextInt();
            }
        }

        int[] dp = new int[n];

        for (int day = 0; day < k; day++)
        {
            int[] next = new int[n];

            for (int destination = 0; destination < n; destination++)
            {
                int best = dp[destination] + stayScore[day, destination];

                for (int current = 0; current < n; current++)
                {
                    if (current == destination) continue;

                    int score = dp[current] + travelScore[current, destination];
                    if (score > best)
                    {
                        best = score;
                    }
                }

                next[destination] = best;
            }

            dp = next;
        }

        int answer = dp[0];
        for (int city = 1; city < n; city++)
        {
            if (dp[city] > answer)
            {
                answer = dp[city];
            }
        }

        Console.WriteLine(answer);
    }
}
