        string s = Console.In.ReadToEnd().Trim();
        int n = s.Length;
        int offset = n;
        int width = 2 * n + 1;

        int[][] dp = new int[3][];
        int[][] next = new int[3][];

        for (int move = 0; move < 3; move++)
        {
            dp[move] = new int[width];
            next[move] = new int[width];
        }

        int aliceMove = GetMove(s[0]);
        for (int bobMove = 0; bobMove < 3; bobMove++)
        {
            int score = GetScore(bobMove, aliceMove);
            dp[bobMove][offset + score] = 1;
        }

        for (int round = 1; round < n; round++)
        {
            for (int move = 0; move < 3; move++)
                Array.Clear(next[move], 0, width);

            aliceMove = GetMove(s[round]);

            for (int bobMove = 0; bobMove < 3; bobMove++)
            {
                int scoreChange = GetScore(bobMove, aliceMove);

                for (int score = -round; score <= round; score++)
                {
                    int sourceIndex = offset + score;
                    int ways = 0;

                    for (int previousMove = 0; previousMove < 3; previousMove++)
                    {
                        if (previousMove != bobMove)
                        {
                            ways += dp[previousMove][sourceIndex];
                            if (ways >= Mod)
                                ways -= Mod;
                        }
                    }

                    if (ways != 0)
                    {
                        int targetIndex = offset + score + scoreChange;
                        next[bobMove][targetIndex] = ways;
                    }
                }
            }

            int[][] temp = dp;
            dp = next;
            next = temp;
        }

        long answer = 0;
        for (int move = 0; move < 3; move++)
        {
            for (int score = 1; score <= n; score++)
            {
                answer += dp[move][offset + score];
                if (answer >= Mod)
                    answer -= Mod;
            }
        }

        Console.WriteLine(answer);
    }

    private static int GetMove(char creature)
    {
        if (creature == 'F') return 0;
        if (creature == 'W') return 1;
        return 2; // E
    }

    private static int GetScore(int bobMove, int aliceMove)
    {
        if (bobMove == aliceMove)
            return 0;

        return (bobMove - aliceMove + 3) % 3 == 1 ? 1 : -1;
    }
}
