using System.Collections.Generic;
using System.Text.RegularExpressions;

public class Program
{
    static long Gcd(long a, long b)
    {
        while (b != 0)
        {
            long temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }

    static long Lcm(long a, long b)
    {
        return a / Gcd(a, b) * b;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        MatchCollection matches = Regex.Matches(input, @"\d+");
        var nums = new List<int>();

        foreach (Match match in matches)
            nums.Add(int.Parse(match.Value));

        long maximumScore = 0;

        // removed == -1 means no element is removed.
        for (int removed = -1; removed < nums.Count; removed++)
        {
            long gcd = 0;
            long lcm = 1;
            int remaining = 0;

            for (int i = 0; i < nums.Count; i++)
            {
                if (i == removed)
                    continue;

                gcd = Gcd(gcd, nums[i]);
                lcm = Lcm(lcm, nums[i]);
                remaining++;
            }

            long score = remaining == 0 ? 0 : gcd * lcm;
            maximumScore = Math.Max(maximumScore, score);
        }

        Console.WriteLine(maximumScore);
    }
}
