        var frequency = new Dictionary<int, int>();

        foreach (int number in nums)
        {
            total += number;
            int count;
            frequency.TryGetValue(number, out count);
            frequency[number] = count + 1;
        }

        int largestOutlier = int.MinValue;

        foreach (KeyValuePair<int, int> entry in frequency)
        {
            int outlier = entry.Key;
            long remaining = total - outlier;

            if (remaining % 2 != 0)
                continue;

            long sumValueLong = remaining / 2;
            if (sumValueLong < int.MinValue || sumValueLong > int.MaxValue)
                continue;

            int sumValue = (int)sumValueLong;
            int sumCount;

            if (!frequency.TryGetValue(sumValue, out sumCount))
                continue;

            if (sumValue == outlier && sumCount < 2)
                continue;

            if (outlier > largestOutlier)
                largestOutlier = outlier;
        }

        Console.WriteLine(largestOutlier);
    }

    private static List<int> ParseIntegers(string input)
    {
        var result = new List<int>();

        for (int i = 0; i < input.Length;)
        {
            while (i < input.Length &&
                   !char.IsDigit(input[i]) &&
                   input[i] != '-')
            {
                i++;
            }

            if (i >= input.Length)
                break;

            int sign = 1;
            if (input[i] == '-')
            {
                sign = -1;
                i++;

                if (i >= input.Length || !char.IsDigit(input[i]))
                    continue;
            }

            int value = 0;
            while (i < input.Length && char.IsDigit(input[i]))
            {
                value = value * 10 + (input[i] - '0');
                i++;
