using System;
using System.Collections.Generic;
using System.Text;

public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<int> numbers = new List<int>();
        string s = "";

        int p = 0;
        while (p < input.Length)
        {
            if (input[p] == '-' || char.IsDigit(input[p]))
            {
                int sign = 1;
                if (input[p] == '-')
                {
                    sign = -1;
                    p++;
                }

                int value = 0;
                while (p < input.Length && char.IsDigit(input[p]))
                {
                    value = value * 10 + (input[p] - '0');
                    p++;
                }
                numbers.Add(sign * value);
            }
            else if (input[p] >= 'a' && input[p] <= 'z')
            {
                int start = p;
                while (p < input.Length && input[p] >= 'a' && input[p] <= 'z')
                    p++;
                s = input.Substring(start, p - start);
            }
            else
            {
                p++;
            }
        }

        int n = s.Length;
        if (n == 0)
        {
            Console.WriteLine();
            return;
        }

        int[] parent = numbers.ToArray();
        List<int>[] children = new List<int>[n];
        for (int i = 0; i < n; i++)
            children[i] = new List<int>();

        for (int i = 1; i < n; i++)
            children[parent[i]].Add(i);

        int[] reverseOrder = new int[n];
        int orderCount = 0;
        Stack<int> stack = new Stack<int>();
        stack.Push(0);

        while (stack.Count > 0)
        {
            int node = stack.Pop();
            reverseOrder[orderCount++] = node;

            List<int> list = children[node];
            for (int i = 0; i < list.Count; i++)
                stack.Push(list[i]);
        }

        char[] postorderString = new char[n];
        int[] subtreeSize = new int[n];
        int[] right = new int[n];

        for (int pos = 0; pos < n; pos++)
        {
            int node = reverseOrder[n - 1 - pos];
            int size = 1;

            List<int> list = children[node];
            for (int i = 0; i < list.Count; i++)
                size += subtreeSize[list[i]];

            subtreeSize[node] = size;
            right[node] = pos;
            postorderString[pos] = s[node];
        }

        int[] odd = BuildOddRadii(postorderString);
        int[] even = BuildEvenRadii(postorderString);

        bool[] answer = new bool[n];

        for (int node = 0; node < n; node++)
        {
            int r = right[node];
            int l = r - subtreeSize[node] + 1;
            int length = r - l + 1;

            if ((length & 1) == 1)
            {
                int center = (l + r) / 2;
                answer[node] = odd[center] >= length / 2 + 1;
            }
            else
            {
                int center = (l + r + 1) / 2;
                answer[node] = even[center] >= length / 2;
            }
        }

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < n; i++)
        {
            if (i > 0)
                output.Append(' ');
            output.Append(answer[i] ? "true" : "false");
        }

        Console.WriteLine(output.ToString());
    }

    private static int[] BuildOddRadii(char[] text)
    {
        int n = text.Length;
        int[] radius = new int[n];
        int left = 0;
        int right = -1;

        for (int i = 0; i < n; i++)
        {
            int k = i > right
                ? 1
                : Math.Min(radius[left + right - i], right - i + 1);

            while (i - k >= 0 && i + k < n && text[i - k] == text[i + k])
                k++;

            radius[i] = k;

            if (i + k - 1 > right)
            {
                left = i - k + 1;
                right = i + k - 1;
            }
        }

        return radius;
    }

    private static int[] BuildEvenRadii(char[] text)
    {
        int n = text.Length;
        int[] radius = new int[n];
        int left = 0;
        int right = -1;

        for (int i = 0; i < n; i++)
        {
            int k = i > right
                ? 0
                : Math.Min(radius[left + right - i + 1], right - i + 1);

            while (i - k - 1 >= 0 && i + k < n &&
                   text[i - k - 1] == text[i + k])
            {
                k++;
            }

            radius[i] = k;

            if (i + k - 1 > right)
            {
                left = i - k;
                right = i + k - 1;
            }
        }

        return radius;
    }
}
