    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        int n = int.Parse(tokens[0]);
        int x = int.Parse(tokens[1]);
        int y = int.Parse(tokens[2]);

        int limit = Math.Min(n, x);
        long[] stirling = new long[limit + 1];
        stirling[0] = 1;

        for (int i = 1; i <= n; i++)
        {
            int upper = Math.Min(i, limit);
            for (int k = upper; k >= 1; k--)
            {
                stirling[k] = (stirling[k - 1] + k * stirling[k]) % Mod;
            }
            stirling[0] = 0;
        }

        long answer = 0;
        long fallingFactorial = 1;
        long scoreWays = 1;

        for (int k = 1; k <= limit; k++)
        {
            fallingFactorial = fallingFactorial * (x - k + 1) % Mod;
            scoreWays = scoreWays * y % Mod;

            long ways = stirling[k] * fallingFactorial % Mod;
            ways = ways * scoreWays % Mod;
            answer = (answer + ways) % Mod;
        }

        Console.WriteLine(answer);
    }
