            if ((num & 1) == 0)
            {
                answers.Add("-1");
                continue;
            }

            int trailingOnes = 0;
            int value = num;

            while ((value & 1) == 1)
            {
                trailingOnes++;
                value >>= 1;
            }

            int ans = num - (1 << (trailingOnes - 1));
            answers.Add(ans.ToString());
        }

        Console.WriteLine(string.Join(" ", answers));
    }
