        List<int> nums = ParseIntegers(input);

        if (nums.Count <= 1)
        {
            Console.WriteLine(0);
            return;
        }

        int maxValue = 0;
        for (int i = 0; i < nums.Count; i++)
            maxValue = Math.Max(maxValue, nums[i]);

        int[] smallestPrimeFactor = BuildSmallestPrimeFactors(maxValue);
        int operations = 0;

        for (int i = nums.Count - 2; i >= 0; i--)
        {
            if (nums[i] <= nums[i + 1])
                continue;

            int reduced = smallestPrimeFactor[nums[i]];

            if (nums[i] <= 1 || reduced == nums[i] || reduced > nums[i + 1])
            {
                Console.WriteLine(-1);
                return;
            }

            nums[i] = reduced;
            operations++;
        }

        Console.WriteLine(operations);
    }

    private static int[] BuildSmallestPrimeFactors(int maxValue)
    {
        int[] spf = new int[maxValue + 1];

        if (maxValue >= 1)
            spf[1] = 1;

        for (int i = 2; i <= maxValue; i++)
        {
            if (spf[i] != 0)
                continue;

            spf[i] = i;

            if ((long)i * i > maxValue)
                continue;

            for (long j = (long)i * i; j <= maxValue; j += i)
            {
                if (spf[(int)j] == 0)
                    spf[(int)j] = i;
            }
        }

        return spf;
    }

    private static List<int> ParseIntegers(string input)
    {
        List<int> values = new List<int>();

        for (int i = 0; i < input.Length;)
        {
            while (i < input.Length && !char.IsDigit(input[i]) && input[i] != '-')
                i++;

            if (i >= input.Length)
                break;

            int sign = 1;
            if (input[i] == '-')
            {
                sign = -1;
                i++;
            }

            int value = 0;
            bool hasDigit = false;

            while (i < input.Length && char.IsDigit(input[i]))
            {
                hasDigit = true;
                value = value * 10 + (input[i] - '0');
                i++;
            }

            if (hasDigit)
                values.Add(value * sign);
        }

        return values;
    }
