using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private const int Mod = 1000000007;
    private const int MaxValue = 200;
    private const int Size = MaxValue + 1;

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<int> nums = ParseIntegers(input);

        int[] dp = new int[Size * Size];
        dp[0] = 1;

        foreach (int x in nums)
        {
            int[] next = (int[])dp.Clone();

            for (int g1 = 0; g1 <= MaxValue; g1++)
            {
                int newG1 = Gcd(g1, x);
                int row = g1 * Size;
                int newRow = newG1 * Size;

                for (int g2 = 0; g2 <= MaxValue; g2++)
                {
                    int count = dp[row + g2];
                    if (count == 0)
                        continue;

                    AddModulo(next, newRow + g2, count);

                    int newG2 = Gcd(g2, x);
                    AddModulo(next, row + newG2, count);
                }
            }

            dp = next;
        }

        long answer = 0;
        for (int gcd = 1; gcd <= MaxValue; gcd++)
            answer += dp[gcd * Size + gcd];

        Console.WriteLine(answer % Mod);
    }

    private static void AddModulo(int[] array, int index, int value)
    {
        int sum = array[index] + value;
        if (sum >= Mod)
            sum -= Mod;
        array[index] = sum;
    }

    private static int Gcd(int a, int b)
    {
        while (b != 0)
        {
            int remainder = a % b;
            a = b;
            b = remainder;
        }
        return a;
    }

    private static List<int> ParseIntegers(string input)
    {
        var result = new List<int>();
        int i = 0;

        while (i < input.Length)
        {
            while (i < input.Length && !char.IsDigit(input[i]))
                i++;

            if (i >= input.Length)
                break;

            int value = 0;
            while (i < input.Length && char.IsDigit(input[i]))
            {
                value = value * 10 + (input[i] - '0');
                i++;
            }

            result.Add(value);
        }

        return result;
    }
}
