    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        List<long> values = ParseNumbers(input);

        if (values.Count < 2)
        {
            Console.WriteLine(values.Count == 0 ? 0 : 1);
            return;
        }

        long k = values[values.Count - 1];
        int n = values.Count - 1;
        long[] nums = new long[n];

        for (int i = 0; i < n; i++)
            nums[i] = values[i];

        Array.Sort(nums);

        long lastAssigned = long.MinValue / 4;
        int distinctCount = 0;

        foreach (long num in nums)
        {
            long assigned = Math.Max(num - k, lastAssigned + 1);

            if (assigned <= num + k)
            {
                lastAssigned = assigned;
                distinctCount++;
            }
        }

        Console.WriteLine(distinctCount);
    }

    private static List<long> ParseNumbers(string input)
    {
        var numbers = new List<long>();
        int i = 0;

        while (i < input.Length)
        {
            while (i < input.Length &&
                   !char.IsDigit(input[i]) &&
                   input[i] != '-')
            {
                i++;
            }

            if (i >= input.Length)
                break;

            int sign = 1;
            if (input[i] == '-')
            {
                sign = -1;
                i++;

                if (i >= input.Length || !char.IsDigit(input[i]))
                    continue;
            }

            long value = 0;
            while (i < input.Length && char.IsDigit(input[i]))
            {
                value = value * 10 + (input[i] - '0');
                i++;
            }

            numbers.Add(value * sign);
        }

        return numbers;
    }
}
