using System;
using System.Collections.Generic;

public class Program
{
    public static void Main()
    {
        var lines = new List<int[]>();
        string line;

        while ((line = Console.ReadLine()) != null)
        {
            int[] values = ExtractIntegers(line);
            if (values.Length > 0)
                lines.Add(values);
        }

        if (lines.Count < 3)
            return;

        int[] nums = lines[0];
        int k = lines[1][0];
        int numOperations = lines[2][0];

        Array.Sort(nums);
        int n = nums.Length;
        int answer = 0;

        // Targets not necessarily already present in nums.
        int left = 0;
        for (int right = 0; right < n; right++)
        {
            while ((long)nums[right] - nums[left] > 2L * k)
                left++;

            answer = Math.Max(answer, Math.Min(right - left + 1, numOperations));
        }

        // Targets already present in nums.
        int index = 0;
        while (index < n)
        {
            int value = nums[index];
            int next = index + 1;

            while (next < n && nums[next] == value)
                next++;

            int existingFrequency = next - index;
            int rangeLeft = LowerBound(nums, (long)value - k);
            int rangeRight = UpperBound(nums, (long)value + k);
            int candidates = rangeRight - rangeLeft;

            int frequency = Math.Min(candidates, existingFrequency + numOperations);
            answer = Math.Max(answer, frequency);

            index = next;
        }

        Console.WriteLine(answer);
    }

    private static int LowerBound(int[] nums, long target)
    {
        int left = 0;
        int right = nums.Length;

        while (left < right)
        {
            int mid = left + (right - left) / 2;
            if (nums[mid] < target)
                left = mid + 1;
            else
                right = mid;
        }

        return left;
    }

    private static int UpperBound(int[] nums, long target)
    {
        int left = 0;
        int right = nums.Length;

        while (left < right)
        {
            int mid = left + (right - left) / 2;
            if (nums[mid] <= target)
                left = mid + 1;
            else
                right = mid;
        }

        return left;
    }

    private static int[] ExtractIntegers(string text)
    {
        var result = new List<int>();
        int i = 0;

        while (i < text.Length)
        {
            while (i < text.Length &&
                   !char.IsDigit(text[i]) &&
                   !(text[i] == '-' && i + 1 < text.Length && char.IsDigit(text[i + 1])))
            {
                i++;
            }

            if (i >= text.Length)
                break;

            int sign = 1;
            if (text[i] == '-')
            {
                sign = -1;
                i++;
            }

            int value = 0;
            while (i < text.Length && char.IsDigit(text[i]))
            {
                value = value * 10 + (text[i] - '0');
                i++;
            }

            result.Add(sign * value);
        }

        return result.ToArray();
    }
}
