using System;

public class Program
{
    private const int Mod = 1000000007;

    public static void Main()
    {
        string[] input = Console.In.ReadToEnd()
            .Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        if (input.Length < 2)
            return;

        string s = input[0];
        int k = int.Parse(input[1]);
        int length = s.Length;

        int[,] combinations = new int[length + 1, length + 1];
        combinations[0, 0] = 1;

        for (int i = 1; i <= length; i++)
        {
            combinations[i, 0] = 1;
            combinations[i, i] = 1;

            for (int j = 1; j < i; j++)
            {
                int value = combinations[i - 1, j - 1] + combinations[i - 1, j];
                if (value >= Mod)
                    value -= Mod;
                combinations[i, j] = value;
            }
        }

        int[] reductionSteps = new int[length + 1];
        for (int i = 2; i <= length; i++)
            reductionSteps[i] = 1 + reductionSteps[PopCount(i)];

        bool[] validPopCount = new bool[length + 1];
        for (int ones = 1; ones <= length; ones++)
            validPopCount[ones] = reductionSteps[ones] <= k - 1;

        long answer = 0;
        int prefixOnes = 0;

        for (int position = 0; position < length; position++)
        {
            if (s[position] != '1')
                continue;

            int remaining = length - position - 1;

            for (int totalOnes = 1; totalOnes <= length; totalOnes++)
            {
                if (!validPopCount[totalOnes])
                    continue;

                int needed = totalOnes - prefixOnes;
                if (needed >= 0 && needed <= remaining)
                {
                    answer += combinations[remaining, needed];
                    if (answer >= Mod)
                        answer %= Mod;
                }
            }

            prefixOnes++;
        }

        Console.WriteLine(answer % Mod);
    }

    private static int PopCount(int value)
    {
        int count = 0;
        while (value > 0)
        {
            count += value & 1;
            value >>= 1;
        }
        return count;
    }
}
