public class Program
{
    public static void Main()
    {
        var reader = new FastReader(Console.OpenStandardInput());
        int n = reader.NextInt();

        int longestIndex = int.MaxValue;
        int longestTime = -1;
        int previousTime = 0;

        for (int i = 0; i < n; i++)
        {
            int index = reader.NextInt();
            int time = reader.NextInt();
            int duration = time - previousTime;

            if (duration > longestTime ||
                (duration == longestTime && index < longestIndex))
            {
                longestTime = duration;
                longestIndex = index;
            }

            previousTime = time;
        }

        Console.WriteLine(longestIndex);
    }

    private sealed class FastReader
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int position;
        private int length;

        public FastReader(Stream stream)
        {
            this.stream = stream;
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }
    }
}
