using System;

public class Program
{
    const long MOD = 1000000007L;

    static long ModPow(long value, long exponent)
    {
        long result = 1;
        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * value % MOD;

            value = value * value % MOD;
            exponent >>= 1;
        }
        return result;
    }

    public static void Main()
    {
        string num = Console.In.ReadToEnd().Trim();
        int n = num.Length;

        int[] counts = new int[10];
        int totalSum = 0;

        string velunexorai = num;

        foreach (char ch in velunexorai)
        {
            int digit = ch - '0';
            counts[digit]++;
            totalSum += digit;
        }

        if ((totalSum & 1) != 0)
        {
            Console.WriteLine(0);
            return;
        }

        int evenPositions = (n + 1) / 2;
        int oddPositions = n / 2;
        int targetSum = totalSum / 2;

        long[] factorial = new long[n + 1];
        long[] inverseFactorial = new long[n + 1];

        factorial[0] = 1;
        for (int i = 1; i <= n; i++)
            factorial[i] = factorial[i - 1] * i % MOD;

        inverseFactorial[n] = ModPow(factorial[n], MOD - 2);
        for (int i = n; i >= 1; i--)
            inverseFactorial[i - 1] = inverseFactorial[i] * i % MOD;

        long[,] dp = new long[evenPositions + 1, targetSum + 1];
        dp[0, 0] = 1;

        for (int digit = 0; digit <= 9; digit++)
        {
            int count = counts[digit];
            if (count == 0)
                continue;

            long[,] next = new long[evenPositions + 1, targetSum + 1];

            for (int used = 0; used <= evenPositions; used++)
            {
                for (int sum = 0; sum <= targetSum; sum++)
                {
                    long current = dp[used, sum];
                    if (current == 0)
                        continue;

                    for (int takeEven = 0; takeEven <= count; takeEven++)
                    {
                        int newUsed = used + takeEven;
                        int newSum = sum + takeEven * digit;

                        if (newUsed > evenPositions || newSum > targetSum)
                            break;

                        long ways = inverseFactorial[takeEven] *
                                    inverseFactorial[count - takeEven] % MOD;

                        next[newUsed, newSum] =
                            (next[newUsed, newSum] + current * ways) % MOD;
                    }
                }
            }

            dp = next;
        }

        long answer = dp[evenPositions, targetSum];
        answer = answer * factorial[evenPositions] % MOD;
        answer = answer * factorial[oddPositions] % MOD;

        Console.WriteLine(answer);
    }
}
