using System;

public class Program
{
    public static void Main()
    {
        string s = Console.ReadLine();
        if (string.IsNullOrEmpty(s))
            return;

        s = s.Trim();

        int[] frequency = new int[26];
        int maxFrequency = 0;

        foreach (char c in s)
        {
            int index = c - 'a';
            frequency[index]++;
            if (frequency[index] > maxFrequency)
                maxFrequency = frequency[index];
        }

        int answer = s.Length;

        for (int target = 1; target <= maxFrequency; target++)
        {
            // State 0: the previous character has final frequency 0.
            // State 1: the previous character has final frequency target.
            int dpZero = frequency[0];
            int dpTarget = Math.Abs(frequency[0] - target);

            for (int i = 1; i < 26; i++)
            {
                int currentZeroCost = frequency[i];
                int currentTargetCost = Math.Abs(frequency[i] - target);
                int deficit = Math.Max(target - frequency[i], 0);

                int previousZeroSurplus = frequency[i - 1];
                int previousTargetSurplus =
                    Math.Max(frequency[i - 1] - target, 0);

                int nextZero = Math.Min(dpZero, dpTarget) + currentZeroCost;

                int fromZero = dpZero + currentTargetCost
                    - Math.Min(previousZeroSurplus, deficit);

                int fromTarget = dpTarget + currentTargetCost
                    - Math.Min(previousTargetSurplus, deficit);

                int nextTarget = Math.Min(fromZero, fromTarget);

                dpZero = nextZero;
                dpTarget = nextTarget;
            }

            answer = Math.Min(answer, Math.Min(dpZero, dpTarget));
        }

        Console.WriteLine(answer);
    }
}
