        int maxValue = 0;
        for (int i = 0; i < nums.Count; i++)
            if (nums[i] > maxValue)
                maxValue = nums[i];

        long[] count = new long[maxValue + 2];
        long[] sum = new long[maxValue + 2];
        long answer = 0;

        foreach (int x in nums)
        {
            long newCount = 1;
            long newSum = x;

            if (x > 0)
            {
                newCount = (newCount + count[x - 1]) % Mod;
                newSum = (newSum + sum[x - 1] + count[x - 1] * x) % Mod;
            }

            if (x + 1 < count.Length)
            {
                newCount = (newCount + count[x + 1]) % Mod;
                newSum = (newSum + sum[x + 1] + count[x + 1] * x) % Mod;
            }

            count[x] = (count[x] + newCount) % Mod;
            sum[x] = (sum[x] + newSum) % Mod;
            answer = (answer + newSum) % Mod;
        }

