using System;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c != -1 && c != '-' && (c < '0' || c > '9'));

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value * sign;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int[,] fruits = new int[n, n];

        long diagonalSum = 0;
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                fruits[i, j] = scanner.NextInt();
                if (i == j)
                    diagonalSum += fruits[i, j];
            }
        }

        const long NegativeInfinity = long.MinValue / 4;

        // Child starting at (0, n - 1), restricted to rooms above the diagonal.
        long[] previous = new long[n];
        long[] current = new long[n];

        for (int i = 0; i < n; i++)
            previous[i] = NegativeInfinity;

        previous[n - 1] = fruits[0, n - 1];

        for (int row = 1; row <= n - 2; row++)
        {
            for (int i = 0; i < n; i++)
                current[i] = NegativeInfinity;

            for (int col = row + 1; col < n; col++)
            {
                long best = previous[col];

                if (col > 0 && previous[col - 1] > best)
                    best = previous[col - 1];

                if (col + 1 < n && previous[col + 1] > best)
                    best = previous[col + 1];

                if (best != NegativeInfinity)
                    current[col] = best + fruits[row, col];
            }

            long[] temp = previous;
            previous = current;
            current = temp;
        }

        long upperPath = previous[n - 1];

        // Child starting at (n - 1, 0), restricted to rooms below the diagonal.
        for (int i = 0; i < n; i++)
            previous[i] = NegativeInfinity;

        previous[n - 1] = fruits[n - 1, 0];

        for (int col = 1; col <= n - 2; col++)
        {
            for (int i = 0; i < n; i++)
                current[i] = NegativeInfinity;

            for (int row = col + 1; row < n; row++)
            {
                long best = previous[row];

                if (row > 0 && previous[row - 1] > best)
                    best = previous[row - 1];

                if (row + 1 < n && previous[row + 1] > best)
                    best = previous[row + 1];

                if (best != NegativeInfinity)
                    current[row] = best + fruits[row, col];
            }

            long[] temp = previous;
            previous = current;
            current = temp;
        }

        long lowerPath = previous[n - 1];

        Console.WriteLine(diagonalSum + upperPath + lowerPath);
    }
}
