using System;
using System.IO;
using System.Collections.Generic;

public class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        if (tokens.Length < 2)
            return;

        int n = tokens.Length - 1;
        int[] strength = new int[n];

        for (int i = 0; i < n; i++)
            strength[i] = int.Parse(tokens[i]);

        int k = int.Parse(tokens[n]);
        int totalMasks = 1 << n;
        long[] dp = new long[totalMasks];

        for (int i = 1; i < totalMasks; i++)
            dp[i] = long.MaxValue;

        for (int mask = 0; mask < totalMasks; mask++)
        {
            int broken = CountBits(mask);
            long factor = 1L + (long)broken * k;

            for (int i = 0; i < n; i++)
            {
                if ((mask & (1 << i)) != 0)
                    continue;

                long time = (strength[i] + factor - 1) / factor;
                int nextMask = mask | (1 << i);
                long candidate = dp[mask] + time;

                if (candidate < dp[nextMask])
                    dp[nextMask] = candidate;
            }
        }

        Console.WriteLine(dp[totalMasks - 1]);
    }

    private static int CountBits(int value)
    {
        int count = 0;
        while (value != 0)
        {
            value &= value - 1;
            count++;
        }
        return count;
    }
}
