using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

public class Program
{
    private const long INF = long.MaxValue / 4;

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] lines = Regex.Split(input, @"\r?\n");
        var groups = new List<List<int>>();

        foreach (string line in lines)
        {
            MatchCollection matches = Regex.Matches(line, @"-?\d+");
            if (matches.Count == 0)
                continue;

            var group = new List<int>();
            foreach (Match match in matches)
                group.Add(int.Parse(match.Value));
            groups.Add(group);
        }

        if (groups.Count == 0)
            return;

        int[] nums;
        int k, op1, op2;

        var remaining = new List<int>();
        for (int i = 1; i < groups.Count; i++)
            remaining.AddRange(groups[i]);

        if (remaining.Count >= 3)
        {
            nums = groups[0].ToArray();
            k = remaining[0];
            op1 = remaining[1];
            op2 = remaining[2];
        }
        else
        {
            var all = new List<int>();
            foreach (var group in groups)
                all.AddRange(group);

            if (all.Count < 4)
                return;

            int n = all.Count - 3;
            nums = all.GetRange(0, n).ToArray();
            k = all[n];
            op1 = all[n + 1];
            op2 = all[n + 2];
        }

        long[,] dp = new long[op1 + 1, op2 + 1];
        Fill(dp, INF);
        dp[0, 0] = 0;

        for (int index = 0; index < nums.Length; index++)
        {
            int x = nums[index];
            int half = (x + 1) / 2;

            long[,] next = new long[op1 + 1, op2 + 1];
            Fill(next, INF);

            for (int used1 = 0; used1 <= op1; used1++)
            {
                for (int used2 = 0; used2 <= op2; used2++)
                {
                    long current = dp[used1, used2];
                    if (current == INF)
                        continue;

                    Relax(next, used1, used2, current + x);

                    if (used1 < op1)
                        Relax(next, used1 + 1, used2, current + half);

                    if (used2 < op2 && x >= k)
                        Relax(next, used1, used2 + 1, current + (x - k));

                    if (used1 < op1 && used2 < op2)
                    {
                        long bestBoth = INF;

                        // Operation 2 followed by Operation 1.
                        if (x >= k)
                            bestBoth = Math.Min(bestBoth, (x - k + 1L) / 2L);

                        // Operation 1 followed by Operation 2.
                        if (half >= k)
                            bestBoth = Math.Min(bestBoth, half - (long)k);

                        if (bestBoth != INF)
                            Relax(next, used1 + 1, used2 + 1, current + bestBoth);
                    }
                }
            }

            dp = next;
        }

        long answer = INF;
        for (int used1 = 0; used1 <= op1; used1++)
        {
            for (int used2 = 0; used2 <= op2; used2++)
                answer = Math.Min(answer, dp[used1, used2]);
        }

        Console.WriteLine(answer);
    }

    private static void Fill(long[,] array, long value)
    {
        for (int i = 0; i < array.GetLength(0); i++)
        {
            for (int j = 0; j < array.GetLength(1); j++)
                array[i, j] = value;
        }
    }

    private static void Relax(long[,] dp, int i, int j, long value)
    {
        if (value < dp[i, j])
            dp[i, j] = value;
    }
}
