using System;
using System.IO;

public class Program
{
    private struct HeapNode
    {
        public int Value;
        public long Cost;

        public HeapNode(int value, long cost)
        {
            Value = value;
            Cost = cost;
        }
    }

    private class MinHeap
    {
        private HeapNode[] heap = new HeapNode[16];
        private int count;

        public int Count
        {
            get { return count; }
        }

        public void Push(HeapNode node)
        {
            if (count == heap.Length)
                Array.Resize(ref heap, heap.Length * 2);

            int index = count++;
            while (index > 0)
            {
                int parent = (index - 1) / 2;
                if (heap[parent].Cost <= node.Cost)
                    break;

                heap[index] = heap[parent];
                index = parent;
            }

            heap[index] = node;
        }

        public HeapNode Pop()
        {
            HeapNode result = heap[0];
            HeapNode last = heap[--count];

            if (count > 0)
            {
                int index = 0;

                while (true)
                {
                    int left = index * 2 + 1;
                    if (left >= count)
                        break;

                    int right = left + 1;
                    int child = left;

                    if (right < count && heap[right].Cost < heap[left].Cost)
                        child = right;

                    if (heap[child].Cost >= last.Cost)
                        break;

                    heap[index] = heap[child];
                    index = child;
                }

                heap[index] = last;
            }

            return result;
        }
    }

    private static bool[] BuildPrimeSieve(int limit)
    {
        bool[] isPrime = new bool[limit];

        for (int i = 2; i < limit; i++)
            isPrime[i] = true;

        for (int i = 2; i * i < limit; i++)
        {
            if (!isPrime[i])
                continue;

            for (int j = i * i; j < limit; j += i)
                isPrime[j] = false;
        }

        return isPrime;
    }

    private static long MinimumCost(int start, int target)
    {
        int limit = 10;
        int temp = start;

        while (temp >= 10)
        {
            limit *= 10;
            temp /= 10;
        }

        bool[] isPrime = BuildPrimeSieve(limit);

        if (isPrime[start] || isPrime[target])
            return -1;

        long[] distance = new long[limit];
        for (int i = 0; i < limit; i++)
            distance[i] = long.MaxValue;

        MinHeap heap = new MinHeap();
        distance[start] = start;
        heap.Push(new HeapNode(start, start));

        while (heap.Count > 0)
        {
            HeapNode current = heap.Pop();
            int value = current.Value;
            long cost = current.Cost;

            if (cost != distance[value])
                continue;

            if (value == target)
                return cost;

            int highestPlace = 1;
            if (value > 0)
            {
                while (highestPlace <= value / 10)
                    highestPlace *= 10;
            }

            for (int place = 1; place <= highestPlace; place *= 10)
            {
                int digit = (value / place) % 10;

                if (digit < 9)
                {
                    int next = value + place;
                    if (next < limit && !isPrime[next])
                    {
                        long nextCost = cost + next;
                        if (nextCost < distance[next])
                        {
                            distance[next] = nextCost;
                            heap.Push(new HeapNode(next, nextCost));
                        }
                    }
                }

                if (digit > 0)
                {
                    int next = value - place;
                    if (!isPrime[next])
                    {
                        long nextCost = cost + next;
                        if (nextCost < distance[next])
                        {
                            distance[next] = nextCost;
                            heap.Push(new HeapNode(next, nextCost));
                        }
                    }
                }

                if (place > highestPlace / 10)
                    break;
            }
        }

        return -1;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split(
            new char[] { ' ', '\t', '\r', '\n' },
            StringSplitOptions.RemoveEmptyEntries
        );

        if (tokens.Length < 2)
            return;

        int n = int.Parse(tokens[0]);
        int m = int.Parse(tokens[1]);

        Console.WriteLine(MinimumCost(n, m));
    }
}
