        public int Compare(Interval a, Interval b)
        {
            int comparison = a.Start.CompareTo(b.Start);
            return comparison != 0 ? comparison : a.End.CompareTo(b.End);
        }
    }

    private static bool HasThreeSections(Interval[] intervals)
    {
        Array.Sort(intervals, new IntervalComparer());

        int groups = 1;
        int currentEnd = intervals[0].End;

        for (int i = 1; i < intervals.Length; i++)
        {
            if (intervals[i].Start >= currentEnd)
            {
                groups++;
                if (groups >= 3)
                    return true;

                currentEnd = intervals[i].End;
            }
            else if (intervals[i].End > currentEnd)
            {
                currentEnd = intervals[i].End;
            }
        }

        return false;
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        scanner.NextInt(); // n
        int rectangleCount = scanner.NextInt();

        Interval[] horizontal = new Interval[rectangleCount];
        Interval[] vertical = new Interval[rectangleCount];

        for (int i = 0; i < rectangleCount; i++)
        {
            int startX = scanner.NextInt();
            int startY = scanner.NextInt();
            int endX = scanner.NextInt();
            int endY = scanner.NextInt();

            vertical[i] = new Interval(startX, endX);
            horizontal[i] = new Interval(startY, endY);
        }

        bool possible = HasThreeSections(vertical) || HasThreeSections(horizontal);
        Console.WriteLine(possible ? "true" : "false");
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value * sign;
        }
    }
