using System;
using System.Collections.Generic;

public class Program
{
    private static long[] nums;
    private static long[] lows;
    private static long[] highs;
    private static int intervalCount;

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        nums = ParseNumbers(input);

        if (nums.Length < 2)
        {
            Console.WriteLine(0);
            return;
        }

        lows = new long[nums.Length * 2 + 5];
        highs = new long[nums.Length * 2 + 5];

        long lower = 0;
        for (int i = 1; i < nums.Length; i++)
        {
            if (nums[i - 1] != -1 && nums[i] != -1)
            {
                long difference = Math.Abs(nums[i] - nums[i - 1]);
                if (difference > lower)
                    lower = difference;
            }
        }

        long upper = 1000000000L;

        while (lower < upper)
        {
            long middle = lower + (upper - lower) / 2;

            if (IsFeasible(middle))
                upper = middle;
            else
                lower = middle + 1;
        }

        Console.WriteLine(lower);
    }

    private static bool IsFeasible(long maxDifference)
    {
        // Case 1: |x - y| <= maxDifference, so a missing run of
        // length at least two may switch between x and y.
        if (CheckMode(maxDifference, true))
            return true;

        // Case 2: x and y may be farther apart, so each missing run
        // must use only one of them.
        return CheckMode(maxDifference, false);
    }

    private static bool CheckMode(long maxDifference, bool allowSwitch)
    {
        intervalCount = 0;
        int n = nums.Length;
        int i = 0;

        while (i < n)
        {
            if (nums[i] != -1)
            {
                i++;
                continue;
            }

            int start = i;
            while (i < n && nums[i] == -1)
                i++;

            int end = i - 1;
            int runLength = end - start + 1;
            bool hasLeft = start > 0;
            bool hasRight = i < n;

            if (!hasLeft && !hasRight)
                continue;

            if (allowSwitch)
            {
                if (hasLeft && hasRight)
                {
                    if (runLength == 1)
                    {
                        if (!AddIntersection(nums[start - 1], nums[i], maxDifference))
                            return false;
                    }
                    else
                    {
                        if (!AddAround(nums[start - 1], maxDifference))
                            return false;
                        if (!AddAround(nums[i], maxDifference))
                            return false;
                    }
                }
                else
                {
                    long boundary = hasLeft ? nums[start - 1] : nums[i];
                    if (!AddAround(boundary, maxDifference))
                        return false;
                }
            }
            else
            {
                if (hasLeft && hasRight)
                {
                    if (!AddIntersection(nums[start - 1], nums[i], maxDifference))
                        return false;
                }
                else
                {
                    long boundary = hasLeft ? nums[start - 1] : nums[i];
                    if (!AddAround(boundary, maxDifference))
                        return false;
                }
            }
        }

        return CanPierceWithTwoPoints(maxDifference, allowSwitch);
    }

    private static bool AddAround(long value, long distance)
    {
        long low = value - distance;
        if (low < 1)
            low = 1;

        long high = value + distance;
        return AddInterval(low, high);
    }

    private static bool AddIntersection(long a, long b, long distance)
    {
        long low = Math.Max(a, b) - distance;
        if (low < 1)
            low = 1;

        long high = Math.Min(a, b) + distance;
        return AddInterval(low, high);
    }

    private static bool AddInterval(long low, long high)
    {
        if (low > high)
            return false;

        lows[intervalCount] = low;
        highs[intervalCount] = high;
        intervalCount++;
        return true;
    }

    private static bool CanPierceWithTwoPoints(long distance, bool requireClosePoints)
    {
        if (intervalCount == 0)
            return true;

        long firstPoint = highs[0];
        for (int i = 1; i < intervalCount; i++)
        {
            if (highs[i] < firstPoint)
                firstPoint = highs[i];
        }

        bool needsSecondPoint = false;
        long secondLow = long.MinValue;
        long secondHigh = long.MaxValue;

        for (int i = 0; i < intervalCount; i++)
        {
            if (lows[i] > firstPoint)
            {
                needsSecondPoint = true;

                if (lows[i] > secondLow)
                    secondLow = lows[i];
                if (highs[i] < secondHigh)
                    secondHigh = highs[i];
            }
        }

        if (!needsSecondPoint)
            return true;

        if (secondLow > secondHigh)
            return false;

        return !requireClosePoints || secondLow - firstPoint <= distance;
    }

    private static long[] ParseNumbers(string input)
    {
        List<long> values = new List<long>();

        int i = 0;
        while (i < input.Length)
        {
            while (i < input.Length && input[i] != '-' && !char.IsDigit(input[i]))
                i++;

            if (i >= input.Length)
                break;

            bool negative = false;
            if (input[i] == '-')
            {
                negative = true;
                i++;
            }

            if (i >= input.Length || !char.IsDigit(input[i]))
                continue;

            long value = 0;
            while (i < input.Length && char.IsDigit(input[i]))
            {
                value = value * 10 + (input[i] - '0');
                i++;
            }

            values.Add(negative ? -value : value);
        }

        return values.ToArray();
    }
}
