using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value * sign;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int edgeCount = scanner.NextInt();
        int n = edgeCount + 1;

        int[] head = new int[n];
        for (int i = 0; i < n; i++) head[i] = -1;

        int[] to = new int[edgeCount * 2];
        int[] weight = new int[edgeCount * 2];
        int[] next = new int[edgeCount * 2];
        int edgeIndex = 0;

        for (int i = 0; i < edgeCount; i++)
        {
            int u = scanner.NextInt();
            int v = scanner.NextInt();
            int w = scanner.NextInt();

            to[edgeIndex] = v;
            weight[edgeIndex] = w;
            next[edgeIndex] = head[u];
            head[u] = edgeIndex++;

            to[edgeIndex] = u;
            weight[edgeIndex] = w;
            next[edgeIndex] = head[v];
            head[v] = edgeIndex++;
        }

        int k = scanner.NextInt();

        int[] parent = new int[n];
        int[] parentWeight = new int[n];
        int[] order = new int[n];

        for (int i = 0; i < n; i++) parent[i] = -2;

        parent[0] = -1;
        order[0] = 0;
        int orderSize = 1;

        for (int i = 0; i < orderSize; i++)
        {
            int u = order[i];

            for (int e = head[u]; e != -1; e = next[e])
            {
                int v = to[e];
                if (parent[v] != -2) continue;

                parent[v] = u;
                parentWeight[v] = weight[e];
                order[orderSize++] = v;
            }
        }

        // free[u]: maximum sum in u's subtree when the parent edge is not kept.
        // linked[u]: maximum sum when the parent edge is kept.
        long[] free = new long[n];
        long[] linked = new long[n];

        for (int index = n - 1; index >= 0; index--)
        {
            int u = order[index];
            long baseSum = 0;
            var gains = new List<long>();

            for (int e = head[u]; e != -1; e = next[e])
            {
                int v = to[e];
                if (parent[v] != u) continue;

                baseSum += free[v];
                long gain = linked[v] + weight[e] - free[v];

                if (gain > 0)
                    gains.Add(gain);
            }

            gains.Sort();

            long freeValue = baseSum;
            int freeCount = Math.Min(k, gains.Count);
            for (int i = 0; i < freeCount; i++)
                freeValue += gains[gains.Count - 1 - i];

            long linkedValue = baseSum;
            int linkedCount = Math.Min(k - 1, gains.Count);
            for (int i = 0; i < linkedCount; i++)
                linkedValue += gains[gains.Count - 1 - i];

            free[u] = freeValue;
            linked[u] = linkedValue;
        }

        Console.WriteLine(free[0]);
    }
}
