using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private class DisjointSet
    {
        private readonly int[] parent;
        private readonly int[] size;

        public DisjointSet(int n)
        {
            parent = new int[n];
            size = new int[n];

            for (int i = 0; i < n; i++)
            {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int Find(int x)
        {
            int root = x;

            while (parent[root] != root)
                root = parent[root];

            while (parent[x] != x)
            {
                int next = parent[x];
                parent[x] = root;
                x = next;
            }

            return root;
        }

        public bool Union(int a, int b)
        {
            int rootA = Find(a);
            int rootB = Find(b);

            if (rootA == rootB)
                return false;

            if (size[rootA] < size[rootB])
            {
                int temp = rootA;
                rootA = rootB;
                rootB = temp;
            }

            parent[rootB] = rootA;
            size[rootA] += size[rootB];
            return true;
        }
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split(
            (char[])null,
            StringSplitOptions.RemoveEmptyEntries
        );

        if (tokens.Length < 2)
            return;

        int n = tokens.Length - 1;
        int threshold = int.Parse(tokens[tokens.Length - 1]);
        int[] nums = new int[n];

        for (int i = 0; i < n; i++)
            nums[i] = int.Parse(tokens[i]);

        DisjointSet dsu = new DisjointSet(n);
        int[] owner = new int[threshold + 1];

        for (int i = 0; i <= threshold; i++)
            owner[i] = -1;

        int components = n;

        for (int i = 0; i < n; i++)
        {
            int value = nums[i];

            if (value > threshold)
                continue;

            for (int multiple = value; multiple <= threshold; multiple += value)
            {
                if (owner[multiple] == -1)
                {
                    owner[multiple] = i;
                }
                else if (dsu.Union(i, owner[multiple]))
                {
                    components--;
                }
            }
        }

        Console.WriteLine(components);
    }
}
