        var pointSet = new HashSet<string>();

        for (int i = 0; i < n; i++)
        {
            string[] parts = Console.ReadLine()
                .Split(new[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);

            int x = int.Parse(parts[0]);
            int y = int.Parse(parts[1]);

            points[i, 0] = x;
            points[i, 1] = y;
            pointSet.Add(x + "," + y);
        }

        int maximumArea = -1;

        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                int x1 = points[i, 0];
                int y1 = points[i, 1];
                int x2 = points[j, 0];
                int y2 = points[j, 1];

                if (x1 == x2 || y1 == y2)
                    continue;

                if (!pointSet.Contains(x1 + "," + y2) ||
                    !pointSet.Contains(x2 + "," + y1))
                    continue;

                int minX = Math.Min(x1, x2);
                int maxX = Math.Max(x1, x2);
                int minY = Math.Min(y1, y2);
                int maxY = Math.Max(y1, y2);

                bool valid = true;

                for (int k = 0; k < n; k++)
                {
                    int x = points[k, 0];
                    int y = points[k, 1];

                    if (x < minX || x > maxX || y < minY || y > maxY)
                        continue;

                    bool isCorner =
                        (x == minX || x == maxX) &&
                        (y == minY || y == maxY);

                    if (!isCorner)
                    {
                        valid = false;
                        break;
                    }
                }

                if (valid)
                {
                    int area = (maxX - minX) * (maxY - minY);
                    maximumArea = Math.Max(maximumArea, area);
                }
            }
        }

        Console.WriteLine(maximumArea);
    }
