using System;

public class Program
{
    const long Mod = 1000000007L;

    static long ModPow(long value, long exponent)
    {
        long result = 1;
        value %= Mod;

        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * value % Mod;

            value = value * value % Mod;
            exponent >>= 1;
        }

        return result;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        int n = int.Parse(tokens[0]);
        long m = long.Parse(tokens[1]);
        int k = int.Parse(tokens[2]);

        int transitions = n - 1;

        long[] factorial = new long[transitions + 1];
        long[] inverseFactorial = new long[transitions + 1];

        factorial[0] = 1;
        for (int i = 1; i <= transitions; i++)
            factorial[i] = factorial[i - 1] * i % Mod;

        inverseFactorial[transitions] = ModPow(factorial[transitions], Mod - 2);
        for (int i = transitions; i >= 1; i--)
            inverseFactorial[i - 1] = inverseFactorial[i] * i % Mod;

        long combinations = factorial[transitions];
        combinations = combinations * inverseFactorial[k] % Mod;
        combinations = combinations * inverseFactorial[transitions - k] % Mod;

        long answer = m % Mod;
        answer = answer * combinations % Mod;
        answer = answer * ModPow(m - 1, transitions - k) % Mod;

        Console.WriteLine(answer);
    }
}
