using System;

public class Program
{
    public static void Main()
    {
        string[] input = Console.In.ReadToEnd()
            .Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        if (input.Length < 2)
            return;

        string s = input[0];
        string p = input[1];

        int starIndex = p.IndexOf('*');
        string prefix = p.Substring(0, starIndex);
        string suffix = p.Substring(starIndex + 1);

        bool matches = CanMatchSubstring(s, prefix, suffix);
        Console.WriteLine(matches ? "true" : "false");
    }

    private static bool CanMatchSubstring(string s, string prefix, string suffix)
    {
        int n = s.Length;

        for (int start = 0; start <= n; start++)
        {
            if (!MatchesAt(s, start, prefix))
                continue;

            int suffixStartMin = start + prefix.Length;

            for (int suffixStart = suffixStartMin;
                 suffixStart + suffix.Length <= n;
                 suffixStart++)
            {
                if (suffixStart + suffix.Length <= start)
                    continue;

                if (MatchesAt(s, suffixStart, suffix))
                    return true;
            }
        }

        return false;
    }

    private static bool MatchesAt(string s, int index, string value)
    {
        if (index < 0 || index + value.Length > s.Length)
            return false;

        for (int i = 0; i < value.Length; i++)
        {
            if (s[index + i] != value[i])
                return false;
        }

        return true;
    }
}
