            int[] temp = next;
            next = current;
            current = temp;
        }

        Console.WriteLine(answer);
    }

    private static int[] BuildZArray(int[] nums)
    {
        int n = nums.Length;
        int[] z = new int[n];
        z[0] = n;

        int left = 0;
        int right = 0;

        for (int i = 1; i < n; i++)
        {
            if (i <= right)
                z[i] = Math.Min(right - i + 1, z[i - left]);

            while (i + z[i] < n && nums[z[i]] == nums[i + z[i]])
                z[i]++;

            if (i + z[i] - 1 > right)
            {
                left = i;
                right = i + z[i] - 1;
            }
        }

        return z;
    }

    private static List<int> ParseIntegers(string input)
    {
        List<int> result = new List<int>();

        for (int i = 0; i < input.Length;)
        {
            while (i < input.Length &&
                   !char.IsDigit(input[i]) &&
                   input[i] != '-')
            {
