using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private sealed class SegmentTree
    {
        private readonly int size;
        private readonly long[] sum;
        private readonly long[] prefix;
        private readonly long[] suffix;
        private readonly long[] best;
        private readonly int[] count;

        public SegmentTree(int[] values)
        {
            size = GetTreeSize(values.Length);
            int totalSize = size * 2;

            sum = new long[totalSize];
            prefix = new long[totalSize];
            suffix = new long[totalSize];
            best = new long[totalSize];
            count = new int[totalSize];

            for (int i = 0; i < values.Length; i++)
                SetLeaf(size + i, values[i]);

            for (int i = size - 1; i >= 1; i--)
                Merge(i);
        }

        public long MaximumSubarraySum
        {
            get { return best[1]; }
        }

        public void Remove(int index)
        {
            int node = size + index;
            count[node] = 0;
            sum[node] = prefix[node] = suffix[node] = best[node] = 0;
            Rebuild(node / 2);
        }

        public void Restore(int index, int value)
        {
            int node = size + index;
            SetLeaf(node, value);
            Rebuild(node / 2);
        }

        private static int GetTreeSize(int length)
        {
            int result = 1;
            while (result < length)
                result <<= 1;
            return result;
        }

        private void SetLeaf(int node, long value)
        {
            count[node] = 1;
            sum[node] = value;
            prefix[node] = value;
            suffix[node] = value;
            best[node] = value;
        }

        private void Rebuild(int node)
        {
            while (node >= 1)
            {
                Merge(node);
                node /= 2;
            }
        }

        private void Merge(int node)
        {
            int left = node * 2;
            int right = left + 1;

            if (count[left] == 0)
            {
                CopyNode(right, node);
                return;
            }

            if (count[right] == 0)
            {
                CopyNode(left, node);
                return;
            }

            count[node] = count[left] + count[right];
            sum[node] = sum[left] + sum[right];
            prefix[node] = Math.Max(prefix[left], sum[left] + prefix[right]);
            suffix[node] = Math.Max(suffix[right], sum[right] + suffix[left]);
            best[node] = Math.Max(
                Math.Max(best[left], best[right]),
                suffix[left] + prefix[right]
            );
        }

        private void CopyNode(int source, int destination)
        {
            count[destination] = count[source];
            sum[destination] = sum[source];
            prefix[destination] = prefix[source];
            suffix[destination] = suffix[source];
            best[destination] = best[source];
        }
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        int[] nums = ParseIntegers(input);

        if (nums.Length == 0)
            return;

        var positionsByNegativeValue = new Dictionary<int, List<int>>();

        for (int i = 0; i < nums.Length; i++)
        {
            int value = nums[i];
            if (value >= 0)
                continue;

            List<int> positions;
            if (!positionsByNegativeValue.TryGetValue(value, out positions))
            {
                positions = new List<int>();
                positionsByNegativeValue[value] = positions;
            }
            positions.Add(i);
        }

        var tree = new SegmentTree(nums);
        long answer = tree.MaximumSubarraySum;

        foreach (KeyValuePair<int, List<int>> entry in positionsByNegativeValue)
        {
            int value = entry.Key;
            List<int> positions = entry.Value;

            if (positions.Count == nums.Length)
                continue;

            for (int i = 0; i < positions.Count; i++)
                tree.Remove(positions[i]);

            answer = Math.Max(answer, tree.MaximumSubarraySum);

            for (int i = 0; i < positions.Count; i++)
                tree.Restore(positions[i], value);
        }

        Console.WriteLine(answer);
    }

    private static int[] ParseIntegers(string input)
    {
        var values = new List<int>();
        int i = 0;

        while (i < input.Length)
