using System;

public static class Program
{
    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        if (tokens.Length < 2)
            return;

        string s = tokens[0];
        int numOps = int.Parse(tokens[1]);

        int left = 1;
        int right = s.Length;

        while (left < right)
        {
            int mid = left + (right - left) / 2;

            if (CanAchieve(s, numOps, mid))
                right = mid;
            else
                left = mid + 1;
        }

        Console.WriteLine(left);
    }

    private static bool CanAchieve(string s, int numOps, int maxRun)
    {
        const int INF = 1000000000;

        int[] prev0 = new int[maxRun + 1];
        int[] prev1 = new int[maxRun + 1];
        int[] cur0 = new int[maxRun + 1];
        int[] cur1 = new int[maxRun + 1];

        for (int run = 0; run <= maxRun; run++)
        {
            prev0[run] = INF;
            prev1[run] = INF;
        }

        prev0[1] = s[0] == '0' ? 0 : 1;
        prev1[1] = s[0] == '1' ? 0 : 1;

        for (int i = 1; i < s.Length; i++)
        {
            int minPrev0 = INF;
            int minPrev1 = INF;

            for (int run = 1; run <= maxRun; run++)
            {
                if (prev0[run] < minPrev0)
                    minPrev0 = prev0[run];
                if (prev1[run] < minPrev1)
                    minPrev1 = prev1[run];

                cur0[run] = INF;
                cur1[run] = INF;
            }

            int cost0 = s[i] == '0' ? 0 : 1;
            int cost1 = s[i] == '1' ? 0 : 1;

            cur0[1] = minPrev1 + cost0;
            cur1[1] = minPrev0 + cost1;

            for (int run = 2; run <= maxRun; run++)
            {
                if (prev0[run - 1] < INF)
                    cur0[run] = prev0[run - 1] + cost0;

                if (prev1[run - 1] < INF)
                    cur1[run] = prev1[run - 1] + cost1;
            }

            int[] temp = prev0;
            prev0 = cur0;
            cur0 = temp;

            temp = prev1;
            prev1 = cur1;
            cur1 = temp;
        }

        int minimumFlips = INF;

        for (int run = 1; run <= maxRun; run++)
        {
            if (prev0[run] < minimumFlips)
                minimumFlips = prev0[run];
            if (prev1[run] < minimumFlips)
                minimumFlips = prev1[run];
        }

        return minimumFlips <= numOps;
    }
}
