    private static int Gcd(int a, int b)
    {
        while (b != 0)
        {
            int temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }

    private static int RatioKey(int numerator, int denominator)
    {
        int gcd = Gcd(numerator, denominator);
        numerator /= gcd;
        denominator /= gcd;
        return numerator * 1001 + denominator;
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        var numbers = new List<int>();
        int value = 0;
        bool readingNumber = false;

        foreach (char c in input)
        {
            if (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                readingNumber = true;
            }
            else if (readingNumber)
            {
                numbers.Add(value);
                value = 0;
                readingNumber = false;
            }
        }

        if (readingNumber)
            numbers.Add(value);

        int[] nums = numbers.ToArray();
        int n = nums.Length;
        long answer = 0;
        var leftPairs = new Dictionary<int, long>();

        for (int r = 4; r <= n - 3; r++)
        {
            int q = r - 2;

            for (int p = 0; p <= q - 2; p++)
            {
                int key = RatioKey(nums[p], nums[q]);
                long count;
                leftPairs.TryGetValue(key, out count);
                leftPairs[key] = count + 1;
            }

            for (int s = r + 2; s < n; s++)
            {
                int key = RatioKey(nums[s], nums[r]);
                long count;
                if (leftPairs.TryGetValue(key, out count))
                    answer += count;
            }
        }

        Console.WriteLine(answer);
    }
