using System;
using System.Collections.Generic;

public class Program
{
    const long Mod = 1000000007L;

    static long Choose(long n, int k)
    {
        if (k == 0) return 1;
        if (k == 1) return n;
        if (k == 2) return n >= 2 ? n * (n - 1) / 2 : 0;
        return 0;
    }

    static List<long> ReadNumbers()
    {
        string input = Console.In.ReadToEnd();
        List<long> numbers = new List<long>();

        int i = 0;
        while (i < input.Length)
        {
            bool negative = false;

            if (input[i] == '-' && i + 1 < input.Length &&
                input[i + 1] >= '0' && input[i + 1] <= '9')
            {
                negative = true;
                i++;
            }
            else if (input[i] < '0' || input[i] > '9')
            {
                i++;
                continue;
            }

            long value = 0;
            while (i < input.Length && input[i] >= '0' && input[i] <= '9')
            {
                value = value * 10 + (input[i] - '0');
                i++;
            }

            numbers.Add(negative ? -value : value);
        }

        return numbers;
    }

    public static void Main()
    {
        List<long> nums = ReadNumbers();
        int n = nums.Count;

        if (n < 5)
        {
            Console.WriteLine(0);
            return;
        }

        Dictionary<long, int> ids = new Dictionary<long, int>();
        int[] compressed = new int[n];
        int distinct = 0;

        for (int i = 0; i < n; i++)
        {
            int id;
            if (!ids.TryGetValue(nums[i], out id))
            {
                id = distinct++;
                ids[nums[i]] = id;
            }
            compressed[i] = id;
        }

        long[] left = new long[distinct];
        long[] right = new long[distinct];

        for (int i = 0; i < n; i++)
            right[compressed[i]]++;

        long answer = 0;

        for (int middle = 0; middle < n; middle++)
        {
            int x = compressed[middle];
            right[x]--;

            long leftSize = middle;
            long rightSize = n - middle - 1;

            if (leftSize >= 2 && rightSize >= 2)
            {
                long leftX = left[x];
                long rightX = right[x];
                long leftNonX = leftSize - leftX;
                long rightNonX = rightSize - rightX;

                // Cases where the middle value occurs at least three times.
                long atLeastThree = 0;

                for (int selectedLeftX = 0; selectedLeftX <= 2; selectedLeftX++)
                {
                    for (int selectedRightX = 0; selectedRightX <= 2; selectedRightX++)
                    {
                        if (selectedLeftX + selectedRightX < 2)
                            continue;

                        long ways =
                            Choose(leftX, selectedLeftX) *
                            Choose(leftNonX, 2 - selectedLeftX) *
                            Choose(rightX, selectedRightX) *
                            Choose(rightNonX, 2 - selectedRightX);

                        atLeastThree += ways;
                    }
                }

                // Cases where the middle value occurs exactly twice.
                // The remaining three selected values must be pairwise distinct.
                long distinctRightPairs = Choose(rightNonX, 2);
                long distinctLeftPairs = Choose(leftNonX, 2);

                for (int v = 0; v < distinct; v++)
                {
                    if (v == x) continue;
                    distinctRightPairs -= Choose(right[v], 2);
                    distinctLeftPairs -= Choose(left[v], 2);
                }

                long oneXOnLeftBase = 0;
                long oneXOnRightBase = 0;

                for (int v = 0; v < distinct; v++)
                {
                    if (v == x) continue;

                    long rightPairsAvoidingV =
                        distinctRightPairs - right[v] * (rightNonX - right[v]);

                    long leftPairsAvoidingV =
                        distinctLeftPairs - left[v] * (leftNonX - left[v]);

                    oneXOnLeftBase += left[v] * rightPairsAvoidingV;
                    oneXOnRightBase += right[v] * leftPairsAvoidingV;
                }

                long exactlyTwo =
                    leftX * oneXOnLeftBase +
                    rightX * oneXOnRightBase;

                answer = (answer + atLeastThree + exactlyTwo) % Mod;
            }

            left[x]++;
        }

        Console.WriteLine(answer);
    }
}
