using System;
using System.Collections.Generic;
using System.IO;

public static class Program
{
    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int pointer;

        private int ReadByte()
        {
            if (pointer >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0) return -1;
            }
            return buffer[pointer++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }

        public string Next()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            char[] chars = new char[512];
            int count = 0;

            while (c > 32 && c != -1)
            {
                if (count == chars.Length)
                    Array.Resize(ref chars, chars.Length * 2);

                chars[count++] = (char)c;
                c = ReadByte();
            }

            return new string(chars, 0, count);
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();

        int h = scanner.NextInt();
        int w = scanner.NextInt();
        int t = scanner.NextInt();
        int cellCount = h * w;

        char[] grid = new char[cellCount];
        int start = -1;
        int goal = -1;
        List<int> candies = new List<int>();

        for (int r = 0; r < h; r++)
        {
            string row = scanner.Next();
            for (int c = 0; c < w; c++)
            {
                int p = r * w + c;
                char ch = row[c];
                grid[p] = ch;

                if (ch == 'S')
                    start = p;
                else if (ch == 'G')
                    goal = p;
                else if (ch == 'o')
                    candies.Add(p);
            }
        }

        int originalCandyCount = candies.Count;
        int[] specialPositions = new int[originalCandyCount + 2];
        specialPositions[0] = start;

        for (int i = 0; i < originalCandyCount; i++)
            specialPositions[i + 1] = candies[i];

        specialPositions[originalCandyCount + 1] = goal;

        // Rows are BFS sources: start and each candy.
        // Columns are targets: start, each candy, and goal.
        int[,] allDistances = new int[originalCandyCount + 1, originalCandyCount + 2];

        int[] queue = new int[cellCount];
        int[] distance = new int[cellCount];
        int[] seen = new int[cellCount];
        int stamp = 0;

        for (int sourceIndex = 0; sourceIndex <= originalCandyCount; sourceIndex++)
        {
            stamp++;
            int head = 0;
            int tail = 0;
            int source = specialPositions[sourceIndex];

            queue[tail++] = source;
            seen[source] = stamp;
            distance[source] = 0;

            while (head < tail)
            {
                int p = queue[head++];
                int nextDistance = distance[p] + 1;

                int next = p - w;
                if (p >= w && grid[next] != '#' && seen[next] != stamp)
                {
                    seen[next] = stamp;
                    distance[next] = nextDistance;
                    queue[tail++] = next;
                }

                next = p + w;
                if (next < cellCount && grid[next] != '#' && seen[next] != stamp)
                {
                    seen[next] = stamp;
                    distance[next] = nextDistance;
                    queue[tail++] = next;
                }

                int column = p % w;

                next = p - 1;
                if (column > 0 && grid[next] != '#' && seen[next] != stamp)
                {
                    seen[next] = stamp;
                    distance[next] = nextDistance;
                    queue[tail++] = next;
                }

                next = p + 1;
                if (column + 1 < w && grid[next] != '#' && seen[next] != stamp)
                {
                    seen[next] = stamp;
                    distance[next] = nextDistance;
                    queue[tail++] = next;
                }
            }

            for (int targetIndex = 0; targetIndex < specialPositions.Length; targetIndex++)
            {
                int target = specialPositions[targetIndex];
                allDistances[sourceIndex, targetIndex] =
                    seen[target] == stamp ? distance[target] : -1;
            }
        }

        int directDistance = allDistances[0, originalCandyCount + 1];
        if (directDistance < 0 || directDistance > t)
        {
            Console.WriteLine(-1);
            return;
        }

        // A candy can only be part of a feasible route if the shortest
        // start-to-candy-to-goal route is within T.
        List<int> validCandies = new List<int>();
        for (int i = 0; i < originalCandyCount; i++)
        {
            int fromStart = allDistances[0, i + 1];
            int toGoal = allDistances[i + 1, originalCandyCount + 1];

            if (fromStart >= 0 && toGoal >= 0 &&
                (long)fromStart + toGoal <= t)
            {
                validCandies.Add(i);
            }
        }

        int n = validCandies.Count;
        if (n == 0)
        {
            Console.WriteLine(0);
            return;
        }

        int stateCount = 1 << n;
        int fullMask = stateCount - 1;

        // dp[mask, last] is the minimum distance needed to start at S,
        // visit all candies in mask, and finish at candy last.
        // Zero denotes an unreachable state; all actual distances are positive.
        int[] dp = new int[stateCount * n];
        int[] bitToIndex = new int[stateCount];
        byte[] popCount = new byte[stateCount];

        for (int i = 0; i < n; i++)
            bitToIndex[1 << i] = i;

        for (int mask = 1; mask < stateCount; mask++)
            popCount[mask] = (byte)(popCount[mask >> 1] + (mask & 1));

        for (int i = 0; i < n; i++)
        {
            int originalIndex = validCandies[i];
            int d = allDistances[0, originalIndex + 1];
            if (d <= t)
                dp[(1 << i) * n + i] = d;
        }

        int answer = 0;

        for (int mask = 1; mask < stateCount; mask++)
        {
            int endpointBits = mask;

            while (endpointBits != 0)
            {
                int endpointBit = endpointBits & -endpointBits;
                endpointBits -= endpointBit;
                int last = bitToIndex[endpointBit];

                int currentDistance = dp[mask * n + last];
                if (currentDistance == 0)
                    continue;

                int originalLast = validCandies[last];
                int toGoal = allDistances[originalLast + 1, originalCandyCount + 1];

                if (toGoal >= 0 && (long)currentDistance + toGoal <= t)
                {
                    int collected = popCount[mask];
                    if (collected > answer)
                        answer = collected;
                }

                int remaining = fullMask ^ mask;
                while (remaining != 0)
                {
                    int nextBit = remaining & -remaining;
                    remaining -= nextBit;
                    int nextCandy = bitToIndex[nextBit];

                    int originalNext = validCandies[nextCandy];
                    int between = allDistances[originalLast + 1, originalNext + 1];

                    if (between < 0)
                        continue;

                    int newDistance = currentDistance + between;
                    if (newDistance > t)
                        continue;

                    int nextMask = mask | nextBit;
                    int dpIndex = nextMask * n + nextCandy;
                    int oldDistance = dp[dpIndex];

                    if (oldDistance == 0 || newDistance < oldDistance)
                        dp[dpIndex] = newDistance;
                }
            }
        }

        Console.WriteLine(answer);
    }
}
