using System;

public class Program
{
    private const long Mod = 998244353;
    private static long[] pow26;
    private static long[] inverse;

    private static long ModPow(long value, long exponent)
    {
        long result = 1;
        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * value % Mod;

            value = value * value % Mod;
            exponent >>= 1;
        }
        return result;
    }

    // mode:
    // 0 = all valid prefixes with distinct uppercase letters
    // 1 = weighted by the number of distinct uppercase letters
    // 2 = valid prefixes containing a specified uppercase letter
    //     which is not among the fixed uppercase letters
    private static long PrefixWays(int fixedUpperCount, int wildcardCount, int mode)
    {
        int available = 26 - fixedUpperCount;
        int limit = Math.Min(wildcardCount, available);

        long combination = 1;
        long lowercaseWays = pow26[wildcardCount];
        long falling = 1;
        long result = 0;

        for (int t = 0; t <= limit; t++)
        {
            long ways = combination * lowercaseWays % Mod * falling % Mod;
            long factor;

            if (mode == 0)
            {
                factor = 1;
            }
            else if (mode == 1)
            {
                factor = fixedUpperCount + t;
            }
            else
            {
                factor = (available == 0)
                    ? 0
                    : (long)t * inverse[available] % Mod;
            }

            result = (result + ways * factor) % Mod;

            if (t < limit)
            {
                combination = combination * (wildcardCount - t) % Mod;
                combination = combination * inverse[t + 1] % Mod;
                lowercaseWays = lowercaseWays * inverse[26] % Mod;
                falling = falling * (available - t) % Mod;
            }
        }

        return result;
    }

    public static void Main()
    {
        string s = Console.In.ReadToEnd().Trim();
        int n = s.Length;

        pow26 = new long[n + 1];
        pow26[0] = 1;
        for (int i = 1; i <= n; i++)
            pow26[i] = pow26[i - 1] * 26 % Mod;

        inverse = new long[27];
        for (int i = 1; i <= 26; i++)
            inverse[i] = ModPow(i, Mod - 2);

        // suffixWays[i] is the number of replacements of s[i..]
        // whose character types are uppercase* followed by lowercase*.
        long[] suffixWays = new long[n + 1];
        long upperPhase = 1;
        long lowerPhase = 1;
        suffixWays[n] = 1;

        for (int i = n - 1; i >= 0; i--)
        {
            char c = s[i];
            long nextUpper;
            long nextLower;

            if (c == '?')
            {
                nextUpper = 26 * ((upperPhase + lowerPhase) % Mod) % Mod;
                nextLower = 26 * lowerPhase % Mod;
            }
            else if (c >= 'A' && c <= 'Z')
            {
                nextUpper = upperPhase;
                nextLower = 0;
            }
            else
            {
                nextUpper = lowerPhase;
                nextLower = lowerPhase;
            }

            upperPhase = nextUpper;
            lowerPhase = nextLower;
            suffixWays[i] = upperPhase;
        }

        bool[] fixedSeen = new bool[26];
        bool fixedUppercaseUnique = true;
        int fixedUpperCount = 0;
        int wildcardCount = 0;
        long answer = 0;

        for (int i = 0; i < n; i++)
        {
            char c = s[i];

            if (fixedUppercaseUnique)
            {
                long prefixWays = 0;

                if (c == '?')
                {
                    prefixWays = PrefixWays(fixedUpperCount, wildcardCount, 1);
                }
                else if (c >= 'A' && c <= 'Z')
                {
                    int letter = c - 'A';
                    if (fixedSeen[letter])
                        prefixWays = PrefixWays(fixedUpperCount, wildcardCount, 0);
                    else
                        prefixWays = PrefixWays(fixedUpperCount, wildcardCount, 2);
                }

                answer = (answer + prefixWays * suffixWays[i + 1]) % Mod;
            }

            if (c == '?')
            {
                wildcardCount++;
            }
            else if (c >= 'A' && c <= 'Z')
            {
                int letter = c - 'A';
                if (fixedSeen[letter])
                {
                    fixedUppercaseUnique = false;
                }
                else
                {
                    fixedSeen[letter] = true;
                    fixedUpperCount++;
                }
            }
        }

        if (fixedUppercaseUnique)
            answer = (answer + PrefixWays(fixedUpperCount, wildcardCount, 0)) % Mod;

        Console.WriteLine(answer);
    }
}
