            {
                int differences = 0;
                for (int k = 0; k < m; k++)
                {
                    if (strings[i][k] != strings[j][k])
                        differences++;
                }

                if (differences == 1)
                {
                    adjacent[i, j] = true;
                    adjacent[j, i] = true;
                }
            }
        }

        int totalMasks = 1 << n;
        bool[,] dp = new bool[totalMasks, n];

        for (int i = 0; i < n; i++)
            dp[1 << i, i] = true;

        for (int mask = 1; mask < totalMasks; mask++)
        {
            for (int last = 0; last < n; last++)
            {
                if (!dp[mask, last])
                    continue;

                for (int next = 0; next < n; next++)
                {
                    if ((mask & (1 << next)) == 0 && adjacent[last, next])
                        dp[mask | (1 << next), next] = true;
                }
            }
        }

        int fullMask = totalMasks - 1;
        for (int last = 0; last < n; last++)
        {
            if (dp[fullMask, last])
            {
                Console.WriteLine("Yes");
                return;
            }
        }

        Console.WriteLine("No");
