    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    private static int UpperBound(long[] array, long value)
    {
        int left = 0;
        int right = array.Length;

        while (left < right)
        {
            int mid = left + (right - left) / 2;
            if (array[mid] <= value)
                left = mid + 1;
            else
                right = mid;
        }

        return left;
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = (int)scanner.NextLong();
        int m = (int)scanner.NextLong();
        long d = scanner.NextLong();

        var a = new long[n];
        var b = new long[m];

        for (int i = 0; i < n; i++)
            a[i] = scanner.NextLong();

        for (int i = 0; i < m; i++)
            b[i] = scanner.NextLong();

        Array.Sort(b);

        long answer = -1;

        for (int i = 0; i < n; i++)
        {
            int index = UpperBound(b, a[i] + d) - 1;

            if (index >= 0 && b[index] >= a[i] - d)
            {
                long sum = a[i] + b[index];
                if (sum > answer)
                    answer = sum;
            }
        }

        Console.WriteLine(answer);
    }
