            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value;
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();
        int n = scanner.NextInt();
        int q = scanner.NextInt();

        HashSet<int>[] adjacency = new HashSet<int>[n];
        int isolatedCount = n;
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < q; i++)
        {
            int type = scanner.NextInt();

            if (type == 1)
            {
                int u = scanner.NextInt() - 1;
                int v = scanner.NextInt() - 1;

                if (adjacency[u] == null)
                    adjacency[u] = new HashSet<int>();
                if (adjacency[v] == null)
                    adjacency[v] = new HashSet<int>();

                if (adjacency[u].Count == 0)
                    isolatedCount--;
                if (adjacency[v].Count == 0)
                    isolatedCount--;

                adjacency[u].Add(v);
                adjacency[v].Add(u);
            }
            else
            {
                int v = scanner.NextInt() - 1;

                if (adjacency[v] != null && adjacency[v].Count > 0)
                {
                    foreach (int neighbor in adjacency[v])
                    {
                        adjacency[neighbor].Remove(v);
                        if (adjacency[neighbor].Count == 0)
                            isolatedCount++;
                    }

                    adjacency[v].Clear();
                    isolatedCount++;
                }
            }

            output.Append(isolatedCount).Append('\n');
        }

        Console.Write(output.ToString());
    }
