        int n = scanner.NextInt();
        int m = scanner.NextInt();

        int[][] sets = new int[n][];
        var setsByElement = new List<int>[m + 1];
        bool[] containsM = new bool[n];

        for (int i = 0; i < n; i++)
        {
            int count = scanner.NextInt();
            sets[i] = new int[count];

            for (int j = 0; j < count; j++)
            {
                int value = scanner.NextInt();
                sets[i][j] = value;

                if (setsByElement[value] == null)
                    setsByElement[value] = new List<int>();

                setsByElement[value].Add(i);

                if (value == m)
                    containsM[i] = true;
            }
