        {
            if (distance[setIndex] == -1)
            {
                distance[setIndex] = 0;
                queue[tail++] = setIndex;
            }
        }

        bool[] processedElement = new bool[m + 1];

        while (head < tail)
        {
            int current = queue[head++];

            if (containsM[current])
