            while (c > 32 && c != -1)
            {
                chars.Append((char)c);
                c = Read();
            }
            return chars.ToString();
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value * sign;
        }
    }

    private static long Encode(int x, int y)
    {
        return ((long)x << 32) ^ (uint)y;
    }

