            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        int[] head = new int[n];
        int[] degree = new int[n];
        for (int i = 0; i < n; i++) head[i] = -1;

        int[] to = new int[2 * (n - 1)];
        int[] next = new int[2 * (n - 1)];
        int edgeIndex = 0;

        for (int i = 0; i < n - 1; i++)
        {
            int u = scanner.NextInt() - 1;
            int v = scanner.NextInt() - 1;

            to[edgeIndex] = v;
            next[edgeIndex] = head[u];
            head[u] = edgeIndex++;

            to[edgeIndex] = u;
            next[edgeIndex] = head[v];
            head[v] = edgeIndex++;

            degree[u]++;
            degree[v]++;
        }

        int root = 0;
        for (int i = 0; i < n; i++)
        {
            if (degree[i] == 1)
            {
                root = i;
                break;
            }
        }

        int[] distance = new int[n];
        for (int i = 0; i < n; i++) distance[i] = -1;

        int[] queue = new int[n];
        int front = 0, back = 0;
        queue[back++] = root;
        distance[root] = 0;

        var levels = new List<int>();

        while (front < back)
        {
            int v = queue[front++];

            if (distance[v] % 3 == 1)
                levels.Add(degree[v]);

            for (int e = head[v]; e != -1; e = next[e])
            {
                int u = to[e];
                if (distance[u] != -1) continue;

                distance[u] = distance[v] + 1;
                queue[back++] = u;
            }
        }

        levels.Sort();

        var output = new StringBuilder();
        for (int i = 0; i < levels.Count; i++)
        {
            if (i > 0) output.Append(' ');
            output.Append(levels[i]);
        }

        Console.WriteLine(output.ToString());
    }
}
