public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    private sealed class DisjointSetUnion
    {
        private readonly int[] parent;
        private readonly int[] size;

        public DisjointSetUnion(int n)
        {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++)
            {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int Find(int x)
        {
            int root = x;
            while (parent[root] != root)
                root = parent[root];

            while (parent[x] != x)
            {
                int next = parent[x];
                parent[x] = root;
                x = next;
            }

            return root;
        }

        public void Union(int a, int b)
        {
            a = Find(a);
            b = Find(b);
            if (a == b) return;

            if (size[a] < size[b])
            {
                int temp = a;
                a = b;
                b = temp;
            }

            parent[b] = a;
            size[a] += size[b];
        }
    }

    private static long EncodePair(int a, int b)
    {
        if (a > b)
        {
            int temp = a;
            a = b;
            b = temp;
        }

        return ((long)a << 32) | (uint)b;
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();

        int n = scanner.NextInt();
        int m = scanner.NextInt();

        DisjointSetUnion dsu = new DisjointSetUnion(n);

        for (int i = 0; i < m; i++)
        {
            int u = scanner.NextInt() - 1;
            int v = scanner.NextInt() - 1;
            dsu.Union(u, v);
        }

        int k = scanner.NextInt();
        HashSet<long> forbiddenPairs = new HashSet<long>();

        for (int i = 0; i < k; i++)
        {
            int x = scanner.NextInt() - 1;
            int y = scanner.NextInt() - 1;
            int componentX = dsu.Find(x);
            int componentY = dsu.Find(y);
            forbiddenPairs.Add(EncodePair(componentX, componentY));
        }

        int q = scanner.NextInt();
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < q; i++)
        {
            int p = scanner.NextInt() - 1;
            int qVertex = scanner.NextInt() - 1;

            int componentP = dsu.Find(p);
            int componentQ = dsu.Find(qVertex);

            bool isGood = componentP == componentQ ||
                          !forbiddenPairs.Contains(EncodePair(componentP, componentQ));

            output.AppendLine(isGood ? "Yes" : "No");
        }

        Console.Write(output.ToString());
    }
}
