using System;
using System.IO;
using System.Text;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    private static long[] times;
    private static long[] prefix;

    private static long SleepUntil(long time)
    {
        int left = 0;
        int right = times.Length;

        // Find the first index whose time is greater than 'time'.
        while (left < right)
        {
            int mid = left + (right - left) / 2;
            if (times[mid] <= time)
                left = mid + 1;
            else
                right = mid;
        }

        int index = left - 1;
        long result = prefix[index];

        // After an odd zero-based index, Takahashi is asleep.
        if ((index & 1) == 1)
            result += time - times[index];

        return result;
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        times = new long[n];
        prefix = new long[n];

        for (int i = 0; i < n; i++)
            times[i] = scanner.NextLong();

        for (int i = 1; i < n; i++)
        {
            prefix[i] = prefix[i - 1];

            // The interval [times[i-1], times[i]) is asleep when i is even.
            if ((i & 1) == 0)
                prefix[i] += times[i] - times[i - 1];
        }

        int q = scanner.NextInt();
        var output = new StringBuilder();

        for (int i = 0; i < q; i++)
        {
            long l = scanner.NextLong();
            long r = scanner.NextLong();
            output.Append(SleepUntil(r) - SleepUntil(l)).Append('\n');
        }

        Console.Write(output.ToString());
    }
}
