using System.IO;
using System.Text;

public class Program
{
    private struct Entry
    {
        public int Vertex;
        public int Power;

        public Entry(int vertex, int power)
        {
            Vertex = vertex;
            Power = power;
        }
    }

    private class MaxHeap
    {
        private Entry[] heap;
        private int count;

        public MaxHeap(int capacity)
        {
            heap = new Entry[Math.Max(4, capacity)];
            count = 0;
        }

        public int Count
        {
            get { return count; }
        }

        public void Push(Entry value)
        {
            if (count == heap.Length)
                Array.Resize(ref heap, heap.Length * 2);

            int index = count++;
            while (index > 0)
            {
                int parent = (index - 1) / 2;
                if (heap[parent].Power >= value.Power)
                    break;

                heap[index] = heap[parent];
                index = parent;
            }
            heap[index] = value;
        }

        public Entry Pop()
        {
            Entry result = heap[0];
            Entry last = heap[--count];

            if (count > 0)
            {
                int index = 0;
                while (true)
                {
                    int left = index * 2 + 1;
                    if (left >= count)
                        break;

                    int right = left + 1;
                    int child = left;

                    if (right < count && heap[right].Power > heap[left].Power)
                        child = right;

                    if (heap[child].Power <= last.Power)
                        break;

                    heap[index] = heap[child];
                    index = child;
                }
                heap[index] = last;
            }

            return result;
        }
    }

