        for (int i = 0; i < m; i++)
        {
            int a = scanner.NextInt() - 1;
            int b = scanner.NextInt() - 1;
            graph[a].Add(b);
            graph[b].Add(a);
        }

        int[] best = new int[n];
        for (int i = 0; i < n; i++)
            best[i] = -1;

        MaxHeap heap = new MaxHeap(k);

        for (int i = 0; i < k; i++)
        {
            int position = scanner.NextInt() - 1;
            int stamina = scanner.NextInt();

            if (stamina > best[position])
            {
                best[position] = stamina;
                heap.Push(new Entry(position, stamina));
            }
        }

        while (heap.Count > 0)
        {
            Entry current = heap.Pop();

            if (current.Power != best[current.Vertex])
                continue;

            if (current.Power == 0)
                continue;

            int nextPower = current.Power - 1;
            List<int> neighbors = graph[current.Vertex];

            for (int i = 0; i < neighbors.Count; i++)
            {
                int next = neighbors[i];
                if (nextPower > best[next])
                {
                    best[next] = nextPower;
                    heap.Push(new Entry(next, nextPower));
                }
            }
        }

        int guardedCount = 0;
        for (int i = 0; i < n; i++)
        {
            if (best[i] >= 0)
                guardedCount++;
        }

        StringBuilder output = new StringBuilder();
        output.Append(guardedCount).Append('\n');

        bool first = true;
        for (int i = 0; i < n; i++)
        {
            if (best[i] >= 0)
            {
                if (!first)
                    output.Append(' ');
                output.Append(i + 1);
                first = false;
            }
        }
        output.Append('\n');

        Console.Write(output.ToString());
    }
}
