public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    private sealed class FenwickTree
    {
        private readonly int size;
        private readonly int[] counts;
        private readonly long[] sums;

        public FenwickTree(int size)
        {
            this.size = size;
            counts = new int[size + 1];
            sums = new long[size + 1];
        }

        public void Add(int index, int countDelta, long sumDelta)
        {
            for (int i = index; i <= size; i += i & -i)
            {
                counts[i] += countDelta;
                sums[i] += sumDelta;
            }
        }

        public int PrefixCount(int index)
        {
            int result = 0;
            for (int i = index; i > 0; i -= i & -i)
                result += counts[i];
            return result;
        }

        public long PrefixSum(int index)
        {
            long result = 0;
            for (int i = index; i > 0; i -= i & -i)
                result += sums[i];
            return result;
        }

        public int FindByOrder(int order)
        {
            int index = 0;
            int accumulated = 0;
            int step = 1;

            while ((step << 1) <= size)
                step <<= 1;

            for (; step > 0; step >>= 1)
            {
                int next = index + step;
                if (next <= size && accumulated + counts[next] < order)
                {
                    index = next;
                    accumulated += counts[next];
                }
            }

            return index + 1;
        }
    }

    private static int LowerBound(int[] values, int target)
    {
        int left = 0;
        int right = values.Length;

        while (left < right)
        {
            int mid = left + ((right - left) >> 1);
            if (values[mid] < target)
                left = mid + 1;
            else
                right = mid;
        }

        return left;
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();

        int n = scanner.NextInt();
        int k = scanner.NextInt();
        int q = scanner.NextInt();

        int[] updateIndices = new int[q];
        int[] updateValues = new int[q];
        int[] coordinates = new int[q + 1];
        coordinates[0] = 0;

        for (int i = 0; i < q; i++)
        {
            updateIndices[i] = scanner.NextInt() - 1;
            updateValues[i] = scanner.NextInt();
            coordinates[i + 1] = updateValues[i];
        }

        Array.Sort(coordinates);
        int uniqueCount = 0;
        for (int i = 0; i < coordinates.Length; i++)
        {
            if (uniqueCount == 0 || coordinates[i] != coordinates[uniqueCount - 1])
                coordinates[uniqueCount++] = coordinates[i];
        }
        Array.Resize(ref coordinates, uniqueCount);

        FenwickTree fenwick = new FenwickTree(uniqueCount);
        int zeroPosition = LowerBound(coordinates, 0) + 1;
        fenwick.Add(zeroPosition, n, 0);

        int[] currentValues = new int[n];
        long totalSum = 0;
        int smallestCount = n - k;

        StringBuilder output = new StringBuilder();

        for (int i = 0; i < q; i++)
        {
            int arrayIndex = updateIndices[i];
            int oldValue = currentValues[arrayIndex];
            int newValue = updateValues[i];

            int oldPosition = LowerBound(coordinates, oldValue) + 1;
            int newPosition = LowerBound(coordinates, newValue) + 1;

            fenwick.Add(oldPosition, -1, -(long)oldValue);
            fenwick.Add(newPosition, 1, newValue);

            currentValues[arrayIndex] = newValue;
            totalSum += (long)newValue - oldValue;

            long smallestSum = 0;

            if (smallestCount > 0)
            {
                int boundaryPosition = fenwick.FindByOrder(smallestCount);
                int countBefore = fenwick.PrefixCount(boundaryPosition - 1);
                long sumBefore = fenwick.PrefixSum(boundaryPosition - 1);
                int remaining = smallestCount - countBefore;

                smallestSum = sumBefore +
                              (long)remaining * coordinates[boundaryPosition - 1];
            }

            output.Append(totalSum - smallestSum).Append('\n');
        }

        Console.Write(output.ToString());
    }
}
