using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private class FastScanner
    {
        private readonly TextReader reader = Console.In;
        private readonly Queue<string> tokens = new Queue<string>();

        public string Next()
        {
            while (tokens.Count == 0)
            {
                string line = reader.ReadLine();
                if (line == null) return null;

                foreach (string token in line.Split(new[] { ' ', '\t' },
                             StringSplitOptions.RemoveEmptyEntries))
                {
                    tokens.Enqueue(token);
                }
            }
            return tokens.Dequeue();
        }

        public int NextInt()
        {
            return int.Parse(Next());
        }
    }

    private static List<bool[]> GetValidPlacements(
        string[] sheet, string[] target, int targetHeight, int targetWidth)
    {
        var cells = new List<Tuple<int, int>>();
        int minRow = int.MaxValue;
        int minCol = int.MaxValue;
        int maxRow = int.MinValue;
        int maxCol = int.MinValue;

        for (int r = 0; r < sheet.Length; r++)
        {
            for (int c = 0; c < sheet[r].Length; c++)
            {
                if (sheet[r][c] == '#')
                {
                    cells.Add(Tuple.Create(r, c));
                    minRow = Math.Min(minRow, r);
                    minCol = Math.Min(minCol, c);
                    maxRow = Math.Max(maxRow, r);
                    maxCol = Math.Max(maxCol, c);
                }
            }
        }

        int shapeHeight = maxRow - minRow + 1;
        int shapeWidth = maxCol - minCol + 1;
        var placements = new List<bool[]>();

        if (shapeHeight > targetHeight || shapeWidth > targetWidth)
            return placements;

        for (int top = 0; top + shapeHeight <= targetHeight; top++)
        {
            for (int left = 0; left + shapeWidth <= targetWidth; left++)
            {
                bool valid = true;
                bool[] covered = new bool[targetHeight * targetWidth];

                foreach (var cell in cells)
                {
                    int r = top + cell.Item1 - minRow;
                    int c = left + cell.Item2 - minCol;

                    if (target[r][c] != '#')
                    {
                        valid = false;
                        break;
                    }

                    covered[r * targetWidth + c] = true;
                }

                if (valid)
                    placements.Add(covered);
            }
        }

        return placements;
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int ha = scanner.NextInt();
        int wa = scanner.NextInt();
        string[] a = new string[ha];
        for (int i = 0; i < ha; i++)
            a[i] = scanner.Next();

        int hb = scanner.NextInt();
        int wb = scanner.NextInt();
        string[] b = new string[hb];
        for (int i = 0; i < hb; i++)
            b[i] = scanner.Next();

        int hx = scanner.NextInt();
        int wx = scanner.NextInt();
        string[] x = new string[hx];
        for (int i = 0; i < hx; i++)
            x[i] = scanner.Next();

        List<bool[]> placementsA = GetValidPlacements(a, x, hx, wx);
        List<bool[]> placementsB = GetValidPlacements(b, x, hx, wx);

        foreach (bool[] coverA in placementsA)
        {
            foreach (bool[] coverB in placementsB)
            {
                bool matches = true;

                for (int r = 0; r < hx && matches; r++)
                {
                    for (int c = 0; c < wx; c++)
                    {
                        bool isBlack = coverA[r * wx + c] || coverB[r * wx + c];
                        if (isBlack != (x[r][c] == '#'))
                        {
                            matches = false;
                            break;
                        }
                    }
                }

                if (matches)
                {
                    Console.WriteLine("Yes");
                    return;
                }
            }
        }

        Console.WriteLine("No");
    }
}
