        string[] first = Console.ReadLine().Split();
        int h = int.Parse(first[0]);
        int w = int.Parse(first[1]);

        string[] grid = new string[h];
        for (int i = 0; i < h; i++)
            grid[i] = Console.ReadLine();

        if (grid[0][0] != 's')
        {
            Console.WriteLine("No");
            return;
        }

        const string pattern = "snuke";
        bool[,] visited = new bool[h, w];
        Queue<int> queue = new Queue<int>();

        visited[0, 0] = true;
        queue.Enqueue(0);

        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        while (queue.Count > 0)
        {
            int position = queue.Dequeue();
            int row = position / w;
            int col = position % w;

            if (row == h - 1 && col == w - 1)
            {
                Console.WriteLine("Yes");
                return;
            }

            int index = pattern.IndexOf(grid[row][col]);
            char nextLetter = pattern[(index + 1) % 5];

            for (int direction = 0; direction < 4; direction++)
            {
                int nextRow = row + dr[direction];
                int nextCol = col + dc[direction];

                if (nextRow < 0 || nextRow >= h ||
                    nextCol < 0 || nextCol >= w ||
                    visited[nextRow, nextCol] ||
                    grid[nextRow][nextCol] != nextLetter)
                {
                    continue;
                }

                visited[nextRow, nextCol] = true;
                queue.Enqueue(nextRow * w + nextCol);
            }
        }

        Console.WriteLine("No");
    }
