    private static int Mex(int a, int b, int c)
    {
        int mask = (1 << a) | (1 << b) | (1 << c);
        for (int x = 0; x <= 3; x++)
        {
            if ((mask & (1 << x)) == 0)
                return x;
        }
        return 3;
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int[] a = new int[n];

        for (int i = 0; i < n; i++)
            a[i] = scanner.NextInt();

