        for (int i = 0; i < n; i++)
        {
            int value = a[i];

            if (s[i] == 'M')
            {
                mCount[value]++;
            }
            else if (s[i] == 'E')
            {
                for (int m = 0; m < 3; m++)
                    meCount[m, value] += mCount[m];
            }
            else
            {
                for (int m = 0; m < 3; m++)
                {
                    for (int e = 0; e < 3; e++)
                    {
                        answer += meCount[m, e] * Mex(m, e, value);
                    }
                }
            }
        }

        Console.WriteLine(answer);
    }
