    private static int MaximumDistance(List<int>[] graph, int start)
    {
        int n = graph.Length;
        int[] distance = new int[n];
        for (int i = 0; i < n; i++)
            distance[i] = -1;

        int[] queue = new int[n];
        int head = 0;
        int tail = 0;

        distance[start] = 0;
        queue[tail++] = start;
        int maximum = 0;

        while (head < tail)
        {
            int vertex = queue[head++];
            if (distance[vertex] > maximum)
                maximum = distance[vertex];

            foreach (int next in graph[vertex])
            {
                if (distance[next] != -1)
                    continue;

                distance[next] = distance[vertex] + 1;
                queue[tail++] = next;
            }
        }

        return maximum;
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n1 = scanner.NextInt();
        int n2 = scanner.NextInt();
        int m = scanner.NextInt();
        int n = n1 + n2;

        var graph = new List<int>[n];
        for (int i = 0; i < n; i++)
            graph[i] = new List<int>();

        for (int i = 0; i < m; i++)
        {
            int a = scanner.NextInt() - 1;
            int b = scanner.NextInt() - 1;
            graph[a].Add(b);
            graph[b].Add(a);
        }

        int leftMaximum = MaximumDistance(graph, 0);
        int rightMaximum = MaximumDistance(graph, n - 1);

        Console.WriteLine(leftMaximum + rightMaximum + 1);
    }
}
