    static int n, targetTeams;
    static int[] incompatible;
    static int[] teams;

    static long CountWays(int player, int teamCount)
    {
        if (player == n)
            return teamCount == targetTeams ? 1L : 0L;

        int remaining = n - player;
        if (teamCount > targetTeams || teamCount + remaining < targetTeams)
            return 0L;

        long result = 0;

        for (int i = 0; i < teamCount; i++)
        {
            if ((teams[i] & incompatible[player]) != 0)
                continue;

            teams[i] |= 1 << player;
            result += CountWays(player + 1, teamCount);
            teams[i] ^= 1 << player;
        }

        if (teamCount < targetTeams)
        {
            teams[teamCount] = 1 << player;
            result += CountWays(player + 1, teamCount + 1);
            teams[teamCount] = 0;
        }

        return result;
    }

