using System;
using System.IO;

public class Program
{
    const long Mod = 998244353;
    const int MaxSum = 10;
    const int MaskCount = 1 << (MaxSum + 1);
    const int FullMask = MaskCount - 1;

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());
        int n = scanner.NextInt();

        long[] dp = new long[MaskCount];
        dp[1] = 1; // Only sum 0 is initially reachable.

        for (int i = 0; i < n; i++)
        {
            int a = scanner.NextInt();
            int relevant = Math.Min(a, MaxSum);
            long unchangedWays = Math.Max(0, a - MaxSum);
            long[] next = new long[MaskCount];

            for (int mask = 0; mask < MaskCount; mask++)
            {
                long probability = dp[mask];
                if (probability == 0) continue;

                if (unchangedWays > 0)
                {
                    next[mask] = (next[mask] + probability * unchangedWays) % Mod;
                }

                for (int value = 1; value <= relevant; value++)
                {
                    int newMask = mask | ((mask << value) & FullMask);
                    next[newMask] += probability;
                    if (next[newMask] >= Mod)
                        next[newMask] -= Mod;
                }
            }

            long inverseA = ModPow(a, Mod - 2);
            for (int mask = 0; mask < MaskCount; mask++)
            {
                next[mask] = next[mask] * inverseA % Mod;
            }

            dp = next;
        }

        long answer = 0;
        int targetBit = 1 << MaxSum;

        for (int mask = 0; mask < MaskCount; mask++)
        {
            if ((mask & targetBit) != 0)
            {
                answer += dp[mask];
                if (answer >= Mod)
                    answer -= Mod;
            }
        }

        Console.WriteLine(answer);
    }

    static long ModPow(long value, long exponent)
    {
        long result = 1;
        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * value % Mod;

            value = value * value % Mod;
            exponent >>= 1;
        }
        return result;
    }

