    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        int[] next = new int[n];

        for (int i = 0; i < n; i++)
            next[i] = scanner.NextInt() - 1;

        int[] position = new int[n];
        for (int i = 0; i < n; i++)
            position[i] = -1;

        List<int> path = new List<int>();
        int current = 0;

        while (position[current] == -1)
        {
            position[current] = path.Count;
            path.Add(current);
            current = next[current];
        }

        int cycleStart = position[current];
        int cycleLength = path.Count - cycleStart;

        StringBuilder output = new StringBuilder();
        output.AppendLine(cycleLength.ToString());

        for (int i = cycleStart; i < path.Count; i++)
        {
            if (i > cycleStart)
                output.Append(' ');
            output.Append(path[i] + 1);
        }
        output.AppendLine();

        Console.Write(output.ToString());
    }

