    public static void Main()
    {
        string[] first = Console.ReadLine().Split();
        int n = int.Parse(first[0]);
        int m = int.Parse(first[1]);

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++)
            grid[i] = Console.ReadLine().ToCharArray();

        bool[,] visitedStops = new bool[n, m];
        bool[,] touched = new bool[n, m];
        Queue<int> queue = new Queue<int>();

        int startRow = 1;
        int startCol = 1;
        visitedStops[startRow, startCol] = true;
        touched[startRow, startCol] = true;
        queue.Enqueue(startRow * m + startCol);

        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        while (queue.Count > 0)
        {
            int position = queue.Dequeue();
            int row = position / m;
            int col = position % m;

            for (int direction = 0; direction < 4; direction++)
            {
                int currentRow = row;
                int currentCol = col;

                while (grid[currentRow + dr[direction]][currentCol + dc[direction]] == '.')
                {
                    currentRow += dr[direction];
                    currentCol += dc[direction];
                    touched[currentRow, currentCol] = true;
                }

                if (!visitedStops[currentRow, currentCol])
                {
                    visitedStops[currentRow, currentCol] = true;
                    queue.Enqueue(currentRow * m + currentCol);
                }
            }
        }

        int answer = 0;
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < m; j++)
            {
                if (touched[i, j])
                    answer++;
            }
        }

        Console.WriteLine(answer);
    }
}
