        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int h = scanner.NextInt();
        int w = scanner.NextInt();
        int n = scanner.NextInt();

        var holed = new byte[h * w];

        for (int i = 0; i < n; i++)
        {
            int row = scanner.NextInt() - 1;
            int col = scanner.NextInt() - 1;
            holed[row * w + col] = 1;
        }

        var dp = new int[w + 1];
        long answer = 0;

        for (int row = 0; row < h; row++)
        {
            int diagonal = 0;
            int offset = row * w;

            for (int col = 1; col <= w; col++)
            {
                int above = dp[col];

                if (holed[offset + col - 1] != 0)
                {
                    dp[col] = 0;
                }
                else
                {
                    int minimum = above;
                    if (dp[col - 1] < minimum) minimum = dp[col - 1];
                    if (diagonal < minimum) minimum = diagonal;

                    dp[col] = minimum + 1;
                    answer += dp[col];
                }

                diagonal = above;
            }
        }

        Console.WriteLine(answer);
    }
}
