        int m = int.Parse(first[1]);

        string[] grid = new string[n];
        for (int i = 0; i < n; i++)
            grid[i] = Console.ReadLine();

        StringBuilder output = new StringBuilder();

        for (int row = 0; row <= n - 9; row++)
        {
            for (int col = 0; col <= m - 9; col++)
            {
                if (IsTakCode(grid, row, col))
                    output.Append(row + 1).Append(' ').Append(col + 1).Append('\n');
            }
        }

        Console.Write(output.ToString());
    }

    private static bool IsTakCode(string[] grid, int row, int col)
    {
        // Top-left 3x3 region must be black.
        for (int i = 0; i < 3; i++)
            for (int j = 0; j < 3; j++)
                if (grid[row + i][col + j] != '#')
                    return false;

        // Cells adjacent to the top-left region must be white.
        for (int i = 0; i < 4; i++)
            if (grid[row + i][col + 3] != '.')
                return false;

        for (int j = 0; j < 3; j++)
            if (grid[row + 3][col + j] != '.')
                return false;

        // Bottom-right 3x3 region must be black.
        for (int i = 6; i < 9; i++)
            for (int j = 6; j < 9; j++)
                if (grid[row + i][col + j] != '#')
                    return false;

        // Cells adjacent to the bottom-right region must be white.
        for (int j = 5; j < 9; j++)
            if (grid[row + 5][col + j] != '.')
                return false;

        for (int i = 6; i < 9; i++)
            if (grid[row + i][col + 5] != '.')
                return false;

        return true;
    }
