public class Program
{
    private const int Mod = 998244353;

    public static void Main()
    {
        string s = Console.ReadLine();
        int n = s.Length;

        int[] dp = new int[n + 2];
        int[] next = new int[n + 2];
        dp[0] = 1;

        for (int i = 0; i < n; i++)
        {
            Array.Clear(next, 0, next.Length);
            char c = s[i];

            for (int balance = 0; balance <= i; balance++)
            {
                int ways = dp[balance];
                if (ways == 0) continue;

                if (c == '(' || c == '?')
                {
                    int value = next[balance + 1] + ways;
                    if (value >= Mod) value -= Mod;
                    next[balance + 1] = value;
                }

                if ((c == ')' || c == '?') && balance > 0)
                {
                    int value = next[balance - 1] + ways;
                    if (value >= Mod) value -= Mod;
                    next[balance - 1] = value;
                }
            }

            int[] temp = dp;
            dp = next;
            next = temp;
        }

        Console.WriteLine(dp[0]);
    }
}
