            {
                int xBase = x * Plane;
                for (int y = y1; y < y2; y++)
                {
                    int index = xBase + y * Size + z1;
                    for (int z = z1; z < z2; z++)
                        owner[index++] = id;
                }
            }
        }

        int[] answer = new int[n];
        var adjacentPairs = new HashSet<long>();

        for (int x = 0; x < Size; x++)
        {
            int xBase = x * Plane;
            for (int y = 0; y < Size; y++)
            {
                int index = xBase + y * Size;
                for (int z = 0; z < Size; z++, index++)
                {
                    int a = owner[index];
                    if (a < 0)
                        continue;

                    if (x + 1 < Size)
                        AddPair(a, owner[index + Plane], n, adjacentPairs, answer);

                    if (y + 1 < Size)
                        AddPair(a, owner[index + Size], n, adjacentPairs, answer);

                    if (z + 1 < Size)
                        AddPair(a, owner[index + 1], n, adjacentPairs, answer);
                }
