            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32);

            int value = 0;
            while (c > 32)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int m = scanner.NextInt();

        var pullTabCans = new List<long>();
        var regularCans = new List<long>();
        var openers = new List<long>();

        for (int i = 0; i < n; i++)
        {
            int type = scanner.NextInt();
            long x = scanner.NextInt();

            if (type == 0)
                pullTabCans.Add(x);
            else if (type == 1)
                regularCans.Add(x);
            else
                openers.Add(x);
        }

        pullTabCans.Sort((a, b) => b.CompareTo(a));
        regularCans.Sort((a, b) => b.CompareTo(a));
        openers.Sort((a, b) => b.CompareTo(a));

        long[] pullTabPrefix = new long[pullTabCans.Count + 1];
        for (int i = 0; i < pullTabCans.Count; i++)
            pullTabPrefix[i + 1] = pullTabPrefix[i] + pullTabCans[i];

        long[] regularPrefix = new long[regularCans.Count + 1];
        for (int i = 0; i < regularCans.Count; i++)
            regularPrefix[i + 1] = regularPrefix[i] + regularCans[i];

        long answer = 0;
        long capacity = 0;
        int openerCount = 0;
        int maxRegular = Math.Min(m, regularCans.Count);

        for (int regularCount = 0; regularCount <= maxRegular; regularCount++)
        {
            while (capacity < regularCount && openerCount < openers.Count)
            {
                capacity += openers[openerCount];
                openerCount++;
            }

            if (capacity < regularCount)
                break;

            if (regularCount + openerCount > m)
                break;

            int remainingSlots = m - regularCount - openerCount;
            int pullTabCount = Math.Min(remainingSlots, pullTabCans.Count);

            long happiness = regularPrefix[regularCount] + pullTabPrefix[pullTabCount];
            if (happiness > answer)
                answer = happiness;
        }

        Console.WriteLine(answer);
    }
}
