        long[] a = new long[n];
        long sum = 0;

        for (int i = 0; i < n; i++)
        {
            a[i] = scanner.NextLong();
            sum += a[i];
        }

        long lower = sum / n;
        long upper = (sum + n - 1) / n;

        long deficit = 0;
        long excess = 0;

        for (int i = 0; i < n; i++)
        {
            if (a[i] < lower)
                deficit += lower - a[i];
            else if (a[i] > upper)
                excess += a[i] - upper;
        }

        Console.WriteLine(Math.Max(deficit, excess));
    }
