        {
            int c = SkipWhiteSpace();
            char[] chars = new char[16];
            int count = 0;

            while (c > 32 && c != -1)
            {
                if (count == chars.Length)
                    Array.Resize(ref chars, chars.Length * 2);

                chars[count++] = (char)c;
                c = ReadByte();
            }

            return new string(chars, 0, count);
        }

        public char NextChar()
        {
            return (char)SkipWhiteSpace();
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        char[] s = scanner.Next().ToCharArray();
        int q = scanner.NextInt();

        int[] lastUpdate = new int[n];
        int lastGlobalOperation = -1;
        int globalType = 0;

        for (int operation = 1; operation <= q; operation++)
        {
            int type = scanner.NextInt();
            int x = scanner.NextInt();
            char c = scanner.NextChar();

            if (type == 1)
            {
                int index = x - 1;
                s[index] = c;
                lastUpdate[index] = operation;
            }
            else
            {
                lastGlobalOperation = operation;
                globalType = type;
            }
        }

        if (globalType != 0)
        {
            for (int i = 0; i < n; i++)
            {
                if (lastUpdate[i] < lastGlobalOperation)
                {
                    if (globalType == 2)
                        s[i] = char.ToLowerInvariant(s[i]);
                    else
                        s[i] = char.ToUpperInvariant(s[i]);
                }
            }
        }

        Console.WriteLine(new string(s));
    }
}
