public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value * sign;
        }
    }

    private sealed class Wheel
    {
        public int Cost;
        public int TotalCount;
        public int[] PositiveScores;
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int m = scanner.NextInt();

        var wheels = new Wheel[n];

        for (int i = 0; i < n; i++)
        {
            int cost = scanner.NextInt();
            int p = scanner.NextInt();

            int[] scores = new int[p];
            int positiveCount = 0;

            for (int j = 0; j < p; j++)
            {
                int score = scanner.NextInt();
                if (score > 0)
                    scores[positiveCount++] = score;
            }

            int[] positiveScores = new int[positiveCount];
            Array.Copy(scores, positiveScores, positiveCount);

            wheels[i] = new Wheel
            {
                Cost = cost,
                TotalCount = p,
                PositiveScores = positiveScores
            };
        }

        // dp[x]: minimum expected cost to earn at least x more points.
        double[] dp = new double[m + 1];

        for (int x = 1; x <= m; x++)
        {
            double best = double.PositiveInfinity;

            for (int i = 0; i < n; i++)
            {
                Wheel wheel = wheels[i];
                double numerator = (double)wheel.Cost * wheel.TotalCount;

                foreach (int score in wheel.PositiveScores)
                {
                    numerator += dp[Math.Max(0, x - score)];
                }

                double expectedCost = numerator / wheel.PositiveScores.Length;
                if (expectedCost < best)
                    best = expectedCost;
            }

            dp[x] = best;
        }

        Console.WriteLine(dp[m].ToString("R", CultureInfo.InvariantCulture));
    }
}
