using System;
using System.IO;
using System.Text;

public class Program
{
    const long Mod = 998244353;

    sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }
    }

    static int Find(int[] parent, int x)
    {
        int root = x;
        while (parent[root] != root)
            root = parent[root];

        while (parent[x] != x)
        {
            int next = parent[x];
            parent[x] = root;
            x = next;
        }

        return root;
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int totalNodes = 2 * n - 1;

        int[] dsuParent = new int[n];
        int[] componentSize = new int[n];
        int[] treeRoot = new int[n];

        for (int i = 0; i < n; i++)
        {
            dsuParent[i] = i;
            componentSize[i] = 1;
            treeRoot[i] = i;
        }

        long[] inverse = new long[n + 1];
        inverse[1] = 1;
        for (int i = 2; i <= n; i++)
            inverse[i] = Mod - (Mod / i) * inverse[Mod % i] % Mod;

        int[] leftChild = new int[totalNodes];
        int[] rightChild = new int[totalNodes];
        long[] leftWeight = new long[totalNodes];
        long[] rightWeight = new long[totalNodes];

        for (int match = 0; match < n - 1; match++)
        {
            int p = scanner.NextInt() - 1;
            int q = scanner.NextInt() - 1;

            int rootP = Find(dsuParent, p);
            int rootQ = Find(dsuParent, q);

            int sizeP = componentSize[rootP];
            int sizeQ = componentSize[rootQ];
            int combinedSize = sizeP + sizeQ;
            int newTreeNode = n + match;

            leftChild[newTreeNode] = treeRoot[rootP];
            rightChild[newTreeNode] = treeRoot[rootQ];
            leftWeight[newTreeNode] = sizeP * inverse[combinedSize] % Mod;
            rightWeight[newTreeNode] = sizeQ * inverse[combinedSize] % Mod;

            if (componentSize[rootP] < componentSize[rootQ])
            {
                int temp = rootP;
                rootP = rootQ;
                rootQ = temp;
            }

            dsuParent[rootQ] = rootP;
            componentSize[rootP] = combinedSize;
            treeRoot[rootP] = newTreeNode;
        }

        int finalRoot = treeRoot[Find(dsuParent, 0)];
        long[] expected = new long[totalNodes];
        expected[finalRoot] = 0;

        for (int node = totalNodes - 1; node >= n; node--)
        {
            int left = leftChild[node];
            int right = rightChild[node];

            expected[left] = (expected[node] + leftWeight[node]) % Mod;
            expected[right] = (expected[node] + rightWeight[node]) % Mod;
        }

        var output = new StringBuilder();
        for (int i = 0; i < n; i++)
        {
            if (i > 0) output.Append(' ');
            output.Append(expected[i]);
        }

        Console.WriteLine(output.ToString());
    }
}
