                if (length == 0) return -1;
            }
            return buffer[pointer++];
        }

        public string Next()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            char[] chars = new char[4096];
            int count = 0;

            while (c > 32 && c != -1)
            {
                chars[count++] = (char)c;
                c = Read();
            }

            return new string(chars, 0, count);
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();

        int h = scanner.NextInt();
        int w = scanner.NextInt();

        byte[][] grid = new byte[h][];
        int[][] rowCounts = new int[h][];
        int[][] columnCounts = new int[w][];

        for (int i = 0; i < h; i++)
            rowCounts[i] = new int[26];

        for (int j = 0; j < w; j++)
            columnCounts[j] = new int[26];

        for (int i = 0; i < h; i++)
        {
            string s = scanner.Next();
            grid[i] = new byte[w];

            for (int j = 0; j < w; j++)
            {
                int color = s[j] - 'a';
                grid[i][j] = (byte)color;
                rowCounts[i][color]++;
                columnCounts[j][color]++;
            }
        }

        int[] rowKinds = new int[h];
        int[] columnKinds = new int[w];

        for (int i = 0; i < h; i++)
        {
            for (int color = 0; color < 26; color++)
            {
                if (rowCounts[i][color] > 0)
                    rowKinds[i]++;
            }
        }

        for (int j = 0; j < w; j++)
        {
            for (int color = 0; color < 26; color++)
            {
                if (columnCounts[j][color] > 0)
                    columnKinds[j]++;
            }
        }

        bool[] activeRows = new bool[h];
        bool[] activeColumns = new bool[w];

        for (int i = 0; i < h; i++)
            activeRows[i] = true;

        for (int j = 0; j < w; j++)
            activeColumns[j] = true;

        int activeRowCount = h;
        int activeColumnCount = w;

        int[] rowsToDelete = new int[h];
        int[] columnsToDelete = new int[w];

        while (true)
        {
            int deletedRowCount = 0;
            int deletedColumnCount = 0;

            if (activeColumnCount >= 2)
            {
                for (int i = 0; i < h; i++)
                {
                    if (activeRows[i] && rowKinds[i] == 1)
                        rowsToDelete[deletedRowCount++] = i;
                }
            }

            if (activeRowCount >= 2)
            {
                for (int j = 0; j < w; j++)
                {
                    if (activeColumns[j] && columnKinds[j] == 1)
                        columnsToDelete[deletedColumnCount++] = j;
                }
            }

            if (deletedRowCount == 0 && deletedColumnCount == 0)
                break;

            for (int k = 0; k < deletedRowCount; k++)
                activeRows[rowsToDelete[k]] = false;

            activeRowCount -= deletedRowCount;

            for (int k = 0; k < deletedRowCount; k++)
            {
                int row = rowsToDelete[k];

                for (int column = 0; column < w; column++)
                {
                    if (!activeColumns[column])
                        continue;

                    int color = grid[row][column];
                    columnCounts[column][color]--;

                    if (columnCounts[column][color] == 0)
                        columnKinds[column]--;
                }
            }

            for (int k = 0; k < deletedColumnCount; k++)
                activeColumns[columnsToDelete[k]] = false;

            activeColumnCount -= deletedColumnCount;

            for (int k = 0; k < deletedColumnCount; k++)
            {
                int column = columnsToDelete[k];

                for (int row = 0; row < h; row++)
                {
                    if (!activeRows[row])
                        continue;

                    int color = grid[row][column];
                    rowCounts[row][color]--;

                    if (rowCounts[row][color] == 0)
                        rowKinds[row]--;
                }
            }
        }

        Console.WriteLine(activeRowCount * activeColumnCount);
    }
}
