        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32);

            int value = 0;
            while (c > 32)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        int[][] prerequisites = new int[n][];
        for (int i = 0; i < n; i++)
        {
            int count = scanner.NextInt();
            prerequisites[i] = new int[count];
            for (int j = 0; j < count; j++)
                prerequisites[i][j] = scanner.NextInt() - 1;
        }

        bool[] visited = new bool[n];
        int[] nodeStack = new int[n];
        int[] indexStack = new int[n];
        var order = new List<int>();

        int top = 0;
        nodeStack[0] = 0;
        indexStack[0] = 0;
        visited[0] = true;

        while (top >= 0)
        {
            int book = nodeStack[top];

            if (indexStack[top] < prerequisites[book].Length)
            {
                int required = prerequisites[book][indexStack[top]++];
                if (!visited[required])
                {
                    visited[required] = true;
                    top++;
                    nodeStack[top] = required;
                    indexStack[top] = 0;
                }
            }
            else
            {
                top--;
                if (book != 0)
                    order.Add(book + 1);
            }
        }

        var output = new StringBuilder();
        for (int i = 0; i < order.Count; i++)
        {
            if (i > 0) output.Append(' ');
            output.Append(order[i]);
        }

        Console.WriteLine(output.ToString());
    }
}
