    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int d = scanner.NextInt();
        long p = scanner.NextLong();

        long[] fares = new long[n];
        long totalFare = 0;

        for (int i = 0; i < n; i++)
        {
            fares[i] = scanner.NextLong();
            totalFare += fares[i];
        }

        Array.Sort(fares);
        Array.Reverse(fares);

        long answer = totalFare;
        long coveredFare = 0;
        int maxBatches = (n + d - 1) / d;

        for (int batches = 1; batches <= maxBatches; batches++)
        {
            int previousCovered = (batches - 1) * d;
            int covered = Math.Min(n, batches * d);

            for (int i = previousCovered; i < covered; i++)
                coveredFare += fares[i];

            long cost = (long)batches * p + totalFare - coveredFare;
            if (cost < answer)
                answer = cost;
        }

        Console.WriteLine(answer);
    }
}
