    static readonly int[][] Lines =
    {
        new[] { 0, 1, 2 },
        new[] { 3, 4, 5 },
        new[] { 6, 7, 8 },
        new[] { 0, 3, 6 },
        new[] { 1, 4, 7 },
        new[] { 2, 5, 8 },
        new[] { 0, 4, 8 },
        new[] { 2, 4, 6 }
    };

    static int[] values = new int[9];
    static bool[] seen = new bool[9];
    static long validOrders;

    static void Search(int depth)
    {
        if (depth == 9)
        {
            validOrders++;
            return;
        }

        for (int cell = 0; cell < 9; cell++)
        {
            if (seen[cell]) continue;

            bool disappointed = false;

            foreach (int[] line in Lines)
            {
                int firstOther = -1;
                int secondOther = -1;
                bool containsCell = false;

                for (int i = 0; i < 3; i++)
                {
                    if (line[i] == cell)
                    {
                        containsCell = true;
                    }
                    else if (firstOther == -1)
                    {
                        firstOther = line[i];
                    }
                    else
                    {
                        secondOther = line[i];
                    }
                }

                if (containsCell &&
                    seen[firstOther] &&
                    seen[secondOther] &&
                    values[firstOther] == values[secondOther] &&
                    values[cell] != values[firstOther])
                {
                    disappointed = true;
                    break;
                }
            }

            if (disappointed) continue;

            seen[cell] = true;
            Search(depth + 1);
            seen[cell] = false;
        }
    }

    public static void Main()
    {
        string input = Console.In.ReadToEnd();
        string[] tokens = input.Split(
            new[] { ' ', '\n', '\r', '\t' },
            StringSplitOptions.RemoveEmptyEntries
        );

        for (int i = 0; i < 9; i++)
            values[i] = int.Parse(tokens[i]);

        Search(0);

        const long totalOrders = 362880; // 9!
        double probability = (double)validOrders / totalOrders;
        Console.WriteLine(probability.ToString("G17", CultureInfo.InvariantCulture));
    }
