using System;
using System.IO;
using System.Text;

public static class Program
{
    private const int Period = 840;

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        long x = scanner.NextLong();
        long y = scanner.NextLong();

        var times = new long[Period];
        var remainders = new int[Period];

        int xRemainder = (int)(x % Period);
        for (int r = 0; r < Period; r++)
        {
            times[r] = r + x;
            int remainder = r + xRemainder;
            if (remainder >= Period) remainder -= Period;
            remainders[r] = remainder;
        }

        var waitingTimes = new int[9 * Period];
        for (int p = 1; p <= 8; p++)
        {
            int offset = p * Period;
            for (int r = 0; r < Period; r++)
            {
                waitingTimes[offset + r] = (p - r % p) % p;
            }
        }

        for (int i = 0; i < n - 1; i++)
        {
            int p = scanner.NextInt();
            long t = scanner.NextLong();

            int tableOffset = p * Period;
            int tRemainder = (int)(t % Period);

            for (int r = 0; r < Period; r++)
            {
                int wait = waitingTimes[tableOffset + remainders[r]];
                times[r] += wait + t;

                int newRemainder = remainders[r] + wait + tRemainder;
                if (newRemainder >= Period) newRemainder -= Period;
                remainders[r] = newRemainder;
            }
        }

        int q = scanner.NextInt();
        var output = new StringBuilder(q * 16);

        for (int i = 0; i < q; i++)
        {
            long departure = scanner.NextLong();
            int remainder = (int)(departure % Period);
            long answer = departure - remainder + times[remainder] + y;
            output.Append(answer).Append('\n');
        }

        Console.Write(output.ToString());
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            return (int)NextLong();
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            bool negative = false;
            if (c == '-')
            {
                negative = true;
                c = Read();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return negative ? -value : value;
        }
    }
}
