using System;

public class Program
{
    static int FindNextTime(string reel, char digit, int start, int m)
    {
        for (int time = start; time < start + m; time++)
        {
            if (reel[time % m] == digit)
                return time;
        }
        return -1;
    }

    public static void Main()
    {
        int m = int.Parse(Console.ReadLine());
        string[] reels =
        {
            Console.ReadLine(),
            Console.ReadLine(),
            Console.ReadLine()
        };

        int[,] orders =
        {
            { 0, 1, 2 },
            { 0, 2, 1 },
            { 1, 0, 2 },
            { 1, 2, 0 },
            { 2, 0, 1 },
            { 2, 1, 0 }
        };

        int answer = int.MaxValue;

        for (char digit = '0'; digit <= '9'; digit++)
        {
            for (int p = 0; p < 6; p++)
            {
                int nextStart = 0;
                int finishTime = -1;
                bool possible = true;

                for (int i = 0; i < 3; i++)
                {
                    int reelIndex = orders[p, i];
                    int time = FindNextTime(reels[reelIndex], digit, nextStart, m);

                    if (time == -1)
                    {
                        possible = false;
                        break;
                    }

                    finishTime = time;
                    nextStart = time + 1;
                }

                if (possible)
                    answer = Math.Min(answer, finishTime);
            }
        }

        Console.WriteLine(answer == int.MaxValue ? -1 : answer);
    }
