using System;
using System.IO;
using System.Text;
using System.Collections.Generic;

public class Program
{
    private struct Edge
    {
        public int To;
        public long Dx;
        public long Dy;

        public Edge(int to, long dx, long dy)
        {
            To = to;
            Dx = dx;
            Dy = dy;
        }
    }

    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            long sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value * sign;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int m = scanner.NextInt();

        var graph = new List<Edge>[n];
        for (int i = 0; i < n; i++)
            graph[i] = new List<Edge>();

        for (int i = 0; i < m; i++)
        {
            int a = scanner.NextInt() - 1;
            int b = scanner.NextInt() - 1;
            long x = scanner.NextLong();
            long y = scanner.NextLong();

            graph[a].Add(new Edge(b, x, y));
            graph[b].Add(new Edge(a, -x, -y));
        }

        var xCoordinates = new long[n];
        var yCoordinates = new long[n];
        var determined = new bool[n];
        var queue = new Queue<int>();

        determined[0] = true;
        queue.Enqueue(0);

        while (queue.Count > 0)
        {
            int current = queue.Dequeue();

            foreach (Edge edge in graph[current])
            {
                if (determined[edge.To])
                    continue;

                determined[edge.To] = true;
                xCoordinates[edge.To] = xCoordinates[current] + edge.Dx;
                yCoordinates[edge.To] = yCoordinates[current] + edge.Dy;
                queue.Enqueue(edge.To);
            }
        }

        var output = new StringBuilder();
        for (int i = 0; i < n; i++)
        {
            if (determined[i])
            {
                output.Append(xCoordinates[i])
                      .Append(' ')
                      .Append(yCoordinates[i])
                      .Append('\n');
            }
            else
            {
                output.Append("undecidable\n");
            }
        }

        Console.Write(output.ToString());
    }
}
