using System;
using System.IO;
using System.Text;

public class Program
{
    private struct ReturnEvent
    {
        public long Time;
        public int Person;

        public ReturnEvent(long time, int person)
        {
            Time = time;
            Person = person;
        }
    }

    private class IntMinHeap
    {
        private int[] data;
        private int count;

        public int Count { get { return count; } }

        public IntMinHeap(int capacity)
        {
            data = new int[Math.Max(1, capacity)];
        }

        public void Push(int value)
        {
            if (count == data.Length)
                Array.Resize(ref data, data.Length * 2);

            int i = count++;
            while (i > 0)
            {
                int parent = (i - 1) / 2;
                if (data[parent] <= value)
                    break;

                data[i] = data[parent];
                i = parent;
            }
            data[i] = value;
        }

        public int Pop()
        {
            int result = data[0];
            int value = data[--count];

            if (count > 0)
            {
                int i = 0;
                while (true)
                {
                    int left = i * 2 + 1;
                    if (left >= count)
                        break;

                    int right = left + 1;
                    int child = left;

                    if (right < count && data[right] < data[left])
                        child = right;

                    if (data[child] >= value)
                        break;

                    data[i] = data[child];
                    i = child;
                }
                data[i] = value;
            }

            return result;
        }
    }

    private class ReturnMinHeap
    {
        private ReturnEvent[] data;
        private int count;

        public int Count { get { return count; } }

        public ReturnMinHeap(int capacity)
        {
            data = new ReturnEvent[Math.Max(1, capacity)];
        }

        private static bool Less(ReturnEvent a, ReturnEvent b)
        {
            if (a.Time != b.Time)
                return a.Time < b.Time;
            return a.Person < b.Person;
        }

        public void Push(ReturnEvent value)
        {
            if (count == data.Length)
                Array.Resize(ref data, data.Length * 2);

            int i = count++;
            while (i > 0)
            {
                int parent = (i - 1) / 2;
                if (!Less(value, data[parent]))
                    break;

                data[i] = data[parent];
                i = parent;
            }
            data[i] = value;
        }

        public ReturnEvent Peek()
        {
            return data[0];
        }

        public ReturnEvent Pop()
        {
            ReturnEvent result = data[0];
            ReturnEvent value = data[--count];

            if (count > 0)
            {
                int i = 0;
                while (true)
                {
                    int left = i * 2 + 1;
                    if (left >= count)
                        break;

                    int right = left + 1;
                    int child = left;

                    if (right < count && Less(data[right], data[left]))
                        child = right;

                    if (!Less(data[child], value))
                        break;

                    data[i] = data[child];
                    i = child;
                }
                data[i] = value;
            }

            return result;
        }
    }

    private class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }
            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();

        int n = scanner.NextInt();
        int m = scanner.NextInt();

        long[] totals = new long[n];
        IntMinHeap available = new IntMinHeap(n);
        ReturnMinHeap returning = new ReturnMinHeap(m);

        for (int i = 0; i < n; i++)
            available.Push(i);

        for (int i = 0; i < m; i++)
        {
            long time = scanner.NextLong();
            long noodles = scanner.NextLong();
            long absence = scanner.NextLong();

            while (returning.Count > 0 && returning.Peek().Time <= time)
            {
                available.Push(returning.Pop().Person);
            }

            if (available.Count > 0)
            {
                int person = available.Pop();
                totals[person] += noodles;
                returning.Push(new ReturnEvent(time + absence, person));
            }
        }

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < n; i++)
            output.AppendLine(totals[i].ToString());

        Console.Write(output.ToString());
    }
}
