using System;
using System.IO;
using System.Text;

public static class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }
    }

    private static long CountDescendants(long n, long root, long depth)
    {
        // Since n <= 10^18 < 2^60, no vertex can have a descendant
        // at depth 60 or greater.
        if (depth >= 60)
            return 0;

        long width = 1L << (int)depth;

        if (root > n / width)
            return 0;

        long first = root * width;
        long available = n - first + 1;

        return available < width ? available : width;
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int testCases = (int)scanner.NextLong();
        var output = new StringBuilder();

        for (int test = 0; test < testCases; test++)
        {
            long n = scanner.NextLong();
            long x = scanner.NextLong();
            long k = scanner.NextLong();

            long answer = CountDescendants(n, x, k);
            long current = x;

            for (long upward = 1; current > 1 && upward <= k; upward++)
            {
                long parent = current / 2;

                if (upward == k)
                {
                    answer++;
                }
                else
                {
                    long sibling = current ^ 1L;
                    long remainingDepth = k - upward - 1;
                    answer += CountDescendants(n, sibling, remainingDepth);
                }

                current = parent;
            }

            output.Append(answer).Append('\n');
        }

        Console.Write(output.ToString());
    }
}
