using System;
using System.Collections.Generic;

public class Program
{
    private struct Cell
    {
        public int Row;
        public int Col;

        public Cell(int row, int col)
        {
            Row = row;
            Col = col;
        }
    }

    private static List<int> GeneratePlacements(List<Cell> original)
    {
        var placements = new HashSet<int>();
        var cells = new List<Cell>(original);

        for (int rotation = 0; rotation < 4; rotation++)
        {
            int minRow = int.MaxValue;
            int minCol = int.MaxValue;

            foreach (Cell cell in cells)
            {
                minRow = Math.Min(minRow, cell.Row);
                minCol = Math.Min(minCol, cell.Col);
            }

            var normalized = new List<Cell>();
            int height = 0;
            int width = 0;

            foreach (Cell cell in cells)
            {
                int row = cell.Row - minRow;
                int col = cell.Col - minCol;
                normalized.Add(new Cell(row, col));
                height = Math.Max(height, row + 1);
                width = Math.Max(width, col + 1);
            }

            for (int rowOffset = 0; rowOffset + height <= 4; rowOffset++)
            {
                for (int colOffset = 0; colOffset + width <= 4; colOffset++)
                {
                    int mask = 0;
                    foreach (Cell cell in normalized)
                    {
                        int row = cell.Row + rowOffset;
                        int col = cell.Col + colOffset;
                        mask |= 1 << (row * 4 + col);
                    }
                    placements.Add(mask);
                }
            }

            var rotated = new List<Cell>();
            foreach (Cell cell in normalized)
            {
                rotated.Add(new Cell(cell.Col, -cell.Row));
            }
            cells = rotated;
        }

        return new List<int>(placements);
    }

    public static void Main()
    {
        string[] input = Console.In.ReadToEnd()
            .Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        var shapes = new List<Cell>[3];
        int totalSquares = 0;
        int index = 0;

        for (int shape = 0; shape < 3; shape++)
        {
            shapes[shape] = new List<Cell>();

            for (int row = 0; row < 4; row++)
            {
                string line = input[index++];
                for (int col = 0; col < 4; col++)
                {
                    if (line[col] == '#')
                    {
                        shapes[shape].Add(new Cell(row, col));
                        totalSquares++;
                    }
                }
            }
        }

        if (totalSquares != 16)
        {
            Console.WriteLine("No");
            return;
        }

        List<int>[] placements = new List<int>[3];
        for (int i = 0; i < 3; i++)
        {
            placements[i] = GeneratePlacements(shapes[i]);
        }

        const int fullMask = (1 << 16) - 1;

        foreach (int first in placements[0])
        {
            foreach (int second in placements[1])
            {
                if ((first & second) != 0)
                    continue;

                int combined = first | second;

                foreach (int third in placements[2])
                {
                    if ((combined & third) == 0 &&
                        (combined | third) == fullMask)
                    {
                        Console.WriteLine("Yes");
                        return;
                    }
                }
            }
        }

        Console.WriteLine("No");
    }
}
