using System;
using System.IO;

public class Program
{
    private const long INF = long.MaxValue / 4;

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        int k = scanner.NextInt();
        int p = scanner.NextInt();

        long[] costs = new long[n];
        int[][] improvements = new int[n][];

        for (int i = 0; i < n; i++)
        {
            costs[i] = scanner.NextLong();
            improvements[i] = new int[k];
            for (int j = 0; j < k; j++)
                improvements[i][j] = scanner.NextInt();
        }

        int baseValue = p + 1;
        int stateCount = 1;
        for (int i = 0; i < k; i++)
            stateCount *= baseValue;

        long[] dp = new long[stateCount];
        for (int i = 1; i < stateCount; i++)
            dp[i] = INF;

        for (int i = 0; i < n; i++)
        {
            long[] next = (long[])dp.Clone();

            for (int state = 0; state < stateCount; state++)
            {
                if (dp[state] == INF)
                    continue;

                int remaining = state;
                int nextState = 0;
                int multiplier = 1;

                for (int j = 0; j < k; j++)
                {
                    int value = remaining % baseValue;
                    remaining /= baseValue;

                    int newValue = value + improvements[i][j];
                    if (newValue > p)
                        newValue = p;

                    nextState += newValue * multiplier;
                    multiplier *= baseValue;
                }

                long newCost = dp[state] + costs[i];
                if (newCost < next[nextState])
                    next[nextState] = newCost;
            }

            dp = next;
        }

        long answer = dp[stateCount - 1];
        Console.WriteLine(answer == INF ? -1 : answer);
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value * sign;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }
}
