            while (c > 32 && c != -1)
            {
                sb.Append((char)c);
                c = ReadByte();
            }
            return sb.ToString();
        }

        public int NextInt()
        {
            return int.Parse(Next());
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int m = scanner.NextInt();

        int[] scores = new int[m];
        for (int j = 0; j < m; j++)
            scores[j] = scanner.NextInt();

        string[] solved = new string[n];
        int[] totals = new int[n];

        for (int i = 0; i < n; i++)
        {
            solved[i] = scanner.Next();
            totals[i] = i + 1;

            for (int j = 0; j < m; j++)
            {
                if (solved[i][j] == 'o')
                    totals[i] += scores[j];
            }
        }

        var output = new StringBuilder();

        for (int i = 0; i < n; i++)
        {
            int maxOther = int.MinValue;
            for (int k = 0; k < n; k++)
            {
                if (k != i && totals[k] > maxOther)
                    maxOther = totals[k];
            }

            if (totals[i] > maxOther)
            {
                output.AppendLine("0");
                continue;
            }

            var unsolvedScores = new List<int>();
            for (int j = 0; j < m; j++)
            {
                if (solved[i][j] == 'x')
                    unsolvedScores.Add(scores[j]);
            }

            unsolvedScores.Sort((a, b) => b.CompareTo(a));

            int current = totals[i];
            int count = 0;

            foreach (int score in unsolvedScores)
            {
                current += score;
                count++;

                if (current > maxOther)
                    break;
            }

            output.AppendLine(count.ToString());
        }

        Console.Write(output.ToString());
    }
