public class Program
{
    private const long Mod = 998244353;

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        int x = scanner.NextInt();

        int[] lengths = new int[n];
        for (int i = 0; i < n; i++)
            lengths[i] = scanner.NextInt();

        long invN = ModPow(n, Mod - 2);
        long[] dp = new long[x + 1];
        dp[0] = 1;

        for (int time = 1; time <= x; time++)
        {
            long sum = 0;
            for (int i = 0; i < n; i++)
            {
                int previous = time - lengths[i];
                if (previous >= 0)
                    sum += dp[previous];
            }

            dp[time] = (sum % Mod) * invN % Mod;
        }

        int firstStart = Math.Max(0, x - lengths[0] + 1);
        long answer = 0;

        for (int time = firstStart; time <= x; time++)
            answer += dp[time];

        answer = (answer % Mod) * invN % Mod;
        Console.WriteLine(answer);
    }

    private static long ModPow(long value, long exponent)
    {
        long result = 1;
        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * value % Mod;

            value = value * value % Mod;
            exponent >>= 1;
        }
        return result;
    }

