        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public string Next()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            var sb = new StringBuilder();
            while (c > 32 && c != -1)
            {
                sb.Append((char)c);
                c = ReadByte();
            }
            return sb.ToString();
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    private static bool CanBeOriginal(string candidate, string received)
    {
        int n = candidate.Length;
        int m = received.Length;

        if (Math.Abs(n - m) > 1)
            return false;

        int i = 0;
        int j = 0;
        int edits = 0;

        while (i < n && j < m)
        {
            if (candidate[i] == received[j])
            {
                i++;
                j++;
                continue;
            }

            edits++;
            if (edits > 1)
                return false;

            if (n == m)
            {
                i++;
                j++;
            }
            else if (n > m)
            {
                i++;
            }
            else
            {
                j++;
            }
        }

        if (i < n || j < m)
            edits++;

        return edits <= 1;
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        string received = scanner.Next();

        var answer = new List<int>();

        for (int i = 1; i <= n; i++)
        {
            string candidate = scanner.Next();
            if (CanBeOriginal(candidate, received))
                answer.Add(i);
        }

        var output = new StringBuilder();
        output.AppendLine(answer.Count.ToString());

        for (int i = 0; i < answer.Count; i++)
        {
            if (i > 0)
                output.Append(' ');
            output.Append(answer[i]);
        }

        if (answer.Count > 0)
            output.AppendLine();

        Console.Write(output.ToString());
    }
