public class Program
{
    public static void Main()
    {
        using (var reader = new StreamReader(
            Console.OpenStandardInput(), Encoding.UTF8, false, 1 << 16))
        {
            string[] first = reader.ReadLine().Split();
            int n = int.Parse(first[0]);
            string t = first[1];
            int m = t.Length;

            long[] prefixFrequency = new long[m + 1];
            long[] suffixFrequency = new long[m + 1];

            for (int index = 0; index < n; index++)
            {
                string s = reader.ReadLine();

                int prefixMatched = 0;
                for (int i = 0; i < s.Length && prefixMatched < m; i++)
                {
                    if (s[i] == t[prefixMatched])
                        prefixMatched++;
                }

                int suffixPosition = m - 1;
                for (int i = s.Length - 1; i >= 0 && suffixPosition >= 0; i--)
                {
                    if (s[i] == t[suffixPosition])
                        suffixPosition--;
                }

                int suffixMatched = m - 1 - suffixPosition;
                prefixFrequency[prefixMatched]++;
                suffixFrequency[suffixMatched]++;
            }

            long[] suffixAtLeast = new long[m + 1];
            long running = 0;
            for (int matched = m; matched >= 0; matched--)
            {
                running += suffixFrequency[matched];
                suffixAtLeast[matched] = running;
            }

            long answer = 0;
            for (int prefixMatched = 0; prefixMatched <= m; prefixMatched++)
            {
                answer += prefixFrequency[prefixMatched] *
                          suffixAtLeast[m - prefixMatched];
            }

            Console.WriteLine(answer);
        }
    }
}
