public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c >= 0);

            int value = 0;
            while (c > 32)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int m = scanner.NextInt();

        int[] head = new int[n + 1];
        for (int i = 0; i <= n; i++) head[i] = -1;

        int[] to = new int[m];
        int[] next = new int[m];
        int[] beauty = new int[m];
        int[] cost = new int[m];

        double upper = 0.0;

        for (int i = 0; i < m; i++)
        {
            int u = scanner.NextInt();
            int v = scanner.NextInt();
            int b = scanner.NextInt();
            int c = scanner.NextInt();

            to[i] = v;
            beauty[i] = b;
            cost[i] = c;
            next[i] = head[u];
            head[u] = i;

            double ratio = (double)b / c;
            if (ratio > upper) upper = ratio;
        }

        double[] dp = new double[n + 1];
        double lower = 0.0;

        for (int iteration = 0; iteration < 100; iteration++)
        {
            double mid = (lower + upper) * 0.5;

            for (int i = 1; i <= n; i++)
                dp[i] = double.NegativeInfinity;
            dp[1] = 0.0;

            for (int u = 1; u <= n; u++)
            {
                if (double.IsNegativeInfinity(dp[u])) continue;

                for (int edge = head[u]; edge != -1; edge = next[edge])
                {
                    int v = to[edge];
                    double candidate = dp[u] + beauty[edge] - mid * cost[edge];
                    if (candidate > dp[v])
                        dp[v] = candidate;
                }
            }

            if (dp[n] >= 0.0)
                lower = mid;
            else
                upper = mid;
        }

        Console.WriteLine(lower.ToString("F16", CultureInfo.InvariantCulture));
    }
}
