                for (int j = 0; j < w; j++)
                {
                    if (grid[i][j] != '#')
                        continue;

                    components++;
                    grid[i][j] = '.';
                    queue.Enqueue(i * w + j);

                    while (queue.Count > 0)
                    {
                        int cell = queue.Dequeue();
                        int row = cell / w;
                        int col = cell % w;

                        int minRow = Math.Max(0, row - 1);
                        int maxRow = Math.Min(h - 1, row + 1);
                        int minCol = Math.Max(0, col - 1);
                        int maxCol = Math.Min(w - 1, col + 1);

                        for (int nr = minRow; nr <= maxRow; nr++)
                        {
                            for (int nc = minCol; nc <= maxCol; nc++)
                            {
                                if (grid[nr][nc] == '#')
                                {
