using System;
using System.IO;

public class Program
{
    private struct Product
    {
        public long Start;
        public long End;

        public Product(long start, long end)
        {
            Start = start;
            End = end;
        }
    }

    private sealed class MinHeap
    {
        private long[] data;
        public int Count { get; private set; }

        public MinHeap(int capacity)
        {
            data = new long[Math.Max(1, capacity)];
        }

        public void Push(long value)
        {
            int index = Count++;
            data[index] = value;

            while (index > 0)
            {
                int parent = (index - 1) / 2;
                if (data[parent] <= value) break;

                data[index] = data[parent];
                index = parent;
            }

            data[index] = value;
        }

        public long Peek()
        {
            return data[0];
        }

        public long Pop()
        {
            long result = data[0];
            long last = data[--Count];

            if (Count > 0)
            {
                int index = 0;

                while (true)
                {
                    int left = index * 2 + 1;
                    if (left >= Count) break;

                    int right = left + 1;
                    int child = left;

                    if (right < Count && data[right] < data[left])
                        child = right;

                    if (data[child] >= last) break;

                    data[index] = data[child];
                    index = child;
                }

                data[index] = last;
            }

            return result;
        }
    }

    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }

            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = (int)scanner.NextLong();
        var products = new Product[n];

        for (int i = 0; i < n; i++)
        {
            long t = scanner.NextLong();
            long d = scanner.NextLong();
            products[i] = new Product(t, t + d);
        }

        Array.Sort(products, delegate(Product a, Product b)
        {
            int comparison = a.Start.CompareTo(b.Start);
            if (comparison != 0) return comparison;
            return a.End.CompareTo(b.End);
        });

        var heap = new MinHeap(n);
        int next = 0;
        int answer = 0;
        long time = 0;

        while (next < n || heap.Count > 0)
        {
            if (heap.Count == 0 && time < products[next].Start)
                time = products[next].Start;

            while (next < n && products[next].Start <= time)
            {
                heap.Push(products[next].End);
                next++;
            }

            while (heap.Count > 0 && heap.Peek() < time)
                heap.Pop();

            if (heap.Count > 0)
            {
                heap.Pop();
                answer++;
                time++;
            }
        }

        Console.WriteLine(answer);
    }
}
