            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }
    }

    private static long[] Dijkstra(int start, int[][] distances, long multiplier, long additionalCost)
    {
        int n = distances.Length;
        const long INF = long.MaxValue / 4;
        long[] shortest = new long[n];
        bool[] used = new bool[n];

        for (int i = 0; i < n; i++)
            shortest[i] = INF;

        shortest[start] = 0;

        for (int iteration = 0; iteration < n; iteration++)
        {
            int city = -1;
            long best = INF;

            for (int i = 0; i < n; i++)
            {
                if (!used[i] && shortest[i] < best)
                {
                    best = shortest[i];
                    city = i;
                }
            }

            if (city == -1) break;
            used[city] = true;

            int[] row = distances[city];
            for (int next = 0; next < n; next++)
            {
                if (used[next]) continue;

                long candidate = best + (long)row[next] * multiplier + additionalCost;
                if (candidate < shortest[next])
                    shortest[next] = candidate;
            }
        }

        return shortest;
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();

        int n = (int)scanner.NextLong();
        long a = scanner.NextLong();
        long b = scanner.NextLong();
        long c = scanner.NextLong();

        int[][] distances = new int[n][];
        for (int i = 0; i < n; i++)
        {
            distances[i] = new int[n];
            for (int j = 0; j < n; j++)
                distances[i][j] = (int)scanner.NextLong();
        }

        long[] carTime = Dijkstra(0, distances, a, 0);
        long[] trainTimeToDestination = Dijkstra(n - 1, distances, b, c);

        long answer = long.MaxValue;
        for (int city = 0; city < n; city++)
        {
            long total = carTime[city] + trainTimeToDestination[city];
            if (total < answer)
                answer = total;
        }

        Console.WriteLine(answer);
    }
}
