using System;
using System.IO;
using System.Collections.Generic;

public class Program
{
    private const int INF = 1 << 28;

    private struct Option
    {
        public int X;
        public int Y;

        public Option(int x, int y)
        {
            X = x;
            Y = y;
        }
    }

    public static void Main()
    {
        FastScanner fs = new FastScanner(Console.OpenStandardInput());

        int n = fs.NextInt();
        long[] d = new long[n];
        long totalLength = 0;

        for (int i = 0; i < n; i++)
        {
            d[i] = fs.NextLong();
            totalLength += d[i];
        }

        long l1 = fs.NextLong();
        long c1 = fs.NextLong();
        int k1 = fs.NextInt();

        long l2 = fs.NextLong();
        long c2 = fs.NextLong();
        int k2 = fs.NextInt();

        if (totalLength > l1 * k1 + l2 * k2)
        {
            Console.WriteLine("-1");
            return;
        }

        int[] dp = new int[k1 + 1];
        for (int i = 0; i <= k1; i++) dp[i] = INF;
        dp[0] = 0;

        for (int section = 0; section < n; section++)
        {
            List<Option> options = new List<Option>();
            int maxX = (int)Math.Min((long)k1, (d[section] + l1 - 1) / l1);
            int lastY = INF;

            for (int x = 0; x <= maxX; x++)
            {
                long remaining = d[section] - l1 * x;
                int y = remaining <= 0 ? 0 : (int)((remaining + l2 - 1) / l2);

                if (y <= k2 && y < lastY)
                {
                    options.Add(new Option(x, y));
                    lastY = y;
                }

                if (y == 0) break;
            }

            if (options.Count == 0)
            {
                Console.WriteLine("-1");
                return;
            }

            int[] next = new int[k1 + 1];
            for (int i = 0; i <= k1; i++) next[i] = INF;

            for (int usedX = 0; usedX <= k1; usedX++)
            {
                if (dp[usedX] == INF) continue;

                for (int j = 0; j < options.Count; j++)
                {
                    int newX = usedX + options[j].X;
                    if (newX > k1) break;

                    int newY = dp[usedX] + options[j].Y;
                    if (newY <= k2 && newY < next[newX])
                    {
                        next[newX] = newY;
                    }
                }
            }

            // Remove states dominated by a state using no more sensors of either type.
            int bestY = INF;
            bool hasState = false;

            for (int x = 0; x <= k1; x++)
            {
                if (next[x] < bestY)
                {
                    bestY = next[x];
                    hasState = true;
                }
                else
                {
                    next[x] = INF;
                }
            }

            if (!hasState)
            {
                Console.WriteLine("-1");
                return;
            }

            dp = next;
        }

        long answer = long.MaxValue;

        for (int x = 0; x <= k1; x++)
        {
            if (dp[x] == INF) continue;
            long cost = c1 * x + c2 * dp[x];
            if (cost < answer) answer = cost;
        }

        Console.WriteLine(answer == long.MaxValue ? "-1" : answer.ToString());
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
