using System;
using System.Collections.Generic;

public class Program
{
    static int n;
    static string r, c;
    static List<char[]>[] candidates;
    static char[][] grid;
    static int[] columnMasks;
    static HashSet<long> failedStates;

    static long GetStateKey(int row)
    {
        long key = row;
        for (int j = 0; j < n; j++)
            key = key * 8 + columnMasks[j];
        return key;
    }

    static bool Search(int row)
    {
        if (row == n)
        {
            for (int j = 0; j < n; j++)
            {
                if (columnMasks[j] != 7)
                    return false;
            }
            return true;
        }

        long stateKey = GetStateKey(row);
        if (failedStates.Contains(stateKey))
            return false;

        foreach (char[] pattern in candidates[row])
        {
            bool valid = true;

            for (int col = 0; col < n; col++)
            {
                char ch = pattern[col];
                if (ch == '.')
                    continue;

                int bit = 1 << (ch - 'A');

                if ((columnMasks[col] & bit) != 0)
                {
                    valid = false;
                    break;
                }

                if (columnMasks[col] == 0 && c[col] != ch)
                {
                    valid = false;
                    break;
                }
            }

            if (!valid)
                continue;

            for (int col = 0; col < n; col++)
            {
                char ch = pattern[col];
                if (ch != '.')
                    columnMasks[col] |= 1 << (ch - 'A');
            }

            grid[row] = pattern;

            if (Search(row + 1))
                return true;

            for (int col = 0; col < n; col++)
            {
                char ch = pattern[col];
                if (ch != '.')
                    columnMasks[col] ^= 1 << (ch - 'A');
            }
        }

        failedStates.Add(stateKey);
        return false;
    }

    static List<char[]> GenerateCandidates(char requiredLeftmost)
    {
        var result = new List<char[]>();

        for (int posA = 0; posA < n; posA++)
        {
            for (int posB = 0; posB < n; posB++)
            {
                if (posB == posA)
                    continue;

                for (int posC = 0; posC < n; posC++)
                {
                    if (posC == posA || posC == posB)
                        continue;

                    char[] row = new char[n];
                    for (int i = 0; i < n; i++)
                        row[i] = '.';

                    row[posA] = 'A';
                    row[posB] = 'B';
                    row[posC] = 'C';

                    int leftmost = Math.Min(posA, Math.Min(posB, posC));
                    if (row[leftmost] == requiredLeftmost)
                        result.Add(row);
                }
            }
        }

        return result;
    }

    public static void Main()
    {
        n = int.Parse(Console.ReadLine());
        r = Console.ReadLine();
        c = Console.ReadLine();

        candidates = new List<char[]>[n];
        for (int i = 0; i < n; i++)
            candidates[i] = GenerateCandidates(r[i]);

        grid = new char[n][];
        columnMasks = new int[n];
        failedStates = new HashSet<long>();

        if (!Search(0))
        {
            Console.WriteLine("No");
            return;
        }

        Console.WriteLine("Yes");
        for (int i = 0; i < n; i++)
            Console.WriteLine(new string(grid[i]));
    }
}
