using System;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    private sealed class ParityUnionFind
    {
        private readonly int[] parent;
        private readonly int[] size;
        private readonly int[] parity;

        public ParityUnionFind(int n)
        {
            parent = new int[n];
            size = new int[n];
            parity = new int[n];

            for (int i = 0; i < n; i++)
            {
                parent[i] = i;
                size[i] = 1;
            }
        }

        private int Find(int x)
        {
            if (parent[x] == x) return x;

            int p = parent[x];
            parent[x] = Find(p);
            parity[x] ^= parity[p];
            return parent[x];
        }

        public bool AddDifferentConstraint(int a, int b)
        {
            int rootA = Find(a);
            int xorA = parity[a];
            int rootB = Find(b);
            int xorB = parity[b];

            if (rootA == rootB)
                return (xorA ^ xorB) == 1;

            int rootParity = xorA ^ xorB ^ 1;

            if (size[rootA] < size[rootB])
            {
                parent[rootA] = rootB;
                parity[rootA] = rootParity;
                size[rootB] += size[rootA];
            }
            else
            {
                parent[rootB] = rootA;
                parity[rootB] = rootParity;
                size[rootA] += size[rootB];
            }

            return true;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int m = scanner.NextInt();

        int[] a = new int[m];
        for (int i = 0; i < m; i++)
            a[i] = scanner.NextInt() - 1;

        var unionFind = new ParityUnionFind(n);
        bool possible = true;

        for (int i = 0; i < m; i++)
        {
            int b = scanner.NextInt() - 1;
            if (possible && !unionFind.AddDifferentConstraint(a[i], b))
                possible = false;
        }

        Console.WriteLine(possible ? "Yes" : "No");
    }
}
