            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        double[] dp = new double[n + 1];
        for (int i = 1; i <= n; i++)
            dp[i] = double.NegativeInfinity;

        for (int i = 1; i <= n; i++)
        {
            int performance = scanner.NextInt();

            for (int k = i; k >= 1; k--)
            {
                double candidate = 0.9 * dp[k - 1] + performance;
                if (candidate > dp[k])
                    dp[k] = candidate;
            }
        }

        double answer = double.NegativeInfinity;
        double denominator = 0.0;

        for (int k = 1; k <= n; k++)
        {
            denominator = 0.9 * denominator + 1.0;
            double rating = dp[k] / denominator - 1200.0 / Math.Sqrt(k);
            if (rating > answer)
                answer = rating;
        }

        Console.WriteLine(answer.ToString("F15", CultureInfo.InvariantCulture));
    }
