using System;
using System.IO;

public class Program
{
    static int n, m;
    static long k, answer;
    static Edge[] edges;
    static int[] parent;
    static int[] size;

    struct Edge
    {
        public int U;
        public int V;
        public long W;
    }

    static int Find(int x)
    {
        while (parent[x] != x)
            x = parent[x];
        return x;
    }

    static void Search(int start, int selected, long sum)
    {
        if (selected == n - 1)
        {
            if (sum < answer)
                answer = sum;
            return;
        }

        int needed = (n - 1) - selected;

        for (int i = start; i <= m - needed; i++)
        {
            int rootU = Find(edges[i].U);
            int rootV = Find(edges[i].V);

            if (rootU == rootV)
                continue;

            if (size[rootU] < size[rootV])
            {
                int temp = rootU;
                rootU = rootV;
                rootV = temp;
            }

            parent[rootV] = rootU;
            int oldSize = size[rootU];
            size[rootU] += size[rootV];

            long nextSum = (sum + edges[i].W) % k;
            Search(i + 1, selected + 1, nextSum);

            parent[rootV] = rootV;
            size[rootU] = oldSize;
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        n = scanner.NextInt();
        m = scanner.NextInt();
        k = scanner.NextLong();

        edges = new Edge[m];
        for (int i = 0; i < m; i++)
        {
            edges[i] = new Edge
            {
                U = scanner.NextInt() - 1,
                V = scanner.NextInt() - 1,
                W = scanner.NextLong()
            };
        }

        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++)
        {
            parent[i] = i;
            size[i] = 1;
        }

        answer = k;
        Search(0, 0, 0);

        Console.WriteLine(answer);
    }

    sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }
}
