using System;
using System.Collections.Generic;

public class Program
{
    public static void Main()
    {
        string[] first = Console.ReadLine().Split();
        int n = int.Parse(first[0]);
        int m = int.Parse(first[1]);

        string s = Console.ReadLine();
        string t = Console.ReadLine();

        int windowCount = n - m + 1;
        int[] mismatchCount = new int[windowCount];
        bool[] queued = new bool[windowCount];
        bool[] erased = new bool[n];
        Queue<int> queue = new Queue<int>();

        for (int start = 0; start < windowCount; start++)
        {
            int mismatches = 0;
            for (int offset = 0; offset < m; offset++)
            {
                if (s[start + offset] != t[offset])
                    mismatches++;
            }

            mismatchCount[start] = mismatches;
            if (mismatches == 0)
            {
                queued[start] = true;
                queue.Enqueue(start);
            }
        }

        int erasedCount = 0;

        while (queue.Count > 0)
        {
            int start = queue.Dequeue();

            for (int offset = 0; offset < m; offset++)
            {
                int position = start + offset;
                if (erased[position])
                    continue;

                erased[position] = true;
                erasedCount++;

                int left = Math.Max(0, position - m + 1);
                int right = Math.Min(position, n - m);

                for (int affectedStart = left; affectedStart <= right; affectedStart++)
                {
                    int tIndex = position - affectedStart;

                    if (s[position] != t[tIndex])
                    {
                        mismatchCount[affectedStart]--;

                        if (mismatchCount[affectedStart] == 0 && !queued[affectedStart])
                        {
                            queued[affectedStart] = true;
                            queue.Enqueue(affectedStart);
                        }
                    }
                }
            }
        }

        Console.WriteLine(erasedCount == n ? "Yes" : "No");
    }
}
