        long y = (long)Math.Sqrt(d);

        while ((y + 1) * (y + 1) <= d) y++;
        while (y * y > d) y--;

        for (long x = 0; x * x <= d; x++)
        {
            while (y > 0 && x * x + y * y > d)
                y--;

            long sum1 = x * x + y * y;
            answer = Math.Min(answer, Math.Abs(sum1 - d));

            long sum2 = x * x + (y + 1) * (y + 1);
            answer = Math.Min(answer, Math.Abs(sum2 - d));

            if (answer == 0)
                break;
        }

