using System;
using System.IO;
using System.Text;

public class Program
{
    private static int n;
    private static int[,] prefix;

    private static long CountFromOrigin(long rows, long columns)
    {
        long fullRowBlocks = rows / n;
        long fullColumnBlocks = columns / n;
        int remainingRows = (int)(rows % n);
        int remainingColumns = (int)(columns % n);

        return fullRowBlocks * fullColumnBlocks * prefix[n, n]
             + fullRowBlocks * prefix[n, remainingColumns]
             + fullColumnBlocks * prefix[remainingRows, n]
             + prefix[remainingRows, remainingColumns];
    }

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        n = scanner.NextInt();
        int q = scanner.NextInt();

        prefix = new int[n + 1, n + 1];

        for (int i = 0; i < n; i++)
        {
            string row = scanner.Next();
            for (int j = 0; j < n; j++)
            {
                int black = row[j] == 'B' ? 1 : 0;
                prefix[i + 1, j + 1] =
                    prefix[i, j + 1] +
                    prefix[i + 1, j] -
                    prefix[i, j] +
                    black;
            }
        }

        var output = new StringBuilder();

        for (int i = 0; i < q; i++)
        {
            long a = scanner.NextLong();
            long b = scanner.NextLong();
            long c = scanner.NextLong();
            long d = scanner.NextLong();

            long answer =
                CountFromOrigin(c + 1, d + 1)
                - CountFromOrigin(a, d + 1)
                - CountFromOrigin(c + 1, b)
                + CountFromOrigin(a, b);

            output.AppendLine(answer.ToString());
        }

        Console.Write(output.ToString());
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public string Next()
        {
            var result = new StringBuilder();
            int c;

            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            while (c > 32 && c != -1)
            {
                result.Append((char)c);
                c = ReadByte();
            }

            return result.ToString();
        }

        public int NextInt()
        {
            return (int)NextLong();
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            bool negative = false;
            if (c == '-')
            {
                negative = true;
                c = ReadByte();
            }

            long value = 0;
            while (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return negative ? -value : value;
        }
    }
}
