    private struct SideDish
    {
        public long Price;
        public int Index;

        public SideDish(long price, int index)
        {
            Price = price;
            Index = index;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int m = scanner.NextInt();
        int l = scanner.NextInt();

        long[] mainPrices = new long[n];
        for (int i = 0; i < n; i++)
            mainPrices[i] = scanner.NextLong();

        SideDish[] sideDishes = new SideDish[m];
        for (int i = 0; i < m; i++)
            sideDishes[i] = new SideDish(scanner.NextLong(), i);

        HashSet<int>[] forbidden = new HashSet<int>[n];

        for (int i = 0; i < l; i++)
        {
            int mainIndex = scanner.NextInt() - 1;
            int sideIndex = scanner.NextInt() - 1;

            if (forbidden[mainIndex] == null)
                forbidden[mainIndex] = new HashSet<int>();

            forbidden[mainIndex].Add(sideIndex);
        }

        Array.Sort(sideDishes, delegate(SideDish x, SideDish y)
        {
            return y.Price.CompareTo(x.Price);
        });

        long answer = long.MinValue;

        for (int i = 0; i < n; i++)
        {
            HashSet<int> blocked = forbidden[i];

            for (int j = 0; j < m; j++)
            {
                if (blocked == null || !blocked.Contains(sideDishes[j].Index))
                {
                    long total = mainPrices[i] + sideDishes[j].Price;
                    if (total > answer)
                        answer = total;
                    break;
                }
            }
        }

        Console.WriteLine(answer);
    }
