using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private class Permutation
    {
        public int[] Values;
        public int Cost;

        public Permutation(int[] values, int cost)
        {
            Values = values;
            Cost = cost;
        }
    }

    private class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int pointer;

        private int ReadByte()
        {
            if (pointer >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0) return -1;
            }
            return buffer[pointer++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value * sign;
        }
    }

    private static List<Permutation> GeneratePermutations(int n)
    {
        var result = new List<Permutation>();
        int[] current = new int[n];
        bool[] used = new bool[n];
        Generate(0, n, current, used, result);
        return result;
    }

    private static void Generate(
        int index,
        int n,
        int[] current,
        bool[] used,
        List<Permutation> result)
    {
        if (index == n)
        {
            int[] permutation = (int[])current.Clone();
            int inversions = 0;

            for (int i = 0; i < n; i++)
            {
                for (int j = i + 1; j < n; j++)
                {
                    if (permutation[i] > permutation[j])
                        inversions++;
                }
            }

            result.Add(new Permutation(permutation, inversions));
            return;
        }

        for (int value = 0; value < n; value++)
        {
            if (used[value]) continue;

            used[value] = true;
            current[index] = value;
            Generate(index + 1, n, current, used, result);
            used[value] = false;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int h = scanner.NextInt();
        int w = scanner.NextInt();

        int[,] a = new int[h, w];
        int[,] b = new int[h, w];

        for (int i = 0; i < h; i++)
        {
            for (int j = 0; j < w; j++)
                a[i, j] = scanner.NextInt();
        }

        for (int i = 0; i < h; i++)
        {
            for (int j = 0; j < w; j++)
                b[i, j] = scanner.NextInt();
        }

        List<Permutation> rowPermutations = GeneratePermutations(h);
        List<Permutation> columnPermutations = GeneratePermutations(w);

        int answer = int.MaxValue;

        foreach (Permutation rows in rowPermutations)
        {
            foreach (Permutation columns in columnPermutations)
            {
                int cost = rows.Cost + columns.Cost;
                if (cost >= answer) continue;

                bool matches = true;

                for (int i = 0; i < h && matches; i++)
                {
                    for (int j = 0; j < w; j++)
                    {
                        if (a[rows.Values[i], columns.Values[j]] != b[i, j])
                        {
                            matches = false;
                            break;
                        }
                    }
                }

                if (matches)
                    answer = cost;
            }
        }

        Console.WriteLine(answer == int.MaxValue ? -1 : answer);
    }
}
