            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        int[] type = new int[n];
        int[] itemType = new int[n];
        bool[] take = new bool[n];
        int[] needed = new int[n + 1];

        for (int i = 0; i < n; i++)
        {
            type[i] = scanner.NextInt();
            itemType[i] = scanner.NextInt();
        }

        for (int i = n - 1; i >= 0; i--)
        {
            int x = itemType[i];

            if (type[i] == 2)
            {
                needed[x]++;
            }
            else if (needed[x] > 0)
            {
                take[i] = true;
                needed[x]--;
            }
        }

        for (int x = 1; x <= n; x++)
        {
            if (needed[x] > 0)
            {
                Console.WriteLine("-1");
                return;
            }
