        int held = 0;
        int minimumMaximum = 0;

        for (int i = 0; i < n; i++)
        {
            if (type[i] == 1)
            {
                if (take[i])
                {
                    held++;
                    if (held > minimumMaximum)
                        minimumMaximum = held;
                }
            }
            else
            {
                held--;
            }
        }

        var output = new StringBuilder();
        output.AppendLine(minimumMaximum.ToString());

        bool first = true;
        for (int i = 0; i < n; i++)
        {
            if (type[i] != 1) continue;

            if (!first) output.Append(' ');
            output.Append(take[i] ? '1' : '0');
            first = false;
        }
        output.AppendLine();

        Console.Write(output.ToString());
    }
