            for (int i = 0; i < k; i += 2)
                answer += a[i + 1] - a[i];

            Console.WriteLine(answer);
            return;
        }

        long[] left = new long[k + 1];
        for (int i = 2; i <= k; i += 2)
            left[i] = left[i - 2] + a[i - 1] - a[i - 2];

        long[] right = new long[k + 1];
        for (int i = k - 2; i >= 0; i -= 2)
            right[i] = right[i + 2] + a[i + 1] - a[i];

        long minimum = long.MaxValue;
        for (int excluded = 0; excluded < k; excluded += 2)
        {
            long cost = left[excluded] + right[excluded + 1];
            if (cost < minimum)
                minimum = cost;
        }

