using System;
using System.IO;
using System.Text;

public class Program
{
    const long Mod = 998244353;
    static int[] parent;

    static int Find(int x)
    {
        int root = x;
        while (parent[root] >= 0)
            root = parent[root];

        while (x != root)
        {
            int next = parent[x];
            parent[x] = root;
            x = next;
        }

        return root;
    }

    static bool Union(int a, int b)
    {
        a = Find(a);
        b = Find(b);

        if (a == b)
            return false;

        if (parent[a] > parent[b])
        {
            int temp = a;
            a = b;
            b = temp;
        }

        parent[a] += parent[b];
        parent[b] = a;
        return true;
    }

    static long ModPow(long value, long exponent)
    {
        long result = 1;
        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * value % Mod;

            value = value * value % Mod;
            exponent >>= 1;
        }
        return result;
    }

    static void AddDistinctRoot(
        int root,
        ref int count,
        ref int r0,
        ref int r1,
        ref int r2,
        ref int r3)
    {
        if (root == r0 || root == r1 || root == r2 || root == r3)
            return;

        if (count == 0) r0 = root;
        else if (count == 1) r1 = root;
        else if (count == 2) r2 = root;
        else r3 = root;

        count++;
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int h = scanner.NextInt();
        int w = scanner.NextInt();
        int n = h * w;

        byte[] green = new byte[n];
        parent = new int[n];

        int components = 0;
        int redCount = 0;

        for (int i = 0; i < h; i++)
        {
            string row = scanner.Next();
            for (int j = 0; j < w; j++)
            {
                int index = i * w + j;

                if (row[j] == '#')
                {
                    green[index] = 1;
                    parent[index] = -1;
                    components++;

                    if (j > 0 && green[index - 1] != 0)
                    {
                        if (Union(index, index - 1))
                            components--;
                    }

                    if (i > 0 && green[index - w] != 0)
                    {
                        if (Union(index, index - w))
                            components--;
                    }
                }
                else
                {
                    redCount++;
                }
            }
        }

        long totalComponents = 0;

        for (int i = 0; i < h; i++)
        {
            for (int j = 0; j < w; j++)
            {
                int index = i * w + j;
                if (green[index] != 0)
                    continue;

                int count = 0;
                int r0 = -1, r1 = -1, r2 = -1, r3 = -1;

                if (i > 0 && green[index - w] != 0)
                    AddDistinctRoot(Find(index - w), ref count, ref r0, ref r1, ref r2, ref r3);

                if (i + 1 < h && green[index + w] != 0)
                    AddDistinctRoot(Find(index + w), ref count, ref r0, ref r1, ref r2, ref r3);

                if (j > 0 && green[index - 1] != 0)
                    AddDistinctRoot(Find(index - 1), ref count, ref r0, ref r1, ref r2, ref r3);

                if (j + 1 < w && green[index + 1] != 0)
                    AddDistinctRoot(Find(index + 1), ref count, ref r0, ref r1, ref r2, ref r3);

                totalComponents += components + 1L - count;
            }
        }

        long answer = (totalComponents % Mod) * ModPow(redCount, Mod - 2) % Mod;
        Console.WriteLine(answer);
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public string Next()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            StringBuilder builder = new StringBuilder();
            while (c > 32 && c != -1)
            {
                builder.Append((char)c);
                c = ReadByte();
            }

            return builder.ToString();
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value;
        }
    }
