                    else if (grid[i][j] == 'x') blocks++;

                    if (j >= k)
                    {
                        char removed = grid[i][j - k];
                        if (removed == '.') dots--;
                        else if (removed == 'x') blocks--;
                    }

                    if (j >= k - 1 && blocks == 0)
                        answer = Math.Min(answer, dots);
                }
