    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        long[] q = new long[n];
        long[] a = new long[n];
        long[] b = new long[n];

        for (int i = 0; i < n; i++) q[i] = scanner.NextLong();
        for (int i = 0; i < n; i++) a[i] = scanner.NextLong();
        for (int i = 0; i < n; i++) b[i] = scanner.NextLong();

        long maxA = long.MaxValue;
        for (int i = 0; i < n; i++)
        {
            if (a[i] > 0)
                maxA = Math.Min(maxA, q[i] / a[i]);
        }

        long answer = 0;

        for (long servingsA = 0; servingsA <= maxA; servingsA++)
        {
            long maxB = long.MaxValue;

            for (int i = 0; i < n; i++)
            {
                if (b[i] > 0)
                {
                    long remaining = q[i] - a[i] * servingsA;
                    maxB = Math.Min(maxB, remaining / b[i]);
                }
            }

            answer = Math.Max(answer, servingsA + maxB);
        }

        Console.WriteLine(answer);
    }
