            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int m = scanner.NextInt();

        long[] difference = new long[n + 2];

        int previous = scanner.NextInt();
        long baseLength = 0;

        for (int i = 1; i < m; i++)
        {
            int current = scanner.NextInt();

            int left = Math.Min(previous, current);
            int right = Math.Max(previous, current);
            int directDistance = right - left;

            baseLength += directDistance;

            long change = (long)n - 2L * directDistance;

            difference[left] += change;
            difference[right] -= change;

            previous = current;
        }

        long answer = long.MaxValue;
        long accumulatedChange = 0;

        for (int bridge = 1; bridge <= n; bridge++)
        {
            accumulatedChange += difference[bridge];
            long length = baseLength + accumulatedChange;
            if (length < answer)
                answer = length;
        }

        Console.WriteLine(answer);
    }
}
