using System;

public class Program
{
    public static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        string[] grid = new string[n];
        for (int i = 0; i < n; i++)
            grid[i] = Console.ReadLine();

        int totalCells = n * n;
        int[] id = new int[totalCells];
        for (int i = 0; i < totalCells; i++)
            id[i] = -1;

        int[] cellOf = new int[totalCells];
        int[] players = new int[2];
        int emptyCount = 0;
        int playerCount = 0;

        for (int r = 0; r < n; r++)
        {
            for (int c = 0; c < n; c++)
            {
                if (grid[r][c] == '#')
                    continue;

                int cell = r * n + c;
                id[cell] = emptyCount;
                cellOf[emptyCount] = cell;

                if (grid[r][c] == 'P')
                    players[playerCount++] = emptyCount;

                emptyCount++;
            }
        }

        int[] next = new int[emptyCount * 4];
        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        for (int p = 0; p < emptyCount; p++)
        {
            int cell = cellOf[p];
            int r = cell / n;
            int c = cell % n;

            for (int d = 0; d < 4; d++)
            {
                int nr = r + dr[d];
                int nc = c + dc[d];

                if (nr >= 0 && nr < n && nc >= 0 && nc < n &&
                    id[nr * n + nc] >= 0)
                {
                    next[p * 4 + d] = id[nr * n + nc];
                }
                else
                {
                    next[p * 4 + d] = p;
                }
            }
        }

        int first = players[0];
        int second = players[1];
        if (first > second)
        {
            int temp = first;
            first = second;
            second = temp;
        }

        byte[] visited = new byte[emptyCount * emptyCount];
        int maxPairs = (int)((long)emptyCount * (emptyCount - 1) / 2);
        int[] queue = new int[maxPairs];

        const int Shift = 12;
        const int Mask = (1 << Shift) - 1;

        int head = 0;
        int tail = 0;
        queue[tail++] = (first << Shift) | second;
        visited[first * emptyCount + second] = 1;

        int moves = 0;

        while (head < tail)
        {
            int levelEnd = tail;

            while (head < levelEnd)
            {
                int state = queue[head++];
                int a = state >> Shift;
                int b = state & Mask;

                for (int d = 0; d < 4; d++)
                {
                    int na = next[a * 4 + d];
                    int nb = next[b * 4 + d];

                    if (na == nb)
                    {
                        Console.WriteLine(moves + 1);
                        return;
                    }

                    if (na > nb)
                    {
                        int temp = na;
                        na = nb;
                        nb = temp;
                    }

                    int stateIndex = na * emptyCount + nb;
                    if (visited[stateIndex] == 0)
                    {
                        visited[stateIndex] = 1;
                        queue[tail++] = (na << Shift) | nb;
                    }
                }
            }

            moves++;
        }

        Console.WriteLine(-1);
    }
}
