    private static readonly Dictionary<long, long> Memo = new Dictionary<long, long>();

    private static long Calculate(long n)
    {
        if (n <= 1)
            return 0;

        long cached;
        if (Memo.TryGetValue(n, out cached))
            return cached;

        long lower = n / 2;
        long upper = n - lower;
        long result = n + Calculate(lower) + Calculate(upper);

        Memo[n] = result;
        return result;
    }

