    private struct HeapNode
    {
        public int Vertex;
        public long Distance;

        public HeapNode(int vertex, long distance)
        {
            Vertex = vertex;
            Distance = distance;
        }
    }

    private sealed class MinHeap
    {
        private HeapNode[] heap = new HeapNode[16];
        private int count;

        public int Count
        {
            get { return count; }
        }

        public void Push(int vertex, long distance)
        {
            if (count == heap.Length)
                Array.Resize(ref heap, heap.Length * 2);

            int index = count++;
            while (index > 0)
            {
                int parent = (index - 1) / 2;
                if (heap[parent].Distance <= distance) break;

                heap[index] = heap[parent];
                index = parent;
            }
            heap[index] = new HeapNode(vertex, distance);
        }

        public HeapNode Pop()
        {
            HeapNode result = heap[0];
            HeapNode last = heap[--count];

            if (count > 0)
            {
                int index = 0;
                while (true)
                {
                    int left = index * 2 + 1;
                    if (left >= count) break;

                    int right = left + 1;
                    int child = left;

                    if (right < count && heap[right].Distance < heap[left].Distance)
                        child = right;

                    if (heap[child].Distance >= last.Distance) break;

                    heap[index] = heap[child];
                    index = child;
                }
                heap[index] = last;
            }

            return result;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        long[] a = new long[n];
        long[] b = new long[n];
        int[] x = new int[n];

        for (int i = 0; i < n - 1; i++)
        {
            a[i] = scanner.NextLong();
            b[i] = scanner.NextLong();
            x[i] = scanner.NextInt() - 1;
        }

        long[] distance = new long[n];
        for (int i = 0; i < n; i++)
            distance[i] = long.MaxValue;

        var heap = new MinHeap();
        distance[0] = 0;
        heap.Push(0, 0);

        while (heap.Count > 0)
        {
            HeapNode current = heap.Pop();
            int vertex = current.Vertex;
            long currentDistance = current.Distance;

            if (currentDistance != distance[vertex])
                continue;

            if (vertex == n - 1)
            {
                Console.WriteLine(currentDistance);
                return;
            }

            long nextDistance = currentDistance + a[vertex];
            if (nextDistance < distance[vertex + 1])
            {
                distance[vertex + 1] = nextDistance;
                heap.Push(vertex + 1, nextDistance);
            }

            int destination = x[vertex];
            nextDistance = currentDistance + b[vertex];
            if (nextDistance < distance[destination])
            {
                distance[destination] = nextDistance;
                heap.Push(destination, nextDistance);
            }
        }
    }
