using System;
using System.IO;
using System.Text;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    private sealed class FenwickTree
    {
        private readonly int size;
        private readonly long[] tree;

        public FenwickTree(int size)
        {
            this.size = size;
            tree = new long[size + 1];
        }

        private void Add(int index, long value)
        {
            for (int i = index + 1; i <= size; i += i & -i)
                tree[i] += value;
        }

        public void RangeAdd(int left, int right, long value)
        {
            if (left > right) return;

            Add(left, value);
            if (right + 1 < size)
                Add(right + 1, -value);
        }

        public long PointQuery(int index)
        {
            long sum = 0;
            for (int i = index + 1; i > 0; i -= i & -i)
                sum += tree[i];
            return sum;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int m = scanner.NextInt();

        var fenwick = new FenwickTree(n);

        long previous = 0;
        for (int i = 0; i < n; i++)
        {
            long current = scanner.NextLong();
            fenwick.RangeAdd(i, n - 1, current - previous);
            previous = current;
        }

        for (int operation = 0; operation < m; operation++)
        {
            int box = scanner.NextInt();
            long balls = fenwick.PointQuery(box);

            fenwick.RangeAdd(box, box, -balls);

            long quotient = balls / n;
            int remainder = (int)(balls % n);

            if (quotient != 0)
                fenwick.RangeAdd(0, n - 1, quotient);

            if (remainder > 0)
            {
                int start = box + 1;

                if (start == n)
                {
                    fenwick.RangeAdd(0, remainder - 1, 1);
                }
                else
                {
                    int untilEnd = n - start;
                    if (remainder <= untilEnd)
                    {
                        fenwick.RangeAdd(start, start + remainder - 1, 1);
                    }
                    else
                    {
                        fenwick.RangeAdd(start, n - 1, 1);
                        fenwick.RangeAdd(0, remainder - untilEnd - 1, 1);
                    }
                }
            }
        }

        var output = new StringBuilder();
