using System;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public string Next()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c >= 0);

            var chars = new System.Text.StringBuilder();
            while (c > 32)
            {
                chars.Append((char)c);
                c = ReadByte();
            }
            return chars.ToString();
        }

        public int NextInt()
        {
            return int.Parse(Next());
        }
    }

    private static int PopCount(ulong value)
    {
        int count = 0;
        while (value != 0)
        {
            value &= value - 1;
            count++;
        }
        return count;
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int h = scanner.NextInt();
        int w = scanner.NextInt();
        int n = scanner.NextInt();
        string moves = scanner.Next();

        int wordCount = (w + 63) / 64;
        int size = h * wordCount;

        ulong[] land = new ulong[size];

        for (int r = 0; r < h; r++)
        {
            string row = scanner.Next();
            int offset = r * wordCount;

            for (int c = 0; c < w; c++)
            {
                if (row[c] == '.')
                    land[offset + c / 64] |= 1UL << (c % 64);
            }
        }

        ulong[] current = (ulong[])land.Clone();
        ulong[] next = new ulong[size];

        for (int step = 0; step < n; step++)
        {
            char move = moves[step];

            if (move == 'R')
            {
                for (int r = 0; r < h; r++)
                {
                    int offset = r * wordCount;
                    for (int k = 0; k < wordCount; k++)
                    {
                        ulong shifted = current[offset + k] << 1;
                        if (k > 0)
                            shifted |= current[offset + k - 1] >> 63;

                        next[offset + k] = shifted & land[offset + k];
                    }
                }
            }
            else if (move == 'L')
            {
                for (int r = 0; r < h; r++)
                {
                    int offset = r * wordCount;
                    for (int k = 0; k < wordCount; k++)
                    {
                        ulong shifted = current[offset + k] >> 1;
                        if (k + 1 < wordCount)
                            shifted |= current[offset + k + 1] << 63;

                        next[offset + k] = shifted & land[offset + k];
                    }
                }
            }
            else if (move == 'D')
            {
                for (int r = 0; r < h; r++)
                {
                    int destinationOffset = r * wordCount;
                    int sourceOffset = (r - 1) * wordCount;

                    for (int k = 0; k < wordCount; k++)
                    {
                        ulong source = r > 0 ? current[sourceOffset + k] : 0UL;
                        next[destinationOffset + k] =
                            source & land[destinationOffset + k];
                    }
                }
            }
            else // U
            {
                for (int r = 0; r < h; r++)
                {
                    int destinationOffset = r * wordCount;
                    int sourceOffset = (r + 1) * wordCount;

                    for (int k = 0; k < wordCount; k++)
                    {
                        ulong source = r + 1 < h ? current[sourceOffset + k] : 0UL;
                        next[destinationOffset + k] =
                            source & land[destinationOffset + k];
                    }
                }
            }

            ulong[] temp = current;
            current = next;
            next = temp;
        }

        long answer = 0;
        for (int i = 0; i < size; i++)
            answer += PopCount(current[i]);

        Console.WriteLine(answer);
    }
}
