                c = ReadByte();
            }
            return value;
        }

        public string Next()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            var sb = new StringBuilder();
            while (c > 32 && c != -1)
            {
                sb.Append((char)c);
                c = ReadByte();
            }
            return sb.ToString();
        }
    }

    private sealed class FenwickTree
    {
        private readonly int[] tree;

        public FenwickTree(int size)
        {
            tree = new int[size + 1];
        }

        public void Add(int index, int value)
        {
            for (int i = index; i < tree.Length; i += i & -i)
                tree[i] += value;
        }

        public int Sum(int index)
        {
            int result = 0;
            for (int i = index; i > 0; i -= i & -i)
                result += tree[i];
            return result;
        }

        public int RangeSum(int left, int right)
        {
            if (left > right) return 0;
            return Sum(right) - Sum(left - 1);
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int q = scanner.NextInt();
        string s = scanner.Next();

        // bad[i] is true when the i-th and (i+1)-th characters are equal.
        var bad = new bool[n];
        var fenwick = new FenwickTree(n);

        for (int i = 1; i < n; i++)
        {
            if (s[i - 1] == s[i])
            {
                bad[i] = true;
                fenwick.Add(i, 1);
            }
        }

        var output = new StringBuilder();

        for (int query = 0; query < q; query++)
        {
            int type = scanner.NextInt();
            int left = scanner.NextInt();
            int right = scanner.NextInt();

            if (type == 1)
            {
                if (left > 1)
                    ToggleBoundary(left - 1, bad, fenwick);

                if (right < n)
                    ToggleBoundary(right, bad, fenwick);
            }
            else
            {
                int badCount = fenwick.RangeSum(left, right - 1);
                output.AppendLine(badCount == 0 ? "Yes" : "No");
            }
        }

        Console.Write(output.ToString());
    }

    private static void ToggleBoundary(int index, bool[] bad, FenwickTree fenwick)
    {
        bad[index] = !bad[index];
        fenwick.Add(index, bad[index] ? 1 : -1);
    }
}
