using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value * sign;
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return sign == 1 ? value : -value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int m = scanner.NextInt();

        var graph = new List<int>[n];
        for (int i = 0; i < n; i++)
            graph[i] = new List<int>();

        for (int i = 0; i < m; i++)
        {
            int u = scanner.NextInt() - 1;
            int v = scanner.NextInt() - 1;
            graph[u].Add(v);
            graph[v].Add(u);
        }

        int[] weight = new int[n];
        for (int i = 0; i < n; i++)
            weight[i] = scanner.NextInt();

        long[] pieces = new long[n];
        for (int i = 0; i < n; i++)
            pieces[i] = scanner.NextLong();

        int[] order = new int[n];
        for (int i = 0; i < n; i++)
            order[i] = i;

        Array.Sort(order, delegate(int x, int y)
        {
            return weight[x].CompareTo(weight[y]);
        });

        long[] value = new long[n];

        foreach (int vertex in order)
        {
            int capacity = weight[vertex] - 1;
            long[] dp = new long[capacity + 1];

            foreach (int neighbor in graph[vertex])
            {
                int cost = weight[neighbor];
                if (cost >= weight[vertex])
                    continue;

                long gain = value[neighbor];
                for (int c = capacity; c >= cost; c--)
                {
                    long candidate = dp[c - cost] + gain;
                    if (candidate > dp[c])
                        dp[c] = candidate;
                }
            }

            value[vertex] = 1 + dp[capacity];
        }

        long answer = 0;
        for (int i = 0; i < n; i++)
            answer += pieces[i] * value[i];

        Console.WriteLine(answer);
    }
}
