            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int[] values = new int[n];
        int maxValue = 0;

        for (int i = 0; i < n; i++)
        {
            values[i] = scanner.NextInt();
            if (values[i] > maxValue) maxValue = values[i];
        }

        int[] smallestPrime = new int[maxValue + 1];

        for (int i = 2; i <= maxValue; i++)
        {
            if (smallestPrime[i] != 0) continue;

            smallestPrime[i] = i;
            if ((long)i * i > maxValue) continue;

            for (int j = i * i; j <= maxValue; j += i)
            {
                if (smallestPrime[j] == 0)
                    smallestPrime[j] = i;
            }
        }

        long answer = 0;
        long zeroCount = 0;
        long[] frequency = new long[maxValue + 1];

        for (int index = 0; index < n; index++)
        {
            int value = values[index];

            if (value == 0)
            {
                answer += index;
                zeroCount++;
                continue;
            }

            int x = value;
            int squareFreePart = 1;

            while (x > 1)
            {
                int prime = smallestPrime[x];
                int exponentParity = 0;

                while (x % prime == 0)
                {
                    x /= prime;
                    exponentParity ^= 1;
                }

                if (exponentParity == 1)
                    squareFreePart *= prime;
            }

            answer += zeroCount + frequency[squareFreePart];
            frequency[squareFreePart]++;
        }

        Console.WriteLine(answer);
    }
