using System;
using System.IO;
using System.Text;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    private sealed class MaxHeap
    {
        private long[] values;
        private int[] nodes;
        private int count;

        public MaxHeap(int capacity)
        {
            values = new long[Math.Max(4, capacity)];
            nodes = new int[values.Length];
        }

        public int Count
        {
            get { return count; }
        }

        public void Push(long value, int node)
        {
            if (count == values.Length)
            {
                Array.Resize(ref values, values.Length * 2);
                Array.Resize(ref nodes, nodes.Length * 2);
            }

            int index = count++;
            while (index > 0)
            {
                int parent = (index - 1) >> 1;
                if (values[parent] >= value) break;

                values[index] = values[parent];
                nodes[index] = nodes[parent];
                index = parent;
            }

            values[index] = value;
            nodes[index] = node;
        }

        public void Pop(out long value, out int node)
        {
            value = values[0];
            node = nodes[0];

            count--;
            if (count == 0) return;

            long lastValue = values[count];
            int lastNode = nodes[count];
            int index = 0;

            while (true)
            {
                int left = index * 2 + 1;
                if (left >= count) break;

                int right = left + 1;
                int larger = left;

                if (right < count && values[right] > values[left])
                    larger = right;

                if (values[larger] <= lastValue) break;

                values[index] = values[larger];
                nodes[index] = nodes[larger];
                index = larger;
            }

            values[index] = lastValue;
            nodes[index] = lastNode;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int m = scanner.NextInt();

        long[] l = new long[m];
        long[] d = new long[m];
        long[] k = new long[m];
        long[] c = new long[m];
        int[] from = new int[m];
        int[] next = new int[m];
        int[] head = new int[n];

        for (int i = 0; i < n; i++)
            head[i] = -1;

        for (int i = 0; i < m; i++)
        {
            l[i] = scanner.NextLong();
            d[i] = scanner.NextLong();
            k[i] = scanner.NextLong();
            c[i] = scanner.NextLong();

            int a = scanner.NextInt() - 1;
            int b = scanner.NextInt() - 1;

            from[i] = a;
            next[i] = head[b];
            head[b] = i;
        }

        long[] latest = new long[n];
        for (int i = 0; i < n; i++)
            latest[i] = -1;

        latest[n - 1] = long.MaxValue;

        var heap = new MaxHeap(m + 1);
        heap.Push(long.MaxValue, n - 1);

        while (heap.Count > 0)
        {
            long currentTime;
            int station;
            heap.Pop(out currentTime, out station);

            if (latest[station] != currentTime)
                continue;

            for (int edge = head[station]; edge != -1; edge = next[edge])
            {
                long arrivalLimit = currentTime - c[edge];
                if (arrivalLimit < l[edge])
                    continue;

                long index = (arrivalLimit - l[edge]) / d[edge];
                if (index >= k[edge])
                    index = k[edge] - 1;

                long departure = l[edge] + index * d[edge];
                int previousStation = from[edge];

                if (departure > latest[previousStation])
                {
                    latest[previousStation] = departure;
                    heap.Push(departure, previousStation);
                }
            }
        }

        var output = new StringBuilder();

        for (int i = 0; i < n - 1; i++)
        {
            if (latest[i] < 0)
                output.AppendLine("Unreachable");
            else
                output.AppendLine(latest[i].ToString());
        }

        Console.Write(output.ToString());
    }
}
