public class Program
{
    private struct Position
    {
        public int X, Y, Z;
        public int OriginOverlap;

        public Position(int x, int y, int z)
        {
            X = x;
            Y = y;
            Z = z;
            OriginOverlap =
                (7 - Math.Abs(x)) *
                (7 - Math.Abs(y)) *
                (7 - Math.Abs(z));
        }
    }

    public static void Main()
    {
        string[] input = Console.In.ReadToEnd()
            .Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        int v1 = int.Parse(input[0]);
        int v2 = int.Parse(input[1]);
        int v3 = int.Parse(input[2]);

        const int totalVolume = 3 * 7 * 7 * 7;

        if (v1 + 2 * v2 + 3 * v3 != totalVolume)
        {
            Console.WriteLine("No");
            return;
        }

        Position[] positions = new Position[15 * 15 * 15];
        int count = 0;

        for (int x = -7; x <= 7; x++)
        {
            for (int y = -7; y <= 7; y++)
            {
                for (int z = -7; z <= 7; z++)
                {
                    positions[count++] = new Position(x, y, z);
                }
            }
        }

        int requiredPairSum = v2 + 3 * v3;

        for (int i = 0; i < count; i++)
        {
            Position p = positions[i];

            for (int j = i; j < count; j++)
            {
                Position q = positions[j];

                int requiredPQ = requiredPairSum
                               - p.OriginOverlap
                               - q.OriginOverlap;

                if (requiredPQ < 0 || requiredPQ > 343)
                    continue;

                int dx = 7 - Math.Abs(p.X - q.X);
                int pairOverlap = 0;

                if (dx > 0)
                {
                    int dy = 7 - Math.Abs(p.Y - q.Y);
                    if (dy > 0)
                    {
                        int dz = 7 - Math.Abs(p.Z - q.Z);
                        if (dz > 0)
                            pairOverlap = dx * dy * dz;
                    }
                }

                if (pairOverlap != requiredPQ)
                    continue;

                int tx = Math.Min(7, Math.Min(p.X + 7, q.X + 7))
                       - Math.Max(0, Math.Max(p.X, q.X));

                int tripleOverlap = 0;

                if (tx > 0)
                {
                    int ty = Math.Min(7, Math.Min(p.Y + 7, q.Y + 7))
                           - Math.Max(0, Math.Max(p.Y, q.Y));

                    if (ty > 0)
                    {
                        int tz = Math.Min(7, Math.Min(p.Z + 7, q.Z + 7))
                               - Math.Max(0, Math.Max(p.Z, q.Z));

                        if (tz > 0)
                            tripleOverlap = tx * ty * tz;
                    }
                }

                if (tripleOverlap == v3)
                {
                    Console.WriteLine("Yes");
                    Console.WriteLine(
                        "0 0 0 " +
                        p.X + " " + p.Y + " " + p.Z + " " +
                        q.X + " " + q.Y + " " + q.Z);
                    return;
                }
            }
        }

        Console.WriteLine("No");
    }
