using System;
using System.IO;

public class Program
{
    static int N, H, W;
    static int[] A, B;
    static bool[,] occupied;
    static bool[] used;

    static bool CanPlace(int row, int col, int height, int width)
    {
        if (row + height > H || col + width > W)
            return false;

        for (int r = row; r < row + height; r++)
            for (int c = col; c < col + width; c++)
                if (occupied[r, c])
                    return false;

        return true;
    }

    static void SetTile(int row, int col, int height, int width, bool value)
    {
        for (int r = row; r < row + height; r++)
            for (int c = col; c < col + width; c++)
                occupied[r, c] = value;
    }

    static bool Dfs()
    {
        int firstRow = -1;
        int firstCol = -1;

        for (int r = 0; r < H && firstRow == -1; r++)
        {
            for (int c = 0; c < W; c++)
            {
                if (!occupied[r, c])
                {
                    firstRow = r;
                    firstCol = c;
                    break;
                }
            }
        }

        if (firstRow == -1)
            return true;

        for (int i = 0; i < N; i++)
        {
            if (used[i])
                continue;

            for (int rotation = 0; rotation < 2; rotation++)
            {
                int height = rotation == 0 ? A[i] : B[i];
                int width = rotation == 0 ? B[i] : A[i];

                if (rotation == 1 && A[i] == B[i])
                    continue;

                if (!CanPlace(firstRow, firstCol, height, width))
                    continue;

                used[i] = true;
                SetTile(firstRow, firstCol, height, width, true);

                if (Dfs())
                    return true;

                SetTile(firstRow, firstCol, height, width, false);
                used[i] = false;
            }
        }

        return false;
    }

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        N = scanner.NextInt();
        H = scanner.NextInt();
        W = scanner.NextInt();

        A = new int[N];
        B = new int[N];

        int totalArea = 0;
        for (int i = 0; i < N; i++)
        {
            A[i] = scanner.NextInt();
            B[i] = scanner.NextInt();
            totalArea += A[i] * B[i];
        }

        if (totalArea < H * W)
        {
            Console.WriteLine("No");
            return;
        }

        occupied = new bool[H, W];
        used = new bool[N];

        Console.WriteLine(Dfs() ? "Yes" : "No");
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int pointer;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (pointer >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[pointer++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value;
        }
    }
}
