public class Program
{
    private const long INF = long.MaxValue / 4;

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        string s = scanner.Next();
        long[] costs = new long[n];

        for (int i = 0; i < n; i++)
            costs[i] = scanner.NextLong();

        long[,] dp = new long[2, 2];
        Fill(dp, INF);

        dp[0, 0] = s[0] == '0' ? 0 : costs[0];
        dp[1, 0] = s[0] == '1' ? 0 : costs[0];

        for (int i = 1; i < n; i++)
        {
            long[,] next = new long[2, 2];
            Fill(next, INF);

            for (int previous = 0; previous <= 1; previous++)
            {
                for (int equalCount = 0; equalCount <= 1; equalCount++)
                {
                    if (dp[previous, equalCount] == INF)
                        continue;

                    for (int current = 0; current <= 1; current++)
                    {
                        int newCount = equalCount + (previous == current ? 1 : 0);
                        if (newCount > 1)
                            continue;

                        long changeCost = (s[i] - '0' == current) ? 0 : costs[i];
                        long value = dp[previous, equalCount] + changeCost;

                        if (value < next[current, newCount])
                            next[current, newCount] = value;
                    }
                }
            }

            dp = next;
        }

        Console.WriteLine(Math.Min(dp[0, 1], dp[1, 1]));
    }

