            colors[i] = scanner.NextInt();
        }

        bool[] processedRows = new bool[h];
        bool[] processedColumns = new bool[w];
        int rowCount = 0;
        int columnCount = 0;

        long[] counts = new long[200001];

        for (int i = m - 1; i >= 0; i--)
        {
            if (types[i] == 1)
            {
                int row = indices[i];
                if (processedRows[row]) continue;

                processedRows[row] = true;
                rowCount++;
                counts[colors[i]] += (long)w - columnCount;
            }
            else
            {
                int column = indices[i];
                if (processedColumns[column]) continue;

                processedColumns[column] = true;
                columnCount++;
                counts[colors[i]] += (long)h - rowCount;
            }
        }

        counts[0] += ((long)h - rowCount) * ((long)w - columnCount);

        int distinctCount = 0;
        for (int color = 0; color < counts.Length; color++)
        {
            if (counts[color] > 0) distinctCount++;
        }

        var output = new StringBuilder();
        output.AppendLine(distinctCount.ToString());

        for (int color = 0; color < counts.Length; color++)
        {
            if (counts[color] > 0)
            {
                output.Append(color);
                output.Append(' ');
                output.AppendLine(counts[color].ToString());
            }
        }

