using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length, position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public string Next()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            var chars = new System.Text.StringBuilder();
            while (c > 32 && c != -1)
            {
                chars.Append((char)c);
                c = ReadByte();
            }
            return chars.ToString();
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int h = scanner.NextInt();
        int w = scanner.NextInt();
        char[][] grid = new char[h][];

        int startCell = -1;
        int targetCell = -1;

        for (int r = 0; r < h; r++)
        {
            grid[r] = scanner.Next().ToCharArray();
            for (int c = 0; c < w; c++)
            {
                if (grid[r][c] == 'S') startCell = r * w + c;
                if (grid[r][c] == 'T') targetCell = r * w + c;
            }
        }

        int n = scanner.NextInt();
        int[] medicineCell = new int[n];
        int[] energy = new int[n];
        int[] medicineAt = new int[h * w];
        for (int i = 0; i < medicineAt.Length; i++) medicineAt[i] = -1;

        for (int i = 0; i < n; i++)
        {
            int r = scanner.NextInt() - 1;
            int c = scanner.NextInt() - 1;
            int e = scanner.NextInt();

            medicineCell[i] = r * w + c;
            energy[i] = e;
            medicineAt[medicineCell[i]] = i;
        }

        int startMedicine = medicineAt[startCell];
        if (startMedicine == -1)
        {
            Console.WriteLine("No");
            return;
        }

        bool[] reachableMedicine = new bool[n];
        int[] medicineQueue = new int[n];
        int medicineHead = 0;
        int medicineTail = 0;

        reachableMedicine[startMedicine] = true;
        medicineQueue[medicineTail++] = startMedicine;

        int cellCount = h * w;
        int[] cellQueue = new int[cellCount];
        int[] distance = new int[cellCount];
        int[] seen = new int[cellCount];
        int stamp = 0;

        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        while (medicineHead < medicineTail)
        {
            int medicine = medicineQueue[medicineHead++];
            int limit = energy[medicine];
            int source = medicineCell[medicine];

            stamp++;
            int head = 0;
            int tail = 0;

            cellQueue[tail++] = source;
            seen[source] = stamp;
            distance[source] = 0;

            while (head < tail)
            {
                int cell = cellQueue[head++];
                int dist = distance[cell];

                if (cell == targetCell)
                {
                    Console.WriteLine("Yes");
                    return;
                }

                int foundMedicine = medicineAt[cell];
                if (foundMedicine != -1 && !reachableMedicine[foundMedicine])
                {
                    reachableMedicine[foundMedicine] = true;
                    medicineQueue[medicineTail++] = foundMedicine;
                }

                if (dist == limit) continue;

                int r = cell / w;
                int c = cell % w;

                for (int d = 0; d < 4; d++)
                {
                    int nr = r + dr[d];
                    int nc = c + dc[d];

                    if (nr < 0 || nr >= h || nc < 0 || nc >= w)
                        continue;
                    if (grid[nr][nc] == '#')
                        continue;

                    int next = nr * w + nc;
                    if (seen[next] == stamp)
                        continue;

                    seen[next] = stamp;
                    distance[next] = dist + 1;
                    cellQueue[tail++] = next;
                }
            }
        }

        Console.WriteLine("No");
    }
}
