using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        var graph = new List<int>[n];
        for (int i = 0; i < n; i++)
            graph[i] = new List<int>();

        for (int i = 0; i < n - 1; i++)
        {
            int a = scanner.NextInt() - 1;
            int b = scanner.NextInt() - 1;
            graph[a].Add(b);
            graph[b].Add(a);
        }

        var weights = new long[n];
        long totalWeight = 0;
        for (int i = 0; i < n; i++)
        {
            weights[i] = scanner.NextInt();
            totalWeight += weights[i];
        }

        var parent = new int[n];
        var depth = new int[n];
        var order = new int[n];
        Array.Fill(parent, -2);

        int orderCount = 0;
        order[orderCount++] = 0;
        parent[0] = -1;

        for (int i = 0; i < orderCount; i++)
        {
            int v = order[i];
            foreach (int next in graph[v])
            {
                if (next == parent[v]) continue;
                parent[next] = v;
                depth[next] = depth[v] + 1;
                order[orderCount++] = next;
            }
        }

        var subtreeWeight = new long[n];
        long rootCost = 0;

        for (int i = 0; i < n; i++)
        {
            subtreeWeight[i] = weights[i];
            rootCost += weights[i] * depth[i];
        }

        for (int i = n - 1; i > 0; i--)
        {
            int v = order[i];
            subtreeWeight[parent[v]] += subtreeWeight[v];
        }

        var cost = new long[n];
        cost[0] = rootCost;
        long answer = rootCost;

        for (int i = 1; i < n; i++)
        {
            int v = order[i];
            cost[v] = cost[parent[v]] + totalWeight - 2L * subtreeWeight[v];
            if (cost[v] < answer)
                answer = cost[v];
        }

        Console.WriteLine(answer);
    }
}
