    public static void Main()
    {
        string[] input = Console.In.ReadToEnd()
            .Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        long L = long.Parse(input[0]);
        long R = long.Parse(input[1]);

        var intervals = new List<KeyValuePair<long, long>>();
        long current = L;

        while (current < R)
        {
            long remaining = R - current;
            long length;

            if (current == 0)
            {
                length = LargestPowerOfTwoAtMost(remaining);
            }
            else
            {
                length = current & -current;
                while (length > remaining)
                    length >>= 1;
            }

            intervals.Add(new KeyValuePair<long, long>(current, current + length));
            current += length;
        }

        var output = new StringBuilder();
        output.AppendLine(intervals.Count.ToString());

        foreach (var interval in intervals)
        {
            output.Append(interval.Key);
            output.Append(' ');
            output.AppendLine(interval.Value.ToString());
        }

        Console.Write(output.ToString());
    }

    private static long LargestPowerOfTwoAtMost(long value)
    {
        long result = 1;
        while (result <= value / 2)
            result <<= 1;
        return result;
    }
}
