```csharp
using System;

public class Program
{
    static readonly int[] LineMasks =
    {
        0b000000111,
        0b000111000,
        0b111000000,
        0b001001001,
        0b010010010,
        0b100100100,
        0b100010001,
        0b001010100
    };

    static readonly int[] Pow3 = new int[9];
    static readonly long[] Values = new long[9];
    static readonly sbyte[] Memo = new sbyte[19683];

    // Returns 1 if Takahashi wins, 0 if Aoki wins.
    static int Solve(int code, int redMask, int blueMask, int moves)
    {
        foreach (int line in LineMasks)
        {
            if ((redMask & line) == line)
                return 1;
            if ((blueMask & line) == line)
                return 0;
        }

        if (moves == 9)
        {
            long takahashiScore = 0;
            long aokiScore = 0;

            for (int i = 0; i < 9; i++)
            {
                int bit = 1 << i;
                if ((redMask & bit) != 0)
                    takahashiScore += Values[i];
                else
                    aokiScore += Values[i];
            }

            return takahashiScore > aokiScore ? 1 : 0;
        }

        if (Memo[code] != -1)
            return Memo[code];

        int occupied = redMask | blueMask;

        if (moves % 2 == 0)
        {
            // Takahashi chooses any move that lets him win.
            for (int i = 0; i < 9; i++)
            {
                int bit = 1 << i;
                if ((occupied & bit) == 0)
                {
                    int result = Solve(
                        code + Pow3[i],
                        redMask | bit,
                        blueMask,
                        moves + 1
                    );

                    if (result == 1)
                    {
                        Memo[code] = 1;
                        return 1;
                    }
                }
            }

            Memo[code] = 0;
            return 0;
        }
        else
        {
            // Aoki chooses any move that lets him win.
            for (int i = 0; i < 9; i++)
            {
                int bit = 1 << i;
                if ((occupied & bit) == 0)
                {
                    int result = Solve(
                        code + 2 * Pow3[i],
                        redMask,
                        blueMask | bit,
                        moves + 1
                    );

                    if (result == 0)
                    {
                        Memo[code] = 0;
                        return 0;
                    }
                }
            }

            Memo[code] = 1;
            return 1;
        }
    }

    public static void Main()
    {
        string[] input = Console.In.ReadToEnd()
            .Split((char[])null, StringSplitOptions.RemoveEmptyEntries);

        for (int i = 0; i < 9; i++)
            Values[i] = long.Parse(input[i]);

        Pow3[0] = 1;
        for (int i = 1; i < 9; i++)
            Pow3[i] = Pow3[i - 1] * 3;

        for (int i = 0; i < Memo.Length; i++)
            Memo[i] = -1;

        Console.WriteLine(Solve(0, 0, 0, 0) == 1 ? "Takahashi" : "Aoki");
    }
}
