            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }
    }

    private sealed class DisjointSetUnion
    {
        private readonly int[] parent;
        private readonly int[] size;

        public DisjointSetUnion(int n)
        {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++)
            {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int Find(int x)
        {
            int root = x;
            while (parent[root] != root)
                root = parent[root];

            while (parent[x] != x)
            {
                int next = parent[x];
                parent[x] = root;
                x = next;
            }

            return root;
        }

        public void Union(int a, int b)
        {
            a = Find(a);
            b = Find(b);
            if (a == b) return;

            if (size[a] < size[b])
            {
                int temp = a;
                a = b;
                b = temp;
            }

            parent[b] = a;
            size[a] += size[b];
        }

        public int ComponentSize(int root)
        {
            return size[root];
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int m = scanner.NextInt();

        var dsu = new DisjointSetUnion(n);

        for (int i = 0; i < m; i++)
        {
            int a = scanner.NextInt() - 1;
            int b = scanner.NextInt() - 1;
            dsu.Union(a, b);
        }

        long totalPossibleEdges = 0;

        for (int i = 0; i < n; i++)
        {
            if (dsu.Find(i) == i)
            {
                long size = dsu.ComponentSize(i);
                totalPossibleEdges += size * (size - 1) / 2;
            }
        }

        Console.WriteLine(totalPossibleEdges - m);
    }
}
