using System;
using System.Collections.Generic;
using System.Globalization;

public class Program
{
    static long A;
    static double X, Y;
    static Dictionary<long, double> memo = new Dictionary<long, double>();

    static double Solve(long n)
    {
        if (n == 0) return 0.0;

        double cached;
        if (memo.TryGetValue(n, out cached))
            return cached;

        double deterministic = X + Solve(n / A);

        double sum = 0.0;
        for (int b = 2; b <= 6; b++)
            sum += Solve(n / b);

        // The outcome b = 1 leaves n unchanged. Solving the resulting
        // self-referential expectation gives this expression.
        double dice = (6.0 * Y + sum) / 5.0;

        double result = Math.Min(deterministic, dice);
        memo[n] = result;
        return result;
    }

    public static void Main()
    {
        string[] input = Console.ReadLine().Split();
        long n = long.Parse(input[0], CultureInfo.InvariantCulture);
        A = long.Parse(input[1], CultureInfo.InvariantCulture);
        X = double.Parse(input[2], CultureInfo.InvariantCulture);
        Y = double.Parse(input[3], CultureInfo.InvariantCulture);

        double answer = Solve(n);
        Console.WriteLine(answer.ToString("G17", CultureInfo.InvariantCulture));
    }
}
