using System;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public string Next()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            var chars = new char[1024];
            int count = 0;

            while (c > 32 && c != -1)
            {
                if (count == chars.Length)
                    Array.Resize(ref chars, chars.Length * 2);

                chars[count++] = (char)c;
                c = ReadByte();
            }

            return new string(chars, 0, count);
        }

        public int NextInt()
        {
            return int.Parse(Next());
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int h = scanner.NextInt();
        int w = scanner.NextInt();
        int n = h * w;

        string[] grid = new string[h];
        for (int r = 0; r < h; r++)
            grid[r] = scanner.Next();

        bool[] dangerous = new bool[n];

        for (int r = 0; r < h; r++)
        {
            for (int c = 0; c < w; c++)
            {
                if (grid[r][c] != '#') continue;

                if (r > 0 && grid[r - 1][c] == '.')
                    dangerous[(r - 1) * w + c] = true;
                if (r + 1 < h && grid[r + 1][c] == '.')
                    dangerous[(r + 1) * w + c] = true;
                if (c > 0 && grid[r][c - 1] == '.')
                    dangerous[r * w + c - 1] = true;
                if (c + 1 < w && grid[r][c + 1] == '.')
                    dangerous[r * w + c + 1] = true;
            }
        }

        bool[] visited = new bool[n];
        int[] boundaryMark = new int[n];
        int[] queue = new int[n];
        int stamp = 0;
        int answer = 1;

        for (int r = 0; r < h; r++)
        {
            for (int c = 0; c < w; c++)
            {
                int start = r * w + c;

                if (grid[r][c] == '#' || dangerous[start] || visited[start])
                    continue;

                stamp++;
                int head = 0;
                int tail = 0;
                int reachable = 0;

                visited[start] = true;
                queue[tail++] = start;

                while (head < tail)
                {
                    int current = queue[head++];
                    reachable++;

                    int cr = current / w;
                    int cc = current - cr * w;

                    if (cr > 0)
                        ProcessNeighbor(current - w, cr - 1, cc, grid, dangerous,
                                        visited, boundaryMark, stamp, queue,
                                        ref tail, ref reachable);

                    if (cr + 1 < h)
                        ProcessNeighbor(current + w, cr + 1, cc, grid, dangerous,
                                        visited, boundaryMark, stamp, queue,
                                        ref tail, ref reachable);

                    if (cc > 0)
                        ProcessNeighbor(current - 1, cr, cc - 1, grid, dangerous,
                                        visited, boundaryMark, stamp, queue,
                                        ref tail, ref reachable);

                    if (cc + 1 < w)
                        ProcessNeighbor(current + 1, cr, cc + 1, grid, dangerous,
                                        visited, boundaryMark, stamp, queue,
                                        ref tail, ref reachable);
                }

                if (reachable > answer)
                    answer = reachable;
            }
        }

        Console.WriteLine(answer);
    }

    private static void ProcessNeighbor(
        int index,
        int row,
        int column,
        string[] grid,
        bool[] dangerous,
        bool[] visited,
        int[] boundaryMark,
        int stamp,
        int[] queue,
        ref int tail,
        ref int reachable)
    {
        if (grid[row][column] == '#')
            return;

        if (dangerous[index])
        {
            if (boundaryMark[index] != stamp)
            {
                boundaryMark[index] = stamp;
                reachable++;
            }
        }
        else if (!visited[index])
        {
            visited[index] = true;
            queue[tail++] = index;
        }
    }
}
