    private static long SumAbsoluteDifferences(List<long> values)
    {
        values.Sort();

        long sum = 0;
        long prefixSum = 0;

        for (int i = 0; i < values.Count; i++)
        {
            sum += values[i] * i - prefixSum;
            prefixSum += values[i];
        }

        return sum;
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        var uEven = new List<long>();
        var vEven = new List<long>();
        var uOdd = new List<long>();
        var vOdd = new List<long>();

        for (int i = 0; i < n; i++)
