            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    private sealed class FenwickTree
    {
        private readonly long[] tree;

        public FenwickTree(int size)
        {
            tree = new long[size + 1];
        }

        public void Add(int index, long value)
        {
            for (int i = index; i < tree.Length; i += i & -i)
                tree[i] += value;
        }

        public long Sum(int index)
        {
            long result = 0;
            for (int i = index; i > 0; i -= i & -i)
                result += tree[i];
            return result;
        }
    }

    private static int LowerBound(int[] array, int value)
    {
        int left = 0;
        int right = array.Length;

        while (left < right)
        {
            int middle = left + (right - left) / 2;
            if (array[middle] < value)
                left = middle + 1;
            else
                right = middle;
        }

        return left;
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        int[] values = new int[n];
        for (int i = 0; i < n; i++)
            values[i] = scanner.NextInt();

        int[] sorted = (int[])values.Clone();
        Array.Sort(sorted);

        var countTree = new FenwickTree(n);
        var sumTree = new FenwickTree(n);

        long answer = 0;

        for (int i = 0; i < n; i++)
        {
            int value = values[i];
            int rank = LowerBound(sorted, value);

            long smallerCount = countTree.Sum(rank);
            long smallerSum = sumTree.Sum(rank);

            answer += smallerCount * value - smallerSum;

            int fenwickIndex = rank + 1;
            countTree.Add(fenwickIndex, 1);
            sumTree.Add(fenwickIndex, value);
        }

        Console.WriteLine(answer);
    }
}
