public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value * sign;
        }
    }

    private sealed class DisjointSetUnion
    {
        private readonly int[] parent;
        private readonly int[] size;

        public DisjointSetUnion(int n)
        {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++)
            {
                parent[i] = i;
                size[i] = 1;
            }
        }

        private int Find(int x)
        {
            int root = x;
            while (parent[root] != root)
                root = parent[root];

            while (parent[x] != x)
            {
                int next = parent[x];
                parent[x] = root;
                x = next;
            }

            return root;
        }

        public bool Union(int a, int b)
        {
            a = Find(a);
            b = Find(b);

            if (a == b) return false;

            if (size[a] < size[b])
            {
                int temp = a;
                a = b;
                b = temp;
            }

            parent[b] = a;
            size[a] += size[b];
            return true;
        }
    }

    private sealed class Operation
    {
        public int Cost;
        public int[] Vertices;
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();

        int n = scanner.NextInt();
        int m = scanner.NextInt();

        Operation[] operations = new Operation[m];

        for (int i = 0; i < m; i++)
        {
            int k = scanner.NextInt();
            int cost = scanner.NextInt();
            int[] vertices = new int[k];

            for (int j = 0; j < k; j++)
                vertices[j] = scanner.NextInt() - 1;

            operations[i] = new Operation
            {
                Cost = cost,
                Vertices = vertices
            };
        }

        Array.Sort(operations, delegate(Operation x, Operation y)
        {
            return x.Cost.CompareTo(y.Cost);
        });

        DisjointSetUnion dsu = new DisjointSetUnion(n);
        long totalWeight = 0;
        int selectedEdges = 0;

        for (int i = 0; i < m && selectedEdges < n - 1; i++)
        {
            Operation operation = operations[i];
            int anchor = operation.Vertices[0];

            for (int j = 1; j < operation.Vertices.Length; j++)
            {
                if (dsu.Union(anchor, operation.Vertices[j]))
                {
                    totalWeight += operation.Cost;
                    selectedEdges++;

                    if (selectedEdges == n - 1)
                        break;
                }
            }
        }

        Console.WriteLine(selectedEdges == n - 1 ? totalWeight.ToString() : "-1");
    }
}
