                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public string Next()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            char[] chars = new char[16];
            int count = 0;

            while (c > 32 && c != -1)
            {
                if (count == chars.Length)
                    Array.Resize(ref chars, chars.Length * 2);

                chars[count++] = (char)c;
                c = ReadByte();
            }

            return new string(chars, 0, count);
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        const int MaxNodes = 300005;
        const int AlphabetSize = 26;

        var scanner = new FastScanner();
        int n = scanner.NextInt();

        int[] children = new int[MaxNodes * AlphabetSize];
        int[] prefixCount = new int[MaxNodes];
        int nodeCount = 1;
        long answer = 0;

        for (int i = 0; i < n; i++)
        {
            string s = scanner.Next();
            int node = 0;

            for (int j = 0; j < s.Length; j++)
            {
                int letter = s[j] - 'a';
                int edgeIndex = node * AlphabetSize + letter;
                int next = children[edgeIndex];

                if (next == 0)
                {
                    next = nodeCount++;
                    children[edgeIndex] = next;
                }

                node = next;
                answer += prefixCount[node];
                prefixCount[node]++;
            }
        }

        Console.WriteLine(answer);
    }
