    private struct Card
    {
        public long Strength;
        public long Cost;
        public int Index;

        public Card(long strength, long cost, int index)
        {
            Strength = strength;
            Cost = cost;
            Index = index;
        }
    }

    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int pointer;

        private int Read()
        {
            if (pointer >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0) return -1;
            }
            return buffer[pointer++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        var cards = new Card[n];

        for (int i = 0; i < n; i++)
        {
            long strength = scanner.NextLong();
            long cost = scanner.NextLong();
            cards[i] = new Card(strength, cost, i + 1);
        }

        Array.Sort(cards, delegate(Card x, Card y)
        {
            return y.Strength.CompareTo(x.Strength);
        });

        long minimumCost = long.MaxValue;
        var remaining = new List<int>();

        for (int i = 0; i < n; i++)
        {
            if (cards[i].Cost < minimumCost)
            {
                remaining.Add(cards[i].Index);
                minimumCost = cards[i].Cost;
            }
        }

        remaining.Sort();

        var output = new StringBuilder();
        output.AppendLine(remaining.Count.ToString());
        for (int i = 0; i < remaining.Count; i++)
        {
            if (i > 0) output.Append(' ');
            output.Append(remaining[i]);
        }
        output.AppendLine();

        Console.Write(output.ToString());
    }
}
