        long b = long.Parse(input[1]);
        long c = long.Parse(input[2]);
        long d = long.Parse(input[3]);

        const long offset = 1000000000L;
        a += offset;
        b += offset;
        c += offset;
        d += offset;

        long answer = Prefix(c, d)
                    - Prefix(a, d)
                    - Prefix(c, b)
                    + Prefix(a, b);

        Console.WriteLine(answer);
    }
