using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly TextReader reader = Console.In;

        public int NextInt()
        {
            int c;
            do
            {
                c = reader.Read();
            } while (c <= ' ' && c != -1);

            if (c == -1) return -1;

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = reader.Read();
            }

            int value = 0;
            while (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
                c = reader.Read();
            }

            return value * sign;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int l = scanner.NextInt();
        int r = scanner.NextInt();

        int size = 1 << n;
        int start = l;
        int goal = r + 1;

        int[] previous = new int[size + 1];
        for (int i = 0; i <= size; i++)
            previous[i] = -2;

        int[] queue = new int[size + 1];
        int head = 0;
        int tail = 0;

        previous[start] = -1;
        queue[tail++] = start;

        while (head < tail && previous[goal] == -2)
        {
            int current = queue[head++];

            for (int i = 0; i <= n; i++)
            {
                int blockSize = 1 << i;

                if (current % blockSize != 0)
                    break;

                int next = current - blockSize;
                if (next >= 0 && previous[next] == -2)
                {
                    previous[next] = current;
                    queue[tail++] = next;
                }

                next = current + blockSize;
                if (next <= size && previous[next] == -2)
                {
                    previous[next] = current;
                    queue[tail++] = next;
                }
            }
        }

        var path = new List<int>();
        for (int current = goal; current != -1; current = previous[current])
            path.Add(current);

        path.Reverse();

        int answer = 0;

        for (int k = 0; k + 1 < path.Count; k++)
        {
            int from = path[k];
            int to = path[k + 1];
            int difference = Math.Abs(to - from);

            int i = 0;
            while ((1 << i) != difference)
                i++;

            int j = Math.Min(from, to) / difference;

            Console.WriteLine("? {0} {1}", i, j);
            Console.Out.Flush();

            int response = scanner.NextInt();
            if (response == -1)
                return;

            if (from < to)
                answer += response;
            else
                answer -= response;

            answer %= 100;
        }

        answer = (answer + 100) % 100;
        Console.WriteLine("! {0}", answer);
        Console.Out.Flush();
    }
}
