        bool[] opened = new bool[m];

        for (int i = 0; i < m; i++)
        {
            int c = scanner.NextInt();
            int mask = 0;

            for (int j = 0; j < c; j++)
            {
                int key = scanner.NextInt() - 1;
                mask |= 1 << key;
            }

            testMasks[i] = mask;
            opened[i] = scanner.Next()[0] == 'o';
        }

        int totalMasks = 1 << n;
        int[] bitCount = new int[totalMasks];

        for (int mask = 1; mask < totalMasks; mask++)
            bitCount[mask] = bitCount[mask >> 1] + (mask & 1);

        int answer = 0;

        for (int realMask = 0; realMask < totalMasks; realMask++)
        {
            bool valid = true;

            for (int i = 0; i < m; i++)
            {
                bool wouldOpen = bitCount[realMask & testMasks[i]] >= k;

                if (wouldOpen != opened[i])
                {
                    valid = false;
                    break;
                }
            }

            if (valid) answer++;
        }

        Console.WriteLine(answer);
    }
