        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        const int Limit = 1000000;
        int[] frequency = new int[Limit + 1];
        int maximum = 0;

        for (int i = 0; i < n; i++)
        {
            int value = scanner.NextInt();
            frequency[value]++;
            if (value > maximum) maximum = value;
        }

        int[] prefix = new int[maximum + 1];
        for (int value = 1; value <= maximum; value++)
        {
            prefix[value] = prefix[value - 1] + frequency[value];
        }

        long answer = 0;

        for (int value = 1; value <= maximum; value++)
        {
            int count = frequency[value];
            if (count == 0) continue;

            answer += (long)count * (count - 1) / 2;

            int left = value + 1;
            while (left <= maximum)
            {
                int quotient = left / value;
                int right = (quotient + 1) * value - 1;
                if (right > maximum) right = maximum;

                int otherCount = prefix[right] - prefix[left - 1];
                answer += (long)count * otherCount * quotient;

                left = right + 1;
            }
        }

        Console.WriteLine(answer);
    }
}
