public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        int[] next = new int[n];
        int[] indegree = new int[n];

        for (int i = 0; i < n; i++)
        {
            next[i] = scanner.NextInt() - 1;
            indegree[next[i]]++;
        }

        int[] queue = new int[n];
        int[] removedOrder = new int[n];
        int head = 0, tail = 0, removedCount = 0;

        for (int i = 0; i < n; i++)
        {
            if (indegree[i] == 0)
                queue[tail++] = i;
        }

        while (head < tail)
        {
            int u = queue[head++];
            removedOrder[removedCount++] = u;

            int v = next[u];
            indegree[v]--;
            if (indegree[v] == 0)
                queue[tail++] = v;
        }

        long[] reachableCount = new long[n];
        bool[] visited = new bool[n];

        for (int i = 0; i < n; i++)
        {
            if (indegree[i] > 0 && !visited[i])
            {
                int cycleLength = 0;
                int current = i;

                do
                {
                    visited[current] = true;
                    cycleLength++;
                    current = next[current];
                } while (current != i);

                current = i;
                do
                {
                    reachableCount[current] = cycleLength;
                    current = next[current];
                } while (current != i);
            }
        }

        for (int i = removedCount - 1; i >= 0; i--)
        {
            int u = removedOrder[i];
            reachableCount[u] = reachableCount[next[u]] + 1;
        }

        long answer = 0;
        for (int i = 0; i < n; i++)
            answer += reachableCount[i];

        Console.WriteLine(answer);
    }
}
