using System;

public class Program
{
    private const int Mod = 998244353;

    public static void Main()
    {
        string[] first = Console.ReadLine().Split();
        int n = int.Parse(first[0]);
        int k = int.Parse(first[1]);
        string s = Console.ReadLine().Trim();

        int stateCount = 1 << (k - 1);
        int stateMask = stateCount - 1;

        bool[] palindrome = new bool[1 << k];
        for (int mask = 0; mask < (1 << k); mask++)
        {
            bool isPalindrome = true;
            for (int i = 0; i < k / 2; i++)
            {
                int left = (mask >> i) & 1;
                int right = (mask >> (k - 1 - i)) & 1;
                if (left != right)
                {
                    isPalindrome = false;
                    break;
                }
            }
            palindrome[mask] = isPalindrome;
        }

        int[] dp = new int[stateCount];
        dp[0] = 1;

        for (int i = 0; i < n; i++)
        {
            int[] next = new int[stateCount];

            int firstBit = s[i] == 'B' ? 1 : 0;
            int lastBit = s[i] == 'A' ? 0 : 1;

            for (int state = 0; state < stateCount; state++)
            {
                if (dp[state] == 0)
                    continue;

                for (int bit = firstBit; bit <= lastBit; bit++)
                {
                    int fullMask = (state << 1) | bit;

                    if (i >= k - 1 && palindrome[fullMask])
                        continue;

                    int newState = fullMask & stateMask;
                    int value = next[newState] + dp[state];
                    if (value >= Mod)
                        value -= Mod;
                    next[newState] = value;
                }
            }

            dp = next;
        }

        int answer = 0;
        for (int state = 0; state < stateCount; state++)
        {
            answer += dp[state];
            if (answer >= Mod)
                answer -= Mod;
        }

        Console.WriteLine(answer);
    }
}
