                c = ReadByte();
            }
            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        long[] values = new long[n];
        long[] counts = new long[n];
        int top = 0;
        long suffixMaximumSum = 0;

        var output = new StringBuilder();

        for (int i = 0; i < n; i++)
        {
            long h = scanner.NextLong();
            long count = 1;

            while (top > 0 && values[top - 1] <= h)
            {
                top--;
                suffixMaximumSum -= values[top] * counts[top];
                count += counts[top];
            }

            values[top] = h;
            counts[top] = count;
            top++;

            suffixMaximumSum += h * count;
            long answer = suffixMaximumSum + 1;

            if (i > 0) output.Append(' ');
            output.Append(answer);
        }

        Console.WriteLine(output.ToString());
    }
