using System.IO;
using System.Text;

public class Program
{
    private struct Ant
    {
        public long Position;
        public char Direction;

        public Ant(long position, char direction)
        {
            Position = position;
            Direction = direction;
        }
    }

    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int pointer;

        private int ReadByte()
        {
            if (pointer >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0) return -1;
            }
            return buffer[pointer++];
        }

        public string Next()
        {
            var sb = new StringBuilder();
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            while (c > 32 && c != -1)
            {
                sb.Append((char)c);
                c = ReadByte();
            }
            return sb.ToString();
        }

        public int NextInt()
        {
            return int.Parse(Next());
        }

        public long NextLong()
        {
            return long.Parse(Next());
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        long t = scanner.NextLong();
        string s = scanner.Next();

        var ants = new Ant[n];
        for (int i = 0; i < n; i++)
        {
            ants[i] = new Ant(scanner.NextLong(), s[i]);
        }

        Array.Sort(ants, (a, b) => a.Position.CompareTo(b.Position));

        long answer = 0;
        long activeRightMoving = 0;
        long maxDistance = 2L * t;
        int left = 0;

        for (int right = 0; right < n; right++)
        {
            long minimumPosition = ants[right].Position - maxDistance;

            while (left < right && ants[left].Position < minimumPosition)
            {
                if (ants[left].Direction == '1')
                    activeRightMoving--;
                left++;
            }

            if (ants[right].Direction == '0')
            {
                answer += activeRightMoving;
            }
            else
            {
                activeRightMoving++;
            }
        }

        Console.WriteLine(answer);
    }
}
