using System;

public class Program
{
    const long Mod = 998244353;

    static long ModPow(long value, long exponent)
    {
        long result = 1;
        value %= Mod;

        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * value % Mod;

            value = value * value % Mod;
            exponent >>= 1;
        }

        return result;
    }

    public static void Main()
    {
        string[] input = Console.ReadLine().Split();
        long n = long.Parse(input[0]);
        long k = long.Parse(input[1]);

        long inverseN = ModPow(n, Mod - 2);
        long ratio = ((n - 2 + Mod) % Mod) * inverseN % Mod;
        long ratioPower = ModPow(ratio, k);
        long inverseTwo = (Mod + 1) / 2;

        long answer = ((n + 1) % Mod
                     - ((n - 1) % Mod) * ratioPower % Mod
                     + Mod) % Mod;

        answer = answer * inverseTwo % Mod;
        Console.WriteLine(answer);
    }
}
