public class Program
{
    public static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        string s = Console.ReadLine().Trim();
        string t = Console.ReadLine().Trim();

        int length = n + 2;
        int maskRange = 1 << length;
        int stateCount = (n + 1) * maskRange;

        int initialMask = 0;
        int targetMask = 0;

        for (int i = 0; i < n; i++)
        {
            if (s[i] == 'B')
                initialMask |= 1 << i;
            if (t[i] == 'B')
                targetMask |= 1 << i;
        }

        int initialState = n * maskRange + initialMask;
        int targetState = n * maskRange + targetMask;

        int[] distance = new int[stateCount];
        for (int i = 0; i < stateCount; i++)
            distance[i] = -1;

        int[] queue = new int[stateCount];
        int head = 0;
        int tail = 0;

        distance[initialState] = 0;
        queue[tail++] = initialState;

        while (head < tail)
        {
            int state = queue[head++];

            if (state == targetState)
            {
                Console.WriteLine(distance[state]);
                return;
            }

            int gap = state / maskRange;
            int mask = state % maskRange;

            for (int x = 0; x <= n; x++)
            {
                // The selected pair must not overlap the two empty cells.
                if (!(x + 1 < gap || x > gap + 1))
                    continue;

                bool firstBlack = (mask & (1 << x)) != 0;
                bool secondBlack = (mask & (1 << (x + 1))) != 0;

                int newMask = mask;
                newMask &= ~(1 << x);
                newMask &= ~(1 << (x + 1));

                if (firstBlack)
                    newMask |= 1 << gap;
                if (secondBlack)
                    newMask |= 1 << (gap + 1);

                int newState = x * maskRange + newMask;

                if (distance[newState] == -1)
                {
                    distance[newState] = distance[state] + 1;
                    queue[tail++] = newState;
                }
            }
        }

        Console.WriteLine(-1);
    }
}
