using System;
using System.Collections.Generic;

public class Program
{
    static long IntegerSquareRoot(long n)
    {
        long r = (long)Math.Sqrt(n);

        while (r + 1 <= n / (r + 1))
            r++;

        while (r > n / r)
            r--;

        return r;
    }

    static long IntegerCubeRoot(long n)
    {
        long low = 0;
        long high = 1_000_001;

        while (high - low > 1)
        {
            long mid = (low + high) / 2;
            long cube = mid * mid * mid;

            if (cube <= n)
                low = mid;
            else
                high = mid;
        }

        return low;
    }

    public static void Main()
    {
        long n = long.Parse(Console.ReadLine().Trim());

        // Every square is a perfect power, including 1.
        long squareCount = IntegerSquareRoot(n);
        long maxBase = IntegerCubeRoot(n);

        // Store non-square perfect powers having an odd exponent >= 3.
        var nonSquarePowers = new HashSet<long>();

        for (long a = 2; a <= maxBase; a++)
        {
            long root = (long)Math.Sqrt(a);
            if (root * root == a)
                continue;

            long value = a * a * a;
            long multiplier = a * a;

            // Generate a^3, a^5, a^7, ...
            while (value <= n)
            {
                nonSquarePowers.Add(value);

                if (value > n / multiplier)
                    break;

                value *= multiplier;
            }
        }

        Console.WriteLine(squareCount + nonSquarePowers.Count);
    }
}
