public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int pointer;

        private int Read()
        {
            if (pointer >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0) return -1;
            }
            return buffer[pointer++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value * sign;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        long[] left = new long[n];
        long[] right = new long[n];
        long sumLeft = 0;
        long sumRight = 0;

        for (int i = 0; i < n; i++)
        {
            left[i] = scanner.NextLong();
            right[i] = scanner.NextLong();
            sumLeft += left[i];
            sumRight += right[i];
        }

        if (sumLeft > 0 || sumRight < 0)
        {
            Console.WriteLine("No");
            return;
        }

        long[] result = new long[n];
        long remaining = -sumLeft;

        for (int i = 0; i < n; i++)
        {
            long increase = Math.Min(remaining, right[i] - left[i]);
            result[i] = left[i] + increase;
            remaining -= increase;
        }

        var output = new StringBuilder();
        output.AppendLine("Yes");

        for (int i = 0; i < n; i++)
        {
            if (i > 0) output.Append(' ');
            output.Append(result[i]);
        }
        output.AppendLine();

        Console.Write(output.ToString());
    }
}
