using System;
using System.IO;
using System.Text;
using System.Collections.Generic;

public class Program
{
    private struct Edge
    {
        public int To;
        public long Weight;

        public Edge(int to, long weight)
        {
            To = to;
            Weight = weight;
        }
    }

    private struct HeapNode
    {
        public int Vertex;
        public long Distance;

        public HeapNode(int vertex, long distance)
        {
            Vertex = vertex;
            Distance = distance;
        }
    }

    private sealed class MinHeap
    {
        private HeapNode[] heap = new HeapNode[16];
        private int count;

        public int Count
        {
            get { return count; }
        }

        public void Push(HeapNode node)
        {
            if (count == heap.Length)
                Array.Resize(ref heap, heap.Length * 2);

            int index = count++;
            while (index > 0)
            {
                int parent = (index - 1) / 2;
                if (heap[parent].Distance <= node.Distance)
                    break;

                heap[index] = heap[parent];
                index = parent;
            }

            heap[index] = node;
        }

        public HeapNode Pop()
        {
            HeapNode result = heap[0];
            HeapNode last = heap[--count];

            if (count > 0)
            {
                int index = 0;

                while (true)
                {
                    int left = index * 2 + 1;
                    if (left >= count)
                        break;

                    int right = left + 1;
                    int child = left;

                    if (right < count && heap[right].Distance < heap[left].Distance)
                        child = right;

                    if (heap[child].Distance >= last.Distance)
                        break;

                    heap[index] = heap[child];
                    index = child;
                }

                heap[index] = last;
            }

            return result;
        }
    }

    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner();

        int n = scanner.NextInt();
        int m = scanner.NextInt();

        long[] vertexWeights = new long[n];
        for (int i = 0; i < n; i++)
            vertexWeights[i] = scanner.NextLong();

        List<Edge>[] graph = new List<Edge>[n];
        for (int i = 0; i < n; i++)
            graph[i] = new List<Edge>();

        for (int i = 0; i < m; i++)
        {
            int u = scanner.NextInt() - 1;
            int v = scanner.NextInt() - 1;
            long weight = scanner.NextLong();

            graph[u].Add(new Edge(v, weight));
            graph[v].Add(new Edge(u, weight));
        }

        const long INF = long.MaxValue / 4;
        long[] distances = new long[n];

        for (int i = 0; i < n; i++)
            distances[i] = INF;

        distances[0] = vertexWeights[0];

        MinHeap queue = new MinHeap();
        queue.Push(new HeapNode(0, distances[0]));

        while (queue.Count > 0)
        {
            HeapNode current = queue.Pop();
            int vertex = current.Vertex;

            if (current.Distance != distances[vertex])
                continue;

            List<Edge> edges = graph[vertex];
            for (int i = 0; i < edges.Count; i++)
            {
                Edge edge = edges[i];
                long newDistance = current.Distance + edge.Weight + vertexWeights[edge.To];

                if (newDistance < distances[edge.To])
                {
                    distances[edge.To] = newDistance;
                    queue.Push(new HeapNode(edge.To, newDistance));
                }
            }
        }

        StringBuilder output = new StringBuilder();

        for (int i = 1; i < n; i++)
        {
            if (i > 1)
                output.Append(' ');

            output.Append(distances[i]);
        }

        Console.WriteLine(output.ToString());
    }
}
