using System;
using System.Collections.Generic;
using System.Text;

public class Program
{
    private const int Mod = 998244353;

    public static void Main()
    {
        FastScanner scanner = new FastScanner();
        int n = scanner.NextInt();
        long[] a = new long[n];

        for (int i = 0; i < n; i++)
            a[i] = scanner.NextLong();

        int[] answer = new int[n + 1];
        answer[1] = n;

        var dp = new Dictionary<long, int[]>[n];
        for (int i = 0; i < n; i++)
            dp[i] = new Dictionary<long, int[]>();

        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < i; j++)
            {
                long difference = a[i] - a[j];

                int[] current;
                if (!dp[i].TryGetValue(difference, out current))
                {
                    current = new int[n + 1];
                    dp[i][difference] = current;
                }

                current[2]++;
                if (current[2] >= Mod)
                    current[2] -= Mod;

                answer[2]++;
                if (answer[2] >= Mod)
                    answer[2] -= Mod;

                int[] previous;
                if (!dp[j].TryGetValue(difference, out previous))
                    continue;

                for (int length = 2; length < n; length++)
                {
                    if (previous[length] == 0)
                        continue;

                    int nextLength = length + 1;

                    current[nextLength] += previous[length];
                    if (current[nextLength] >= Mod)
                        current[nextLength] -= Mod;

                    answer[nextLength] += previous[length];
                    if (answer[nextLength] >= Mod)
                        answer[nextLength] -= Mod;
                }
            }
        }

        StringBuilder output = new StringBuilder();
        for (int k = 1; k <= n; k++)
        {
            if (k > 1)
                output.Append(' ');
            output.Append(answer[k]);
        }

        Console.WriteLine(output.ToString());
    }

    private sealed class FastScanner
    {
        private readonly byte[] buffer = new byte[1 << 16];
        private int index;
        private int length;

        private int Read()
        {
            if (index >= length)
            {
                length = Console.OpenStandardInput().Read(buffer, 0, buffer.Length);
                index = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[index++];
        }

        public int NextInt()
        {
            return (int)NextLong();
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            bool negative = false;
            if (c == '-')
            {
                negative = true;
                c = Read();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return negative ? -value : value;
        }
    }
