    private static void Search(int position)
    {
        if (position == n)
        {
            answer++;
            return;
        }

        for (int i = 0; i < distinctCount; i++)
        {
            if (remaining[i] == 0)
                continue;

            current[position] = letters[i];
            remaining[i]--;

            bool isPalindrome = false;

            if (position + 1 >= k)
            {
                isPalindrome = true;
                int left = position - k + 1;
                int right = position;

                while (left < right)
                {
                    if (current[left] != current[right])
                    {
                        isPalindrome = false;
                        break;
                    }

                    left++;
                    right--;
                }
            }

            if (!isPalindrome)
                Search(position + 1);

            remaining[i]++;
        }
    }

    private static long Factorial(int value)
    {
        long result = 1;
        for (int i = 2; i <= value; i++)
            result *= i;
        return result;
    }

    public static void Main()
    {
        string[] firstLine = Console.ReadLine().Split();
        n = int.Parse(firstLine[0]);
        k = int.Parse(firstLine[1]);
        string s = Console.ReadLine();

        int[] frequencies = new int[26];
        foreach (char c in s)
            frequencies[c - 'a']++;

        distinctCount = 0;
        int availablePairs = 0;

        for (int i = 0; i < 26; i++)
        {
            if (frequencies[i] > 0)
                distinctCount++;

            availablePairs += frequencies[i] / 2;
        }

        if (availablePairs < k / 2)
        {
            long total = Factorial(n);
            for (int i = 0; i < 26; i++)
                total /= Factorial(frequencies[i]);

            Console.WriteLine(total);
            return;
        }

        letters = new char[distinctCount];
        remaining = new int[distinctCount];
        current = new char[n];

        int index = 0;
        for (int i = 0; i < 26; i++)
        {
            if (frequencies[i] == 0)
                continue;

            letters[index] = (char)('a' + i);
            remaining[index] = frequencies[i];
            index++;
        }

        Search(0);
        Console.WriteLine(answer);
    }
}
