            for (int i = halfLength; i < length; i++)
                result[i] = result[length - 1 - i];

            Console.WriteLine(new string(result));
            return;
        }
    }

    private static long Pow10(int exponent)
    {
        long result = 1;
        for (int i = 0; i < exponent; i++)
            result *= 10;
        return result;
    }
