using System;
using System.IO;
using System.Text;

public class Program
{
    private static int[] parent;
    private static int[] componentSize;
    private static byte[] touchesSea;

    private static int Find(int x)
    {
        while (parent[x] != x)
        {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    private static void Union(int x, int y, ref int submerged)
    {
        int rootX = Find(x);
        int rootY = Find(y);

        if (rootX == rootY)
            return;

        bool seaX = touchesSea[rootX] != 0;
        bool seaY = touchesSea[rootY] != 0;

        if (seaX && !seaY)
            submerged += componentSize[rootY];
        else if (!seaX && seaY)
            submerged += componentSize[rootX];

        if (componentSize[rootX] < componentSize[rootY])
        {
            int temp = rootX;
            rootX = rootY;
            rootY = temp;
        }

        parent[rootY] = rootX;
        componentSize[rootX] += componentSize[rootY];
        touchesSea[rootX] = (byte)((seaX || seaY) ? 1 : 0);
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int h = scanner.NextInt();
        int w = scanner.NextInt();
        int y = scanner.NextInt();
        int total = h * w;

        int[] heads = new int[y + 1];
        for (int i = 0; i <= y; i++)
            heads[i] = -1;

        int[] next = new int[total];
        parent = new int[total];
        componentSize = new int[total];
        touchesSea = new byte[total];

        for (int i = 0; i < total; i++)
            parent[i] = -1;

        for (int index = 0; index < total; index++)
        {
            int elevation = scanner.NextInt();
            if (elevation <= y)
            {
                next[index] = heads[elevation];
                heads[elevation] = index;
            }
        }

        int submerged = 0;
        StringBuilder output = new StringBuilder();

        for (int level = 1; level <= y; level++)
        {
            for (int index = heads[level]; index != -1; index = next[index])
            {
                parent[index] = index;
                componentSize[index] = 1;

                int column = index % w;
                bool boundary =
                    index < w ||
                    index >= total - w ||
                    column == 0 ||
                    column == w - 1;

                if (boundary)
                {
                    touchesSea[index] = 1;
                    submerged++;
                }

                if (index >= w && parent[index - w] != -1)
                    Union(index, index - w, ref submerged);

                if (index + w < total && parent[index + w] != -1)
                    Union(index, index + w, ref submerged);

                if (column > 0 && parent[index - 1] != -1)
                    Union(index, index - 1, ref submerged);

                if (column + 1 < w && parent[index + 1] != -1)
                    Union(index, index + 1, ref submerged);
            }

            output.Append(total - submerged).Append('\n');
        }

        Console.Write(output.ToString());
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value;
        }
    }
}
