using System;
using System.Collections.Generic;

public class Program
{
    private class Candidate
    {
        public long Product;
        public int Left;
        public int Right;
    }

    private static List<Candidate> candidates;
    private static HashSet<long> failed;

    public static void Main()
    {
        string input = Console.In.ReadToEnd().Trim();
        long n = long.Parse(input);

        var representatives = new Dictionary<long, Candidate>();

        for (int x = 2; x <= 999999; x++)
        {
            int reversed = ReverseIfNoZero(x);
            if (reversed < 0)
                continue;

            long product = (long)x * reversed;
            if (product <= n && n % product == 0 && !representatives.ContainsKey(product))
            {
                representatives[product] = new Candidate
                {
                    Product = product,
                    Left = x,
                    Right = reversed
                };
            }
        }

        candidates = new List<Candidate>(representatives.Values);
        candidates.Sort(delegate (Candidate a, Candidate b)
        {
            return a.Product.CompareTo(b.Product);
        });

        failed = new HashSet<long>();
        string answer = Solve(n);

        Console.WriteLine(answer ?? "-1");
    }

    private static string Solve(long value)
    {
        if (IsValidPalindromeNumber(value))
            return value.ToString();

        if (failed.Contains(value))
            return null;

        foreach (Candidate candidate in candidates)
        {
            if (candidate.Product > value)
                break;

            if (value % candidate.Product != 0)
                continue;

            string inner = Solve(value / candidate.Product);
            if (inner != null)
            {
                return candidate.Left.ToString() + "*" + inner + "*" +
                       candidate.Right.ToString();
            }
        }

        failed.Add(value);
        return null;
    }

    private static int ReverseIfNoZero(int value)
    {
        int reversed = 0;
        int current = value;

        while (current > 0)
        {
            int digit = current % 10;
            if (digit == 0)
                return -1;

            reversed = reversed * 10 + digit;
            current /= 10;
        }

        return reversed;
    }

    private static bool IsValidPalindromeNumber(long value)
    {
        string s = value.ToString();
        int left = 0;
        int right = s.Length - 1;

        while (left <= right)
        {
            if (s[left] == '0' || s[right] == '0' || s[left] != s[right])
                return false;

            left++;
            right--;
        }

        return true;
    }
}
