    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            bool negative = false;
            if (c == '-')
            {
                negative = true;
                c = ReadByte();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return negative ? -value : value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    private static int LowerBound(long[] array, long value)
    {
        int left = 0;
        int right = array.Length;

        while (left < right)
        {
            int middle = left + (right - left) / 2;
            if (array[middle] < value)
                left = middle + 1;
            else
                right = middle;
        }

        return left;
    }

    private static int UpperBound(long[] array, long value)
    {
        int left = 0;
        int right = array.Length;

        while (left < right)
        {
            int middle = left + (right - left) / 2;
            if (array[middle] <= value)
                left = middle + 1;
            else
                right = middle;
        }

        return left;
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int q = scanner.NextInt();

        var points = new long[n];
        for (int i = 0; i < n; i++)
            points[i] = scanner.NextLong();

        Array.Sort(points);

        var output = new StringBuilder();

        for (int query = 0; query < q; query++)
        {
            long b = scanner.NextLong();
            int k = scanner.NextInt();

            long low = -1;
            long high = Math.Max(Math.Abs(b - points[0]), Math.Abs(b - points[n - 1]));

            while (high - low > 1)
            {
                long middle = low + (high - low) / 2;

                int leftIndex = LowerBound(points, b - middle);
                int rightIndex = UpperBound(points, b + middle);
                int count = rightIndex - leftIndex;

                if (count >= k)
                    high = middle;
                else
                    low = middle;
            }

            output.AppendLine(high.ToString());
        }

        Console.Write(output.ToString());
    }
}
