public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length, position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int x = scanner.NextInt();
        int y = scanner.NextInt();

        int[] a = new int[n];
        int[] b = new int[n];

        for (int i = 0; i < n; i++)
        {
            a[i] = scanner.NextInt();
            b[i] = scanner.NextInt();
        }

        int capacity, otherCapacity;
        int[] indexedCost, otherCost;

        if (x <= y)
        {
            capacity = x;
            otherCapacity = y;
            indexedCost = a;
            otherCost = b;
        }
        else
        {
            capacity = y;
            otherCapacity = x;
            indexedCost = b;
            otherCost = a;
        }

        int width = capacity + 1;
        int inf = int.MaxValue / 4;
        int[] dp = new int[(n + 1) * width];

        for (int i = 0; i < dp.Length; i++)
            dp[i] = inf;

        dp[0] = 0;
        int maxFeasible = 0;

        for (int i = 0; i < n; i++)
        {
            int cost = indexedCost[i];
            int other = otherCost[i];

            if (cost > capacity)
                continue;

            for (int count = i + 1; count >= 1; count--)
            {
                int sourceBase = (count - 1) * width;
                int destinationBase = count * width;

                for (int sum = capacity - cost; sum >= 0; sum--)
                {
                    int previous = dp[sourceBase + sum];
                    if (previous == inf) continue;

                    int newOther = previous + other;
                    if (newOther > otherCapacity) continue;

                    int destination = destinationBase + sum + cost;
                    if (newOther < dp[destination])
                    {
                        dp[destination] = newOther;
                        if (count > maxFeasible)
                            maxFeasible = count;
                    }
                }
            }
        }

        int answer = Math.Min(n, maxFeasible + 1);
        Console.WriteLine(answer);
    }
}
