        long maximum = 0;

        for (int i = 0; i < n; i++)
        {
            costs[i] = scanner.NextLong();
            total += costs[i];
            if (costs[i] > maximum) maximum = costs[i];
        }

        if (total <= budget)
        {
            Console.WriteLine("infinite");
            return;
        }

        long low = 0;
        long high = maximum;

        while (high - low > 1)
        {
            long mid = low + (high - low) / 2;
            long subsidyTotal = 0;

            for (int i = 0; i < n; i++)
            {
                subsidyTotal += Math.Min(mid, costs[i]);
                if (subsidyTotal > budget) break;
            }

            if (subsidyTotal <= budget)
                low = mid;
            else
                high = mid;
        }

        Console.WriteLine(low);
    }
