                {
                    if (move != previous)
                        next[move] = Math.Max(next[move], dp[previous] + score);
                }
            }

            dp = next;
        }

        Console.WriteLine(Math.Max(dp[0], Math.Max(dp[1], dp[2])));
    }

    private static int MoveToInt(char move)
    {
        if (move == 'R') return 0;
        if (move == 'P') return 1;
        return 2;
    }
}
