            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        const int Bits = 30;
        long[] ones = new long[Bits];
        int prefixXor = 0;
        long prefixCount = 1; // Includes the initial prefix XOR 0.
        long answer = 0;

        for (int i = 0; i < n; i++)
        {
            int value = scanner.NextInt();
            prefixXor ^= value;

            for (int bit = 0; bit < Bits; bit++)
            {
                long weight = 1L << bit;
                if ((prefixXor & (1 << bit)) != 0)
                {
                    answer += (prefixCount - ones[bit]) * weight;
                    ones[bit]++;
                }
                else
                {
                    answer += ones[bit] * weight;
                }
            }

            // Exclude the subarray consisting only of A_i.
            answer -= value;
            prefixCount++;
        }

        Console.WriteLine(answer);
    }
