            B = b;
        }
    }

    private sealed class FunctionComparer : IComparer<LinearFunction>
    {
        public int Compare(LinearFunction x, LinearFunction y)
        {
            long left = x.B * (y.A - 1);
            long right = y.B * (x.A - 1);

            if (left > right) return -1;
            if (left < right) return 1;
            return 0;
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        int k = scanner.NextInt();

        LinearFunction[] functions = new LinearFunction[n];
        for (int i = 0; i < n; i++)
        {
            long a = scanner.NextInt();
            long b = scanner.NextInt();
            functions[i] = new LinearFunction(a, b);
