public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int m = scanner.NextInt();

        ulong[] rows = new ulong[n];

        for (int i = 0; i < m; i++)
        {
            int u = scanner.NextInt() - 1;
            int v = scanner.NextInt() - 1;
            rows[u] |= 1UL << v;
            rows[v] |= 1UL << u;
        }

        int rank = 0;
        int[] pivotColumn = new int[n];
        bool[] isPivot = new bool[n];

        for (int col = 0; col < n; col++)
        {
            int pivot = -1;
            for (int row = rank; row < n; row++)
            {
                if (((rows[row] >> col) & 1UL) != 0)
                {
                    pivot = row;
                    break;
                }
            }

            if (pivot == -1) continue;

            ulong temp = rows[rank];
            rows[rank] = rows[pivot];
            rows[pivot] = temp;

            for (int row = 0; row < n; row++)
            {
                if (row != rank && ((rows[row] >> col) & 1UL) != 0)
                    rows[row] ^= rows[rank];
            }

            pivotColumn[rank] = col;
            isPivot[col] = true;
            rank++;
        }

        ulong[] answer = new ulong[n];
        int basisIndex = 0;

        for (int freeColumn = 0; freeColumn < n; freeColumn++)
        {
            if (isPivot[freeColumn]) continue;

            ulong bit = 1UL << basisIndex;
            answer[freeColumn] |= bit;

            for (int row = 0; row < rank; row++)
            {
                if (((rows[row] >> freeColumn) & 1UL) != 0)
                    answer[pivotColumn[row]] |= bit;
            }

            basisIndex++;
        }

        for (int i = 0; i < n; i++)
        {
            if (answer[i] == 0)
            {
                Console.WriteLine("No");
                return;
            }
        }

        var output = new StringBuilder();
        output.AppendLine("Yes");
        for (int i = 0; i < n; i++)
        {
            if (i > 0) output.Append(' ');
            output.Append(answer[i]);
        }
        output.AppendLine();

        Console.Write(output.ToString());
    }
}
