    private sealed class FastScanner
    {
        private readonly Stream _stream = Console.OpenStandardInput();
        private readonly byte[] _buffer = new byte[1 << 16];
        private int _length;
        private int _position;

        private int ReadByte()
        {
            if (_position >= _length)
            {
                _length = _stream.Read(_buffer, 0, _buffer.Length);
                _position = 0;
                if (_length == 0) return -1;
            }
            return _buffer[_position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int m = scanner.NextInt();

        int[] edgeRemainders = new int[n];
        for (int i = 0; i < n; i++)
            edgeRemainders[i] = scanner.NextInt() % m;

        // prefix[i] is the distance modulo M from area 1 to the
        // corresponding area in an unrolled sequence around the lake.
        int[] prefix = new int[2 * n - 1];
        for (int i = 1; i < prefix.Length; i++)
        {
            prefix[i] = prefix[i - 1] + edgeRemainders[(i - 1) % n];
            if (prefix[i] >= m)
                prefix[i] -= m;
        }

        int[] frequency = new int[m];

        // For start index 0, valid targets are indices 1 through N-1.
        for (int i = 1; i < n; i++)
            frequency[prefix[i]]++;

        long answer = 0;

        for (int start = 0; start < n; start++)
        {
            answer += frequency[prefix[start]];

            if (start + 1 < n)
            {
                frequency[prefix[start + 1]]--;
                frequency[prefix[start + n]]++;
            }
        }

        Console.WriteLine(answer);
    }
