        for (int value = 1; value <= n; value++)
        {
            hash1[value] = Mix((ulong)value + 0x243F6A8885A308D3UL);
            hash2[value] = Mix((ulong)value + 0x13198A2E03707344UL);
        }

        ulong[] prefixA1 = new ulong[n + 1];
        ulong[] prefixA2 = new ulong[n + 1];
        ulong[] prefixB1 = new ulong[n + 1];
        ulong[] prefixB2 = new ulong[n + 1];

        unchecked
        {
            for (int i = 1; i <= n; i++)
            {
                int value = scanner.NextInt();
                prefixA1[i] = prefixA1[i - 1] + hash1[value];
                prefixA2[i] = prefixA2[i - 1] + hash2[value];
            }

            for (int i = 1; i <= n; i++)
            {
                int value = scanner.NextInt();
                prefixB1[i] = prefixB1[i - 1] + hash1[value];
                prefixB2[i] = prefixB2[i - 1] + hash2[value];
            }
        }

        var output = new StringBuilder(q * 4);

        for (int i = 0; i < q; i++)
        {
            int l = scanner.NextInt();
            int r = scanner.NextInt();
            int L = scanner.NextInt();
            int R = scanner.NextInt();

            bool equal = r - l == R - L;

            if (equal)
            {
                unchecked
                {
                    ulong a1 = prefixA1[r] - prefixA1[l - 1];
                    ulong a2 = prefixA2[r] - prefixA2[l - 1];
                    ulong b1 = prefixB1[R] - prefixB1[L - 1];
                    ulong b2 = prefixB2[R] - prefixB2[L - 1];

                    equal = a1 == b1 && a2 == b2;
                }
            }

            output.AppendLine(equal ? "Yes" : "No");
        }

        Console.Write(output.ToString());
    }
