using System;
using System.IO;

public static class Program
{
    private const int Mod = 998244353;
    private const int BitCount = 20;
    private const int Size = 1 << BitCount;

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        int m = scanner.NextInt();
        int k = scanner.NextInt();

        int[] frequency = new int[Size];
        for (int i = 0; i < n; i++)
        {
            frequency[scanner.NextInt()]++;
        }

        IntegerWalshHadamardTransform(frequency);

        int[] transformedPowers = new int[Size];
        for (int x = 0; x < Size; x++)
        {
            transformedPowers[x] = ModPow(x, k);
        }
        ModularWalshHadamardTransform(transformedPowers);

        int[] valuesByOddCount = BuildFilteredSubsetSums(n, m);

        long answer = 0;
        for (int s = 0; s < Size; s++)
        {
            int oddCount = (n - frequency[s]) / 2;
            answer += (long)transformedPowers[s] * valuesByOddCount[oddCount] % Mod;
            if (answer >= Mod)
                answer -= Mod;
        }

        answer = answer * ModPow(Size, Mod - 2) % Mod;
        Console.WriteLine(answer);
    }

    private static int[] BuildFilteredSubsetSums(int n, int m)
    {
        int[] inverses = new int[n + 1];
        inverses[1] = 1;
        for (int i = 2; i <= n; i++)
        {
            inverses[i] = Mod - (int)((long)(Mod / i) * inverses[Mod % i] % Mod);
        }

        // v[r] is the sum of coefficients whose degrees are congruent to r mod m.
        // Initially the polynomial is (1+z)^n.
        int[] v = new int[m];
        int combination = 1;

        for (int j = 0; j <= n; j++)
        {
            int index = j % m;
            int sum = v[index] + combination;
            if (sum >= Mod)
                sum -= Mod;
            v[index] = sum;

            if (j < n)
            {
                combination = (int)((long)combination * (n - j) % Mod);
                combination = (int)((long)combination * inverses[j + 1] % Mod);
            }
        }

        int[] result = new int[n + 1];
        int[] next = new int[m];

        int inverseTwo = (Mod + 1) / 2;
        int inverseM = ModPow(m, Mod - 2);
        int twoPowerN = ModPow(2, n);

        for (int c = 0; c <= n; c++)
        {
            result[c] = v[0];

            if (c == n)
                break;

            // P_c(z) = (1+z)^(n-c) (1-z)^c.
            // The next vector satisfies:
            // (1+z) P_{c+1}(z) = (1-z) P_c(z), modulo z^m-1.
            next[0] = 0;

            for (int r = 1; r < m; r++)
            {
                int difference = v[r] - v[r - 1];
                if (difference < 0)
                    difference += Mod;

                int value = difference - next[r - 1];
                if (value < 0)
                    value += Mod;
                next[r] = value;
            }

            int adjustment;

            if ((m & 1) == 1)
            {
                int differenceZero = v[0] - v[m - 1];
                if (differenceZero < 0)
                    differenceZero += Mod;

                int delta = differenceZero - next[m - 1];
                if (delta < 0)
                    delta += Mod;

                adjustment = (int)((long)delta * inverseTwo % Mod);
            }
            else
            {
                int alternatingSum = 0;
                for (int r = 0; r < m; r++)
                {
                    if ((r & 1) == 0)
                    {
                        alternatingSum += next[r];
                        if (alternatingSum >= Mod)
                            alternatingSum -= Mod;
                    }
                    else
                    {
                        alternatingSum -= next[r];
                        if (alternatingSum < 0)
                            alternatingSum += Mod;
                    }
                }

                int targetAtMinusOne = (c + 1 == n) ? twoPowerN : 0;
                int delta = targetAtMinusOne - alternatingSum;
                if (delta < 0)
                    delta += Mod;

                adjustment = (int)((long)delta * inverseM % Mod);
            }

            for (int r = 0; r < m; r++)
            {
                if ((r & 1) == 0)
                {
                    int value = next[r] + adjustment;
                    if (value >= Mod)
                        value -= Mod;
                    next[r] = value;
                }
                else
                {
                    int value = next[r] - adjustment;
                    if (value < 0)
                        value += Mod;
                    next[r] = value;
                }
            }

            int[] temporary = v;
            v = next;
            next = temporary;
        }

        return result;
    }

    private static void IntegerWalshHadamardTransform(int[] values)
    {
        for (int half = 1; half < values.Length; half <<= 1)
        {
            int block = half << 1;
            for (int start = 0; start < values.Length; start += block)
            {
                for (int j = 0; j < half; j++)
                {
                    int left = values[start + j];
                    int right = values[start + j + half];
                    values[start + j] = left + right;
                    values[start + j + half] = left - right;
                }
            }
        }
    }

    private static void ModularWalshHadamardTransform(int[] values)
    {
        for (int half = 1; half < values.Length; half <<= 1)
        {
            int block = half << 1;
            for (int start = 0; start < values.Length; start += block)
            {
                for (int j = 0; j < half; j++)
                {
                    int left = values[start + j];
                    int right = values[start + j + half];

                    int sum = left + right;
                    if (sum >= Mod)
                        sum -= Mod;

                    int difference = left - right;
                    if (difference < 0)
                        difference += Mod;

                    values[start + j] = sum;
                    values[start + j + half] = difference;
                }
            }
        }
    }

    private static int ModPow(int value, int exponent)
    {
        long result = 1;
        long current = value % Mod;

        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * current % Mod;

            current = current * current % Mod;
            exponent >>= 1;
        }

        return (int)result;
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32);

            int value = 0;
            while (c > 32)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value;
        }

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }
    }
}
