    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int k = scanner.NextInt();

        var graph = new List<int>[n];
        var degree = new int[n];

        for (int i = 0; i < n; i++)
            graph[i] = new List<int>();

        for (int i = 0; i < n - 1; i++)
        {
            int a = scanner.NextInt() - 1;
            int b = scanner.NextInt() - 1;
            graph[a].Add(b);
            graph[b].Add(a);
            degree[a]++;
            degree[b]++;
        }

        var required = new bool[n];
        for (int i = 0; i < k; i++)
            required[scanner.NextInt() - 1] = true;

        var queue = new Queue<int>();
        var removed = new bool[n];

        for (int i = 0; i < n; i++)
        {
            if (!required[i] && degree[i] <= 1)
                queue.Enqueue(i);
        }

        int remaining = n;

        while (queue.Count > 0)
        {
            int vertex = queue.Dequeue();

            if (removed[vertex] || required[vertex] || degree[vertex] > 1)
                continue;

            removed[vertex] = true;
            remaining--;

            foreach (int next in graph[vertex])
            {
                if (removed[next]) continue;

                degree[next]--;
                if (!required[next] && degree[next] <= 1)
                    queue.Enqueue(next);
            }
        }

        Console.WriteLine(remaining);
    }
}
