            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int m = scanner.NextInt();
        long initialDelay = scanner.NextLong();

        int[] a = new int[m];
        int[] b = new int[m];
        long[] s = new long[m];
        long[] t = new long[m];
        int[] departureOrder = new int[m];
        int[] arrivalOrder = new int[m];

        for (int i = 0; i < m; i++)
        {
            a[i] = scanner.NextInt() - 1;
            b[i] = scanner.NextInt() - 1;
            s[i] = scanner.NextLong();
            t[i] = scanner.NextLong();
            departureOrder[i] = i;
            arrivalOrder[i] = i;
        }

        Array.Sort(departureOrder, delegate(int x, int y)
        {
            int cmp = s[x].CompareTo(s[y]);
            return cmp != 0 ? cmp : x.CompareTo(y);
        });

        Array.Sort(arrivalOrder, delegate(int x, int y)
        {
            int cmp = t[x].CompareTo(t[y]);
            return cmp != 0 ? cmp : x.CompareTo(y);
        });

        long[] delay = new long[m];
        long[] bestArrival = new long[n];
        delay[0] = initialDelay;

        int departureIndex = 0;
        int arrivalIndex = 0;

        while (departureIndex < m || arrivalIndex < m)
        {
            if (arrivalIndex < m &&
                (departureIndex >= m ||
                 t[arrivalOrder[arrivalIndex]] <= s[departureOrder[departureIndex]]))
            {
                int train = arrivalOrder[arrivalIndex++];
                long delayedArrival = t[train] + delay[train];
                if (delayedArrival > bestArrival[b[train]])
                    bestArrival[b[train]] = delayedArrival;
            }
            else
            {
                int train = departureOrder[departureIndex++];

                if (train != 0)
                {
                    long required = bestArrival[a[train]] - s[train];
                    delay[train] = required > 0 ? required : 0;
                }
            }
        }

        var output = new StringBuilder();
        for (int i = 1; i < m; i++)
        {
            if (i > 1) output.Append(' ');
            output.Append(delay[i]);
        }

        Console.WriteLine(output.ToString());
    }
