using System;
using System.IO;
using System.Text;
using System.Collections.Generic;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int pointer;

        private int ReadByte()
        {
            if (pointer >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0) return -1;
            }
            return buffer[pointer++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    private sealed class FenwickTree
    {
        private readonly long[] tree;

        public FenwickTree(int size)
        {
            tree = new long[size + 1];
        }

        public void Add(int index, long value)
        {
            for (int i = index; i < tree.Length; i += i & -i)
                tree[i] += value;
        }

        public long Sum(int index)
        {
            long result = 0;
            for (int i = index; i > 0; i -= i & -i)
                result += tree[i];
            return result;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        var a = new long[n + 1];
        var b = new long[n + 1];

        for (int i = 1; i <= n; i++)
            a[i] = scanner.NextLong();

        for (int i = 1; i <= n; i++)
            b[i] = scanner.NextLong();

        var fenwick = new FenwickTree(n);
        var multiplyingPositions = new SortedSet<int>();

        for (int i = 1; i <= n; i++)
        {
            if (b[i] == 1)
                fenwick.Add(i, a[i]);
            else
                multiplyingPositions.Add(i);
        }

        int q = scanner.NextInt();
        var output = new StringBuilder();

        for (int query = 0; query < q; query++)
        {
            int type = scanner.NextInt();
            int first = scanner.NextInt();
            long second = scanner.NextLong();

            if (type == 1)
            {
                int index = first;
                long newA = second;

                if (b[index] == 1)
                    fenwick.Add(index, newA - a[index]);

                a[index] = newA;
            }
            else if (type == 2)
            {
                int index = first;
                long newB = second;

                if (b[index] == 1 && newB != 1)
                {
                    fenwick.Add(index, -a[index]);
                    multiplyingPositions.Add(index);
                }
                else if (b[index] != 1 && newB == 1)
                {
                    multiplyingPositions.Remove(index);
                    fenwick.Add(index, a[index]);
                }

                b[index] = newB;
            }
            else
            {
                int left = first;
                int right = (int)second;

                long value = 0;
                long previousPrefix = fenwick.Sum(left - 1);

                foreach (int index in multiplyingPositions.GetViewBetween(left, right))
                {
                    long currentPrefix = fenwick.Sum(index);
                    value += currentPrefix - previousPrefix;

                    long byAddition = value + a[index];
                    long byMultiplication = value * b[index];
                    value = byAddition > byMultiplication
                        ? byAddition
                        : byMultiplication;

                    previousPrefix = currentPrefix;
                }

                value += fenwick.Sum(right) - previousPrefix;
                output.Append(value).Append('\n');
            }
        }

        Console.Write(output.ToString());
    }
}
