        int n = (int)scanner.NextLong();

        long previous = scanner.NextLong();
        long answer = n;

        if (n >= 2)
        {
            long current = scanner.NextLong();
            long previousDifference = current - previous;
            long runLength = 1;
            previous = current;

            for (int i = 2; i < n; i++)
            {
                current = scanner.NextLong();
                long difference = current - previous;

                if (difference == previousDifference)
                {
                    runLength++;
                }
                else
                {
                    answer += runLength * (runLength + 1) / 2;
                    runLength = 1;
                    previousDifference = difference;
                }

                previous = current;
            }

            answer += runLength * (runLength + 1) / 2;
        }

        Console.WriteLine(answer);
    }
