using System;
using System.IO;
using System.Text;
using System.Collections.Generic;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int index;

        private int ReadByte()
        {
            if (index >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                index = 0;
                if (length == 0) return -1;
            }
            return buffer[index++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    private sealed class HeapNode
    {
        public long Key;
        public int Rank;
        public HeapNode Left;
        public HeapNode Right;

        public HeapNode(long key)
        {
            Key = key;
            Rank = 1;
        }
    }

    private static int Rank(HeapNode node)
    {
        return node == null ? 0 : node.Rank;
    }

    private static HeapNode Meld(HeapNode a, HeapNode b)
    {
        if (a == null) return b;
        if (b == null) return a;

        if (a.Key < b.Key)
        {
            HeapNode temp = a;
            a = b;
            b = temp;
        }

        a.Right = Meld(a.Right, b);

        if (Rank(a.Left) < Rank(a.Right))
        {
            HeapNode temp = a.Left;
            a.Left = a.Right;
            a.Right = temp;
        }

        a.Rank = Rank(a.Right) + 1;
        return a;
    }

    public static void Main()
    {
        FastScanner fs = new FastScanner();
        int n = fs.NextInt();

        int edgeCount = 2 * (n - 1);
        int[] head = new int[n];
        int[] to = new int[edgeCount];
        int[] next = new int[edgeCount];
        long[] weight = new long[edgeCount];

        for (int i = 0; i < n; i++) head[i] = -1;

        int edgeIndex = 0;
        for (int i = 0; i < n - 1; i++)
        {
            int u = fs.NextInt() - 1;
            int v = fs.NextInt() - 1;
            long w = fs.NextLong();

            to[edgeIndex] = v;
            weight[edgeIndex] = w;
            next[edgeIndex] = head[u];
            head[u] = edgeIndex++;

            to[edgeIndex] = u;
            weight[edgeIndex] = w;
            next[edgeIndex] = head[v];
            head[v] = edgeIndex++;
        }

        int[] parent = new int[n];
        long[] parentWeight = new long[n];
        int[] order = new int[n];
        int[] stack = new int[n];

        for (int i = 0; i < n; i++) parent[i] = -2;
        parent[0] = -1;

        int top = 0;
        int orderCount = 0;
        stack[top++] = 0;

        while (top > 0)
        {
            int v = stack[--top];
            order[orderCount++] = v;

            for (int e = head[v]; e != -1; e = next[e])
            {
                int u = to[e];
                if (u == parent[v]) continue;

                parent[u] = v;
                parentWeight[u] = weight[e];
                stack[top++] = u;
            }
        }

        HeapNode[] heaps = new HeapNode[n];
        List<HeapNode> leafNodes = new List<HeapNode>();

        for (int i = n - 1; i >= 0; i--)
        {
            int v = order[i];
            HeapNode heap = null;
            bool hasChild = false;

            for (int e = head[v]; e != -1; e = next[e])
            {
                int u = to[e];
                if (parent[u] == v)
                {
                    hasChild = true;
                    heap = Meld(heap, heaps[u]);
                }
            }

            if (!hasChild)
            {
                heap = new HeapNode(0);
                leafNodes.Add(heap);
            }

            if (v != 0)
            {
                heap.Key += parentWeight[v];
            }

            heaps[v] = heap;
        }

        int leafCount = leafNodes.Count;
        long[] marginalGains = new long[leafCount];

        for (int i = 0; i < leafCount; i++)
        {
            marginalGains[i] = leafNodes[i].Key;
        }

        Array.Sort(marginalGains);

        long coveredLength = 0;
        StringBuilder output = new StringBuilder();

        for (int k = 1; k <= n; k++)
        {
            if (k <= leafCount)
            {
                coveredLength += marginalGains[leafCount - k];
            }

            output.Append(coveredLength * 2);
            output.Append('\n');
        }

        Console.Write(output.ToString());
    }
}
