using System;
using System.IO;

public class Program
{
    private static int H, W;
    private static bool[] alive;
    private static Fenwick rowOrder;
    private static Fenwick columnOrder;
    private static long remaining;

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        H = scanner.NextInt();
        W = scanner.NextInt();
        int q = scanner.NextInt();

        int cells = H * W;
        alive = new bool[cells];
        for (int i = 0; i < cells; i++)
            alive[i] = true;

        rowOrder = new Fenwick(cells);
        columnOrder = new Fenwick(cells);
        remaining = cells;

        int[] targets = new int[4];

        for (int query = 0; query < q; query++)
        {
            int r = scanner.NextInt() - 1;
            int c = scanner.NextInt() - 1;
            int cell = r * W + c;

            if (alive[cell])
            {
                Destroy(cell);
                continue;
            }

            int count = 0;

            int rowPosition = cell + 1;
            int rowStart = r * W + 1;
            int rowEnd = (r + 1) * W;

            int left = rowOrder.FindLast(rowStart, rowPosition - 1);
            if (left != -1)
                targets[count++] = left - 1;

            int right = rowOrder.FindFirst(rowPosition + 1, rowEnd);
            if (right != -1)
                targets[count++] = right - 1;

            int columnPosition = c * H + r + 1;
            int columnStart = c * H + 1;
            int columnEnd = (c + 1) * H;

            int up = columnOrder.FindLast(columnStart, columnPosition - 1);
            if (up != -1)
                targets[count++] = ColumnPositionToCell(up);

            int down = columnOrder.FindFirst(columnPosition + 1, columnEnd);
            if (down != -1)
                targets[count++] = ColumnPositionToCell(down);

            for (int i = 0; i < count; i++)
                Destroy(targets[i]);
        }

        Console.WriteLine(remaining);
    }

    private static int ColumnPositionToCell(int position)
    {
        int zeroBased = position - 1;
        int c = zeroBased / H;
        int r = zeroBased % H;
        return r * W + c;
    }

    private static void Destroy(int cell)
    {
        if (!alive[cell])
            return;

        alive[cell] = false;
        remaining--;

        int r = cell / W;
        int c = cell % W;

        rowOrder.Add(cell + 1, -1);
        columnOrder.Add(c * H + r + 1, -1);
    }

    private sealed class Fenwick
    {
        private readonly int n;
        private readonly int[] tree;
        private readonly int highestBit;

        public Fenwick(int size)
        {
            n = size;
            tree = new int[n + 1];

            // Initializes the Fenwick tree for an array containing only ones.
            for (int i = 1; i <= n; i++)
                tree[i] = i & -i;

            int bit = 1;
            while ((bit << 1) <= n)
                bit <<= 1;
            highestBit = bit;
        }

        public void Add(int index, int value)
        {
            for (int i = index; i <= n; i += i & -i)
                tree[i] += value;
        }

        public int Sum(int index)
        {
            int result = 0;
            for (int i = index; i > 0; i -= i & -i)
                result += tree[i];
            return result;
        }

        public int FindFirst(int left, int right)
        {
            if (left > right)
                return -1;

            int before = Sum(left - 1);
            if (Sum(right) == before)
                return -1;

            return LowerBound(before + 1);
        }

        public int FindLast(int left, int right)
        {
            if (left > right)
                return -1;

            int totalToRight = Sum(right);
            if (totalToRight == Sum(left - 1))
                return -1;

            return LowerBound(totalToRight);
        }

        private int LowerBound(int target)
        {
            int index = 0;

            for (int bit = highestBit; bit > 0; bit >>= 1)
            {
                int next = index + bit;
                if (next <= n && tree[next] < target)
                {
                    index = next;
                    target -= tree[next];
                }
            }

            return index + 1;
        }
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value;
        }
    }
}
