using System;
using System.IO;

public static class Program
{
    private static int n;
    private static int k;
    private static int[] doubled;
    private static int[] delta;
    private static int[] power;
    private static int[] temp;
    private static int[] offset;

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        n = scanner.NextInt();
        k = scanner.NextInt();

        doubled = new int[2 * n];
        long total = 0;

        for (int i = 0; i < n; i++)
        {
            int value = scanner.NextInt();
            doubled[i] = value;
            doubled[i + n] = value;
            total += value;
        }

        delta = new int[n];
        power = new int[n];
        temp = new int[n];
        offset = new int[n];

        long low = 0;
        long high = total / k + 1;

        while (high - low > 1)
        {
            long middle = (low + high) / 2;
            if (CountUsableCuts(middle) > 0)
                low = middle;
            else
                high = middle;
        }

        int usableCuts = CountUsableCuts(low);
        int neverCut = n - usableCuts;

        Console.WriteLine(low + " " + neverCut);
    }

    private static int CountUsableCuts(long minimumMass)
    {
        BuildNextDistances(minimumMass);

        Array.Copy(delta, power, n);
        Array.Clear(offset, 0, n);

        int exponent = k;
        int cap = n + 1;

        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
            {
                for (int i = 0; i < n; i++)
                {
                    int current = offset[i];
                    if (current > n)
                        continue;

                    int index = i + current;
                    if (index >= n)
                        index -= n;

                    int next = current + power[index];
                    offset[i] = next > n ? cap : next;
                }
            }

            exponent >>= 1;
            if (exponent == 0)
                break;

            for (int i = 0; i < n; i++)
            {
                int first = power[i];
                if (first > n)
                {
                    temp[i] = cap;
                    continue;
                }

                int index = i + first;
                if (index >= n)
                    index -= n;

                int combined = first + power[index];
                temp[i] = combined > n ? cap : combined;
            }

            int[] swap = power;
            power = temp;
            temp = swap;
        }

        int count = 0;
        for (int i = 0; i < n; i++)
        {
            if (offset[i] <= n)
                count++;
        }

        return count;
    }

    private static void BuildNextDistances(long minimumMass)
