using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    const long Mod = 998244353;

    static long N;
    static int M;
    static int sqrtN;

    static long[] values;
    static long[] primeCounts;
    static long[] primeCharacterSums;
    static int[] smallId;
    static int[] largeId;

    static int[] primes;
    static long[] allowedPrimePrefix;
    static long[] primePowerWeight;
    static long mMod;

    struct Result
    {
        public long Total;
        public long NonGood;

        public Result(long total, long nonGood)
        {
            Total = total;
            NonGood = nonGood;
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());
        N = scanner.NextLong();
        M = (int)scanner.NextLong();
        mMod = M % Mod;

        sqrtN = (int)Math.Sqrt((double)N);
        while ((long)(sqrtN + 1) * (sqrtN + 1) <= N) sqrtN++;
        while ((long)sqrtN * sqrtN > N) sqrtN--;

        BuildPrimes();
        BuildPrimeCountingTables();
        BuildAllowedPrimePrefix();
        BuildPrimePowerWeights();

        Result result = Solve(N, 0);
        long answer = result.Total - result.NonGood;
        if (answer < 0) answer += Mod;

        Console.WriteLine(answer);
    }

    static void BuildPrimes()
    {
        bool[] composite = new bool[sqrtN + 1];
        List<int> list = new List<int>();

        for (int i = 2; i <= sqrtN; i++)
        {
            if (composite[i]) continue;
            list.Add(i);

            if ((long)i * i <= sqrtN)
            {
                for (int j = i * i; j <= sqrtN; j += i)
                    composite[j] = true;
            }
        }

        primes = list.ToArray();
    }

    static void BuildPrimeCountingTables()
    {
        List<long> valueList = new List<long>();
        smallId = new int[sqrtN + 2];
        largeId = new int[sqrtN + 2];

        long left = 1;
        while (left <= N)
        {
            long v = N / left;
            int index = valueList.Count;
            valueList.Add(v);

            if (v <= sqrtN)
                smallId[(int)v] = index;
            else
                largeId[(int)(N / v)] = index;

            left = N / v + 1;
        }

        values = valueList.ToArray();
        primeCounts = new long[values.Length];
        primeCharacterSums = new long[values.Length];

        for (int i = 0; i < values.Length; i++)
        {
            long v = values[i];
            primeCounts[i] = v - 1;

            // Sum of the non-principal character modulo 3 over [2, v].
            primeCharacterSums[i] = (v % 3 == 1) ? 0 : -1;
        }

        for (int pi = 0; pi < primes.Length; pi++)
        {
            int p = primes[pi];
            long pSquared = (long)p * p;

            int prefixId = GetId(p - 1);
            long primesBefore = primeCounts[prefixId];
            long characterBefore = primeCharacterSums[prefixId];

            int characterOfP;
            if (p == 3)
                characterOfP = 0;
            else if (p % 3 == 1)
                characterOfP = 1;
            else
                characterOfP = -1;

            for (int i = 0; i < values.Length && values[i] >= pSquared; i++)
            {
                long divided = values[i] / p;
                int dividedId = GetId(divided);

                primeCounts[i] -= primeCounts[dividedId] - primesBefore;
                primeCharacterSums[i] -=
                    (long)characterOfP *
                    (primeCharacterSums[dividedId] - characterBefore);
            }
        }
    }

    static void BuildAllowedPrimePrefix()
    {
        allowedPrimePrefix = new long[primes.Length + 1];

        for (int i = 0; i < primes.Length; i++)
        {
            int p = primes[i];
            allowedPrimePrefix[i + 1] = allowedPrimePrefix[i];

            if (p == 3 || p % 3 == 1)
                allowedPrimePrefix[i + 1]++;
        }
    }

    static void BuildPrimePowerWeights()
    {
        const int maxExponent = 63;
        primePowerWeight = new long[maxExponent + 1];
        long[] inverse = new long[maxExponent + 1];

        inverse[1] = 1;
        for (int i = 2; i <= maxExponent; i++)
        {
            inverse[i] = Mod -
                (Mod / i) * inverse[(int)(Mod % i)] % Mod;
        }

        primePowerWeight[0] = 1;
        for (int e = 1; e <= maxExponent; e++)
        {
            long factor = (M + (long)e - 1) % Mod;
            primePowerWeight[e] =
                primePowerWeight[e - 1] * factor % Mod * inverse[e] % Mod;
        }
    }

    static int GetId(long x)
    {
        if (x <= sqrtN)
            return smallId[(int)x];

        return largeId[(int)(N / x)];
    }

    static long GetPrimeCount(long x)
    {
        return primeCounts[GetId(x)];
    }

    static long GetAllowedPrimeCount(long x)
    {
        int id = GetId(x);
        long count = primeCounts[id];
        long characterSum = primeCharacterSums[id];
        long containsThree = x >= 3 ? 1 : 0;

        return (count + characterSum + containsThree) / 2;
    }

    static long GetNonGoodPrimePowerWeight(int p, int exponent)
    {
        if (p == 3)
            return primePowerWeight[exponent];

        if (p % 3 == 1)
        {
            return exponent % 3 == 2
                ? 0
                : primePowerWeight[exponent];
        }

        return exponent % 2 == 1
            ? 0
            : primePowerWeight[exponent];
    }

    static Result Solve(long x, int startPrimeIndex)
    {
        long primeCount = GetPrimeCount(x);
        long totalPrimeTerms = primeCount - startPrimeIndex;

        long allowedCount = GetAllowedPrimeCount(x);
        long allowedPrimeTerms =
            allowedCount - allowedPrimePrefix[startPrimeIndex];

        long total = (totalPrimeTerms % Mod) * mMod % Mod;
        long nonGood = (allowedPrimeTerms % Mod) * mMod % Mod;

        for (int i = startPrimeIndex; i < primes.Length; i++)
        {
            int p = primes[i];
            if ((long)p * p > x)
                break;

            long power = p;
            int exponent = 1;

            while (power <= x / p)
            {
                long quotient = x / power;
                Result child = new Result(0, 0);

                if (GetPrimeCount(quotient) > i + 1)
                    child = Solve(quotient, i + 1);

                long currentWeight = primePowerWeight[exponent];
                long nextWeight = primePowerWeight[exponent + 1];

                total += currentWeight * child.Total % Mod;
                if (total >= Mod) total -= Mod;
                total += nextWeight;
                if (total >= Mod) total -= Mod;

                long currentNonGoodWeight =
                    GetNonGoodPrimePowerWeight(p, exponent);
                long nextNonGoodWeight =
                    GetNonGoodPrimePowerWeight(p, exponent + 1);

                nonGood += currentNonGoodWeight * child.NonGood % Mod;
                if (nonGood >= Mod) nonGood -= Mod;
                nonGood += nextNonGoodWeight;
                if (nonGood >= Mod) nonGood -= Mod;

                power *= p;
                exponent++;
            }
        }

        return new Result(total, nonGood);
    }

    sealed class FastScanner
    {
        readonly Stream stream;
        readonly byte[] buffer = new byte[1 << 16];
        int length;
        int pointer;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        int Read()
        {
            if (pointer >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0) return -1;
            }

            return buffer[pointer++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c >= 0);

            long value = 0;
            while (c > 32)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value;
        }
    }
}
