public class Program
{
    private static int n;
    private static bool[,] g;
    private static bool[,] h;
    private static long[,] cost;
    private static int[] permutation;
    private static bool[] used;
    private static long answer = long.MaxValue;

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        n = scanner.NextInt();

        g = new bool[n, n];
        h = new bool[n, n];
        cost = new long[n, n];

        int mg = scanner.NextInt();
        for (int i = 0; i < mg; i++)
        {
            int u = scanner.NextInt() - 1;
            int v = scanner.NextInt() - 1;
            g[u, v] = g[v, u] = true;
        }

        int mh = scanner.NextInt();
        for (int i = 0; i < mh; i++)
        {
            int a = scanner.NextInt() - 1;
            int b = scanner.NextInt() - 1;
            h[a, b] = h[b, a] = true;
        }

        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                cost[i, j] = cost[j, i] = scanner.NextLong();
            }
        }

        permutation = new int[n];
        used = new bool[n];

        Search(0, 0L);

        Console.WriteLine(answer);
    }

    private static void Search(int depth, long currentCost)
    {
        if (currentCost >= answer)
            return;

        if (depth == n)
        {
            answer = currentCost;
            return;
        }

        for (int vertex = 0; vertex < n; vertex++)
        {
            if (used[vertex])
                continue;

            long addedCost = 0;

            for (int previous = 0; previous < depth; previous++)
            {
                int mappedPrevious = permutation[previous];

                if (g[previous, depth] != h[mappedPrevious, vertex])
                    addedCost += cost[mappedPrevious, vertex];
            }

            used[vertex] = true;
            permutation[depth] = vertex;
            Search(depth + 1, currentCost + addedCost);
            used[vertex] = false;
        }
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            return (int)NextLong();
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            bool negative = false;
            if (c == '-')
            {
                negative = true;
                c = Read();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return negative ? -value : value;
        }
    }
