using System;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int pointer;

        private int Read()
        {
            if (pointer >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0) return -1;
            }
            return buffer[pointer++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value * sign;
        }
    }

    private sealed class SegmentTree
    {
        private readonly int n;
        private readonly long[] sum;
        private readonly long[] max;
        private readonly long[] lazy;
        private readonly bool[] hasLazy;

        public SegmentTree(long[] values)
        {
            n = values.Length - 1;
            int size = 4 * n + 5;
            sum = new long[size];
            max = new long[size];
            lazy = new long[size];
            hasLazy = new bool[size];
            Build(1, 1, n, values);
        }

        private void Build(int node, int left, int right, long[] values)
        {
            if (left == right)
            {
                sum[node] = max[node] = values[left];
                return;
            }

            int mid = (left + right) >> 1;
            Build(node << 1, left, mid, values);
            Build(node << 1 | 1, mid + 1, right, values);
            Pull(node);
        }

        private void Pull(int node)
        {
            sum[node] = sum[node << 1] + sum[node << 1 | 1];
            max[node] = Math.Max(max[node << 1], max[node << 1 | 1]);
        }

        private void Apply(int node, int left, int right, long value)
        {
            sum[node] = value * (right - left + 1L);
            max[node] = value;
            lazy[node] = value;
            hasLazy[node] = true;
        }

        private void Push(int node, int left, int right)
        {
            if (!hasLazy[node] || left == right) return;

            int mid = (left + right) >> 1;
            Apply(node << 1, left, mid, lazy[node]);
            Apply(node << 1 | 1, mid + 1, right, lazy[node]);
            hasLazy[node] = false;
        }

        public void Assign(int queryLeft, int queryRight, long value)
        {
            Assign(1, 1, n, queryLeft, queryRight, value);
        }

        private void Assign(int node, int left, int right, int queryLeft, int queryRight, long value)
        {
            if (queryLeft <= left && right <= queryRight)
            {
                Apply(node, left, right, value);
                return;
            }

            Push(node, left, right);
            int mid = (left + right) >> 1;

            if (queryLeft <= mid)
                Assign(node << 1, left, mid, queryLeft, queryRight, value);
            if (queryRight > mid)
                Assign(node << 1 | 1, mid + 1, right, queryLeft, queryRight, value);

            Pull(node);
        }

        public long QuerySum(int queryLeft, int queryRight)
        {
            return QuerySum(1, 1, n, queryLeft, queryRight);
        }

        private long QuerySum(int node, int left, int right, int queryLeft, int queryRight)
        {
            if (queryLeft <= left && right <= queryRight)
                return sum[node];

            Push(node, left, right);
            int mid = (left + right) >> 1;
            long result = 0;

            if (queryLeft <= mid)
                result += QuerySum(node << 1, left, mid, queryLeft, queryRight);
            if (queryRight > mid)
                result += QuerySum(node << 1 | 1, mid + 1, right, queryLeft, queryRight);

            return result;
        }

        public long GetValue(int index)
        {
            return QuerySum(index, index);
        }

        public int FindFirstGreaterOrEqual(long value)
        {
            if (max[1] < value) return n + 1;
            return FindFirstGreaterOrEqual(1, 1, n, value);
        }

        private int FindFirstGreaterOrEqual(int node, int left, int right, long value)
        {
            if (left == right) return left;

            Push(node, left, right);
            int mid = (left + right) >> 1;

            if (max[node << 1] >= value)
                return FindFirstGreaterOrEqual(node << 1, left, mid, value);

            return FindFirstGreaterOrEqual(node << 1 | 1, mid + 1, right, value);
        }

        public int FindFirstGreater(long value)
        {
            if (max[1] <= value) return n + 1;
            return FindFirstGreater(1, 1, n, value);
        }

        private int FindFirstGreater(int node, int left, int right, long value)
        {
            if (left == right) return left;

            Push(node, left, right);
            int mid = (left + right) >> 1;

            if (max[node << 1] > value)
                return FindFirstGreater(node << 1, left, mid, value);

            return FindFirstGreater(node << 1 | 1, mid + 1, right, value);
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        var transformed = new long[n + 1];

        for (int i = 1; i <= n; i++)
        {
            long x = scanner.NextInt();
            transformed[i] = x - i;
        }

        var tree = new SegmentTree(transformed);
        int q = scanner.NextInt();
        long answer = 0;

        for (int query = 0; query < q; query++)
        {
            int person = scanner.NextInt();
            long goal = scanner.NextInt();
            long target = goal - person;
            long current = tree.GetValue(person);

            if (current < target)
            {
                int firstAtLeast = tree.FindFirstGreaterOrEqual(target);
                int right = firstAtLeast - 1;

                long oldSum = tree.QuerySum(person, right);
                answer += target * (right - person + 1L) - oldSum;
                tree.Assign(person, right, target);
            }
            else if (current > target)
            {
                int left = tree.FindFirstGreater(target);

                long oldSum = tree.QuerySum(left, person);
                answer += oldSum - target * (person - left + 1L);
                tree.Assign(left, person, target);
            }
        }

        Console.WriteLine(answer);
    }
}
