            b = nextA;

            long nextU = u - t * v;
            u = v;
            v = nextU;
        }

        u %= mod;
        if (u < 0) u += mod;
        return u;
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        int[] p = new int[n];
        int[] a = new int[n];

        for (int i = 0; i < n; i++)
            p[i] = scanner.NextInt() - 1;

        for (int i = 0; i < n; i++)
            a[i] = scanner.NextInt();

        int[] spf = new int[n + 1];
        for (int i = 2; i <= n; i++)
        {
            if (spf[i] != 0) continue;

            spf[i] = i;
            if ((long)i * i <= n)
            {
                for (int j = i * i; j <= n; j += i)
                {
                    if (spf[j] == 0)
                        spf[j] = i;
                }
            }
        }

        bool[] visited = new bool[n];
        int[] cycle = new int[n];
        int[] answer = new int[n];

        // For each prime, stores the largest prime power currently included
        // in the accumulated LCM, and the chosen exponent modulo that power.
        int[] currentPower = new int[n + 1];
        int[] currentResidue = new int[n + 1];

        for (int start = 0; start < n; start++)
        {
            if (visited[start]) continue;

            int cycleLength = 0;
            int node = start;
            do
            {
                cycle[cycleLength++] = node;
                visited[node] = true;
                node = p[node];
            } while (node != start);

            // Reconstruct the current exponent modulo gcd(LCM, cycleLength).
            long residue = 0;
            long modulus = 1;
            int value = cycleLength;

            while (value > 1)
            {
                int prime = spf[value];
                int power = 1;

                while (value % prime == 0)
                {
                    value /= prime;
                    power *= prime;
                }

                int commonPower = Math.Min(power, currentPower[prime]);
                if (commonPower <= 1) continue;

                long target = currentResidue[prime] % commonPower;
                long difference = (target - residue % commonPower) % commonPower;
                if (difference < 0) difference += commonPower;

                long inverse = ModInverse(modulus % commonPower, commonPower);
                long multiplier = difference * inverse % commonPower;

                residue += modulus * multiplier;
                modulus *= commonPower;
            }

            int bestShift = -1;
            int bestValue = int.MaxValue;

            for (long shift = residue; shift < cycleLength; shift += modulus)
            {
                int candidate = a[cycle[(int)shift]];
                if (candidate < bestValue)
                {
                    bestValue = candidate;
                    bestShift = (int)shift;
                }
            }

            for (int i = 0; i < cycleLength; i++)
            {
                answer[cycle[i]] = a[cycle[(i + bestShift) % cycleLength]];
            }

            // Add the new congruence k ≡ bestShift (mod cycleLength).
            value = cycleLength;
            while (value > 1)
            {
                int prime = spf[value];
                int power = 1;

                while (value % prime == 0)
                {
                    value /= prime;
                    power *= prime;
                }

                if (power > currentPower[prime])
                {
                    currentPower[prime] = power;
                    currentResidue[prime] = bestShift % power;
                }
            }
        }

        var output = new StringBuilder();
        for (int i = 0; i < n; i++)
        {
            if (i > 0) output.Append(' ');
            output.Append(answer[i]);
        }

        Console.WriteLine(output.ToString());
    }
}
