public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public string Next()
        {
            var sb = new StringBuilder();
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            while (c > 32 && c != -1)
            {
                sb.Append((char)c);
                c = ReadByte();
            }

            return sb.ToString();
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value;
        }
    }

    private static bool IsABC(char[] s, int start)
    {
        return start >= 0 &&
               start + 2 < s.Length &&
               s[start] == 'A' &&
               s[start + 1] == 'B' &&
               s[start + 2] == 'C';
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int q = scanner.NextInt();
        char[] s = scanner.Next().ToCharArray();

        int count = 0;
        for (int i = 0; i + 2 < n; i++)
        {
            if (IsABC(s, i)) count++;
        }

        var output = new StringBuilder();

        for (int query = 0; query < q; query++)
        {
            int index = scanner.NextInt() - 1;
            char replacement = scanner.Next()[0];

            for (int start = index - 2; start <= index; start++)
            {
                if (IsABC(s, start)) count--;
            }

            s[index] = replacement;

            for (int start = index - 2; start <= index; start++)
            {
                if (IsABC(s, start)) count++;
            }

            output.AppendLine(count.ToString());
        }

        Console.Write(output.ToString());
    }
}
