public class Program
{
    private const long Mod = 998244353;

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        int m = scanner.NextInt();
        int k = scanner.NextInt();

        int[] x = new int[m];
        int[] y = new int[m];

        for (int i = 0; i < m; i++)
        {
            x[i] = scanner.NextInt() - 1;
            y[i] = scanner.NextInt() - 1;
        }

        // A path following only cycle edges preserves
        // (current vertex position - current time) modulo N.
        long[] phaseCount = new long[n];
        phaseCount[0] = 1;

        long[] eventWays = new long[m];
        long answer = 1;

        for (int time = 1; time <= k; time++)
        {
            int previousTimeMod = (time - 1) % n;

            // All transitions at this time must use the state before
            // any extra edge at this same time is processed.
            for (int i = 0; i < m; i++)
            {
                int phase = x[i] - previousTimeMod;
                if (phase < 0)
                    phase += n;

                eventWays[i] = phaseCount[phase];
            }

            int timeMod = time % n;

            for (int i = 0; i < m; i++)
            {
                long ways = eventWays[i];
                if (ways == 0)
                    continue;

                int newPhase = y[i] - timeMod;
                if (newPhase < 0)
                    newPhase += n;

                phaseCount[newPhase] += ways;
                if (phaseCount[newPhase] >= Mod)
                    phaseCount[newPhase] -= Mod;

                answer += ways;
                if (answer >= Mod)
                    answer -= Mod;
            }
        }

        Console.WriteLine(answer);
    }

