using System;
using System.IO;
using System.Text;
using System.Collections.Generic;

public class Program
{
    private struct Line
    {
        public long A;
        public long B;
        public long D;

        public Line(long a, long b, long d)
        {
            A = a;
            B = b;
            D = d;
        }
    }

    private static int CompareLines(Line x, Line y)
    {
        long left = x.A * y.B;
        long right = y.A * x.B;

        if (left < right) return -1;
        if (left > right) return 1;

        left = x.D * y.B;
        right = y.D * x.B;

        if (left < right) return -1;
        if (left > right) return 1;
        return 0;
    }

    private static bool SameSlope(Line x, Line y)
    {
        return x.A * y.B == y.A * x.B;
    }

    private static bool HasLowerIntercept(Line x, Line y)
    {
        return x.D * y.B < y.D * x.B;
    }

    private static long CeilDiv(long value, long divisor)
    {
        if (value >= 0)
            return value / divisor + (value % divisor == 0 ? 0 : 1);

        return value / divisor;
    }

    private static long FirstNotHigher(Line newer, Line older)
    {
        long numerator = newer.D * older.B - older.D * newer.B;
        long denominator = newer.A * older.B - older.A * newer.B;
        return CeilDiv(numerator, denominator);
    }

    private static long FloorSum(long n, long m, long a, long b)
    {
        long answer = 0;

        while (true)
        {
            if (a >= m)
            {
                long quotient = a / m;
                answer += ((n - 1) * n / 2) * quotient;
                a %= m;
            }

            if (b >= m)
            {
                answer += n * (b / m);
                b %= m;
            }

            long yMax = a * n + b;
            if (yMax < m)
                break;

            n = yMax / m;
            b = yMax % m;

            long temp = m;
            m = a;
            a = temp;
        }

        return answer;
    }

    private static long SumLine(Line line, long left, long right)
    {
        long count = right - left + 1;
        long baseValue = line.D - line.A * right;
        return FloorSum(count, line.B, line.A, baseValue);
    }

    private static long Solve(List<Line> lines, long maxX)
    {
        lines.Sort(CompareLines);

        var unique = new List<Line>(lines.Count);

        for (int i = 0; i < lines.Count; i++)
        {
            Line current = lines[i];

            if (unique.Count == 0 || !SameSlope(unique[unique.Count - 1], current))
            {
                unique.Add(current);
            }
            else if (HasLowerIntercept(current, unique[unique.Count - 1]))
            {
                unique[unique.Count - 1] = current;
            }
        }

        var hull = new List<Line>(unique.Count);
        var starts = new List<long>(unique.Count);
        const long NegativeInfinity = -4000000000000000000L;

        for (int i = 0; i < unique.Count; i++)
        {
            Line current = unique[i];
            long start = NegativeInfinity;

            while (hull.Count > 0)
            {
                start = FirstNotHigher(current, hull[hull.Count - 1]);

                if (start <= starts[starts.Count - 1])
                {
                    hull.RemoveAt(hull.Count - 1);
                    starts.RemoveAt(starts.Count - 1);
                }
                else
                {
                    break;
                }
            }

            if (hull.Count == 0)
                start = NegativeInfinity;

            hull.Add(current);
            starts.Add(start);
        }

        long answer = 0;

        for (int i = 0; i < hull.Count; i++)
        {
            long left = starts[i] < 1 ? 1 : starts[i];
            long right = maxX;

            if (i + 1 < hull.Count)
            {
                long segmentEnd = starts[i + 1] - 1;
                if (segmentEnd < right)
                    right = segmentEnd;
            }

            if (left <= right)
                answer += SumLine(hull[i], left, right);
        }

        return answer;
    }

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());
        int testCases = (int)scanner.NextLong();
        var output = new StringBuilder();

        for (int test = 0; test < testCases; test++)
        {
            int n = (int)scanner.NextLong();
            var lines = new List<Line>(n);

            bool possible = true;
            long maxX = long.MaxValue;

            for (int i = 0; i < n; i++)
            {
                long a = scanner.NextLong();
                long b = scanner.NextLong();
                long c = scanner.NextLong();
                long d = c - 1;

                lines.Add(new Line(a, b, d));

                long remaining = d - b;
                if (remaining < a)
                {
                    possible = false;
                }
                else
                {
                    long bound = remaining / a;
                    if (bound < maxX)
                        maxX = bound;
                }
            }

            long answer = possible ? Solve(lines, maxX) : 0;
            output.Append(answer).Append('\n');
        }

        Console.Write(output.ToString());
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value * sign;
        }
    }
}
