using System;
using System.IO;
using System.Text;

public class Program
{
    private struct Candidate : IComparable<Candidate>
    {
        public long Votes;
        public int Index;

        public int CompareTo(Candidate other)
        {
            int cmp = Votes.CompareTo(other.Votes);
            return cmp != 0 ? cmp : Index.CompareTo(other.Index);
        }
    }

    private static long[] votes;
    private static long[] prefix;
    private static int[] equalEnd;

    private static void GetCountAndSum(int left, int right, int excluded,
                                       out long count, out long sum)
    {
        if (right <= left)
        {
            count = 0;
            sum = 0;
            return;
        }

        count = right - left;
        sum = prefix[right] - prefix[left];

        if (excluded >= left && excluded < right)
        {
            count--;
            sum -= votes[excluded];
        }
    }

    private static long RequiredAtBreakpoint(
        int position, long candidateVotes, int left, int excluded)
    {
        long value = votes[position];
        int right = equalEnd[position];

        long count, sum;
        GetCountAndSum(left, right, excluded, out count, out sum);

        long additionalForCandidate = value - candidateVotes;
        long additionalForOthers = count * (value + 1) - sum;
        return additionalForCandidate + additionalForOthers;
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int n = (int)scanner.NextLong();
        int m = (int)scanner.NextLong();
        long k = scanner.NextLong();

        Candidate[] candidates = new Candidate[n];
        long counted = 0;

        for (int i = 0; i < n; i++)
        {
            long value = scanner.NextLong();
            counted += value;
            candidates[i] = new Candidate { Votes = value, Index = i };
        }

        long remaining = k - counted;
        long[] answer = new long[n];

        if (m == n)
        {
            StringBuilder allZero = new StringBuilder();
            for (int i = 0; i < n; i++)
            {
                if (i > 0) allZero.Append(' ');
                allZero.Append('0');
            }
            Console.WriteLine(allZero.ToString());
            return;
        }

        Array.Sort(candidates);

        votes = new long[n];
        prefix = new long[n + 1];
        equalEnd = new int[n];

        for (int i = 0; i < n; i++)
        {
            votes[i] = candidates[i].Votes;
            prefix[i + 1] = prefix[i] + votes[i];
        }

        equalEnd[n - 1] = n;
        for (int i = n - 2; i >= 0; i--)
        {
            equalEnd[i] = votes[i] == votes[i + 1]
                ? equalEnd[i + 1]
                : i + 1;
        }

        int topStart = n - m;

        for (int p = 0; p < n; p++)
        {
            long current = votes[p];

            int left;
            int excluded;

            if (p < topStart)
            {
                left = topStart;
                excluded = -1;
            }
            else
            {
                left = topStart - 1;
                excluded = p;
            }

            int initiallyActiveEnd = equalEnd[p];
            long initialCount, initialSum;
            GetCountAndSum(left, initiallyActiveEnd, excluded,
                           out initialCount, out initialSum);

            long initialRequired = initialCount * (current + 1) - initialSum;

            if (initialRequired > remaining)
            {
                answer[candidates[p].Index] = 0;
                continue;
            }

            int start = Math.Max(left, equalEnd[p]);

            int low = start - 1;
            int high = n;

            while (high - low > 1)
            {
                int mid = low + (high - low) / 2;
                long required = RequiredAtBreakpoint(
                    mid, current, left, excluded);

                if (required > remaining)
                    high = mid;
                else
                    low = mid;
            }

            int activeEnd = high == n ? n : high;
            long activeCount, activeSum;
            GetCountAndSum(left, activeEnd, excluded,
                           out activeCount, out activeSum);

            long numerator =
                remaining - activeCount * (current + 1) + activeSum;
            long maximumUnsafe = numerator / (activeCount + 1);

            if (high < n)
            {
                long beforeBreakpoint = votes[high] - current - 1;
                if (maximumUnsafe > beforeBreakpoint)
                    maximumUnsafe = beforeBreakpoint;
            }

            long needed = maximumUnsafe + 1;
            answer[candidates[p].Index] =
                needed <= remaining ? needed : -1;
        }

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < n; i++)
        {
            if (i > 0) output.Append(' ');
            output.Append(answer[i]);
        }

        Console.WriteLine(output.ToString());
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }

            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            bool negative = false;
            if (c == '-')
            {
                negative = true;
                c = ReadByte();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return negative ? -value : value;
        }
    }
}
