using System;
using System.IO;

public class Program
{
    private const long NegativeInfinity = long.MinValue / 4;

    private struct Line
    {
        public long Slope;
        public long Intercept;

        public Line(long slope, long intercept)
        {
            Slope = slope;
            Intercept = intercept;
        }
    }

    private static long Evaluate(Line line, long x)
    {
        return line.Slope * x + line.Intercept;
    }

    private static bool IsUnnecessary(Line first, Line second, Line third)
    {
        return (first.Intercept - second.Intercept) * (third.Slope - second.Slope)
             >= (second.Intercept - third.Intercept) * (second.Slope - first.Slope);
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int n = (int)scanner.NextLong();
        int capacity = (int)scanner.NextLong();

        long[] dp = new long[capacity + 1];
        long[] next = new long[capacity + 1];
        Line[] hull = new Line[capacity + 1];

        for (int weight = 0; weight <= capacity; weight++)
            dp[weight] = NegativeInfinity;
        dp[0] = 0;

        for (int itemType = 0; itemType < n; itemType++)
        {
            int w = (int)scanner.NextLong();
            long v = scanner.NextLong();

            for (int weight = 0; weight <= capacity; weight++)
                next[weight] = NegativeInfinity;

            for (int remainder = 0; remainder < w && remainder <= capacity; remainder++)
            {
                int head = 0;
                int tail = 0;
                int maxIndex = (capacity - remainder) / w;

                for (int j = 0; j <= maxIndex; j++)
                {
                    int weight = remainder + j * w;

                    if (dp[weight] != NegativeInfinity)
                    {
                        Line newLine = new Line(
                            2L * j,
                            dp[weight] - (long)j * j - (long)j * v
                        );

                        while (tail - head >= 2 &&
                               IsUnnecessary(hull[tail - 2], hull[tail - 1], newLine))
                        {
                            tail--;
                        }

                        hull[tail++] = newLine;
                    }

                    if (tail > head)
                    {
                        while (tail - head >= 2 &&
                               Evaluate(hull[head + 1], j) >= Evaluate(hull[head], j))
                        {
                            head++;
                        }

                        next[weight] = (long)j * v - (long)j * j
                                     + Evaluate(hull[head], j);
                    }
                }
            }

            long[] temp = dp;
            dp = next;
            next = temp;
        }

        long answer = 0;
        for (int weight = 0; weight <= capacity; weight++)
        {
            if (dp[weight] > answer)
                answer = dp[weight];
        }

        Console.WriteLine(answer);
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
