using System;
using System.Collections.Generic;
using System.Text;
using System.IO;

public class Program
{
    private struct Point
    {
        public int X;
        public int Y;

        public Point(int x, int y)
        {
            X = x;
            Y = y;
        }
    }

    private struct Node
    {
        public bool IsP;
        public int Index;

        public Node(bool isP, int index)
        {
            IsP = isP;
            Index = index;
        }
    }

    private static Point[] pPoints;
    private static Point[] qPoints;
    private static int[] answer;
    private static bool possible = true;

    private static Point GetPoint(Node node)
    {
        return node.IsP ? pPoints[node.Index] : qPoints[node.Index];
    }

    private static void Solve(List<int> pIndices, List<int> qIndices)
    {
        int count = pIndices.Count;
        if (!possible || count == 0)
            return;

        Node anchor = new Node(true, pIndices[0]);
        Point anchorPoint = pPoints[pIndices[0]];

        for (int i = 0; i < pIndices.Count; i++)
        {
            Point point = pPoints[pIndices[i]];
            if (point.X < anchorPoint.X ||
                (point.X == anchorPoint.X && point.Y < anchorPoint.Y))
            {
                anchor = new Node(true, pIndices[i]);
                anchorPoint = point;
            }
        }

        for (int i = 0; i < qIndices.Count; i++)
        {
            Point point = qPoints[qIndices[i]];
            if (point.X < anchorPoint.X ||
                (point.X == anchorPoint.X && point.Y < anchorPoint.Y))
            {
                anchor = new Node(false, qIndices[i]);
                anchorPoint = point;
            }
        }

        List<Node> others = new List<Node>(2 * count - 1);

        for (int i = 0; i < pIndices.Count; i++)
        {
            if (!(anchor.IsP && anchor.Index == pIndices[i]))
                others.Add(new Node(true, pIndices[i]));
        }

        for (int i = 0; i < qIndices.Count; i++)
        {
            if (!(!anchor.IsP && anchor.Index == qIndices[i]))
                others.Add(new Node(false, qIndices[i]));
        }

        others.Sort(delegate(Node u, Node v)
        {
            Point pu = GetPoint(u);
            Point pv = GetPoint(v);

            long ux = pu.X - anchorPoint.X;
            long uy = pu.Y - anchorPoint.Y;
            long vx = pv.X - anchorPoint.X;
            long vy = pv.Y - anchorPoint.Y;

            long cross = ux * vy - uy * vx;
            if (cross > 0) return -1;
            if (cross < 0) return 1;
            return 0;
        });

        int balance = 0;
        int matchedPosition = -1;

        for (int i = 0; i < others.Count; i++)
        {
            Node node = others[i];

            if (node.IsP != anchor.IsP && balance == 0)
            {
                matchedPosition = i;
                break;
            }

            balance += node.IsP == anchor.IsP ? 1 : -1;
        }

        if (matchedPosition == -1)
        {
            possible = false;
            return;
        }

        Node matched = others[matchedPosition];

        if (anchor.IsP)
            answer[anchor.Index] = matched.Index;
        else
            answer[matched.Index] = anchor.Index;

        List<int> leftP = new List<int>();
        List<int> leftQ = new List<int>();
        List<int> rightP = new List<int>();
        List<int> rightQ = new List<int>();

        for (int i = 0; i < matchedPosition; i++)
        {
            Node node = others[i];
            if (node.IsP)
                leftP.Add(node.Index);
            else
                leftQ.Add(node.Index);
        }

        for (int i = matchedPosition + 1; i < others.Count; i++)
        {
            Node node = others[i];
            if (node.IsP)
                rightP.Add(node.Index);
            else
                rightQ.Add(node.Index);
        }

        if (leftP.Count != leftQ.Count || rightP.Count != rightQ.Count)
        {
            possible = false;
            return;
        }

        Solve(leftP, leftQ);
        Solve(rightP, rightQ);
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        pPoints = new Point[n];
        qPoints = new Point[n];
        answer = new int[n];

        for (int i = 0; i < n; i++)
            pPoints[i] = new Point(scanner.NextInt(), scanner.NextInt());

        for (int i = 0; i < n; i++)
            qPoints[i] = new Point(scanner.NextInt(), scanner.NextInt());

        List<int> pIndices = new List<int>(n);
        List<int> qIndices = new List<int>(n);

        for (int i = 0; i < n; i++)
        {
            pIndices.Add(i);
            qIndices.Add(i);
        }

        Solve(pIndices, qIndices);

        if (!possible)
        {
            Console.WriteLine("-1");
            return;
        }

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < n; i++)
        {
            if (i > 0)
                output.Append(' ');
            output.Append(answer[i] + 1);
        }

        Console.WriteLine(output.ToString());
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value * sign;
        }
    }
