using System;
using System.Globalization;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int index;

        private int ReadByte()
        {
            if (index >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                index = 0;
                if (length == 0) return -1;
            }
            return buffer[index++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value * sign;
        }
    }

    private static double Distance(double x1, double y1, double x2, double y2)
    {
        double dx = x1 - x2;
        double dy = y1 - y2;
        return Math.Sqrt(dx * dx + dy * dy);
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int s = scanner.NextInt();
        int t = scanner.NextInt();

        double[] ax = new double[n];
        double[] ay = new double[n];
        double[] bx = new double[n];
        double[] by = new double[n];

        double printingTime = 0.0;

        for (int i = 0; i < n; i++)
        {
            ax[i] = scanner.NextInt();
            ay[i] = scanner.NextInt();
            bx[i] = scanner.NextInt();
            by[i] = scanner.NextInt();

            printingTime += Distance(ax[i], ay[i], bx[i], by[i]) / t;
        }

        int totalMasks = 1 << n;
        double[,,] dp = new double[totalMasks, n, 2];

        for (int mask = 0; mask < totalMasks; mask++)
        {
            for (int i = 0; i < n; i++)
            {
                dp[mask, i, 0] = double.PositiveInfinity;
                dp[mask, i, 1] = double.PositiveInfinity;
            }
        }

        for (int i = 0; i < n; i++)
        {
            // Orientation 0: A -> B, ending at B.
            dp[1 << i, i, 0] = Distance(0, 0, ax[i], ay[i]) / s;

            // Orientation 1: B -> A, ending at A.
            dp[1 << i, i, 1] = Distance(0, 0, bx[i], by[i]) / s;
        }

        for (int mask = 1; mask < totalMasks; mask++)
        {
            for (int last = 0; last < n; last++)
            {
                if ((mask & (1 << last)) == 0) continue;

                for (int orientation = 0; orientation < 2; orientation++)
                {
                    double current = dp[mask, last, orientation];
                    if (double.IsPositiveInfinity(current)) continue;

                    double endX = orientation == 0 ? bx[last] : ax[last];
                    double endY = orientation == 0 ? by[last] : ay[last];

                    for (int next = 0; next < n; next++)
                    {
                        if ((mask & (1 << next)) != 0) continue;

                        int nextMask = mask | (1 << next);

                        double costToA = Distance(endX, endY, ax[next], ay[next]) / s;
                        double candidateA = current + costToA;
                        if (candidateA < dp[nextMask, next, 0])
                            dp[nextMask, next, 0] = candidateA;

                        double costToB = Distance(endX, endY, bx[next], by[next]) / s;
                        double candidateB = current + costToB;
                        if (candidateB < dp[nextMask, next, 1])
                            dp[nextMask, next, 1] = candidateB;
                    }
                }
            }
        }

        int fullMask = totalMasks - 1;
        double minimumMovementTime = double.PositiveInfinity;

        for (int last = 0; last < n; last++)
        {
            minimumMovementTime = Math.Min(minimumMovementTime, dp[fullMask, last, 0]);
            minimumMovementTime = Math.Min(minimumMovementTime, dp[fullMask, last, 1]);
        }

        double answer = printingTime + minimumMovementTime;
        Console.WriteLine(answer.ToString("G17", CultureInfo.InvariantCulture));
    }
}
