    private static int n;
    private static long budget;
    private static long[] a, p, b, q;

    private static long MinimumCost(int index, long required)
    {
        long best = long.MaxValue;

        for (int countS = 0; countS <= b[index]; countS++)
        {
            long remaining = required - a[index] * countS;
            long countT = remaining <= 0 ? 0 : (remaining + b[index] - 1) / b[index];
            long cost = p[index] * countS + q[index] * countT;
            if (cost < best) best = cost;
        }

        for (int countT = 0; countT <= a[index]; countT++)
        {
            long remaining = required - b[index] * countT;
            long countS = remaining <= 0 ? 0 : (remaining + a[index] - 1) / a[index];
            long cost = q[index] * countT + p[index] * countS;
            if (cost < best) best = cost;
        }

        return best;
    }

    private static bool CanAchieve(long capacity)
    {
        long totalCost = 0;

        for (int i = 0; i < n; i++)
        {
            totalCost += MinimumCost(i, capacity);
            if (totalCost > budget) return false;
        }

        return true;
    }

