using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    private static Dictionary<long, long> Prune(Dictionary<long, long> states)
    {
        var days = new List<long>(states.Keys);
        days.Sort();

        var result = new Dictionary<long, long>();
        long bestCost = long.MaxValue;

        foreach (long day in days)
        {
            long cost = states[day];
            if (cost < bestCost)
            {
                result.Add(day, cost);
                bestCost = cost;
            }
        }

        return result;
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int k = scanner.NextInt();
        long x = scanner.NextLong();

        var t = new long[n];
        var prefix = new long[n + 1];

        for (int i = 0; i < n; i++)
        {
            t[i] = scanner.NextLong();
            prefix[i + 1] = prefix[i] + t[i];
        }

        var dp = new Dictionary<long, long>[n + 1];
        for (int i = 0; i <= n; i++)
            dp[i] = new Dictionary<long, long>();

        dp[0][0] = 0;

        for (int shipped = 0; shipped < n; shipped++)
        {
            dp[shipped] = Prune(dp[shipped]);

            foreach (KeyValuePair<long, long> state in dp[shipped])
            {
                long previousDay = state.Key;
                long currentCost = state.Value;
                int maxBatchSize = Math.Min(k, n - shipped);

                for (int batchSize = 1; batchSize <= maxBatchSize; batchSize++)
                {
                    int next = shipped + batchSize;
                    long day;

                    if (shipped == 0)
                    {
                        day = t[next - 1];
                    }
                    else
                    {
                        long earliestAfterPrevious = previousDay + x;
                        day = Math.Max(t[next - 1], earliestAfterPrevious);
                    }

                    long releaseSum = prefix[next] - prefix[shipped];
                    long newCost = currentCost + batchSize * day - releaseSum;

                    long oldCost;
                    if (!dp[next].TryGetValue(day, out oldCost) || newCost < oldCost)
                        dp[next][day] = newCost;
                }
            }
        }

        long answer = long.MaxValue;
        foreach (long cost in dp[n].Values)
            if (cost < answer)
                answer = cost;

        Console.WriteLine(answer);
    }
