public class Program
{
    static List<int>[] graph;
    static int[] pairLeft;
    static int[] pairRight;
    static int[] distance;
    static int shortest;
    const int INF = 1 << 29;

    static bool Bfs()
    {
        int n = graph.Length;
        int[] queue = new int[n];
        int head = 0, tail = 0;
        shortest = INF;

        for (int i = 0; i < n; i++)
        {
            if (pairLeft[i] == -1)
            {
                distance[i] = 0;
                queue[tail++] = i;
            }
            else
            {
                distance[i] = INF;
            }
        }

        while (head < tail)
        {
            int u = queue[head++];
            if (distance[u] >= shortest) continue;

            foreach (int v in graph[u])
            {
                int next = pairRight[v];
                if (next == -1)
                {
                    shortest = distance[u] + 1;
                }
                else if (distance[next] == INF)
                {
                    distance[next] = distance[u] + 1;
                    queue[tail++] = next;
                }
            }
        }

        return shortest != INF;
    }

    static bool Dfs(int u)
    {
        foreach (int v in graph[u])
        {
            int next = pairRight[v];

            if (next == -1)
            {
                if (distance[u] + 1 == shortest)
                {
                    pairLeft[u] = v;
                    pairRight[v] = u;
                    return true;
                }
            }
            else if (distance[next] == distance[u] + 1 && Dfs(next))
            {
                pairLeft[u] = v;
                pairRight[v] = u;
                return true;
            }
        }

        distance[u] = INF;
        return false;
    }

    static int MaximumMatching()
    {
        int n = graph.Length;
        pairLeft = new int[n];
        pairRight = new int[n];
        distance = new int[n];

        for (int i = 0; i < n; i++)
        {
            pairLeft[i] = -1;
            pairRight[i] = -1;
        }

        int matching = 0;

        while (Bfs())
        {
            for (int i = 0; i < n; i++)
            {
                if (pairLeft[i] == -1 && Dfs(i))
                    matching++;
            }
        }

        return matching;
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());
        int n = scanner.NextInt();

        int[] from = new int[n];
        int[] to = new int[n];
        bool[,] reachable = new bool[26, 26];

        for (int i = 0; i < 26; i++)
            reachable[i, i] = true;

        for (int i = 0; i < n; i++)
        {
            string s = scanner.Next();
            from[i] = s[0] - 'A';
            to[i] = s[1] - 'A';
            reachable[from[i], to[i]] = true;
        }

        for (int k = 0; k < 26; k++)
            for (int i = 0; i < 26; i++)
                if (reachable[i, k])
                    for (int j = 0; j < 26; j++)
                        if (reachable[k, j])
                            reachable[i, j] = true;

        int[] component = new int[26];
        for (int i = 0; i < 26; i++) component[i] = -1;

        int componentCount = 0;
        for (int i = 0; i < 26; i++)
        {
            if (component[i] != -1) continue;

            for (int j = 0; j < 26; j++)
            {
                if (component[j] == -1 &&
                    reachable[i, j] && reachable[j, i])
                {
                    component[j] = componentCount;
                }
            }

            componentCount++;
        }

        bool[,] componentReach = new bool[componentCount, componentCount];
        for (int i = 0; i < componentCount; i++)
            componentReach[i, i] = true;

        bool[] hasInternalEdge = new bool[componentCount];

        for (int i = 0; i < n; i++)
        {
            int a = component[from[i]];
            int b = component[to[i]];

            if (a == b)
                hasInternalEdge[a] = true;
            else
                componentReach[a, b] = true;
        }

        for (int k = 0; k < componentCount; k++)
            for (int i = 0; i < componentCount; i++)
                if (componentReach[i, k])
                    for (int j = 0; j < componentCount; j++)
                        if (componentReach[k, j])
                            componentReach[i, j] = true;

        List<int> taskStart = new List<int>();
        List<int> taskEnd = new List<int>();

        for (int c = 0; c < componentCount; c++)
        {
            if (hasInternalEdge[c])
            {
                taskStart.Add(c);
                taskEnd.Add(c);
            }
        }

        for (int i = 0; i < n; i++)
        {
            int a = component[from[i]];
            int b = component[to[i]];

            if (a != b)
            {
                taskStart.Add(a);
                taskEnd.Add(b);
            }
        }

        int taskCount = taskStart.Count;
        graph = new List<int>[taskCount];

        for (int i = 0; i < taskCount; i++)
        {
            graph[i] = new List<int>();

            for (int j = 0; j < taskCount; j++)
            {
                if (i != j && componentReach[taskEnd[i], taskStart[j]])
                    graph[i].Add(j);
            }
        }

        int matching = MaximumMatching();
        Console.WriteLine(taskCount - matching);
    }

