                c = Read();
            } while (c <= 32 && c != -1);

            char[] chars = new char[16];
            int count = 0;

            while (c > 32 && c != -1)
            {
                if (count == chars.Length)
                    Array.Resize(ref chars, chars.Length * 2);

                chars[count++] = (char)c;
                c = Read();
            }

            return new string(chars, 0, count);
        }

