using System;
using System.IO;
using System.Text;

public class Program
{
    public static void Main()
    {
        using (var reader = new StreamReader(Console.OpenStandardInput(), Encoding.ASCII, false, 1 << 16))
        using (var writer = new StreamWriter(Console.OpenStandardOutput(), Encoding.ASCII, 1 << 16))
        {
            int n = int.Parse(reader.ReadLine());
            string[] grid = new string[n];

            for (int i = 0; i < n; i++)
                grid[i] = reader.ReadLine();

            char[] outputRow = new char[n];

            for (int r = 0; r < n; r++)
            {
                for (int c = 0; c < n; c++)
                {
                    int depth = Math.Min(Math.Min(r, c), Math.Min(n - 1 - r, n - 1 - c)) + 1;
                    int rotations = depth & 3;

                    int sourceRow, sourceCol;

                    if (rotations == 0)
                    {
                        sourceRow = r;
                        sourceCol = c;
                    }
                    else if (rotations == 1)
                    {
                        sourceRow = n - 1 - c;
                        sourceCol = r;
                    }
                    else if (rotations == 2)
                    {
                        sourceRow = n - 1 - r;
                        sourceCol = n - 1 - c;
                    }
                    else
                    {
                        sourceRow = c;
                        sourceCol = n - 1 - r;
                    }

                    outputRow[c] = grid[sourceRow][sourceCol];
                }

                writer.WriteLine(outputRow);
            }
        }
    }
}
