            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        int[] teams = new int[n];
        int[] strengths = new int[n];
        int total = 0;

        for (int i = 0; i < n; i++)
        {
            teams[i] = scanner.NextInt();
            strengths[i] = scanner.NextInt();
            total += strengths[i];
        }

        if (total % 3 != 0)
        {
            Console.WriteLine(-1);
            return;
        }

        int target = total / 3;
        int width = target + 1;
        int stateCount = width * width;

        int[] dp = new int[stateCount];
        int[] next = new int[stateCount];

        for (int i = 0; i < stateCount; i++)
            dp[i] = -1;
        dp[0] = 0;

        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < stateCount; j++)
                next[j] = -1;

            int strength = strengths[i];
            int originalTeam = teams[i];

            for (int team1Strength = 0; team1Strength <= target; team1Strength++)
            {
                int row = team1Strength * width;

                for (int team2Strength = 0; team2Strength <= target; team2Strength++)
                {
                    int index = row + team2Strength;
                    int stayed = dp[index];
                    if (stayed < 0) continue;

                    int value = stayed + (originalTeam == 3 ? 1 : 0);
                    if (value > next[index])
                        next[index] = value;

                    if (team1Strength + strength <= target)
                    {
                        int newIndex = index + strength * width;
                        value = stayed + (originalTeam == 1 ? 1 : 0);
                        if (value > next[newIndex])
                            next[newIndex] = value;
                    }

                    if (team2Strength + strength <= target)
                    {
                        int newIndex = index + strength;
                        value = stayed + (originalTeam == 2 ? 1 : 0);
                        if (value > next[newIndex])
                            next[newIndex] = value;
                    }
                }
            }

            int[] temp = dp;
            dp = next;
            next = temp;
        }

        int maximumStayed = dp[target * width + target];
        Console.WriteLine(maximumStayed < 0 ? -1 : n - maximumStayed);
    }
}
