using System;
using System.IO;
using System.Text;

public class Program
{
    const long INF = 1L << 60;

    struct Edge
    {
        public int A;
        public int B;
        public long C;
    }

    struct Query
    {
        public int Type;
        public int X;
        public int Y;
    }

    public static void Main()
    {
        FastScanner fs = new FastScanner(Console.OpenStandardInput());

        int n = fs.NextInt();
        int m = fs.NextInt();
        int q = fs.NextInt();

        Edge[] edges = new Edge[m];
        for (int i = 0; i < m; i++)
        {
            edges[i].A = fs.NextInt() - 1;
            edges[i].B = fs.NextInt() - 1;
            edges[i].C = fs.NextLong();
        }

        Query[] queries = new Query[q];
        bool[] finallyClosed = new bool[m];

        for (int i = 0; i < q; i++)
        {
            int type = fs.NextInt();
            queries[i].Type = type;

            if (type == 1)
            {
                int road = fs.NextInt() - 1;
                queries[i].X = road;
                finallyClosed[road] = true;
            }
            else
            {
                queries[i].X = fs.NextInt() - 1;
                queries[i].Y = fs.NextInt() - 1;
            }
        }

        long[,] dist = new long[n, n];
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
                dist[i, j] = i == j ? 0 : INF;
        }

        for (int i = 0; i < m; i++)
        {
            if (!finallyClosed[i])
            {
                Edge e = edges[i];
                dist[e.A, e.B] = e.C;
                dist[e.B, e.A] = e.C;
            }
        }

        for (int k = 0; k < n; k++)
        {
            for (int i = 0; i < n; i++)
            {
                long dik = dist[i, k];
                if (dik == INF) continue;

                for (int j = 0; j < n; j++)
                {
                    long candidate = dik + dist[k, j];
                    if (candidate < dist[i, j])
                        dist[i, j] = candidate;
                }
            }
        }

        long[] answers = new long[q];
        long[] toA = new long[n];
        long[] toB = new long[n];

        for (int qi = q - 1; qi >= 0; qi--)
        {
            Query query = queries[qi];

            if (query.Type == 2)
            {
                answers[qi] = dist[query.X, query.Y];
            }
            else
            {
                Edge e = edges[query.X];
                int a = e.A;
                int b = e.B;
                long c = e.C;

                for (int i = 0; i < n; i++)
                {
                    toA[i] = dist[i, a];
                    toB[i] = dist[i, b];
                }

                for (int i = 0; i < n; i++)
                {
                    for (int j = i; j < n; j++)
                    {
                        long best = dist[i, j];

                        long candidate1 = toA[i] + c + toB[j];
                        if (candidate1 < best)
                            best = candidate1;

                        long candidate2 = toB[i] + c + toA[j];
                        if (candidate2 < best)
                            best = candidate2;

                        dist[i, j] = best;
                        dist[j, i] = best;
                    }
                }
            }
        }

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < q; i++)
        {
            if (queries[i].Type == 2)
            {
                if (answers[i] == INF)
                    output.Append("-1\n");
                else
                    output.Append(answers[i]).Append('\n');
            }
        }

        Console.Write(output.ToString());
    }

