using System;
using System.IO;
using System.Text;

public class Program
{
    const long INF = long.MaxValue / 4;

    static int N, M;
    static int[] head, to, next, edgeId;
    static long[] cost;

    public static void Main()
    {
        FastScanner fs = new FastScanner(Console.OpenStandardInput());

        N = fs.NextInt();
        M = fs.NextInt();

        int[] a = new int[M];
        int[] b = new int[M];
        cost = new long[M];

        head = new int[N];
        for (int i = 0; i < N; i++) head[i] = -1;

        to = new int[2 * M];
        next = new int[2 * M];
        edgeId = new int[2 * M];

        int edgeCount = 0;
        for (int i = 0; i < M; i++)
        {
            a[i] = fs.NextInt() - 1;
            b[i] = fs.NextInt() - 1;
            cost[i] = fs.NextLong();

            AddEdge(a[i], b[i], i, ref edgeCount);
            AddEdge(b[i], a[i], i, ref edgeCount);
        }

        long[] distFromStart = Dijkstra(0);
        long[] distFromGoal = Dijkstra(N - 1);
        long shortest = distFromStart[N - 1];

        int[] shortestHead = new int[N];
        for (int i = 0; i < N; i++) shortestHead[i] = -1;

        int[] shortestTo = new int[2 * M];
        int[] shortestNext = new int[2 * M];
        int[] shortestEdgeId = new int[2 * M];
        int shortestEdgeCount = 0;

        for (int i = 0; i < M; i++)
        {
            bool isShortestEdge =
                distFromStart[a[i]] + cost[i] + distFromGoal[b[i]] == shortest ||
                distFromStart[b[i]] + cost[i] + distFromGoal[a[i]] == shortest;

            if (isShortestEdge)
            {
                AddShortestEdge(a[i], b[i], i, shortestHead, shortestTo,
                                shortestNext, shortestEdgeId, ref shortestEdgeCount);
                AddShortestEdge(b[i], a[i], i, shortestHead, shortestTo,
                                shortestNext, shortestEdgeId, ref shortestEdgeCount);
            }
        }

        bool[] isBridge = FindBridges(
            shortestHead, shortestTo, shortestNext, shortestEdgeId
        );

        StringBuilder output = new StringBuilder(M * 4);
        for (int i = 0; i < M; i++)
            output.Append(isBridge[i] ? "Yes\n" : "No\n");

        Console.Write(output.ToString());
    }

    static void AddEdge(int from, int destination, int id, ref int count)
    {
        to[count] = destination;
        edgeId[count] = id;
        next[count] = head[from];
        head[from] = count++;
    }

    static void AddShortestEdge(
        int from,
        int destination,
        int id,
        int[] graphHead,
        int[] graphTo,
        int[] graphNext,
        int[] graphEdgeId,
        ref int count)
    {
        graphTo[count] = destination;
        graphEdgeId[count] = id;
        graphNext[count] = graphHead[from];
        graphHead[from] = count++;
    }

    static long[] Dijkstra(int start)
    {
        long[] dist = new long[N];
        for (int i = 0; i < N; i++) dist[i] = INF;
        dist[start] = 0;

        MinHeap heap = new MinHeap();
        heap.Push(start, 0);

        int vertex;
        long currentDistance;

        while (heap.Count > 0)
        {
            heap.Pop(out vertex, out currentDistance);
            if (currentDistance != dist[vertex]) continue;

            for (int e = head[vertex]; e != -1; e = next[e])
            {
                int destination = to[e];
                long newDistance = currentDistance + cost[edgeId[e]];

                if (newDistance < dist[destination])
                {
                    dist[destination] = newDistance;
                    heap.Push(destination, newDistance);
                }
            }
        }

        return dist;
    }

    static bool[] FindBridges(
        int[] graphHead,
        int[] graphTo,
        int[] graphNext,
        int[] graphEdgeId)
    {
        int[] discovery = new int[N];
        int[] low = new int[N];
        int[] parent = new int[N];
        int[] parentEdge = new int[N];
        int[] iterator = new int[N];
        int[] stack = new int[N];
        bool[] bridges = new bool[M];

        for (int i = 0; i < N; i++)
        {
            parent[i] = -1;
            parentEdge[i] = -1;
        }

        int timer = 0;

        for (int root = 0; root < N; root++)
        {
            if (discovery[root] != 0) continue;

            int stackSize = 0;
            discovery[root] = low[root] = ++timer;
            iterator[root] = graphHead[root];
            stack[stackSize++] = root;

            while (stackSize > 0)
            {
                int v = stack[stackSize - 1];
                int adjacencyIndex = iterator[v];

                if (adjacencyIndex == -1)
                {
                    stackSize--;

                    if (parentEdge[v] != -1)
                    {
                        int p = parent[v];

                        if (low[v] > discovery[p])
                            bridges[parentEdge[v]] = true;

                        if (low[v] < low[p])
                            low[p] = low[v];
                    }

                    continue;
                }

                iterator[v] = graphNext[adjacencyIndex];

                int id = graphEdgeId[adjacencyIndex];
                if (id == parentEdge[v]) continue;

                int u = graphTo[adjacencyIndex];

                if (discovery[u] == 0)
                {
                    parent[u] = v;
                    parentEdge[u] = id;
                    discovery[u] = low[u] = ++timer;
                    iterator[u] = graphHead[u];
                    stack[stackSize++] = u;
                }
                else
                {
                    if (discovery[u] < low[v])
                        low[v] = discovery[u];
                }
            }
        }

        return bridges;
    }

    sealed class MinHeap
    {
        private int[] vertices = new int[16];
        private long[] distances = new long[16];

        public int Count { get; private set; }

        public void Push(int vertex, long distance)
        {
            if (Count == vertices.Length)
            {
                Array.Resize(ref vertices, vertices.Length * 2);
                Array.Resize(ref distances, distances.Length * 2);
            }

            int index = Count++;
            while (index > 0)
            {
                int parent = (index - 1) >> 1;
                if (distances[parent] <= distance) break;

                vertices[index] = vertices[parent];
                distances[index] = distances[parent];
                index = parent;
            }

            vertices[index] = vertex;
            distances[index] = distance;
        }

        public void Pop(out int vertex, out long distance)
        {
            vertex = vertices[0];
            distance = distances[0];

            Count--;
            if (Count == 0) return;

            int lastVertex = vertices[Count];
            long lastDistance = distances[Count];
            int index = 0;

            while (true)
            {
                int left = index * 2 + 1;
                if (left >= Count) break;

                int right = left + 1;
                int child = left;

                if (right < Count && distances[right] < distances[left])
                    child = right;

                if (distances[child] >= lastDistance) break;

                vertices[index] = vertices[child];
                distances[index] = distances[child];
                index = child;
            }

            vertices[index] = lastVertex;
            distances[index] = lastDistance;
        }
    }

    sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32);

            int value = 0;
            while (c > 32)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value;
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32);

            long value = 0;
            while (c > 32)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value;
        }
    }
