public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int m = scanner.NextInt();

        var graph = new List<int>[n];
        for (int i = 0; i < n; i++)
            graph[i] = new List<int>();

        var incomingToOne = new List<int>();

        for (int i = 0; i < m; i++)
        {
            int a = scanner.NextInt() - 1;
            int b = scanner.NextInt() - 1;
            graph[a].Add(b);

            if (b == 0)
                incomingToOne.Add(a);
        }

        int[] distance = new int[n];
        Array.Fill(distance, -1);

        int[] queue = new int[n];
        int head = 0;
        int tail = 0;

        distance[0] = 0;
        queue[tail++] = 0;

        while (head < tail)
        {
            int current = queue[head++];

            foreach (int next in graph[current])
            {
                if (distance[next] != -1)
                    continue;

                distance[next] = distance[current] + 1;
                queue[tail++] = next;
            }
        }

        int answer = int.MaxValue;

        foreach (int vertex in incomingToOne)
        {
            if (distance[vertex] != -1)
                answer = Math.Min(answer, distance[vertex] + 1);
        }

        Console.WriteLine(answer == int.MaxValue ? -1 : answer);
    }
}
