using System;
using System.IO;

public class Program
{
    private const long INF = 1L << 60;

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        int q = scanner.NextInt();

        long[] dp = new long[n];
        long[] next = new long[n];

        for (int i = 0; i < n; i++)
            dp[i] = INF;

        // Initially, the left hand is fixed at part 1,
        // and the right hand is at part 2.
        char previousHand = 'L';
        int fixedPosition = 0;
        dp[1] = 0;

        for (int query = 0; query < q; query++)
        {
            char hand = scanner.NextChar();
            int target = scanner.NextInt() - 1;

            for (int i = 0; i < n; i++)
                next[i] = INF;

            for (int otherPosition = 0; otherPosition < n; otherPosition++)
            {
                if (dp[otherPosition] == INF)
                    continue;

                int movingPosition;
                int blockingPosition;

                if (hand == previousHand)
                {
                    movingPosition = fixedPosition;
                    blockingPosition = otherPosition;
                }
                else
                {
                    movingPosition = otherPosition;
                    blockingPosition = fixedPosition;
                }

                // Move clockwise.
                int clockwiseMove = (target - movingPosition + n) % n;
                int clockwiseToBlocker = (blockingPosition - movingPosition + n) % n;

                if (clockwiseToBlocker > 0 && clockwiseToBlocker <= clockwiseMove)
                {
                    int newOtherPosition = (target + 1) % n;
                    int blockerMove = (target - blockingPosition + n) % n + 1;
                    Relax(next, newOtherPosition,
                          dp[otherPosition] + clockwiseMove + blockerMove);
                }
                else
                {
                    Relax(next, blockingPosition,
                          dp[otherPosition] + clockwiseMove);
                }

                // Move counterclockwise.
                int counterclockwiseMove = (movingPosition - target + n) % n;
                int counterclockwiseToBlocker =
                    (movingPosition - blockingPosition + n) % n;

                if (counterclockwiseToBlocker > 0 &&
                    counterclockwiseToBlocker <= counterclockwiseMove)
                {
                    int newOtherPosition = (target - 1 + n) % n;
                    int blockerMove = (blockingPosition - target + n) % n + 1;
                    Relax(next, newOtherPosition,
                          dp[otherPosition] + counterclockwiseMove + blockerMove);
                }
                else
                {
                    Relax(next, blockingPosition,
                          dp[otherPosition] + counterclockwiseMove);
                }
            }

            long[] temp = dp;
            dp = next;
            next = temp;

            previousHand = hand;
            fixedPosition = target;
        }

        long answer = INF;
        for (int i = 0; i < n; i++)
        {
            if (dp[i] < answer)
                answer = dp[i];
        }

        Console.WriteLine(answer);
    }

    private static void Relax(long[] dp, int position, long cost)
    {
        if (cost < dp[position])
            dp[position] = cost;
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int index;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int ReadByte()
        {
            if (index >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                index = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[index++];
        }

        private int SkipWhitespace()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c >= 0);

            return c;
        }

        public int NextInt()
        {
            int c = SkipWhitespace();
            int value = 0;

            while (c > 32)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value;
        }

        public char NextChar()
        {
            return (char)SkipWhitespace();
        }
    }
}
