using System;
using System.IO;
using System.Text;

public static class Program
{
    private const long Mod = 998244353;

    private struct HeapEntry
    {
        public int Id;
        public int Size;
        public long Weight;

        public HeapEntry(int id, int size, long weight)
        {
            Id = id;
            Size = size;
            Weight = weight;
        }
    }

    private sealed class MaxHeap
    {
        private HeapEntry[] data;
        private int count;

        public MaxHeap(int capacity)
        {
            data = new HeapEntry[Math.Max(4, capacity)];
            count = 0;
        }

        private static bool Higher(HeapEntry a, HeapEntry b)
        {
            long left = a.Weight * b.Size;
            long right = b.Weight * a.Size;

            if (left != right)
                return left > right;

            return a.Id < b.Id;
        }

        public void Push(HeapEntry value)
        {
            if (count == data.Length)
                Array.Resize(ref data, data.Length * 2);

            int index = count++;
            while (index > 0)
            {
                int parent = (index - 1) >> 1;
                if (!Higher(value, data[parent]))
                    break;

                data[index] = data[parent];
                index = parent;
            }
            data[index] = value;
        }

        public HeapEntry Pop()
        {
            HeapEntry result = data[0];
            HeapEntry last = data[--count];

            if (count > 0)
            {
                int index = 0;
                while (true)
                {
                    int left = index * 2 + 1;
                    if (left >= count)
                        break;

                    int right = left + 1;
                    int child = left;

                    if (right < count && Higher(data[right], data[left]))
                        child = right;

                    if (!Higher(data[child], last))
                        break;

                    data[index] = data[child];
                    index = child;
                }
                data[index] = last;
            }

            return result;
        }
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c >= 0);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            int value = 0;
            while (c > 32)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value * sign;
        }
    }

    private static int Find(int x, int[] dsu)
    {
        int root = x;
        while (dsu[root] != root)
            root = dsu[root];

        while (dsu[x] != x)
        {
            int next = dsu[x];
            dsu[x] = root;
            x = next;
        }

        return root;
    }

    private static long ModPow(long value, long exponent)
    {
        long result = 1;
        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * value % Mod;

            value = value * value % Mod;
            exponent >>= 1;
        }
        return result;
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());
        int testCases = scanner.NextInt();
        StringBuilder output = new StringBuilder();

        for (int test = 0; test < testCases; test++)
        {
            int n = scanner.NextInt();

            int[] treeParent = new int[n + 1];
            treeParent[0] = -1;
            for (int i = 1; i <= n; i++)
                treeParent[i] = scanner.NextInt();

            int[] dsu = new int[n + 1];
            int[] size = new int[n + 1];
            long[] weight = new long[n + 1];
            long[] cost = new long[n + 1];

            dsu[0] = 0;
            long totalWeight = 0;

            for (int i = 1; i <= n; i++)
            {
                long w = scanner.NextInt();
                dsu[i] = i;
                size[i] = 1;
                weight[i] = w;
                cost[i] = w;
                totalWeight += w;
            }

            MaxHeap heap = new MaxHeap(2 * n + 4);
            for (int i = 1; i <= n; i++)
                heap.Push(new HeapEntry(i, 1, weight[i]));

            for (int merged = 0; merged < n; merged++)
            {
                HeapEntry entry;

                while (true)
                {
                    entry = heap.Pop();
                    int id = entry.Id;

                    if (Find(id, dsu) == id &&
                        size[id] == entry.Size &&
                        weight[id] == entry.Weight)
                    {
                        break;
                    }
                }

                int component = entry.Id;
                int parentComponent = Find(treeParent[component], dsu);

                cost[parentComponent] += cost[component]
                                       + (long)size[parentComponent] * weight[component];
                size[parentComponent] += size[component];
                weight[parentComponent] += weight[component];

                dsu[component] = parentComponent;

                if (parentComponent != 0)
                {
                    heap.Push(new HeapEntry(
                        parentComponent,
                        size[parentComponent],
                        weight[parentComponent]
                    ));
                }
            }

            long numerator = cost[0] % Mod;
            long answer = numerator * ModPow(totalWeight % Mod, Mod - 2) % Mod;
            output.Append(answer).Append('\n');
        }

        Console.Write(output.ToString());
    }
}
