            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        long n = scanner.NextLong();
        int m = scanner.NextInt();

        long[] unavailable = new long[m * 9];
        int count = 0;

        int[] dr = { 2, 1, -1, -2, -2, -1, 1, 2 };
        int[] dc = { 1, 2, 2, 1, -1, -2, -2, -1 };

        for (int k = 0; k < m; k++)
        {
            long row = scanner.NextLong();
            long col = scanner.NextLong();

            unavailable[count++] = (row - 1) * n + (col - 1);

            for (int d = 0; d < 8; d++)
            {
                long nextRow = row + dr[d];
                long nextCol = col + dc[d];

                if (nextRow >= 1 && nextRow <= n &&
                    nextCol >= 1 && nextCol <= n)
                {
                    unavailable[count++] = (nextRow - 1) * n + (nextCol - 1);
                }
            }
        }

