        private int length;
        private int pointer;

        private int Read()
        {
            if (pointer >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0) return -1;
            }
            return buffer[pointer++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    private static int PowMod(long exponent, int modulus)
    {
        long result = 1 % modulus;
        long value = 2 % modulus;

        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * value % modulus;

            value = value * value % modulus;
            exponent >>= 1;
        }

        return (int)result;
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        long k = scanner.NextLong();

        int[] permutation = new int[n];
        for (int i = 0; i < n; i++)
            permutation[i] = scanner.NextInt() - 1;

        int[] answer = new int[n];
        bool[] visited = new bool[n];

        for (int start = 0; start < n; start++)
        {
            if (visited[start]) continue;

            int[] cycle = new int[n];
            int cycleLength = 0;
            int current = start;

            while (!visited[current])
            {
                visited[current] = true;
                cycle[cycleLength++] = current;
                current = permutation[current];
            }

            int shift = PowMod(k, cycleLength);

            for (int i = 0; i < cycleLength; i++)
            {
                answer[cycle[i]] = cycle[(i + shift) % cycleLength];
            }
        }

        var output = new StringBuilder();
        for (int i = 0; i < n; i++)
        {
            if (i > 0) output.Append(' ');
            output.Append(answer[i] + 1);
        }

        Console.WriteLine(output.ToString());
    }
