using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int index;

        private int Read()
        {
            if (index >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                index = 0;
                if (length == 0) return -1;
            }
            return buffer[index++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value * sign;
        }
    }

    private static long CountSafeOnSum(
        long n,
        long sum,
        List<long> blockedRows,
        List<long> blockedColumns,
        HashSet<long> blockedColumnSet)
    {
        long low = Math.Max(1L, sum - n);
        long high = Math.Min(n, sum - 1);

        if (low > high) return 0;

        long total = high - low + 1;
        long excludedRows = 0;
        long excludedColumns = 0;
        long excludedBoth = 0;

        foreach (long row in blockedRows)
        {
            if (row >= low && row <= high)
            {
                excludedRows++;
                long column = sum - row;
                if (blockedColumnSet.Contains(column))
                    excludedBoth++;
            }
        }

        foreach (long column in blockedColumns)
        {
            if (column >= low && column <= high)
                excludedColumns++;
        }

        return total - excludedRows - excludedColumns + excludedBoth;
    }

    private static long CountSafeOnDifference(
        long n,
        long difference,
        List<long> blockedRows,
        List<long> blockedColumns,
        HashSet<long> blockedColumnSet)
    {
        long lowRow = Math.Max(1L, 1L + difference);
        long highRow = Math.Min(n, n + difference);

        if (lowRow > highRow) return 0;

        long lowColumn = Math.Max(1L, 1L - difference);
        long highColumn = Math.Min(n, n - difference);

        long total = highRow - lowRow + 1;
        long excludedRows = 0;
        long excludedColumns = 0;
        long excludedBoth = 0;

        foreach (long row in blockedRows)
        {
            if (row >= lowRow && row <= highRow)
            {
                excludedRows++;
                long column = row - difference;
                if (blockedColumnSet.Contains(column))
                    excludedBoth++;
            }
        }

        foreach (long column in blockedColumns)
        {
            if (column >= lowColumn && column <= highColumn)
                excludedColumns++;
        }

        return total - excludedRows - excludedColumns + excludedBoth;
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        long n = scanner.NextLong();
        int m = (int)scanner.NextLong();

        var rowSet = new HashSet<long>();
        var columnSet = new HashSet<long>();
        var sumSet = new HashSet<long>();
        var differenceSet = new HashSet<long>();

        for (int k = 0; k < m; k++)
        {
            long a = scanner.NextLong();
            long b = scanner.NextLong();

            rowSet.Add(a);
            columnSet.Add(b);
            sumSet.Add(a + b);
            differenceSet.Add(a - b);
        }

        var rows = new List<long>(rowSet);
        var columns = new List<long>(columnSet);
        var sums = new List<long>(sumSet);
        var differences = new List<long>(differenceSet);

        long availableRows = n - rows.Count;
        long availableColumns = n - columns.Count;
        long answer = availableRows * availableColumns;

        foreach (long sum in sums)
        {
            answer -= CountSafeOnSum(
                n, sum, rows, columns, columnSet);
        }

        foreach (long difference in differences)
        {
            answer -= CountSafeOnDifference(
                n, difference, rows, columns, columnSet);
        }

        long intersectionCount = 0;

        foreach (long sum in sums)
        {
            foreach (long difference in differences)
            {
                long twiceRow = sum + difference;
                long twiceColumn = sum - difference;

                if ((twiceRow & 1L) != 0 || (twiceColumn & 1L) != 0)
                    continue;

                long row = twiceRow / 2;
                long column = twiceColumn / 2;

                if (row < 1 || row > n || column < 1 || column > n)
                    continue;

                if (rowSet.Contains(row) || columnSet.Contains(column))
                    continue;

                intersectionCount++;
            }
        }

        answer += intersectionCount;
        Console.WriteLine(answer);
    }
}
