using System;
using System.IO;
using System.Text;

public class Program
{
    const int MaxNodes = 200005;
    const int INF = int.MaxValue / 4;

    static int[] head = new int[MaxNodes];
    static int[] next = new int[MaxNodes];
    static int[] to = new int[MaxNodes];
    static int[] minLength = new int[MaxNodes];
    static byte[] edgeCharacter = new byte[MaxNodes];

    static int nodeCount = 1;
    static int edgeCount = 0;

    static int FindChild(int node, byte character)
    {
        for (int edge = head[node]; edge != -1; edge = next[edge])
        {
            if (edgeCharacter[edge] == character)
                return to[edge];
        }
        return -1;
    }

    static int AddChild(int node, byte character)
    {
        int child = nodeCount++;
        head[child] = -1;
        minLength[child] = INF;

        to[edgeCount] = child;
        edgeCharacter[edgeCount] = character;
        next[edgeCount] = head[node];
        head[node] = edgeCount++;

        return child;
    }

    public static void Main()
    {
        var reader = new StreamReader(Console.OpenStandardInput());

        for (int i = 0; i < MaxNodes; i++)
        {
            head[i] = -1;
            minLength[i] = INF;
        }

        minLength[0] = 0; // The empty string is always an available target.

        int n = int.Parse(reader.ReadLine());
        var output = new StringBuilder();

        for (int k = 0; k < n; k++)
        {
            string s = reader.ReadLine();
            int length = s.Length;
            int answer = length;
            int node = 0;

            for (int i = 0; i < length; i++)
            {
                byte c = (byte)(s[i] - 'a');
                int child = FindChild(node, c);

                if (child == -1)
                    break;

                node = child;
                int depth = i + 1;
                int candidate = length + minLength[node] - 2 * depth;

                if (candidate < answer)
                    answer = candidate;
            }

            output.Append(answer).Append('\n');

            node = 0;
            for (int i = 0; i < length; i++)
            {
                byte c = (byte)(s[i] - 'a');
                int child = FindChild(node, c);

                if (child == -1)
                    child = AddChild(node, c);

                node = child;
                if (length < minLength[node])
                    minLength[node] = length;
            }
        }

        Console.Write(output.ToString());
    }
}
