using System;
using System.Collections.Generic;

public class Program
{
    static int K;
    static int[][] adjacency;
    static bool[] visited;
    static long answer;

    static void Dfs(int cell, int moves)
    {
        if (moves == K)
        {
            answer++;
            return;
        }

        int[] neighbors = adjacency[cell];
        for (int i = 0; i < neighbors.Length; i++)
        {
            int next = neighbors[i];
            if (visited[next]) continue;

            visited[next] = true;
            Dfs(next, moves + 1);
            visited[next] = false;
        }
    }

    public static void Main()
    {
        string[] first = Console.ReadLine().Split();
        int h = int.Parse(first[0]);
        int w = int.Parse(first[1]);
        K = int.Parse(first[2]);

        string[] grid = new string[h];
        for (int i = 0; i < h; i++)
            grid[i] = Console.ReadLine();

        int cells = h * w;
        adjacency = new int[cells][];
        visited = new bool[cells];

        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        for (int r = 0; r < h; r++)
        {
            for (int c = 0; c < w; c++)
            {
                int id = r * w + c;
                if (grid[r][c] == '#')
                {
                    adjacency[id] = new int[0];
                    continue;
                }

                List<int> neighbors = new List<int>(4);
                for (int d = 0; d < 4; d++)
                {
                    int nr = r + dr[d];
                    int nc = c + dc[d];

                    if (nr >= 0 && nr < h && nc >= 0 && nc < w &&
                        grid[nr][nc] == '.')
                    {
                        neighbors.Add(nr * w + nc);
                    }
                }

                adjacency[id] = neighbors.ToArray();
            }
        }

        answer = 0;

        for (int r = 0; r < h; r++)
        {
            for (int c = 0; c < w; c++)
            {
                if (grid[r][c] == '#') continue;

                int start = r * w + c;
                visited[start] = true;
                Dfs(start, 0);
                visited[start] = false;
            }
        }

        Console.WriteLine(answer);
    }
}
