            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    private sealed class FenwickTree
    {
        private readonly long[] tree;

        public FenwickTree(int size)
        {
            tree = new long[size + 1];
        }

        public void Add(int index, long value)
        {
            for (int i = index; i < tree.Length; i += i & -i)
                tree[i] += value;
        }

        public long Sum(int index)
        {
            long result = 0;
            for (int i = index; i > 0; i -= i & -i)
                result += tree[i];
            return result;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = (int)scanner.NextLong();
        long m = scanner.NextLong();

        var counts = new FenwickTree((int)m);

        long answer = 0;
        long prefix = 0;
        long previousCount = 1;
        long previousSum = 0;

        counts.Add(1, 1); // Prefix remainder 0.

        for (int i = 0; i < n; i++)
        {
            long a = scanner.NextLong();
            prefix = (prefix + a % m) % m;

            long countLessOrEqual = counts.Sum((int)prefix + 1);
            long countGreater = previousCount - countLessOrEqual;

            answer += previousCount * prefix - previousSum + m * countGreater;

            counts.Add((int)prefix + 1, 1);
            previousCount++;
            previousSum += prefix;
        }

        Console.WriteLine(answer);
    }
}
