            prefixStones += cells[i].Stones;
            initialPositionSum += cells[i].Position * cells[i].Stones;
        }

        long finalPositionSum = n * (n + 1) / 2;
        Console.WriteLine(finalPositionSum - initialPositionSum);
    }
