using System;
using System.IO;
using System.Text;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int pointer;

        private int Read()
        {
            if (pointer >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0) return -1;
            }
            return buffer[pointer++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }
    }

    private sealed class MaxSegmentTree
    {
        private readonly int size;
        private readonly int[] tree;

        public MaxSegmentTree(int[] values)
        {
            size = 1;
            while (size < values.Length) size <<= 1;

            tree = new int[size << 1];
            for (int i = 0; i < values.Length; i++)
                tree[size + i] = values[i];

            for (int i = size - 1; i >= 1; i--)
                tree[i] = Math.Max(tree[i << 1], tree[(i << 1) | 1]);
        }

        public int QueryMax(int left, int right)
        {
            left += size;
            right += size;
            int result = 0;

            while (left <= right)
            {
                if ((left & 1) == 1)
                    result = Math.Max(result, tree[left++]);
                if ((right & 1) == 0)
                    result = Math.Max(result, tree[right--]);

                left >>= 1;
                right >>= 1;
            }

            return result;
        }

        public int FindFirstGreater(int start, int threshold, int n)
        {
            if (start >= n || tree[1] <= threshold)
                return -1;

            return FindFirstGreater(1, 0, size - 1, start, threshold, n);
        }

        private int FindFirstGreater(
            int node, int nodeLeft, int nodeRight,
            int start, int threshold, int n)
        {
            if (nodeRight < start || nodeLeft >= n || tree[node] <= threshold)
                return -1;

            if (nodeLeft == nodeRight)
                return nodeLeft;

            int middle = (nodeLeft + nodeRight) >> 1;

            int result = FindFirstGreater(
                node << 1, nodeLeft, middle, start, threshold, n);

            if (result != -1)
                return result;

            return FindFirstGreater(
                (node << 1) | 1, middle + 1, nodeRight,
                start, threshold, n);
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int q = scanner.NextInt();

        int[] heights = new int[n];
        for (int i = 0; i < n; i++)
            heights[i] = scanner.NextInt();

        int[] nextGreater = new int[n];
        int[] visibleChainLength = new int[n];
        int[] stack = new int[n];
        int stackSize = 0;

        for (int i = n - 1; i >= 0; i--)
        {
            while (stackSize > 0 &&
                   heights[stack[stackSize - 1]] < heights[i])
            {
                stackSize--;
            }

            nextGreater[i] = stackSize == 0 ? -1 : stack[stackSize - 1];
            visibleChainLength[i] = 1 +
                (nextGreater[i] == -1 ? 0 : visibleChainLength[nextGreater[i]]);

            stack[stackSize++] = i;
        }

        var segmentTree = new MaxSegmentTree(heights);
        var output = new StringBuilder();

        for (int query = 0; query < q; query++)
        {
            int l = scanner.NextInt() - 1;
            int r = scanner.NextInt() - 1;

            int threshold = segmentTree.QueryMax(l + 1, r);
            int first = segmentTree.FindFirstGreater(r + 1, threshold, n);

            int answer = first == -1 ? 0 : visibleChainLength[first];
            output.Append(answer).Append('\n');
        }

        Console.Write(output.ToString());
    }
}
