using System;
using System.IO;

public static class Program
{
    private const long Mod = 998244353L;

    private static int width;
    private static int stateCount;
    private static byte[] canonicalDigits;
    private static int[] offsets;
    private static int[] edges;
    private static int[] channelIndex;
    private static int[] colorMap;
    private static int[] compose;

    private static int currentSource;
    private static int writePosition;
    private static byte[] targetDigits;

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());
        int h = scanner.NextInt();
        int w = scanner.NextInt();

        char[][] original = new char[h][];
        for (int i = 0; i < h; i++)
            original[i] = scanner.Next().ToCharArray();

        int rowCount;
        char[][] rows;

        if (w <= h)
        {
            width = w;
            rowCount = h;
            rows = original;
        }
        else
        {
            width = h;
            rowCount = w;
            rows = new char[rowCount][];
            for (int r = 0; r < rowCount; r++)
            {
                rows[r] = new char[width];
                for (int c = 0; c < width; c++)
                    rows[r][c] = original[c][r];
            }
        }

        if (width == 1)
        {
            SolvePath(rows, rowCount);
            return;
        }

        BuildChannels();
        BuildCanonicalStates();
        BuildTransitions();

        byte[][] allowed = BuildAllowedMasks(rows, rowCount);

        long[] dp = new long[stateCount * 6];
        long[] next = new long[stateCount * 6];

        for (int s = 0; s < stateCount; s++)
        {
            int mask = allowed[0][s];
            int b = s * 6;
            for (int ch = 0; ch < 6; ch++)
            {
                if ((mask & (1 << ch)) != 0)
                    dp[b + ch] = 1;
            }
        }

        for (int row = 1; row < rowCount; row++)
        {
            Array.Clear(next, 0, next.Length);

            for (int s = 0; s < stateCount; s++)
            {
                int sourceBase = s * 6;
                long v0 = dp[sourceBase];
                long v1 = dp[sourceBase + 1];
                long v2 = dp[sourceBase + 2];
                long v3 = dp[sourceBase + 3];
                long v4 = dp[sourceBase + 4];
                long v5 = dp[sourceBase + 5];

                if ((v0 | v1 | v2 | v3 | v4 | v5) == 0)
                    continue;

                bool allNonZero =
                    v0 != 0 && v1 != 0 && v2 != 0 &&
                    v3 != 0 && v4 != 0 && v5 != 0;

                int end = offsets[s + 1];

                if (allNonZero)
                {
                    for (int e = offsets[s]; e < end; e++)
                    {
                        int packed = edges[e];
                        int target = packed >> 3;
                        int relative = packed & 7;
                        int targetBase = target * 6;
                        int cb = relative * 6;

                        next[targetBase + compose[cb]] += v0;
                        next[targetBase + compose[cb + 1]] += v1;
                        next[targetBase + compose[cb + 2]] += v2;
                        next[targetBase + compose[cb + 3]] += v3;
                        next[targetBase + compose[cb + 4]] += v4;
                        next[targetBase + compose[cb + 5]] += v5;
                    }
                }
                else
                {
                    for (int e = offsets[s]; e < end; e++)
                    {
                        int packed = edges[e];
                        int target = packed >> 3;
                        int relative = packed & 7;
                        int targetBase = target * 6;
                        int cb = relative * 6;

                        if (v0 != 0) next[targetBase + compose[cb]] += v0;
                        if (v1 != 0) next[targetBase + compose[cb + 1]] += v1;
                        if (v2 != 0) next[targetBase + compose[cb + 2]] += v2;
                        if (v3 != 0) next[targetBase + compose[cb + 3]] += v3;
                        if (v4 != 0) next[targetBase + compose[cb + 4]] += v4;
                        if (v5 != 0) next[targetBase + compose[cb + 5]] += v5;
                    }
                }
            }

            for (int s = 0; s < stateCount; s++)
            {
                int mask = allowed[row][s];
                int b = s * 6;
                for (int ch = 0; ch < 6; ch++)
                {
                    if ((mask & (1 << ch)) == 0)
                        next[b + ch] = 0;
                    else
                        next[b + ch] %= Mod;
                }
            }

            long[] temp = dp;
            dp = next;
            next = temp;
        }

        long answer = 0;
        for (int i = 0; i < dp.Length; i++)
        {
            answer += dp[i];
            if (answer >= Mod)
                answer -= Mod;
        }

        Console.WriteLine(answer);
    }

    private static void SolvePath(char[][] rows, int rowCount)
    {
        long[] dp = new long[3];
        long[] next = new long[3];

        for (int c = 0; c < 3; c++)
        {
            if (rows[0][0] == '?' || rows[0][0] - '1' == c)
                dp[c] = 1;
        }

        for (int r = 1; r < rowCount; r++)
        {
            long sum = (dp[0] + dp[1] + dp[2]) % Mod;
            for (int c = 0; c < 3; c++)
            {
                if (rows[r][0] == '?' || rows[r][0] - '1' == c)
                    next[c] = (sum - dp[c] + Mod) % Mod;
                else
                    next[c] = 0;
            }

            long[] temp = dp;
            dp = next;
            next = temp;
        }

        Console.WriteLine((dp[0] + dp[1] + dp[2]) % Mod);
    }

    private static void BuildChannels()
    {
        channelIndex = new int[9];
        for (int i = 0; i < channelIndex.Length; i++)
            channelIndex[i] = -1;

        colorMap = new int[18];
        int channel = 0;

        for (int a = 0; a < 3; a++)
        {
            for (int b = 0; b < 3; b++)
            {
                if (a == b) continue;

                int c = 3 - a - b;
                channelIndex[a * 3 + b] = channel;
                colorMap[channel * 3] = a;
                colorMap[channel * 3 + 1] = b;
                colorMap[channel * 3 + 2] = c;
                channel++;
            }
        }

        compose = new int[36];
        for (int relative = 0; relative < 6; relative++)
        {
            int ra = colorMap[relative * 3];
            int rb = colorMap[relative * 3 + 1];

            for (int source = 0; source < 6; source++)
            {
                int a = colorMap[source * 3 + ra];
                int b = colorMap[source * 3 + rb];
                compose[relative * 6 + source] = channelIndex[a * 3 + b];
            }
        }
    }

    private static void BuildCanonicalStates()
    {
        stateCount = 1 << (width - 2);
        canonicalDigits = new byte[stateCount * width];

        for (int id = 0; id < stateCount; id++)
        {
            int b = id * width;
            canonicalDigits[b] = 0;
            canonicalDigits[b + 1] = 1;
            int previous = 1;

            for (int pos = 2; pos < width; pos++)
            {
                int shift = width - 1 - pos;
                int bit = (id >> shift) & 1;

                int first = -1;
                int second = -1;
                for (int color = 0; color < 3; color++)
                {
                    if (color == previous) continue;
                    if (first == -1) first = color;
                    else second = color;
                }

                int chosen = bit == 0 ? first : second;
                canonicalDigits[b + pos] = (byte)chosen;
                previous = chosen;
            }
        }
    }

    private static void BuildTransitions()
    {
        offsets = new int[stateCount + 1];

        for (int s = 0; s < stateCount; s++)
        {
            int b = s * width;
            int[] ways = new int[3];

            int forbidden = canonicalDigits[b];
            for (int c = 0; c < 3; c++)
                ways[c] = c == forbidden ? 0 : 1;

            for (int pos = 1; pos < width; pos++)
            {
                forbidden = canonicalDigits[b + pos];
                int total = ways[0] + ways[1] + ways[2];
                int[] nextWays = new int[3];

                for (int c = 0; c < 3; c++)
                    nextWays[c] = c == forbidden ? 0 : total - ways[c];

                ways = nextWays;
            }

            int degree = ways[0] + ways[1] + ways[2];
            offsets[s + 1] = offsets[s] + degree;
        }

        edges = new int[offsets[stateCount]];
        targetDigits = new byte[width];

        for (currentSource = 0; currentSource < stateCount; currentSource++)
        {
            writePosition = offsets[currentSource];
            EnumerateTargets(0, -1);
        }
    }

    private static void EnumerateTargets(int position, int previous)
    {
        if (position == width)
        {
            int a = targetDigits[0];
            int b = targetDigits[1];
            int relative = channelIndex[a * 3 + b];

            int canonicalId = 0;
            int previousNormalized = 1;

            for (int pos = 2; pos < width; pos++)
            {
                int actual = targetDigits[pos];
                int normalized;

                if (actual == a) normalized = 0;
                else if (actual == b) normalized = 1;
                else normalized = 2;

                int first = -1;
                int second = -1;
                for (int color = 0; color < 3; color++)
                {
                    if (color == previousNormalized) continue;
                    if (first == -1) first = color;
                    else second = color;
                }

                int bit = normalized == first ? 0 : 1;
                canonicalId = (canonicalId << 1) | bit;
                previousNormalized = normalized;
            }

            edges[writePosition++] = (canonicalId << 3) | relative;
            return;
        }

        int forbidden = canonicalDigits[currentSource * width + position];

        for (int color = 0; color < 3; color++)
        {
            if (color == forbidden || color == previous)
                continue;

            targetDigits[position] = (byte)color;
            EnumerateTargets(position + 1, color);
        }
    }

    private static byte[][] BuildAllowedMasks(char[][] rows, int rowCount)
    {
        byte[][] allowed = new byte[rowCount][];

        for (int r = 0; r < rowCount; r++)
        {
            allowed[r] = new byte[stateCount];

            bool unrestricted = true;
            for (int pos = 0; pos < width; pos++)
            {
                if (rows[r][pos] != '?')
                {
                    unrestricted = false;
                    break;
                }
            }

            if (unrestricted)
            {
                for (int s = 0; s < stateCount; s++)
                    allowed[r][s] = 63;
                continue;
            }

            for (int s = 0; s < stateCount; s++)
            {
                int mask = 0;
                int stateBase = s * width;

                for (int ch = 0; ch < 6; ch++)
                {
                    bool ok = true;
                    int mapBase = ch * 3;

                    for (int pos = 0; pos < width; pos++)
                    {
                        char fixedCell = rows[r][pos];
                        if (fixedCell == '?') continue;

                        int canonicalColor = canonicalDigits[stateBase + pos];
                        int actualColor = colorMap[mapBase + canonicalColor];

                        if (actualColor != fixedCell - '1')
                        {
                            ok = false;
                            break;
                        }
                    }

                    if (ok)
                        mask |= 1 << ch;
                }

                allowed[r][s] = (byte)mask;
            }
        }

        return allowed;
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int pointer;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (pointer >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0) return -1;
            }
            return buffer[pointer++];
        }

        public string Next()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c >= 0);

            char[] chars = new char[256];
            int count = 0;

            while (c > 32)
            {
                if (count == chars.Length)
                    Array.Resize(ref chars, chars.Length * 2);
                chars[count++] = (char)c;
                c = Read();
            }

            return new string(chars, 0, count);
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c >= 0);

            int value = 0;
            while (c > 32)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }
    }
}
