        for (int i = 0; i < q; i++)
        {
            long k = scanner.NextLong() - 1;
            long block = k / length;
            int index = (int)(k % length);

            char answer = s[index];
            if (HasOddPopCount(block))
            {
                answer = char.IsUpper(answer)
                    ? char.ToLowerInvariant(answer)
                    : char.ToUpperInvariant(answer);
            }

            if (i > 0)
                output.Append(' ');
            output.Append(answer);
