using System;
using System.IO;
using System.Text;

public class Program
{
    private static int[] parent;
    private static int[] size;
    private static int[] left;
    private static int[] right;
    private static int[] color;

    private static int Find(int x)
    {
        int root = x;
        while (parent[root] != root)
            root = parent[root];

        while (parent[x] != x)
        {
            int next = parent[x];
            parent[x] = root;
            x = next;
        }

        return root;
    }

    private static int Union(int a, int b)
    {
        a = Find(a);
        b = Find(b);

        if (a == b)
            return a;

        if (size[a] < size[b])
        {
            int temp = a;
            a = b;
            b = temp;
        }

        parent[b] = a;
        size[a] += size[b];
        left[a] = Math.Min(left[a], left[b]);
        right[a] = Math.Max(right[a], right[b]);

        return a;
    }

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());
        int n = scanner.NextInt();
        int q = scanner.NextInt();

        parent = new int[n + 1];
        size = new int[n + 1];
        left = new int[n + 1];
        right = new int[n + 1];
        color = new int[n + 1];
        int[] colorCount = new int[n + 1];

        for (int i = 1; i <= n; i++)
        {
            parent[i] = i;
            size[i] = 1;
            left[i] = i;
            right[i] = i;
            color[i] = i;
            colorCount[i] = 1;
        }

        var output = new StringBuilder();

        for (int query = 0; query < q; query++)
        {
            int type = scanner.NextInt();

            if (type == 1)
            {
                int x = scanner.NextInt();
                int newColor = scanner.NextInt();
                int root = Find(x);
                int oldColor = color[root];

                if (oldColor == newColor)
                    continue;

                colorCount[oldColor] -= size[root];
                colorCount[newColor] += size[root];
                color[root] = newColor;

                if (left[root] > 1)
                {
                    int neighbor = Find(left[root] - 1);
                    if (color[neighbor] == newColor)
                        root = Union(root, neighbor);
                }

                root = Find(root);

                if (right[root] < n)
                {
                    int neighbor = Find(right[root] + 1);
                    if (color[neighbor] == newColor)
                        root = Union(root, neighbor);
                }
            }
            else
            {
                int queriedColor = scanner.NextInt();
                output.AppendLine(colorCount[queriedColor].ToString());
            }
        }

        Console.Write(output.ToString());
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

