using System;
using System.IO;

public class Program
{
    private static int cardCount;
    private static long[] values;
    private static int[] powersOfThree;
    private static int[] lowerMasks;
    private static byte[] memo;

    // turn: 0 = Takahashi, 1 = Aoki
    private static bool IsWinning(int state, int turn)
    {
        int memoIndex = state * 2 + turn;
        if (memo[memoIndex] != 0)
            return memo[memoIndex] == 2;

        int owner = turn == 0 ? 1 : 2;
        int currentHand = 0;
        int table = 0;
        int encoded = state;

        for (int i = 0; i < cardCount; i++)
        {
            int position = encoded % 3;
            encoded /= 3;

            if (position == owner)
                currentHand |= 1 << i;
            else if (position == 0)
                table |= 1 << i;
        }

        if (currentHand == 0)
        {
            memo[memoIndex] = 1;
            return false;
        }

        int nextTurn = turn ^ 1;

        for (int handBits = currentHand; handBits != 0; handBits &= handBits - 1)
        {
            int playedBit = handBits & -handBits;
            int played = BitIndex(playedBit);

            int stateAfterPlaying = state - owner * powersOfThree[played];

            // Do not take a card from the table.
            if (!IsWinning(stateAfterPlaying, nextTurn))
            {
                memo[memoIndex] = 2;
                return true;
            }

            // Take a lower-numbered card from the table.
            int candidates = table & lowerMasks[played];
            while (candidates != 0)
            {
                int takenBit = candidates & -candidates;
                candidates -= takenBit;
                int taken = BitIndex(takenBit);

                int nextState = stateAfterPlaying + owner * powersOfThree[taken];
                if (!IsWinning(nextState, nextTurn))
                {
                    memo[memoIndex] = 2;
                    return true;
                }
            }
        }

        memo[memoIndex] = 1;
        return false;
    }

    private static int BitIndex(int bit)
    {
        int index = 0;
        while ((bit >>= 1) != 0)
            index++;
        return index;
    }

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        int m = scanner.NextInt();
        int l = scanner.NextInt();

        cardCount = n + m + l;
        values = new long[cardCount];

        for (int i = 0; i < cardCount; i++)
            values[i] = scanner.NextLong();

        powersOfThree = new int[cardCount + 1];
        powersOfThree[0] = 1;
        for (int i = 1; i <= cardCount; i++)
            powersOfThree[i] = powersOfThree[i - 1] * 3;

        lowerMasks = new int[cardCount];
        for (int i = 0; i < cardCount; i++)
        {
            int mask = 0;
            for (int j = 0; j < cardCount; j++)
            {
                if (values[j] < values[i])
                    mask |= 1 << j;
            }
            lowerMasks[i] = mask;
        }

        int initialState = 0;
        for (int i = 0; i < n; i++)
            initialState += powersOfThree[i];          // Takahashi: 1
        for (int i = n; i < n + m; i++)
            initialState += 2 * powersOfThree[i];      // Aoki: 2
        // Table cards are represented by 0.

        memo = new byte[powersOfThree[cardCount] * 2];

        Console.WriteLine(IsWinning(initialState, 0) ? "Takahashi" : "Aoki");
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            return (int)NextLong();
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
