using System;
using System.IO;

public class Program
{
    const long Mod = 998244353;

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        int k = scanner.NextInt();

        int[] p = new int[n];
        var allFenwick = new FenwickTree(n);

        long totalInversions = 0;

        for (int i = 0; i < n; i++)
        {
            p[i] = scanner.NextInt();
            totalInversions += i - allFenwick.Sum(p[i]);
            allFenwick.Add(p[i], 1);
        }

        var windowFenwick = new FenwickTree(n);
        long windowInversions = 0;

        for (int i = 0; i < k; i++)
        {
            windowInversions += i - windowFenwick.Sum(p[i]);
            windowFenwick.Add(p[i], 1);
        }

        long sumWindowInversions = windowInversions;
        int windowCount = n - k + 1;

        for (int left = 0; left + k < n; left++)
        {
            int removed = p[left];

            // The removed element was the leftmost element, so only smaller
            // elements in the window formed inversions with it.
            windowInversions -= windowFenwick.Sum(removed - 1);
            windowFenwick.Add(removed, -1);

            int added = p[left + k];

            // The added element becomes the rightmost element, so every
            // existing element greater than it forms a new inversion.
            windowInversions += (k - 1) - windowFenwick.Sum(added);
            windowFenwick.Add(added, 1);

            sumWindowInversions += windowInversions;
        }

        long answer = totalInversions % Mod;

        long averageOriginalWindowInversions =
            (sumWindowInversions % Mod) * ModPow(windowCount, Mod - 2) % Mod;

        long expectedShuffledWindowInversions =
            (k % Mod) * ((k - 1L) % Mod) % Mod * ModPow(4, Mod - 2) % Mod;

        answer = (answer - averageOriginalWindowInversions
                          + expectedShuffledWindowInversions) % Mod;

        if (answer < 0)
            answer += Mod;

        Console.WriteLine(answer);
    }

    static long ModPow(long value, long exponent)
    {
        long result = 1;
        value %= Mod;

        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * value % Mod;

            value = value * value % Mod;
            exponent >>= 1;
        }

        return result;
    }

    sealed class FenwickTree
    {
        private readonly int[] tree;

        public FenwickTree(int size)
        {
            tree = new int[size + 1];
        }

        public void Add(int index, int value)
        {
            for (int i = index; i < tree.Length; i += i & -i)
                tree[i] += value;
        }

        public int Sum(int index)
        {
            int result = 0;

            for (int i = index; i > 0; i -= i & -i)
                result += tree[i];

            return result;
        }
    }

    sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;

                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;

            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }

            return value * sign;
        }
    }
}
