using System;
using System.Collections.Generic;
using System.IO;
using System.Text;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int pointer;

        private int ReadByte()
        {
            if (pointer >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0) return -1;
            }
            return buffer[pointer++];
        }

        public string Next()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            var sb = new StringBuilder();
            while (c > 32 && c != -1)
            {
                sb.Append((char)c);
                c = ReadByte();
            }
            return sb.ToString();
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    private static int LowerBound(List<int> list, int value)
    {
        int left = 0;
        int right = list.Count;

        while (left < right)
        {
            int mid = left + (right - left) / 2;
            if (list[mid] < value)
                left = mid + 1;
            else
                right = mid;
        }

        return left;
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int q = scanner.NextInt();
        string s = scanner.Next();

        int[] prefixOnes = new int[n + 1];
        int[] prefixTwos = new int[n + 1];
        var slashPositions = new List<int>();

        for (int i = 1; i <= n; i++)
        {
            prefixOnes[i] = prefixOnes[i - 1];
            prefixTwos[i] = prefixTwos[i - 1];

            char c = s[i - 1];
            if (c == '1')
                prefixOnes[i]++;
            else if (c == '2')
                prefixTwos[i]++;
            else
                slashPositions.Add(i);
        }

        var output = new StringBuilder();

        for (int query = 0; query < q; query++)
        {
            int l = scanner.NextInt();
            int r = scanner.NextInt();

            int firstSlash = LowerBound(slashPositions, l);
            int afterLastSlash = LowerBound(slashPositions, r + 1);

            if (firstSlash == afterLastSlash)
            {
                output.AppendLine("0");
                continue;
            }

            int left = firstSlash;
            int right = afterLastSlash;

            // Find the first slash where the available number of '1's
            // is at least the available number of '2's.
            while (left < right)
            {
                int mid = left + (right - left) / 2;
                int position = slashPositions[mid];

                int ones = prefixOnes[position] - prefixOnes[l - 1];
                int twos = prefixTwos[r] - prefixTwos[position];

                if (ones >= twos)
                    right = mid;
                else
                    left = mid + 1;
            }

            int best = 0;

            if (left < afterLastSlash)
            {
                int position = slashPositions[left];
                int ones = prefixOnes[position] - prefixOnes[l - 1];
                int twos = prefixTwos[r] - prefixTwos[position];
                best = Math.Max(best, Math.Min(ones, twos));
            }

            if (left - 1 >= firstSlash)
            {
                int position = slashPositions[left - 1];
                int ones = prefixOnes[position] - prefixOnes[l - 1];
                int twos = prefixTwos[r] - prefixTwos[position];
                best = Math.Max(best, Math.Min(ones, twos));
            }

            output.AppendLine((2 * best + 1).ToString());
        }

        Console.Write(output.ToString());
    }
}
