using System;
using System.IO;
using System.Text;

public class Program
{
    static int n, k;
    static int[] sequence;
    static StreamWriter writer;
    static StringBuilder buffer = new StringBuilder();

    static void Generate(int index, int minimum)
    {
        if (index == n)
        {
            for (int i = 0; i < n; i++)
            {
                if (i > 0) buffer.Append(' ');
                buffer.Append(sequence[i] + 10 * i);
            }
            buffer.Append('\n');

            if (buffer.Length >= 65536)
            {
                writer.Write(buffer.ToString());
                buffer.Clear();
            }
            return;
        }

        for (int value = minimum; value <= k; value++)
        {
            sequence[index] = value;
            Generate(index + 1, value);
        }
    }

    static long Combination(int total, int choose)
    {
        choose = Math.Min(choose, total - choose);
        long result = 1;

        for (int i = 1; i <= choose; i++)
            result = result * (total - choose + i) / i;

        return result;
    }

    public static void Main()
    {
        string[] input = Console.ReadLine().Split();
        n = int.Parse(input[0]);
        int m = int.Parse(input[1]);

        k = m - 10 * (n - 1);
        sequence = new int[n];

        long count = Combination(n + k - 1, n);

        writer = new StreamWriter(Console.OpenStandardOutput());
        buffer.Append(count).Append('\n');

        Generate(0, 1);

        if (buffer.Length > 0)
            writer.Write(buffer.ToString());

        writer.Flush();
    }
}
