using System;
using System.IO;
using System.Text;

public class Program
{
    private const int INF = 1000000000;

    private struct Bar
    {
        public int Row;
        public int Left;
        public int Right;
        public int Id;
    }

    private sealed class SegmentTree
    {
        private readonly int[] minimum;
        private readonly int[] lazy;
        private readonly int width;

        public SegmentTree(int width)
        {
            this.width = width;
            minimum = new int[width * 4 + 5];
            lazy = new int[width * 4 + 5];

            for (int i = 0; i < minimum.Length; i++)
            {
                minimum[i] = INF;
                lazy[i] = INF;
            }
        }

        private void Apply(int node, int value)
        {
            if (value < minimum[node]) minimum[node] = value;
            if (value < lazy[node]) lazy[node] = value;
        }

        private void Push(int node)
        {
            if (lazy[node] == INF) return;

            Apply(node * 2, lazy[node]);
            Apply(node * 2 + 1, lazy[node]);
            lazy[node] = INF;
        }

        public void Update(int queryLeft, int queryRight, int value)
        {
            Update(1, 1, width, queryLeft, queryRight, value);
        }

        private void Update(int node, int left, int right, int queryLeft, int queryRight, int value)
        {
            if (queryRight < left || right < queryLeft) return;

            if (queryLeft <= left && right <= queryRight)
            {
                Apply(node, value);
                return;
            }

            Push(node);

            int middle = (left + right) >> 1;
            Update(node * 2, left, middle, queryLeft, queryRight, value);
            Update(node * 2 + 1, middle + 1, right, queryLeft, queryRight, value);

            minimum[node] = Math.Min(minimum[node * 2], minimum[node * 2 + 1]);
        }

        public int Query(int queryLeft, int queryRight)
        {
            return Query(1, 1, width, queryLeft, queryRight);
        }

        private int Query(int node, int left, int right, int queryLeft, int queryRight)
        {
            if (queryRight < left || right < queryLeft) return INF;

            if (queryLeft <= left && right <= queryRight)
                return minimum[node];

            Push(node);

            int middle = (left + right) >> 1;
            return Math.Min(
                Query(node * 2, left, middle, queryLeft, queryRight),
                Query(node * 2 + 1, middle + 1, right, queryLeft, queryRight)
            );
        }
    }

    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }

            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int h = scanner.NextInt();
        int w = scanner.NextInt();
        int n = scanner.NextInt();

        var bars = new Bar[n];
        for (int i = 0; i < n; i++)
        {
            int row = scanner.NextInt();
            int column = scanner.NextInt();
            int length = scanner.NextInt();

            bars[i] = new Bar
            {
                Row = row,
                Left = column,
                Right = column + length - 1,
                Id = i
            };
        }

        Array.Sort(bars, delegate(Bar a, Bar b)
        {
            int comparison = b.Row.CompareTo(a.Row);
            return comparison != 0 ? comparison : a.Id.CompareTo(b.Id);
        });

        var segmentTree = new SegmentTree(w);
        var answer = new int[n];

        for (int i = 0; i < n; i++)
        {
            Bar bar = bars[i];
            int obstacleRow = segmentTree.Query(bar.Left, bar.Right);
            int finalRow = obstacleRow == INF ? h : obstacleRow - 1;

            answer[bar.Id] = finalRow;
            segmentTree.Update(bar.Left, bar.Right, finalRow);
        }

        var output = new StringBuilder();
        for (int i = 0; i < n; i++)
            output.Append(answer[i]).Append('\n');

        Console.Write(output.ToString());
    }
}
