public class Program
{
    public static void Main()
    {
        long n = long.Parse(Console.ReadLine().Trim());
        int limit = IntegerSquareRoot(n);

        bool[] composite = new bool[limit + 1];
        var primes = new List<int>();

        for (int i = 2; i <= limit; i++)
        {
            if (!composite[i])
            {
                primes.Add(i);

                if ((long)i * i <= limit)
                {
                    for (int j = i * i; j <= limit; j += i)
                        composite[j] = true;
                }
            }
        }

        long answer = 0;

        // Numbers of the form p^2 * q^2, where p and q are distinct primes.
        int right = primes.Count - 1;
        for (int left = 0; left < right; left++)
        {
            while (left < right && (long)primes[left] * primes[right] > limit)
                right--;

            if (left >= right)
                break;

            answer += right - left;
        }

        // Numbers of the form p^8.
        foreach (int p in primes)
        {
            long power = 1;
            bool valid = true;

            for (int exponent = 0; exponent < 8; exponent++)
            {
                if (power > n / p)
                {
                    valid = false;
                    break;
                }
                power *= p;
            }

            if (!valid)
                break;

            answer++;
        }

        Console.WriteLine(answer);
    }

    private static int IntegerSquareRoot(long n)
    {
        long root = (long)Math.Sqrt(n);

        while ((root + 1) <= n / (root + 1))
            root++;

        while (root > n / root)
            root--;

        return (int)root;
    }
}
