public class Program
{
    private struct Edge : IComparable<Edge>
    {
        public int U;
        public int V;
        public int W;

        public Edge(int u, int v, int w)
        {
            U = u;
            V = v;
            W = w;
        }

        public int CompareTo(Edge other)
        {
            return W.CompareTo(other.W);
        }
    }

    private sealed class DisjointSetUnion
    {
        private readonly int[] parent;
        private readonly int[] size;

        public DisjointSetUnion(int n)
        {
            parent = new int[n];
            size = new int[n];

            for (int i = 0; i < n; i++)
            {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int Find(int x)
        {
            int root = x;
            while (parent[root] != root)
                root = parent[root];

            while (parent[x] != x)
            {
                int next = parent[x];
                parent[x] = root;
                x = next;
            }

            return root;
        }

        public int MergeRoots(int x, int y)
        {
            if (size[x] < size[y])
            {
                int temp = x;
                x = y;
                y = temp;
            }

            parent[y] = x;
            size[x] += size[y];
            return x;
        }
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        int m = scanner.NextInt();
        int k = scanner.NextInt();

        Edge[] edges = new Edge[m];
        for (int i = 0; i < m; i++)
        {
            int u = scanner.NextInt() - 1;
            int v = scanner.NextInt() - 1;
            int w = scanner.NextInt();
            edges[i] = new Edge(u, v, w);
        }

        long[] balance = new long[n];

        for (int i = 0; i < k; i++)
            balance[scanner.NextInt() - 1]++;

        for (int i = 0; i < k; i++)
            balance[scanner.NextInt() - 1]--;

        Array.Sort(edges);

        DisjointSetUnion dsu = new DisjointSetUnion(n);
        long answer = 0;

        for (int i = 0; i < m; i++)
        {
            Edge edge = edges[i];
            int rootU = dsu.Find(edge.U);
            int rootV = dsu.Find(edge.V);

            if (rootU == rootV)
                continue;

            long left = balance[rootU];
            long right = balance[rootV];

            if ((left > 0 && right < 0) || (left < 0 && right > 0))
            {
                long matched = Math.Min(Math.Abs(left), Math.Abs(right));
                answer += matched * edge.W;
            }

            int newRoot = dsu.MergeRoots(rootU, rootV);
            balance[newRoot] = left + right;
        }

        Console.WriteLine(answer);
    }

