using System;
using System.IO;

public class Program
{
    private static int H, W;
    private static long[] strengths;
    private static bool[] discovered;
    private static MinHeap heap;

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());

        H = scanner.NextInt();
        W = scanner.NextInt();
        long x = scanner.NextLong();

        int p = scanner.NextInt() - 1;
        int q = scanner.NextInt() - 1;

        int n = H * W;
        strengths = new long[n];

        for (int i = 0; i < n; i++)
            strengths[i] = scanner.NextLong();

        int start = p * W + q;
        long currentStrength = strengths[start];

        discovered = new bool[n];
        heap = new MinHeap(n, strengths);

        discovered[start] = true;
        DiscoverNeighbors(start);

        while (heap.Count > 0)
        {
            int cell = heap.Peek();
            long slimeStrength = strengths[cell];

            // slimeStrength * x < currentStrength, avoiding multiplication overflow.
            if (slimeStrength > (currentStrength - 1) / x)
                break;

            heap.Pop();
            currentStrength += slimeStrength;
            DiscoverNeighbors(cell);
        }

        Console.WriteLine(currentStrength);
    }

    private static void DiscoverNeighbors(int cell)
    {
        int row = cell / W;
        int col = cell % W;

        if (row > 0)
            Discover(cell - W);
        if (row + 1 < H)
            Discover(cell + W);
        if (col > 0)
            Discover(cell - 1);
        if (col + 1 < W)
            Discover(cell + 1);
    }

    private static void Discover(int cell)
    {
        if (discovered[cell])
            return;

        discovered[cell] = true;
        heap.Push(cell);
    }

    private sealed class MinHeap
    {
        private readonly int[] data;
        private readonly long[] values;

        public int Count { get; private set; }

        public MinHeap(int capacity, long[] values)
        {
            data = new int[capacity + 1];
            this.values = values;
        }

        public void Push(int cell)
        {
            int pos = ++Count;

            while (pos > 1)
            {
                int parent = pos / 2;
                if (values[data[parent]] <= values[cell])
                    break;

                data[pos] = data[parent];
                pos = parent;
            }

            data[pos] = cell;
        }

        public int Peek()
        {
            return data[1];
        }

        public int Pop()
        {
            int result = data[1];
            int last = data[Count--];

            if (Count == 0)
                return result;

            int pos = 1;
            while (true)
            {
                int left = pos * 2;
                if (left > Count)
                    break;

                int right = left + 1;
                int child = left;

                if (right <= Count && values[data[right]] < values[data[left]])
                    child = right;

                if (values[last] <= values[data[child]])
                    break;

                data[pos] = data[child];
                pos = child;
            }

            data[pos] = last;
            return result;
        }
    }

