    private sealed class ResidueMap
    {
        private readonly int[] keys;
        private readonly int[] counts;
        private readonly long[] sums;
        private readonly int[] stamps;
        private readonly int mask;
        private int version;

        public ResidueMap(int maximumEntries)
        {
            int size = 1;
            while (size < maximumEntries * 2)
                size <<= 1;

            keys = new int[size];
            counts = new int[size];
            sums = new long[size];
            stamps = new int[size];
            mask = size - 1;
        }

        public void Clear()
        {
            version++;
        }

        private static uint Hash(uint x)
        {
            unchecked
            {
                x ^= x >> 16;
                x *= 0x7feb352dU;
                x ^= x >> 15;
                x *= 0x846ca68bU;
                x ^= x >> 16;
                return x;
            }
        }

        public void Add(int key, int value)
        {
            int index = (int)(Hash((uint)key) & (uint)mask);

            while (stamps[index] == version)
            {
                if (keys[index] == key)
                {
                    counts[index]++;
                    sums[index] += value;
                    return;
                }
                index = (index + 1) & mask;
            }

            stamps[index] = version;
            keys[index] = key;
            counts[index] = 1;
            sums[index] = value;
        }

        public void Get(int key, out int count, out long sum)
        {
            int index = (int)(Hash((uint)key) & (uint)mask);

            while (stamps[index] == version)
            {
                if (keys[index] == key)
                {
                    count = counts[index];
                    sum = sums[index];
                    return;
                }
                index = (index + 1) & mask;
            }

            count = 0;
            sum = 0;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int[] a = new int[n];

        long total = 0;
        int maximum = 0;

        for (int i = 0; i < n; i++)
        {
            a[i] = scanner.NextInt();
            total += a[i];
            if (a[i] > maximum)
                maximum = a[i];
        }

        long answer = total * (n + 1L);
        int maximumSum = maximum * 2;
        var map = new ResidueMap(n);

        for (int modulus = 2; modulus <= maximumSum; modulus <<= 1)
        {
            int residueMask = modulus - 1;
            map.Clear();

            for (int i = 0; i < n; i++)
                map.Add(a[i] & residueMask, a[i]);

            long orderedSum = 0;

            for (int i = 0; i < n; i++)
            {
                int residue = a[i] & residueMask;
                int complement = (-residue) & residueMask;

                int count;
                long sum;
                map.Get(complement, out count, out sum);

                orderedSum += (long)count * a[i] + sum;
            }

            long diagonalSum = 0;
            int diagonalMask = (modulus >> 1) - 1;

            for (int i = 0; i < n; i++)
            {
                if ((a[i] & diagonalMask) == 0)
                    diagonalSum += 2L * a[i];
            }

            answer -= (orderedSum + diagonalSum) / (2L * modulus);
        }

        Console.WriteLine(answer);
    }
}
