using System;
using System.IO;
using System.Text;

public static class Program
{
    private const int PackShift = 17;
    private const long PackMask = (1L << PackShift) - 1;
    private static readonly int[] RotateDelta = { 3, 0, 0, 1 };

    private struct Query : IComparable<Query>
    {
        public int X;
        public int Y;
        public int Index;
        public long Order;

        public int CompareTo(Query other)
        {
            if (Order < other.Order) return -1;
            if (Order > other.Order) return 1;
            return 0;
        }
    }

    private static long HilbertOrder(int x, int y, int pow, int rotate)
    {
        if (pow == 0) return 0;

        int half = 1 << (pow - 1);
        int segment;

        if (x < half)
            segment = y < half ? 0 : 3;
        else
            segment = y < half ? 1 : 2;

        segment = (segment + rotate) & 3;

        int nx = x & (half - 1);
        int ny = y & (half - 1);
        int nextRotate = (rotate + RotateDelta[segment]) & 3;

        long squareSize = 1L << (2 * pow - 2);
        long result = segment * squareSize;
        long subOrder = HilbertOrder(nx, ny, pow - 1, nextRotate);

        if (segment == 1 || segment == 2)
            result += subOrder;
        else
            result += squareSize - subOrder - 1;

        return result;
    }

    private static void Update(long[] bit, int rank, int value, int delta)
    {
        long packed = ((long)value << PackShift) + 1;
        if (delta < 0) packed = -packed;

        for (int i = rank + 1; i < bit.Length; i += i & -i)
            bit[i] += packed;
    }

    private static long Distance(
        long[] bit, int rank, long value, int totalCount, long totalSum)
    {
        if (totalCount == 0) return 0;

        long packed = 0;
        for (int i = rank + 1; i > 0; i -= i & -i)
            packed += bit[i];

        long lowerCount = packed & PackMask;
        long lowerSum = packed >> PackShift;

        return value * lowerCount - lowerSum
             + (totalSum - lowerSum)
             - value * (totalCount - lowerCount);
    }

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();

        int[] a = new int[n];
        int[] b = new int[n];
        int[] coordinates = new int[2 * n];
        long[] prefixA = new long[n + 1];
        long[] prefixB = new long[n + 1];

        for (int i = 0; i < n; i++)
        {
            a[i] = scanner.NextInt();
            coordinates[i] = a[i];
            prefixA[i + 1] = prefixA[i] + a[i];
        }

        for (int i = 0; i < n; i++)
        {
            b[i] = scanner.NextInt();
            coordinates[n + i] = b[i];
            prefixB[i + 1] = prefixB[i] + b[i];
        }

        Array.Sort(coordinates);
        int uniqueCount = 0;
        for (int i = 0; i < coordinates.Length; i++)
        {
            if (i == 0 || coordinates[i] != coordinates[i - 1])
                coordinates[uniqueCount++] = coordinates[i];
        }
        Array.Resize(ref coordinates, uniqueCount);

        int[] rankA = new int[n];
        int[] rankB = new int[n];

        for (int i = 0; i < n; i++)
        {
            rankA[i] = Array.BinarySearch(coordinates, a[i]);
            rankB[i] = Array.BinarySearch(coordinates, b[i]);
        }

        int k = scanner.NextInt();
        Query[] queries = new Query[k];

        int hilbertPow = 0;
        while ((1 << hilbertPow) <= n) hilbertPow++;

        for (int i = 0; i < k; i++)
        {
            int x = scanner.NextInt();
            int y = scanner.NextInt();
            queries[i] = new Query
            {
                X = x,
                Y = y,
                Index = i,
                Order = HilbertOrder(x, y, hilbertPow, 0)
            };
        }

        Array.Sort(queries);

        long[] bitA = new long[uniqueCount + 1];
        long[] bitB = new long[uniqueCount + 1];
        long[] answers = new long[k];

        int currentX = 0;
        int currentY = 0;
        long currentAnswer = 0;

        for (int qi = 0; qi < k; qi++)
        {
            Query query = queries[qi];

            while (currentX < query.X)
            {
                int index = currentX;
                currentAnswer += Distance(
                    bitB, rankA[index], a[index],
                    currentY, prefixB[currentY]);

                Update(bitA, rankA[index], a[index], 1);
                currentX++;
            }

            while (currentX > query.X)
            {
                currentX--;
                int index = currentX;

                currentAnswer -= Distance(
                    bitB, rankA[index], a[index],
                    currentY, prefixB[currentY]);

                Update(bitA, rankA[index], a[index], -1);
            }

            while (currentY < query.Y)
            {
                int index = currentY;
                currentAnswer += Distance(
                    bitA, rankB[index], b[index],
                    currentX, prefixA[currentX]);

                Update(bitB, rankB[index], b[index], 1);
                currentY++;
            }

            while (currentY > query.Y)
            {
                currentY--;
                int index = currentY;

                currentAnswer -= Distance(
                    bitA, rankB[index], b[index],
                    currentX, prefixA[currentX]);

                Update(bitB, rankB[index], b[index], -1);
            }

            answers[query.Index] = currentAnswer;
        }

        var output = new StringBuilder(k * 22);
        for (int i = 0; i < k; i++)
            output.Append(answers[i]).Append('\n');

        Console.Write(output.ToString());
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value * sign;
        }
    }
}
