        private int SkipWhiteSpace()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c != -1);
            return c;
        }

        public long NextLong()
        {
            int c = SkipWhiteSpace();
            bool negative = false;

            if (c == '-')
            {
                negative = true;
                c = Read();
            }

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return negative ? -value : value;
        }

        public char NextChar()
        {
            return (char)SkipWhiteSpace();
        }
    }

    private static void Add(
        Dictionary<long, SortedSet<long>> map,
        long key,
        long value)
    {
        SortedSet<long> set;
        if (!map.TryGetValue(key, out set))
        {
            set = new SortedSet<long>();
            map[key] = set;
        }
        set.Add(value);
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = (int)scanner.NextLong();
        int m = (int)scanner.NextLong();
        long x = scanner.NextLong();
        long y = scanner.NextLong();

        var byX = new Dictionary<long, SortedSet<long>>();
        var byY = new Dictionary<long, SortedSet<long>>();

        for (int i = 0; i < n; i++)
        {
            long houseX = scanner.NextLong();
            long houseY = scanner.NextLong();

            Add(byX, houseX, houseY);
            Add(byY, houseY, houseX);
        }

        long visited = 0;

        for (int i = 0; i < m; i++)
        {
            char direction = scanner.NextChar();
            long distance = scanner.NextLong();

            long nextX = x;
            long nextY = y;

            switch (direction)
            {
                case 'U':
                    nextY += distance;
                    break;
                case 'D':
                    nextY -= distance;
                    break;
                case 'L':
                    nextX -= distance;
                    break;
                case 'R':
                    nextX += distance;
                    break;
            }

            if (x == nextX)
            {
                long low = Math.Min(y, nextY);
                long high = Math.Max(y, nextY);

                SortedSet<long> verticalSet;
                if (byX.TryGetValue(x, out verticalSet))
                {
                    var houses = new List<long>();
                    foreach (long houseY in verticalSet.GetViewBetween(low, high))
                    {
                        houses.Add(houseY);
                    }

                    foreach (long houseY in houses)
                    {
                        verticalSet.Remove(houseY);

                        SortedSet<long> horizontalSet = byY[houseY];
                        horizontalSet.Remove(x);
                        if (horizontalSet.Count == 0)
                            byY.Remove(houseY);
                    }

                    if (verticalSet.Count == 0)
                        byX.Remove(x);

                    visited += houses.Count;
                }
            }
            else
            {
                long low = Math.Min(x, nextX);
                long high = Math.Max(x, nextX);

                SortedSet<long> horizontalSet;
                if (byY.TryGetValue(y, out horizontalSet))
                {
                    var houses = new List<long>();
                    foreach (long houseX in horizontalSet.GetViewBetween(low, high))
                    {
                        houses.Add(houseX);
                    }

                    foreach (long houseX in houses)
                    {
                        horizontalSet.Remove(houseX);

                        SortedSet<long> verticalSet = byX[houseX];
                        verticalSet.Remove(y);
                        if (verticalSet.Count == 0)
                            byX.Remove(houseX);
                    }

                    if (horizontalSet.Count == 0)
                        byY.Remove(y);

                    visited += houses.Count;
                }
            }

            x = nextX;
            y = nextY;
        }

        Console.WriteLine(x + " " + y + " " + visited);
    }
}
