        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32);

            int value = 0;
            while (c > 32)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        int[] u = new int[n - 1];
        int[] v = new int[n - 1];
        int[] degree = new int[n];

        for (int i = 0; i < n - 1; i++)
        {
            u[i] = scanner.NextInt() - 1;
            v[i] = scanner.NextInt() - 1;
            degree[u[i]]++;
            degree[v[i]]++;
        }

        int[][] adjacent = new int[n][];
        for (int i = 0; i < n; i++)
            adjacent[i] = new int[degree[i]];

        int[] position = new int[n];
        for (int i = 0; i < n - 1; i++)
        {
            adjacent[u[i]][position[u[i]]++] = v[i];
            adjacent[v[i]][position[v[i]]++] = u[i];
        }

        long maximumRemaining = 0;

        for (int center = 0; center < n; center++)
        {
            int[] capacities = adjacent[center];

            for (int i = 0; i < capacities.Length; i++)
                capacities[i] = degree[capacities[i]] - 1;

            Array.Sort(capacities);

            for (int i = 0; i < capacities.Length; i++)
            {
                int y = capacities[i];
                if (y == 0) continue;

                long x = capacities.Length - i;
                long vertices = 1L + x * (y + 1L);

                if (vertices > maximumRemaining)
                    maximumRemaining = vertices;
            }
        }

        Console.WriteLine(n - maximumRemaining);
    }
