        string s = Console.ReadLine();
        string t = Console.ReadLine();

        if (Math.Abs(s.Length - t.Length) > k)
        {
            Console.WriteLine("No");
            return;
        }

        if (s.Length == t.Length)
        {
            int differences = 0;

            for (int i = 0; i < s.Length; i++)
            {
                if (s[i] != t[i] && ++differences > k)
                {
                    Console.WriteLine("No");
                    return;
                }
            }

            Console.WriteLine("Yes");
            return;
        }

        string shorter = s.Length < t.Length ? s : t;
        string longer = s.Length < t.Length ? t : s;

        int iShort = 0;
        int iLong = 0;
        int edits = 0;

        while (iShort < shorter.Length && iLong < longer.Length)
        {
            if (shorter[iShort] == longer[iLong])
            {
                iShort++;
                iLong++;
            }
            else
            {
                edits++;
                iLong++;

                if (edits > k)
                {
                    Console.WriteLine("No");
                    return;
                }
            }
        }

        edits += longer.Length - iLong;
        Console.WriteLine(edits <= k ? "Yes" : "No");
