using System;

public class Program
{
    public static void Main()
    {
        int k = int.Parse(Console.ReadLine());
        string s = Console.ReadLine();
        string t = Console.ReadLine();

        int n = s.Length;
        int m = t.Length;

        if (Math.Abs(n - m) > k)
        {
            Console.WriteLine("No");
            return;
        }

        int inf = k + 1;
        int width = 2 * k + 3;
        int offset = k + 1;

        int[] previous = new int[width];
        int[] current = new int[width];

        for (int i = 0; i < width; i++)
        {
            previous[i] = inf;
            current[i] = inf;
        }

        int initialRight = Math.Min(m, k);
        for (int j = 0; j <= initialRight; j++)
            previous[offset + j] = j;

        for (int i = 1; i <= n; i++)
        {
            int left = Math.Max(0, i - k);
            int right = Math.Min(m, i + k);

            for (int j = left; j <= right; j++)
            {
                int diagonal = j - i;
                int index = offset + diagonal;

                if (j == 0)
                {
                    current[index] = Math.Min(i, inf);
                    continue;
                }

                int deletion = previous[index + 1] + 1;
                int insertion = current[index - 1] + 1;
                int replacement = previous[index] +
                                  (s[i - 1] == t[j - 1] ? 0 : 1);

                int best = Math.Min(deletion, Math.Min(insertion, replacement));
                current[index] = Math.Min(best, inf);
            }

            int[] temp = previous;
            previous = current;
            current = temp;
        }

        int result = previous[offset + (m - n)];
        Console.WriteLine(result <= k ? "Yes" : "No");
    }
}
