            } while (c <= 32 && c != -1);

            var sb = new StringBuilder();
            while (c > 32 && c != -1)
            {
                sb.Append((char)c);
                c = ReadByte();
            }
            return sb.ToString();
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    private static int[] prefix = new int[1];

    private static int PrimitiveRootLength(string s)
    {
        int n = s.Length;
        if (prefix.Length < n)
            prefix = new int[n];

        prefix[0] = 0;
        for (int i = 1; i < n; i++)
        {
            int j = prefix[i - 1];
            while (j > 0 && s[i] != s[j])
                j = prefix[j - 1];

            if (s[i] == s[j])
                j++;

            prefix[i] = j;
        }

        int period = n - prefix[n - 1];
        return n % period == 0 ? period : n;
    }

    private static int CountOnes(string s)
    {
        int count = 0;
        for (int i = 0; i < s.Length; i++)
            if (s[i] == '1')
                count++;
        return count;
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int t = scanner.NextInt();
        var output = new StringBuilder(t * 4);

        for (int caseIndex = 0; caseIndex < t; caseIndex++)
        {
            string s = scanner.Next();
            string x = scanner.Next();
            string y = scanner.Next();

            long onesX = CountOnes(x);
            long onesY = CountOnes(y);
            long zerosX = x.Length - onesX;
            long zerosY = y.Length - onesY;

            long onesDifference = onesX - onesY;
            bool possible;

            if (onesDifference == 0)
            {
                possible = zerosX == zerosY;
            }
            else
            {
                long numerator = (zerosY - zerosX) * s.Length;

                if (numerator % onesDifference != 0)
                {
                    possible = false;
                }
                else
                {
                    long tLength = numerator / onesDifference;
                    if (tLength < 0)
                    {
                        possible = false;
                    }
                    else
                    {
                        int primitiveLength = PrimitiveRootLength(s);
                        possible = tLength % primitiveLength == 0;
                    }
                }
            }

            output.Append(possible ? "Yes\n" : "No\n");
        }

        Console.Write(output.ToString());
    }
