            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    private sealed class FenwickTree
    {
        private readonly int[] tree;

        public FenwickTree(int size)
        {
            tree = new int[size + 1];
        }

        public void Add(int index, int value)
        {
            for (int i = index; i < tree.Length; i += i & -i)
                tree[i] += value;
        }

        public int Sum(int index)
        {
            int result = 0;
            for (int i = index; i > 0; i -= i & -i)
                result += tree[i];
            return result;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int[] greaterBefore = new int[n];
        var fenwick = new FenwickTree(n);

        long inversions = 0;

        for (int i = 0; i < n; i++)
        {
            int value = scanner.NextInt();
            int greater = i - fenwick.Sum(value);
            greaterBefore[i] = greater;
            inversions += greater;
            fenwick.Add(value, 1);
        }

        int m = scanner.NextInt();
        int[] expire = new int[m];
        int active = 0;
        int previousK = 0;

        var output = new StringBuilder();

        for (int operation = 0; operation < m; operation++)
        {
            int k = scanner.NextInt();

            active -= expire[operation];

            for (int j = previousK; j < k; j++)
            {
                int remaining = greaterBefore[j];
                if (remaining > 0)
                {
                    active++;
                    int endOperation = operation + remaining;
                    if (endOperation < m)
                        expire[endOperation]++;
                }
            }

            previousK = k;
            inversions -= active;
            output.Append(inversions).Append('\n');
        }

        Console.Write(output.ToString());
    }
}
