public class Program
{
    const long Mod = 998244353L;

    static long[][] Multiply(long[][] a, long[][] b)
    {
        int n = a.Length;
        long[][] c = new long[n][];
        for (int i = 0; i < n; i++)
            c[i] = new long[n];

        for (int i = 0; i < n; i++)
        {
            for (int k = 0; k < n; k++)
            {
                long aik = a[i][k];
                if (aik == 0) continue;

                for (int j = 0; j < n; j++)
                {
                    long bkj = b[k][j];
                    if (bkj == 0) continue;
                    c[i][j] = (c[i][j] + aik * bkj) % Mod;
                }
            }
        }

        return c;
    }

    static long[] Multiply(long[][] matrix, long[] vector)
    {
        int n = matrix.Length;
        long[] result = new long[n];

        for (int i = 0; i < n; i++)
        {
            long sum = 0;
            for (int j = 0; j < n; j++)
            {
                if (matrix[i][j] == 0 || vector[j] == 0) continue;
                sum = (sum + matrix[i][j] * vector[j]) % Mod;
            }
            result[i] = sum;
        }

        return result;
    }

    public static void Main()
    {
        FastScanner scanner = new FastScanner(Console.OpenStandardInput());
        long n = scanner.NextLong();
        int m = (int)scanner.NextLong();

        int[] allPrimes = { 2, 3, 5, 7, 11, 13 };
        int primeCount = 0;
        for (int i = 0; i < allPrimes.Length; i++)
            if (allPrimes[i] <= m)
                primeCount++;

        int[] primes = new int[primeCount];
        Array.Copy(allPrimes, primes, primeCount);

        int stateCount = 1 << primeCount;
        long[] coefficient = new long[stateCount];

        for (int value = 1; value <= m; value++)
        {
            int[] exponents = new int[primeCount];
            int x = value;

            for (int i = 0; i < primeCount; i++)
            {
                int p = primes[i];
                while (x % p == 0)
                {
                    exponents[i]++;
                    x /= p;
                }
            }

            for (int mask = 0; mask < stateCount; mask++)
            {
                long product = 1;
                for (int i = 0; i < primeCount; i++)
                {
                    if ((mask & (1 << i)) != 0)
                        product *= exponents[i];
                }
                coefficient[mask] = (coefficient[mask] + product) % Mod;
            }
        }

        int dimension = stateCount + 1;
        int answerIndex = stateCount;

        long[][] transition = new long[dimension][];
        for (int i = 0; i < dimension; i++)
            transition[i] = new long[dimension];

        for (int s = 0; s < stateCount; s++)
        {
            for (int t = 0; t < stateCount; t++)
            {
                if ((t & ~s) != 0) continue;

                long value = coefficient[s ^ t];
                transition[s][t] = value;
                transition[answerIndex][t] =
