            {
                length = input.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0) return -1;
            }
            return buffer[pointer++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = ReadByte();
            }

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value * sign;
        }
    }

    private static long FloorDiv(long value, long divisor)
    {
        long quotient = value / divisor;
        if (value % divisor < 0) quotient--;
        return quotient;
    }

    private static long CalculateCost(long[] values, long k, long m)
    {
        long target = k * m;
        long cost = 0;

        for (int i = 0; i < values.Length; i++)
        {
            long difference = target - values[i];
            cost += difference >= 0 ? difference : -difference;
        }

        return cost;
    }

    public static void Main()
    {
        var scanner = new FastScanner();

        int n = scanner.NextInt();
        int m = scanner.NextInt();

        int[] a = new int[n];
        long[] liftedA = new long[n];

        for (int i = 0; i < n; i++)
        {
            a[i] = scanner.NextInt();

            if (i == 0)
            {
                liftedA[i] = a[i];
            }
            else
            {
                int difference = a[i] - a[i - 1];
                if (difference < 0) difference += m;
                liftedA[i] = liftedA[i - 1] + difference;
            }
        }

        int[] b = new int[n];
        long[] values = new long[n];
        long liftedB = 0;

        for (int i = 0; i < n; i++)
        {
            b[i] = scanner.NextInt();

            if (i == 0)
            {
                liftedB = b[i];
            }
            else
            {
                int difference = b[i] - b[i - 1];
                if (difference < 0) difference += m;
                liftedB += difference;
            }

            values[i] = liftedA[i] - liftedB;
        }

        if (m == 2)
        {
            for (int i = 0; i < n; i++)
            {
                if (a[i] != b[i])
                {
                    Console.WriteLine(-1);
                    return;
                }
            }

            Console.WriteLine(0);
            return;
        }

        Array.Sort(values);

        long median = values[n / 2];
        long k = FloorDiv(median, m);

        long answer1 = CalculateCost(values, k, m);
        long answer2 = CalculateCost(values, k + 1, m);

        Console.WriteLine(Math.Min(answer1, answer2));
    }
