using System;
using System.IO;

public class Program
{
    private struct Stats
    {
        public decimal F; // Sum of floor values
        public decimal G; // Sum of i * floor value
        public decimal H; // Sum of squared floor values

        public Stats(decimal f, decimal g, decimal h)
        {
            F = f;
            G = g;
            H = h;
        }
    }

    private struct PrefixResult
    {
        public long Count;
        public long Sum;

        public PrefixResult(long count, long sum)
        {
            Count = count;
            Sum = sum;
        }
    }

    private sealed class ModularPrefixCalculator
    {
        private readonly long n;
        private readonly long m;
        private readonly long a;
        private readonly Stats baseStats;
        private readonly decimal totalResidueSum;

        public ModularPrefixCalculator(long n, long m, long a)
        {
            this.n = n;
            this.m = m;
            this.a = a;

            baseStats = FloorStats(n, m, a, 0);
            totalResidueSum =
                (decimal)a * SumI(n) - (decimal)m * baseStats.F;
        }

        // For residues (a*k mod m), 0 <= k < n:
        // returns their count and sum among residues less than t.
        public PrefixResult Get(long t)
        {
            if (t <= 0)
                return new PrefixResult(0, 0);

            if (t >= m)
                return new PrefixResult(n, (long)totalResidueSum);

            Stats shifted = FloorStats(n, m, a, m - t);

            decimal greaterOrEqualCount = shifted.F - baseStats.F;
            decimal indexSum = shifted.G - baseStats.G;
            decimal quotientSum =
                (shifted.H - baseStats.H - greaterOrEqualCount) / 2m;

            decimal greaterOrEqualResidueSum =
                (decimal)a * indexSum - (decimal)m * quotientSum;

            long countLess = n - (long)greaterOrEqualCount;
            long sumLess = (long)(totalResidueSum - greaterOrEqualResidueSum);

            return new PrefixResult(countLess, sumLess);
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        int n = (int)scanner.NextLong();
        long m = scanner.NextLong();
        long c = scanner.NextLong();
        long k = scanner.NextLong();

        long[] markersRaw = new long[n];
        long minimumA = long.MaxValue;

        for (int i = 0; i < n; i++)
        {
            long value = scanner.NextLong();
            if (value < minimumA)
                minimumA = value;

            markersRaw[i] = value == 0 ? 0 : m - value;
        }

        if (c == 0)
        {
            Console.WriteLine(k * minimumA);
            return;
        }

        Array.Sort(markersRaw);

        int uniqueCount = 0;
        for (int i = 0; i < n; i++)
        {
            if (i == 0 || markersRaw[i] != markersRaw[i - 1])
                markersRaw[uniqueCount++] = markersRaw[i];
        }

        long[] markers = new long[uniqueCount];
        Array.Copy(markersRaw, markers, uniqueCount);

        long gcd = Gcd(c, m);
        long orbitLength = m / gcd;
        long step = c / gcd;

        long[] boundaries = new long[uniqueCount];
        for (int i = 0; i < uniqueCount; i++)
            boundaries[i] = (markers[i] + gcd - 1) / gcd;

        PrefixResult[] fullPrefixes = new PrefixResult[uniqueCount];
        for (int i = 0; i < uniqueCount; i++)
            fullPrefixes[i] = FullPrefix(boundaries[i]);

        PrefixResult fullEnd = FullPrefix(orbitLength);
        long periodSum = Aggregate(
            markers, fullPrefixes, fullEnd, gcd, m);

        long periods = k / orbitLength;
        long remainder = k % orbitLength;
        long remainderSum = 0;

        if (remainder > 0)
        {
            var calculator =
                new ModularPrefixCalculator(remainder, orbitLength, step);

            PrefixResult[] remainderPrefixes =
                new PrefixResult[uniqueCount];

            long previousBoundary = -1;
            PrefixResult previousResult = new PrefixResult();

            for (int i = 0; i < uniqueCount; i++)
            {
                if (boundaries[i] == previousBoundary)
                {
                    remainderPrefixes[i] = previousResult;
                }
                else
                {
                    previousBoundary = boundaries[i];
                    previousResult = calculator.Get(previousBoundary);
                    remainderPrefixes[i] = previousResult;
                }
            }

            PrefixResult remainderEnd = calculator.Get(orbitLength);
            remainderSum = Aggregate(
                markers, remainderPrefixes, remainderEnd, gcd, m);
        }

        long answer = periods * periodSum + remainderSum;
        Console.WriteLine(answer);
    }

    private static long Aggregate(
        long[] markers,
        PrefixResult[] boundaryPrefixes,
        PrefixResult endPrefix,
        long scale,
        long modulus)
    {
        int count = markers.Length;
        PrefixResult zero = new PrefixResult(0, 0);
        long result = 0;

        // Circular interval [0, first marker).
        result += RangeContribution(
            zero,
            boundaryPrefixes[0],
            scale,
            modulus - markers[count - 1]);

        // Intervals [marker[i], marker[i + 1]).
        for (int i = 0; i + 1 < count; i++)
        {
            result += RangeContribution(
                boundaryPrefixes[i],
                boundaryPrefixes[i + 1],
                scale,
                -markers[i]);
        }

        // Final interval [last marker, modulus).
        result += RangeContribution(
            boundaryPrefixes[count - 1],
            endPrefix,
            scale,
            -markers[count - 1]);

        return result;
    }

    private static long RangeContribution(
        PrefixResult left,
        PrefixResult right,
        long scale,
        long offset)
    {
        long count = right.Count - left.Count;
        long sum = right.Sum - left.Sum;
        return scale * sum + offset * count;
    }

    private static PrefixResult FullPrefix(long t)
    {
        return new PrefixResult(t, t * (t - 1) / 2);
    }

    private static decimal SumI(long n)
    {
        return (decimal)n * (n - 1) / 2m;
    }

    private static decimal SumI2(long n)
    {
        return (decimal)n * (n - 1) * (2m * n - 1m) / 6m;
    }

    // Calculates, for 0 <= i < n and y_i = floor((a*i+b)/m):
    // F = sum y_i, G = sum i*y_i, H = sum y_i^2.
    private static Stats FloorStats(long n, long m, long a, long b)
    {
        if (n == 0)
            return new Stats(0m, 0m, 0m);

        long coefficientPart = a / m;
        long constantPart = b / m;
        a %= m;
        b %= m;

        if (coefficientPart != 0 || constantPart != 0)
        {
            Stats reduced = FloorStats(n, m, a, b);

            decimal p = coefficientPart;
            decimal q = constantPart;
            decimal s1 = SumI(n);
            decimal s2 = SumI2(n);

            decimal f =
                p * s1 +
                q * n +
                reduced.F;

            decimal g =
                p * s2 +
                q * s1 +
                reduced.G;

            decimal h =
                reduced.H +
                p * p * s2 +
                q * q * n +
                2m * p * q * s1 +
                2m * p * reduced.G +
                2m * q * reduced.F;

            return new Stats(f, g, h);
        }

        if (a == 0)
            return new Stats(0m, 0m, 0m);

        long maximum = (a * (n - 1) + b) / m;
        if (maximum == 0)
            return new Stats(0m, 0m, 0m);

        Stats transposed =
            FloorStats(maximum, a, m, m - b + a - 1);

        decimal y = maximum;

        decimal fResult =
            y * n - transposed.F;

        decimal gResult =
            y * SumI(n) -
            (transposed.H - transposed.F) / 2m;

        decimal hResult =
            (decimal)n * y * y -
            (2m * transposed.G + transposed.F);

        return new Stats(fResult, gResult, hResult);
    }

    private static long Gcd(long a, long b)
    {
        while (b != 0)
        {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        private int Read()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0)
                    return -1;
            }

            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32 && c >= 0);

            long sign = 1;
            if (c == '-')
            {
                sign = -1;
                c = Read();
            }

            long value = 0;
            while (c > 32)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }

            return value * sign;
        }
    }
}
