    public static void Main()
    {
        string[] input = Console.ReadLine().Split();
        int n = int.Parse(input[0]);
        int k = int.Parse(input[1]);

        int[] counts = new int[n + 1];
        for (int i = 1; i <= n; i++)
            counts[i] = k;

        StringBuilder answer = new StringBuilder(n * k * 4);
        bool first = true;

        Action<int> append = value =>
        {
            if (!first)
                answer.Append(' ');
            answer.Append(value);
            first = false;
        };

        if (n == 1)
        {
            for (int i = 0; i < k; i++)
                append(1);
        }
        else if (n % 2 == 0)
        {
            int middle = n / 2;
            append(middle);
            counts[middle]--;

            for (int value = n; value >= 1; value--)
            {
                for (int j = 0; j < counts[value]; j++)
                    append(value);
            }
        }
        else
        {
            int middle = (n + 1) / 2;

            for (int i = 0; i < k; i++)
                append(middle);
            counts[middle] = 0;

            append(middle - 1);
            counts[middle - 1]--;

            for (int value = n; value >= 1; value--)
            {
                for (int j = 0; j < counts[value]; j++)
                    append(value);
            }
        }

        Console.WriteLine(answer.ToString());
