        int t = scanner.NextInt();
        var output = new StringBuilder();

        for (int test = 0; test < t; test++)
        {
            int n = scanner.NextInt();
            int k = scanner.NextInt();

            var a = new int[n];
            var b = new int[n];
            var presentInA = new bool[n + 1];

            for (int i = 0; i < n; i++)
            {
                a[i] = scanner.NextInt();
                presentInA[a[i]] = true;
            }

            bool same = true;
            bool supportIncluded = true;
            bool hasCloseEqualPair = false;
            var lastPosition = new int[n + 1];

            for (int i = 0; i < n; i++)
            {
                b[i] = scanner.NextInt();

                if (b[i] != a[i])
                    same = false;

                if (!presentInA[b[i]])
                    supportIncluded = false;

                int previous = lastPosition[b[i]];
                if (previous != 0 && (i + 1) - previous <= k)
                    hasCloseEqualPair = true;

                lastPosition[b[i]] = i + 1;
            }

            bool possible;

            if (k == 1)
            {
                var compressedA = new int[n];
                var compressedB = new int[n];
                int countA = 0;
                int countB = 0;

                for (int i = 0; i < n; i++)
                {
                    if (i == 0 || a[i] != a[i - 1])
                        compressedA[countA++] = a[i];

                    if (i == 0 || b[i] != b[i - 1])
                        compressedB[countB++] = b[i];
                }

                int matched = 0;
                for (int i = 0; i < countA && matched < countB; i++)
                {
                    if (compressedA[i] == compressedB[matched])
                        matched++;
                }

                possible = matched == countB;
            }
            else
            {
                possible = supportIncluded && (same || hasCloseEqualPair);
            }

            output.Append(possible ? "Yes\n" : "No\n");
        }

        Console.Write(output.ToString());
    }
