public class Program
{
    private const int Mod = 998244353;

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        int m = scanner.NextInt();

        int[][] minR = new int[n + 2][];
        for (int i = 0; i < n + 2; i++)
        {
            minR[i] = new int[n + 2];
            for (int j = 0; j < n + 2; j++)
                minR[i][j] = n + 1;
        }

        for (int i = 0; i < m; i++)
        {
            int l = scanner.NextInt();
            int r = scanner.NextInt();
            int x = scanner.NextInt();

            if (r < minR[x][l])
                minR[x][l] = r;
        }

        // minR[x][l] is the minimum R among conditions for x whose L >= l.
        for (int x = 1; x <= n; x++)
        {
            for (int l = x - 1; l >= 1; l--)
            {
                if (minR[x][l + 1] < minR[x][l])
                    minR[x][l] = minR[x][l + 1];
            }
        }

        int[][] combination = new int[n + 1][];
        for (int i = 0; i <= n; i++)
            combination[i] = new int[n + 1];

        combination[0][0] = 1;
        for (int i = 1; i <= n; i++)
        {
            combination[i][0] = 1;
            combination[i][i] = 1;
            for (int j = 1; j < i; j++)
            {
                int value = combination[i - 1][j - 1] + combination[i - 1][j];
                if (value >= Mod) value -= Mod;
                combination[i][j] = value;
            }
        }

        int[][] dp = new int[n + 2][];
        for (int i = 0; i < n + 2; i++)
            dp[i] = new int[n + 2];

        for (int i = 1; i <= n + 1; i++)
            dp[i][i - 1] = 1;

        for (int length = 1; length <= n; length++)
        {
            int chooseN = length - 1;

            for (int left = 1; left + length - 1 <= n; left++)
            {
                int right = left + length - 1;
                long ways = 0;

                for (int root = left; root <= right; root++)
                {
                    // A condition is violated exactly when its whole interval
                    // is contained in the Cartesian-tree subtree [left, right].
                    if (minR[root][left] <= right)
                        continue;

                    long current = (long)dp[left][root - 1] * dp[root + 1][right] % Mod;
                    current = current * combination[chooseN][root - left] % Mod;

                    ways += current;
                    if (ways >= Mod)
                        ways -= Mod;
                }

                dp[left][right] = (int)ways;
            }
        }

        Console.WriteLine(dp[1][n]);
    }

