using System;
using System.IO;
using System.Text;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int pointer;

        public int NextInt()
        {
            int c;
            do
            {
                c = Read();
            } while (c <= 32);

            int value = 0;
            while (c > 32)
            {
                value = value * 10 + (c - '0');
                c = Read();
            }
            return value;
        }

        private int Read()
        {
            if (pointer >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0) return -1;
            }
            return buffer[pointer++];
        }
    }

    private sealed class DisjointSetUnion
    {
        private readonly int[] parent;
        private readonly int[] size;

        public DisjointSetUnion(int n)
        {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++)
            {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int Find(int x)
        {
            int root = x;
            while (parent[root] != root)
                root = parent[root];

            while (parent[x] != x)
            {
                int next = parent[x];
                parent[x] = root;
                x = next;
            }
            return root;
        }

        public void Unite(int a, int b)
        {
            a = Find(a);
            b = Find(b);
            if (a == b) return;

            if (size[a] < size[b])
            {
                int t = a;
                a = b;
                b = t;
            }

            parent[b] = a;
            size[a] += size[b];
        }
    }

    private static int n;
    private static int[] head;
    private static int[] to;
    private static int[] next;
    private static int edgeCount;

    private static void AddEdge(int a, int b)
    {
        to[edgeCount] = b;
        next[edgeCount] = head[a];
        head[a] = edgeCount++;
    }

    private static void RootTree(int root, int[] parent, int[] order, int[] subtree)
    {
        int[] stack = new int[n];
        int top = 0;
        int count = 0;

        parent[root] = -1;
        stack[top++] = root;

        while (top > 0)
        {
            int v = stack[--top];
            order[count++] = v;

            for (int e = head[v]; e != -1; e = next[e])
            {
                int u = to[e];
                if (u == parent[v]) continue;
                parent[u] = v;
                stack[top++] = u;
            }
        }

        for (int i = 0; i < n; i++)
            subtree[i] = 1;

        for (int i = n - 1; i > 0; i--)
        {
            int v = order[i];
            subtree[parent[v]] += subtree[v];
        }
    }

    public static void Main()
    {
        FastScanner fs = new FastScanner();
        n = fs.NextInt();
        int operationCount = n / 2;

        head = new int[n];
        for (int i = 0; i < n; i++) head[i] = -1;

        to = new int[2 * (n - 1)];
        next = new int[2 * (n - 1)];
        edgeCount = 0;

        for (int i = 0; i < n - 1; i++)
        {
            int a = fs.NextInt() - 1;
            int b = fs.NextInt() - 1;
            AddEdge(a, b);
            AddEdge(b, a);
        }

        int[] parent = new int[n];
        int[] traversal = new int[n];
        int[] subtree = new int[n];

        RootTree(0, parent, traversal, subtree);

        int centroid = 0;
        for (int v = 0; v < n; v++)
        {
            int largest = n - subtree[v];
            for (int e = head[v]; e != -1; e = next[e])
            {
                int u = to[e];
                if (parent[u] == v && subtree[u] > largest)
                    largest = subtree[u];
            }

            if (largest * 2 <= n)
            {
                centroid = v;
                break;
            }
        }

        RootTree(centroid, parent, traversal, subtree);

        int childCount = 0;
        for (int e = head[centroid]; e != -1; e = next[e])
        {
            if (parent[to[e]] == centroid)
                childCount++;
        }

        int groupCount = childCount + 1;
        int centerGroup = groupCount - 1;

        int[] groupRoot = new int[groupCount];
        int[] degree = new int[groupCount];

        int groupIndex = 0;
        for (int e = head[centroid]; e != -1; e = next[e])
        {
            int u = to[e];
            if (parent[u] == centroid)
            {
                groupRoot[groupIndex] = u;
                degree[groupIndex] = subtree[u];
                groupIndex++;
            }
        }

        groupRoot[centerGroup] = centroid;
        degree[centerGroup] = 1;

        int startGroup = -1;
        for (int i = 0; i < centerGroup; i++)
        {
            if ((degree[i] & 1) != 0)
            {
                startGroup = i;
                break;
            }
        }

        int[] deletionOrder = new int[n];
        int[] groupStart = new int[groupCount];
        int[] groupPosition = new int[groupCount];
        int deletionCount = 0;
        int[] dfsStack = new int[2 * n + 5];

        for (int g = 0; g < centerGroup; g++)
        {
            groupStart[g] = deletionCount;
            int top = 0;
            dfsStack[top++] = groupRoot[g];

            while (top > 0)
            {
                int value = dfsStack[--top];

                if (value < 0)
                {
                    deletionOrder[deletionCount++] = ~value;
                    continue;
                }

                int v = value;
                dfsStack[top++] = ~v;

                int oddChild = -1;
                for (int e = head[v]; e != -1; e = next[e])
                {
                    int u = to[e];
                    if (parent[u] == v && (subtree[u] & 1) != 0)
                    {
                        oddChild = u;
                        break;
                    }
                }

                for (int e = head[v]; e != -1; e = next[e])
                {
                    int u = to[e];
                    if (parent[u] == v && u != oddChild)
                        dfsStack[top++] = u;
                }

                if (oddChild != -1)
                    dfsStack[top++] = oddChild;
            }
        }

        groupStart[centerGroup] = deletionCount;
        deletionOrder[deletionCount++] = centroid;

        int[] stubs = new int[n];
        int stubCount = 0;
        for (int g = 0; g < groupCount; g++)
        {
            for (int j = 0; j < degree[g]; j++)
                stubs[stubCount++] = g;
        }

        int[] edgeU = new int[operationCount];
        int[] edgeV = new int[operationCount];
        DisjointSetUnion dsu = new DisjointSetUnion(groupCount);

        for (int i = 0; i < operationCount; i++)
        {
            edgeU[i] = stubs[i];
            edgeV[i] = stubs[i + operationCount];
            dsu.Unite(edgeU[i], edgeV[i]);
        }

        int[] representativeEdge = new int[groupCount];
        bool[] seenComponent = new bool[groupCount];
        for (int i = 0; i < groupCount; i++)
            representativeEdge[i] = -1;

        for (int i = 0; i < operationCount; i++)
        {
            int root = dsu.Find(edgeU[i]);
            representativeEdge[root] = i;
        }

        int mainComponent = dsu.Find(startGroup);
        int mainEdge = representativeEdge[mainComponent];

        for (int g = 0; g < groupCount; g++)
        {
            int component = dsu.Find(g);
            if (seenComponent[component]) continue;
            seenComponent[component] = true;

            if (component == mainComponent) continue;

            int otherEdge = representativeEdge[component];

            int a = edgeU[mainEdge];
            int b = edgeV[mainEdge];
            int c = edgeU[otherEdge];
            int d = edgeV[otherEdge];

            edgeU[mainEdge] = a;
            edgeV[mainEdge] = c;
            edgeU[otherEdge] = b;
            edgeV[otherEdge] = d;
        }

        int[] graphHead = new int[groupCount];
        for (int i = 0; i < groupCount; i++) graphHead[i] = -1;

        int[] graphTo = new int[2 * operationCount];
        int[] graphNext = new int[2 * operationCount];
        int[] graphEdgeId = new int[2 * operationCount];
        int graphEdgeCount = 0;

        for (int i = 0; i < operationCount; i++)
        {
            int a = edgeU[i];
            int b = edgeV[i];

            graphTo[graphEdgeCount] = b;
            graphEdgeId[graphEdgeCount] = i;
            graphNext[graphEdgeCount] = graphHead[a];
            graphHead[a] = graphEdgeCount++;

            graphTo[graphEdgeCount] = a;
            graphEdgeId[graphEdgeCount] = i;
            graphNext[graphEdgeCount] = graphHead[b];
            graphHead[b] = graphEdgeCount++;
        }

        int[] iterator = new int[groupCount];
        Array.Copy(graphHead, iterator, groupCount);

        bool[] usedEdge = new bool[operationCount];
        int[] eulerStack = new int[operationCount + 2];
        int[] trail = new int[operationCount + 1];

        int eulerTop = 0;
        int trailLength = 0;
        eulerStack[eulerTop++] = startGroup;

        while (eulerTop > 0)
        {
            int v = eulerStack[eulerTop - 1];
            int e = iterator[v];

            while (e != -1 && usedEdge[graphEdgeId[e]])
                e = graphNext[e];

            iterator[v] = e;

            if (e == -1)
            {
                trail[trailLength++] = v;
                eulerTop--;
            }
            else
            {
                iterator[v] = graphNext[e];
                int id = graphEdgeId[e];
                if (!usedEdge[id])
                {
                    usedEdge[id] = true;
                    eulerStack[eulerTop++] = graphTo[e];
                }
            }
        }

        for (int i = 0, j = trailLength - 1; i < j; i++, j--)
        {
            int t = trail[i];
            trail[i] = trail[j];
            trail[j] = t;
        }

        StringBuilder output = new StringBuilder(operationCount * 16);

        for (int i = 0; i < operationCount; i++)
        {
            int groupA = trail[i];
            int groupB = trail[i + 1];

            int vertexA = deletionOrder[groupStart[groupA] + groupPosition[groupA]++];
            int vertexB = deletionOrder[groupStart[groupB] + groupPosition[groupB]++];

            output.Append(vertexA + 1);
            output.Append(' ');
            output.Append(vertexB + 1);
            output.Append('\n');
        }

        Console.Write(output.ToString());
    }
}
