public class Program
{
    const long Mod = 998244353;
    static int n;
    static int[] y;
    static int[] suffixMax;

    // Returns whether the open rectangle between vertices a and b
    // contains no isolated point in its induced comparability graph.
    static bool IsValidEdge(int a, int b)
    {
        int low = y[b];
        int high = y[a];

        suffixMax[b] = int.MinValue;

        for (int i = b - 1; i > a; i--)
        {
            suffixMax[i] = suffixMax[i + 1];
            if (low < y[i] && y[i] < high && y[i] > suffixMax[i])
                suffixMax[i] = y[i];
        }

        int prefixMin = int.MaxValue;

        for (int i = a + 1; i < b; i++)
        {
            if (low < y[i] && y[i] < high)
            {
                bool hasSouthwest = prefixMin < y[i];
                bool hasNortheast = suffixMax[i + 1] > y[i];

                if (!hasSouthwest && !hasNortheast)
                    return false;

                if (y[i] < prefixMin)
                    prefixMin = y[i];
            }
        }

        return true;
    }

    public static void Main()
    {
        FastScanner fs = new FastScanner(Console.OpenStandardInput());

        n = fs.NextInt();
        y = new int[n + 2];
        suffixMax = new int[n + 2];

        for (int i = 0; i < n; i++)
        {
            int x = fs.NextInt();
            int valueY = fs.NextInt();
            y[x] = valueY;
        }

        // Artificial upper-left and lower-right boundary points.
        y[0] = n + 1;
        y[n + 1] = 0;

        long[] dp = new long[n + 2];
        dp[0] = 1;

        for (int b = 1; b <= n + 1; b++)
        {
            long ways = 0;

            for (int a = 0; a < b; a++)
            {
                if (y[a] > y[b] && IsValidEdge(a, b))
                {
                    ways += dp[a];
                    if (ways >= Mod)
                        ways -= Mod;
                }
            }

            dp[b] = ways;
        }

        Console.WriteLine(dp[n + 1]);
    }

