using System;
using System.Collections.Generic;
using System.IO;

public class Program
{
    const long Mod = 998244353L;

    struct HashKey : IEquatable<HashKey>
    {
        public ulong A;
        public ulong B;

        public HashKey(ulong a, ulong b)
        {
            A = a;
            B = b;
        }

        public bool Equals(HashKey other)
        {
            return A == other.A && B == other.B;
        }

        public override bool Equals(object obj)
        {
            return obj is HashKey && Equals((HashKey)obj);
        }

        public override int GetHashCode()
        {
            unchecked
            {
                ulong x = A ^ (B + 0x9E3779B97F4A7C15UL + (A << 6) + (A >> 2));
                return (int)(x ^ (x >> 32));
            }
        }
    }

    sealed class Group
    {
        public ulong[] Bits;
        public int Period;
        public int[] Fenwick;
        public long Count;
        public long SumPhase;
        public int NextCollision;
    }

    sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int pointer;

        private int ReadByte()
        {
            if (pointer >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                pointer = 0;
                if (length == 0) return -1;
            }
            return buffer[pointer++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c >= 0);

            int value = 0;
            while (c > 32)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    static ulong Mix(ulong z)
    {
        z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
        z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
        return z ^ (z >> 31);
    }

    static HashKey ComputeHash(ulong[] bits, int m)
    {
        ulong h1 = 0x243F6A8885A308D3UL ^ (ulong)m;
        ulong h2 = 0x13198A2E03707344UL + (ulong)m;

        for (int i = 0; i < bits.Length; i++)
        {
            ulong x = bits[i];
            h1 = Mix(h1 ^ (x + 0x9E3779B97F4A7C15UL + (ulong)i));
            h2 = Mix(h2 + (x ^ 0xD1B54A32D192ED03UL) + (ulong)i * 0x94D049BB133111EBUL);
        }

        return new HashKey(h1, h2);
    }

    static bool SameBits(ulong[] a, ulong[] b)
    {
        for (int i = 0; i < a.Length; i++)
        {
            if (a[i] != b[i]) return false;
        }
        return true;
    }

    static int FenwickPrefix(int[] tree, int phase)
    {
        int result = 0;
        for (int i = phase + 1; i > 0; i -= i & -i)
            result += tree[i];
        return result;
    }

    static void FenwickAdd(int[] tree, int phase)
    {
        for (int i = phase + 1; i < tree.Length; i += i & -i)
            tree[i]++;
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int m = scanner.NextInt();

        byte[] row = new byte[m];
        int wordCount = (m + 63) >> 6;
        ulong[] packed = new ulong[wordCount];

        int initialCapacity;
        if (m < 20)
            initialCapacity = Math.Min(n, 1 << m);
        else
            initialCapacity = n;

        var hashHeads = new Dictionary<HashKey, int>(initialCapacity);
        var groups = new List<Group>(initialCapacity);

        long answer = 0;

        for (int sequenceIndex = 0; sequenceIndex < n; sequenceIndex++)
        {
            int firstOne = -1;

            for (int j = 0; j < m; j++)
            {
                byte value = (byte)scanner.NextInt();
                row[j] = value;
                if (value != 0 && firstOne < 0)
                    firstOne = j;
            }

            int phase = 0;
            int period = 1;

            if (firstOne >= 0)
            {
                int length = m - firstOne;
                while (period < length)
                    period <<= 1;

                for (int shift = 1; shift < length; shift <<= 1)
                {
                    if (row[firstOne + shift] == 0)
                        continue;

                    phase += shift;

                    for (int k = length - 1; k >= shift; k--)
                        row[firstOne + k] ^= row[firstOne + k - shift];
                }
            }

            for (int w = 0; w < wordCount; w++)
            {
                int start = w << 6;
                int end = Math.Min(start + 64, m);
                ulong value = 0;

                for (int j = start; j < end; j++)
                {
                    if (row[j] != 0)
                        value |= 1UL << (j - start);
                }

                packed[w] = value;
            }

            HashKey key = ComputeHash(packed, m);
            int head;
            int groupIndex = -1;

            if (hashHeads.TryGetValue(key, out head))
            {
                for (int index = head; index >= 0; index = groups[index].NextCollision)
                {
                    if (SameBits(groups[index].Bits, packed))
                    {
                        groupIndex = index;
                        break;
                    }
                }
            }
            else
            {
                head = -1;
            }

            if (groupIndex < 0)
            {
                ulong[] storedBits = new ulong[wordCount];
                Array.Copy(packed, storedBits, wordCount);

                var group = new Group
                {
                    Bits = storedBits,
                    Period = period,
                    Fenwick = period > 1 ? new int[period + 1] : null,
                    Count = 0,
                    SumPhase = 0,
                    NextCollision = head
                };

                groupIndex = groups.Count;
                groups.Add(group);
                hashHeads[key] = groupIndex;
            }

            Group current = groups[groupIndex];

            if (current.Period > 1)
            {
                long notGreater = FenwickPrefix(current.Fenwick, phase);
                long greater = current.Count - notGreater;

                long contribution =
                    current.Count * phase -
                    current.SumPhase +
                    (long)current.Period * greater;

                answer += contribution % Mod;
                if (answer >= Mod)
                    answer %= Mod;

                FenwickAdd(current.Fenwick, phase);
            }

            current.Count++;
            current.SumPhase += phase;
        }

        Console.WriteLine(answer % Mod);
    }
}
