using System;
using System.IO;

public static class Program
{
    private const int Mod = 998244353;
    private const int Root = 3;
    private const int RootInverse = 332748118;

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        int x = scanner.NextInt();

        int[] values = new int[n];
        int[] frequency = new int[x + 1];

        int maxEligibleValue = 0;
        int eligibleCount = 0;

        for (int i = 0; i < n; i++)
        {
            int value = scanner.NextInt();
            values[i] = value;
            frequency[value]++;

            if (value <= x - 2)
            {
                eligibleCount++;
                if (value > maxEligibleValue)
                    maxEligibleValue = value;
            }
        }

        if (x < 3 || eligibleCount < 3)
        {
            Console.WriteLine("-1");
            return;
        }

        int transformSize = 1;
        while (transformSize <= 2 * maxEligibleValue)
            transformSize <<= 1;

        int[] convolution = new int[transformSize];

        for (int value = 1; value <= maxEligibleValue; value++)
        {
            if (frequency[value] > 0)
                convolution[value] = 1;
        }

        Ntt(convolution, false);

        for (int i = 0; i < transformSize; i++)
            convolution[i] = (int)((long)convolution[i] * convolution[i] % Mod);

        Ntt(convolution, true);

        for (int c = 1; c <= maxEligibleValue; c++)
        {
            if (frequency[c] == 0)
                continue;

            int pairSum = x - c;
            if (pairSum < 2 || pairSum >= transformSize)
                continue;

            int pairCount = convolution[pairSum];

            // Remove a diagonal pair (v, v) when only one occurrence of v exists.
            if ((pairSum & 1) == 0)
            {
                int v = pairSum / 2;
                if (v <= x && frequency[v] == 1)
                    pairCount--;
            }

            // The selected occurrence of c must not also be used in the pair.
            if (frequency[c] == 1)
            {
                int other = pairSum - c;
                if (other != c && other >= 1 && other <= x && frequency[other] > 0)
                    pairCount -= 2;
            }
            else if (frequency[c] == 2 && pairSum == 2 * c)
            {
                pairCount--;
            }

            if (pairCount <= 0)
                continue;

            for (int a = 1; a < pairSum; a++)
            {
                int b = pairSum - a;

                if (a > x || b > x || frequency[a] == 0 || frequency[b] == 0)
                    continue;

                bool valid;
                if (a == b && b == c)
                {
                    valid = frequency[a] >= 3;
                }
                else if (a == b)
                {
                    valid = frequency[a] >= 2;
                }
                else if (a == c)
                {
                    valid = frequency[a] >= 2;
                }
                else if (b == c)
                {
                    valid = frequency[b] >= 2;
                }
                else
                {
                    valid = true;
                }

                if (!valid)
                    continue;

                PrintIndices(values, a, b, c);
                return;
            }
        }

        Console.WriteLine("-1");
    }

    private static void PrintIndices(int[] input, int a, int b, int c)
    {
        int[] wanted = { a, b, c };
        bool[] used = new bool[3];
        int[] answer = new int[3];
        int found = 0;

        for (int i = 0; i < input.Length && found < 3; i++)
        {
            for (int j = 0; j < 3; j++)
            {
                if (!used[j] && input[i] == wanted[j])
                {
                    used[j] = true;
                    answer[found++] = i + 1;
                    break;
                }
            }
        }

        Console.WriteLine(answer[0] + " " + answer[1] + " " + answer[2]);
    }

    private static void Ntt(int[] a, bool inverse)
    {
        int n = a.Length;

        for (int i = 1, j = 0; i < n; i++)
        {
            int bit = n >> 1;
            while ((j & bit) != 0)
            {
                j ^= bit;
                bit >>= 1;
            }

            j ^= bit;

            if (i < j)
            {
                int temp = a[i];
                a[i] = a[j];
                a[j] = temp;
            }
        }

        for (int length = 2; length <= n; length <<= 1)
        {
            int root = inverse ? RootInverse : Root;
            int rootStep = ModPow(root, (Mod - 1) / length);
            int half = length >> 1;

            for (int start = 0; start < n; start += length)
            {
                long w = 1;

                for (int j = 0; j < half; j++)
                {
                    int left = a[start + j];
                    int right = (int)(a[start + j + half] * w % Mod);

                    int sum = left + right;
                    if (sum >= Mod)
                        sum -= Mod;

                    int difference = left - right;
                    if (difference < 0)
                        difference += Mod;

                    a[start + j] = sum;
                    a[start + j + half] = difference;

                    w = w * rootStep % Mod;
                }
            }
        }

        if (inverse)
        {
            int inverseN = ModPow(n, Mod - 2);
            for (int i = 0; i < n; i++)
                a[i] = (int)((long)a[i] * inverseN % Mod);
        }
    }

    private static int ModPow(int value, int exponent)
    {
        long result = 1;
        long current = value;

        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * current % Mod;

            current = current * current % Mod;
            exponent >>= 1;
        }

        return (int)result;
    }

    private sealed class FastScanner
    {
        private readonly Stream stream;
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        public FastScanner(Stream stream)
        {
            this.stream = stream;
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32);

            int result = 0;
            while (c > 32)
            {
                result = result * 10 + (c - '0');
                c = ReadByte();
            }

            return result;
        }

