public static class Program
{
    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int q = scanner.NextInt();

        int maxCells = n * n;
        int words = maxCells / 64 + 1;
        int size = n + 1;

        ulong[] dp = new ulong[size * size * words];

        Func<int, int, int> Offset = (r, c) => (r * size + c) * words;
        dp[Offset(0, 0)] = 1UL;

        for (int rows = 2; rows <= n; rows++)
        {
            for (int cols = 2; cols <= n; cols++)
            {
                int destination = Offset(rows, cols);

                for (int addedRows = 2; addedRows <= rows; addedRows++)
                {
                    int previousRows = rows - addedRows;

                    for (int addedCols = 2; addedCols <= cols; addedCols++)
                    {
                        int previousCols = cols - addedCols;
                        int source = Offset(previousRows, previousCols);

                        int shift = addedRows * addedCols;
                        int wordShift = shift >> 6;
                        int bitShift = shift & 63;

                        for (int w = 0; w + wordShift < words; w++)
                        {
                            ulong value = dp[source + w];
                            if (value == 0) continue;

                            int targetWord = destination + w + wordShift;
                            dp[targetWord] |= value << bitShift;

                            if (bitShift != 0 && w + wordShift + 1 < words)
                            {
                                dp[targetWord + 1] |= value >> (64 - bitShift);
                            }
                        }
                    }
                }
            }
        }

        ulong[] possibleNonFixed = new ulong[words];

        for (int rows = 0; rows <= n; rows++)
        {
            for (int cols = 0; cols <= n; cols++)
            {
                int source = Offset(rows, cols);
                for (int w = 0; w < words; w++)
                {
                    possibleNonFixed[w] |= dp[source + w];
                }
            }
        }

        var output = new StringBuilder();

        for (int query = 0; query < q; query++)
        {
            int fixedCount = scanner.NextInt();
            int nonFixedCount = maxCells - fixedCount;

            bool possible =
                ((possibleNonFixed[nonFixedCount >> 6] >>
                  (nonFixedCount & 63)) & 1UL) != 0;

            output.AppendLine(possible ? "Yes" : "No");
        }

        Console.Write(output.ToString());
    }
}
