using System;
using System.IO;
using System.Text;

public class Program
{
    private struct Item : IComparable<Item>
    {
        public long Q;
        public long C;
        public long W;

        public int CompareTo(Item other)
        {
            int cmp = Q.CompareTo(other.Q);
            if (cmp != 0) return cmp;
            return C.CompareTo(other.C);
        }
    }

    private sealed class MaxHeap
    {
        private long[] data;
        public int Count { get; private set; }

        public MaxHeap(int capacity)
        {
            data = new long[Math.Max(4, capacity)];
        }

        public void Push(long value)
        {
            if (Count == data.Length)
                Array.Resize(ref data, data.Length * 2);

            int i = Count++;
            while (i > 0)
            {
                int parent = (i - 1) >> 1;
                if (data[parent] >= value) break;
                data[i] = data[parent];
                i = parent;
            }
            data[i] = value;
        }

        public long Pop()
        {
            long result = data[0];
            long value = data[--Count];

            if (Count > 0)
            {
                int i = 0;
                while (true)
                {
                    int left = i * 2 + 1;
                    if (left >= Count) break;

                    int right = left + 1;
                    int child = (right < Count && data[right] > data[left])
                        ? right
                        : left;

                    if (data[child] <= value) break;
                    data[i] = data[child];
                    i = child;
                }
                data[i] = value;
            }

            return result;
        }
    }

    private sealed class FastScanner
    {
        private readonly Stream stream = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = stream.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public long NextLong()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            long value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }

        public int NextInt()
        {
            return (int)NextLong();
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int testCases = scanner.NextInt();
        var output = new StringBuilder();

        for (int tc = 0; tc < testCases; tc++)
        {
            int n = scanner.NextInt();
            int m = scanner.NextInt();

            var items = new Item[n];
            for (int i = 0; i < n; i++)
            {
                long v = scanner.NextLong();
                long p = scanner.NextLong();

                items[i] = new Item
                {
                    Q = v - 1,
                    C = p - 1,
                    W = v - p
                };
            }

            if (m > n)
            {
                output.AppendLine("0");
                continue;
            }

            Array.Sort(items);

            int unfinished = m - 1;
            var suffixCost = new long[n + 1];

            if (unfinished > 0)
            {
                var heap = new MaxHeap(unfinished + 1);
                long sum = 0;
                const long INF = long.MaxValue / 4;
                suffixCost[n] = INF;

                for (int i = n - 1; i >= 0; i--)
                {
                    heap.Push(items[i].C);
                    sum += items[i].C;

                    if (heap.Count > unfinished)
                        sum -= heap.Pop();

                    suffixCost[i] = heap.Count == unfinished ? sum : INF;
                }
            }

            long answer = 0;
            long positivePrefix = 0;
            int lastCandidate = n - unfinished - 1;

            for (int i = 0; i <= lastCandidate; i++)
            {
                long shieldCost = unfinished == 0 ? 0 : suffixCost[i + 1];
                long candidate = positivePrefix + items[i].W - shieldCost;

                if (candidate > answer)
                    answer = candidate;

                if (items[i].W > 0)
                    positivePrefix += items[i].W;
            }

            output.AppendLine(answer.ToString());
        }

        Console.Write(output.ToString());
    }
}
