    private static long[] factorial;
    private static long[] inverseFactorial;

    private static long ModPow(long value, long exponent)
    {
        long result = 1;
        while (exponent > 0)
        {
            if ((exponent & 1) != 0)
                result = result * value % Mod;

            value = value * value % Mod;
            exponent >>= 1;
        }
        return result;
    }

    private static long Combination(int n, int k)
    {
        if (n < 0 || k < 0 || k > n)
            return 0;

        return factorial[n] * inverseFactorial[k] % Mod
             * inverseFactorial[n - k] % Mod;
    }

    // Sum of the numbers of forests with s roots and r total nodes,
    // for L <= s <= U.
    private static long ForestRangeSum(int r, int l, int u)
    {
        if (l > u)
            return 0;

        int upperN = 2 * r - l;
        int lowerN = 2 * r - u - 1;

        long result = Combination(upperN, r);
        result -= Combination(lowerN, r);
        result -= Combination(upperN, r + 1);
        result += Combination(lowerN, r + 1);

        result %= Mod;
        if (result < 0)
            result += Mod;
        return result;
    }

    public static void Main()
    {
        var scanner = new FastScanner(Console.OpenStandardInput());

        int n = scanner.NextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = scanner.NextInt();

        int limit = 2 * n + 5;
        factorial = new long[limit];
        inverseFactorial = new long[limit];

        factorial[0] = 1;
        for (int i = 1; i < limit; i++)
            factorial[i] = factorial[i - 1] * i % Mod;

        inverseFactorial[limit - 1] = ModPow(factorial[limit - 1], Mod - 2);
        for (int i = limit - 1; i > 0; i--)
            inverseFactorial[i - 1] = inverseFactorial[i] * i % Mod;

        long answer = 0;
        long pending = 1;

        for (int i = 0; i < n; i++)
        {
            int remaining = n - i - 1;

            if (remaining == 0)
            {
                if (pending == 1 && a[i] > 0)
                {
                    answer++;
                    if (answer >= Mod)
                        answer -= Mod;
                }

                if (pending == 1 && a[i] == 0)
                {
                    answer++;
                    if (answer >= Mod)
                        answer -= Mod;
                }

                Console.WriteLine(answer);
                return;
            }

            long low = Math.Max(1L, pending - 1);
            long high = Math.Min((long)remaining, pending + a[i] - 2L);

            if (low <= high)
            {
                answer += ForestRangeSum(remaining, (int)low, (int)high);
                if (answer >= Mod)
                    answer -= Mod;
            }

            pending += a[i] - 1L;

            if (pending < 1 || pending > remaining)
            {
                Console.WriteLine(answer);
                return;
            }
        }

        Console.WriteLine(answer % Mod);
    }

