                        rightMaxExactlyT += Mod;
                }

                long term = (long)leftPowers[m - t] * rightMaxExactlyT % Mod;
                cutCount += term;
                if (cutCount >= Mod)
                    cutCount -= Mod;
            }

            answer += cutCount;
            if (answer >= Mod)
                answer -= Mod;
        }

        Console.WriteLine(answer);
    }

