    private sealed class ParityDsu
    {
        private readonly int[] parent;
        private readonly int[] size;
        private readonly int[] xorToParent;

        public ParityDsu(int n)
        {
            parent = new int[n];
            size = new int[n];
            xorToParent = new int[n];

            for (int i = 0; i < n; i++)
            {
                parent[i] = i;
                size[i] = 1;
            }
        }

        public int Find(int x)
        {
            if (parent[x] == x) return x;

            int p = parent[x];
            int root = Find(p);
            xorToParent[x] ^= xorToParent[p];
            parent[x] = root;
            return root;
        }

        public int ParityToRoot(int x)
        {
            Find(x);
            return xorToParent[x];
        }

        public bool Unite(int a, int b, int requiredXor)
        {
            int rootA = Find(a);
            int rootB = Find(b);
            int parityA = xorToParent[a];
            int parityB = xorToParent[b];

            if (rootA == rootB)
                return (parityA ^ parityB) == requiredXor;

            int rootXor = parityA ^ parityB ^ requiredXor;

            if (size[rootA] < size[rootB])
            {
                parent[rootA] = rootB;
                xorToParent[rootA] = rootXor;
                size[rootB] += size[rootA];
            }
            else
            {
                parent[rootB] = rootA;
                xorToParent[rootB] = rootXor;
                size[rootA] += size[rootB];
            }

            return true;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();
        int m = scanner.NextInt();

        var dsu = new ParityDsu(n);
        var hasTestimony = new bool[n];
        var firstTarget = new int[n];
        var firstClaim = new int[n];

        bool possible = true;

        for (int i = 0; i < m; i++)
        {
            int a = scanner.NextInt() - 1;
            int b = scanner.NextInt() - 1;
            int c = scanner.NextInt();

            if (!hasTestimony[a])
            {
                hasTestimony[a] = true;
                firstTarget[a] = b;
                firstClaim[a] = c;
            }
            else
            {
                int requiredXor = firstClaim[a] ^ c;
                if (!dsu.Unite(firstTarget[a], b, requiredXor))
                    possible = false;
            }
        }

        if (!possible)
        {
            Console.WriteLine("-1");
            return;
        }

        var status = new int[n];
        for (int i = 0; i < n; i++)
            status[i] = dsu.ParityToRoot(i);

        var answer = new char[n];
        for (int i = 0; i < n; i++)
        {
            int confused = 0;
            if (hasTestimony[i])
                confused = status[i] ^ status[firstTarget[i]] ^ firstClaim[i];

            answer[i] = confused == 0 ? '0' : '1';
        }

        Console.WriteLine(new string(answer));
    }
}
