        long[] inverseFactorial = new long[maxOperations + 1];
        long[] doubleFactorial = new long[maxOperations + 1];

        factorial[0] = 1;
        doubleFactorial[0] = 1;

        for (int i = 1; i <= maxOperations; i++)
        {
            factorial[i] = factorial[i - 1] * i % Mod;
            doubleFactorial[i] = doubleFactorial[i - 1] * (2L * i - 1) % Mod;
        }

        inverseFactorial[maxOperations] = ModPow(factorial[maxOperations], Mod - 2);
        for (int i = maxOperations; i >= 1; i--)
            inverseFactorial[i - 1] = inverseFactorial[i] * i % Mod;

