        bool redPossible;
        bool bluePossible;

        int[] redSequence = BuildRequiredSequence(
            redPermutation, redBalls, target, out redPossible);

        int[] blueSequence = BuildRequiredSequence(
            bluePermutation, blueBalls, target, out bluePossible);

        if (!redPossible || !bluePossible)
        {
            Console.WriteLine(-1);
            return;
        }

        int lcs = LongestCommonSubsequenceLength(redSequence, blueSequence, n);
        int answer = redSequence.Length + blueSequence.Length - lcs;

        Console.WriteLine(answer);
    }
}
