using System;
using System.IO;
using System.Text;

public class Program
{
    private sealed class FastScanner
    {
        private readonly Stream input = Console.OpenStandardInput();
        private readonly byte[] buffer = new byte[1 << 16];
        private int length;
        private int position;

        private int ReadByte()
        {
            if (position >= length)
            {
                length = input.Read(buffer, 0, buffer.Length);
                position = 0;
                if (length == 0) return -1;
            }
            return buffer[position++];
        }

        public int NextInt()
        {
            int c;
            do
            {
                c = ReadByte();
            } while (c <= 32 && c != -1);

            int value = 0;
            while (c > 32 && c != -1)
            {
                value = value * 10 + (c - '0');
                c = ReadByte();
            }
            return value;
        }
    }

    public static void Main()
    {
        var scanner = new FastScanner();
        int n = scanner.NextInt();

        int[] a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = scanner.NextInt();

        int[] left = new int[n];
        int[] right = new int[n];
        int[] parent = new int[n];
        for (int i = 0; i < n; i++)
        {
            left[i] = -1;
            right[i] = -1;
            parent[i] = -1;
        }

        // Construct a max Cartesian tree.
        int[] stack = new int[n];
        int stackSize = 0;

        for (int i = 0; i < n; i++)
        {
            int last = -1;

            while (stackSize > 0 && a[stack[stackSize - 1]] < a[i])
                last = stack[--stackSize];

            if (stackSize > 0)
            {
                int p = stack[stackSize - 1];
                right[p] = i;
                parent[i] = p;
            }

            if (last != -1)
            {
                left[i] = last;
                parent[last] = i;
            }

            stack[stackSize++] = i;
        }

        int root = 0;
        while (parent[root] != -1)
            root = parent[root];

        // Produce a parent-before-children traversal order.
        int[] order = new int[n];
        int orderCount = 0;
        stackSize = 0;
        stack[stackSize++] = root;

        while (stackSize > 0)
        {
            int v = stack[--stackSize];
            order[orderCount++] = v;

            if (left[v] != -1)
                stack[stackSize++] = left[v];
            if (right[v] != -1)
                stack[stackSize++] = right[v];
        }

        long[] subtreeSum = new long[n];
        int[] subtreeLeft = new int[n];
        int[] subtreeRight = new int[n];
        bool[] stable = new bool[n];

        // Compute subtree intervals and sums in postorder.
        for (int oi = n - 1; oi >= 0; oi--)
        {
            int v = order[oi];
            long sum = a[v];
            int l = v;
            int r = v;

            if (left[v] != -1)
            {
                int child = left[v];
                sum += subtreeSum[child];
                l = subtreeLeft[child];
            }

            if (right[v] != -1)
            {
                int child = right[v];
                sum += subtreeSum[child];
                r = subtreeRight[child];
            }

            subtreeSum[v] = sum;
            subtreeLeft[v] = l;
            subtreeRight[v] = r;

            bool leftBlocked = l == 0 || (long)a[l - 1] >= sum;
            bool rightBlocked = r == n - 1 || (long)a[r + 1] >= sum;
            stable[v] = leftBlocked && rightBlocked;
        }

        int[] nearestStable = new int[n];
        long[] answer = new long[n];

        // For each Cartesian-tree node, find its lowest stable ancestor.
        for (int oi = 0; oi < n; oi++)
        {
            int v = order[oi];

            if (stable[v])
                nearestStable[v] = v;
            else
                nearestStable[v] = nearestStable[parent[v]];

            answer[v] = subtreeSum[nearestStable[v]];
        }

        // A stable singleton need not be a whole Cartesian subtree.
        for (int i = 0; i < n; i++)
        {
            bool leftBlocked = i == 0 || a[i - 1] >= a[i];
            bool rightBlocked = i == n - 1 || a[i + 1] >= a[i];

            if (leftBlocked && rightBlocked)
                answer[i] = a[i];
        }

        var output = new StringBuilder(n * 12);
        for (int i = 0; i < n; i++)
        {
            if (i > 0) output.Append(' ');
            output.Append(answer[i]);
        }

        Console.WriteLine(output.ToString());
    }
}
